def _amerihealth_caritas_api_plan_code(api_base: str | None) -> str | None:
    parsed_api_base = urllib.parse.urlsplit(_canonical_base(api_base) or "")
    if parsed_api_base.netloc.lower() != "api-ext.amerihealthcaritas.com":
        return None
    path_match = re.fullmatch(
        r"/([^/]+)/provider-api",
        parsed_api_base.path.rstrip("/"),
        re.IGNORECASE,
    )
    return _clean_text(path_match.group(1)) if path_match else None


def _is_amerihealth_caritas_provider_api_base(api_base: str | None) -> bool:
    return bool(_amerihealth_caritas_api_plan_code(api_base))


def _amerihealth_caritas_plan_code(row: dict[str, Any]) -> str | None:
    api_plan_code = _amerihealth_caritas_api_plan_code(row.get("api_base"))
    if api_plan_code:
        return api_plan_code
    plan_name_key = _payer_alias_key(row.get("plan_name"))
    if plan_name_key in AMERIHEALTH_CARITAS_PLAN_CODES_BY_ALIAS:
        return AMERIHEALTH_CARITAS_PLAN_CODES_BY_ALIAS[plan_name_key]
    org_name_key = _payer_alias_key(row.get("org_name"))
    if org_name_key in AMERIHEALTH_CARITAS_PLAN_CODES_BY_ALIAS:
        return AMERIHEALTH_CARITAS_PLAN_CODES_BY_ALIAS[org_name_key]
    return None


def _amerihealth_caritas_provider_directory_base(plan_code: str) -> str:
    return f"{AMERIHEALTH_CARITAS_PROVIDER_API_PREFIX}/{plan_code}/provider-api"


def _amerihealth_caritas_override_metadata(
    seed_row: dict[str, Any],
    plan_code: str,
    alias_base: str,
    *,
    is_carrier_acquisition: bool,
) -> dict[str, Any]:
    """Build provenance while keeping carrier acquisition plan-neutral."""
    supported_resources = list(AMERIHEALTH_CARITAS_SUPPORTED_RESOURCES)
    metadata = {
        "provider_directory_override": "amerihealth_caritas_api_ext_provider_api",
        "provider_directory_override_reason": (
            "AmeriHealth Caritas publishes plan-specific public Provider Directory FHIR bases "
            "at api-ext.amerihealthcaritas.com; seed rows can point at stale Availity or "
            "fhir.amerihealthcaritas.com paths."
        ),
        "provider_directory_previous_api_base": _clean_text(seed_row.get("api_base")),
        "provider_directory_confirmed_base": alias_base,
        "provider_directory_confirmed_metadata_url": f"{alias_base}/metadata",
        "provider_directory_confirmed_catalog_url": AMERIHEALTH_CARITAS_DOC_URL,
        "provider_directory_plan_code": (
            None if is_carrier_acquisition else plan_code
        ),
        "provider_directory_supported_resources": supported_resources,
        "provider_directory_fully_enumerable_resources": (
            supported_resources if is_carrier_acquisition else []
        ),
        "provider_directory_coverage_mode": (
            "carrier_directory" if is_carrier_acquisition else "probe_only"
        ),
        "provider_directory_acquisition_enabled": is_carrier_acquisition,
    }
    if not is_carrier_acquisition:
        metadata["provider_directory_acquisition_blocked_reason"] = (
            "Exhaustive equivalence with the 0900 carrier directory is not "
            "established; this plan alias remains catalog/probe-only."
        )
        return metadata
    metadata.update(
        {
            "provider_directory_directory_scope": "carrier",
            "provider_directory_plan_provenance_neutralized": True,
            "provider_directory_original_alias": {
                "plan_code": plan_code,
                "org_name": _clean_text(seed_row.get("org_name")),
                "plan_name": _clean_text(seed_row.get("plan_name")),
                "api_base": alias_base,
            },
        }
    )
    return metadata


def _amerihealth_caritas_provider_directory_override(seed_row_by_field: dict[str, Any]) -> dict[str, Any] | None:
    """Resolve a catalog alias without assigning graph rows to its product."""
    api_base = _canonical_base(seed_row_by_field.get("api_base"))
    portal_url = (_clean_text(seed_row_by_field.get("portal_url")) or "").lower()
    source_url = (_clean_text(seed_row_by_field.get("source_url")) or "").lower()
    org_name = (_clean_text(seed_row_by_field.get("org_name")) or "").lower()
    plan_code = _amerihealth_caritas_plan_code(seed_row_by_field)
    parsed_api_base = urllib.parse.urlsplit(api_base or "")
    api_host = parsed_api_base.netloc.lower()
    should_override = (
        plan_code
        and (
            _is_amerihealth_caritas_provider_api_base(api_base)
            or "amerihealth caritas" in org_name
            or api_host in {"apps.availity.com", "fhir.amerihealthcaritas.com"}
            or "amerihealthcaritas.com" in portal_url
            or "amerihealthcaritas.com" in source_url
        )
    )
    if not should_override:
        return None
    provider_base = _amerihealth_caritas_provider_directory_base(plan_code)
    is_carrier_acquisition = (
        plan_code == AMERIHEALTH_CARITAS_CARRIER_ACQUISITION_PLAN_CODE
    )
    return {
        "api_base": provider_base,
        "canonical_api_base": provider_base,
        "org_name": (
            AMERIHEALTH_CARITAS_CARRIER_ORG_NAME
            if is_carrier_acquisition
            else _clean_text(seed_row_by_field.get("org_name"))
        ),
        "plan_name": (
            None if is_carrier_acquisition else _clean_text(seed_row_by_field.get("plan_name"))
        ),
        "requires_registration": False,
        "auth_type": "none",
        "last_validated_status": (
            "valid" if is_carrier_acquisition else "probe_only"
        ),
        "endpoints": _source_override_endpoint_fields(provider_base),
        "metadata": _amerihealth_caritas_override_metadata(
            seed_row_by_field,
            plan_code,
            provider_base,
            is_carrier_acquisition=is_carrier_acquisition,
        ),
    }


