def _profile_delta_commit_receipt_values(
    profile_delta: ProviderDirectoryPreparedProfileDelta,
    counts_by_name: Mapping[str, int],
    cutover_actual_by_field: Mapping[str, Any],
) -> dict[str, Any]:
    """Return complete receipt parameters for the committed delta."""
    return {
        **_provider_directory_profile_delta_receipt_static_values(
            profile_delta
        ),
        "from_capacity_geometry_json": (
            profile_delta.from_capacity_geometry_json
        ),
        "capacity_geometry_json": profile_delta.capacity_geometry_json,
        **cutover_actual_by_field,
        **counts_by_name,
    }


async def _insert_profile_delta_receipt(
    profile_delta: ProviderDirectoryPreparedProfileDelta,
    receipt_ref: str,
    counts_by_name: Mapping[str, int],
    cutover_actual_by_field: Mapping[str, Any],
) -> None:
    """Validate and insert the immutable committed delta receipt."""
    receipt_values_by_name = _profile_delta_commit_receipt_values(
        profile_delta,
        counts_by_name,
        cutover_actual_by_field,
    )
    _checked_serialized_metadata_payload_bytes(
        receipt_values_by_name,
        fixed_row_overhead=4_096,
    )
    await db.status(
        _PROFILE_DELTA_RECEIPT_INSERT_SQL.format(receipt_ref=receipt_ref),
        **receipt_values_by_name,
    )


async def _validate_profile_delta_final_wal(
    capacity_admission: _ProviderDirectoryProfileCapacityAdmission,
    capacity_forecast: _ProviderDirectoryProfileCutoverCapacityForecast,
) -> None:
    """Validate transaction WAL before admitting the commit envelope."""
    cutover_wal_bytes = int(
        await db.scalar(
            """
            SELECT pg_wal_lsn_diff(
                       pg_current_wal_insert_lsn(),
                       CAST(CAST(:wal_start_lsn AS text) AS pg_lsn)
                   )::bigint;
            """,
            wal_start_lsn=capacity_forecast.wal_start_lsn,
        )
        or 0
    )
    projected_cutover_wal_bytes = (
        capacity_forecast.target_projection.wal_bytes
        + capacity_forecast.metadata_projection.wal_bytes
    )
    if not 0 <= cutover_wal_bytes <= projected_cutover_wal_bytes:
        raise RuntimeError(
            "provider_directory_profile_capacity_cutover_wal_exceeded:"
            f"observed={cutover_wal_bytes}:"
            f"projected={projected_cutover_wal_bytes}"
        )
    final_wal_bytes = await _provider_directory_profile_current_wal_bytes(
        capacity_admission
    )
    maximum_wal_bytes = (
        capacity_admission.geometry.reservation_bytes_by_storage_class["wal"]
    )
    commit_envelope_bytes = (
        capacity_forecast.metadata_projection.commit_envelope_bytes
    )
    if final_wal_bytes + commit_envelope_bytes > maximum_wal_bytes:
        raise RuntimeError(
            "provider_directory_profile_capacity_final_wal_exceeded:"
            f"observed={final_wal_bytes}:"
            f"commit_envelope={commit_envelope_bytes}:"
            f"maximum={maximum_wal_bytes}"
        )


async def _apply_provider_directory_profile_delta(
    profile_delta: ProviderDirectoryPreparedProfileDelta,
    *,
    pending_commit_items: int,
) -> None:
    """Apply one source delta while readers retain their old MVCC snapshot."""

    if _provider_directory_profile_capacity_admission() is None:
        raise RuntimeError(
            "provider_directory_profile_capacity_admission_required"
        )
    locked_state = await _profile_delta_locked_state(profile_delta)
    if locked_state is None:
        return
    capacity_admission = _provider_directory_profile_capacity_admission()
    capacity_forecast = await _prepare_profile_delta_capacity(
        profile_delta,
        locked_state.counts_by_name,
        locked_state.serving_state,
        capacity_admission,
        pending_commit_items,
    )
    target_wal_start_lsn = await _profile_delta_target_wal_start_lsn()
    await _apply_profile_delta_target_rows(
        profile_delta,
        locked_state.relations,
        locked_state.counts_by_name,
    )
    target_bytes = await _profile_delta_target_bytes_after(
        capacity_forecast,
        locked_state.relations,
    )
    cutover_actual_by_field = await _profile_delta_cutover_actual(
        capacity_forecast,
        target_wal_start_lsn,
        target_bytes,
    )
    await _update_profile_delta_serving_generation(
        profile_delta,
        locked_state.counts_by_name,
        capacity_forecast,
    )
    await _insert_profile_delta_receipt(
        profile_delta,
        locked_state.receipt_ref,
        locked_state.counts_by_name,
        cutover_actual_by_field,
    )
    await _validate_profile_delta_final_wal(
        capacity_admission,
        capacity_forecast,
    )


async def _remove_provider_directory_profile_delta_stages(
    profile_delta: ProviderDirectoryPreparedProfileDelta,
) -> None:
    """Best-effort removal of exact committed delta scratch relations."""

    for stage_table in (
        profile_delta.profile_stage,
        profile_delta.evidence_stage,
        profile_delta.affected_npi_stage,
    ):
        capacity_admission = _provider_directory_profile_capacity_admission()
        try:
            if capacity_admission is not None:
                await _reserve_provider_directory_profile_wal_budget(
                    capacity_admission,
                    control_operation_counts={"profile_stage_drop": 1},
                )
            await _provider_directory_profile_capacity_status(
                f"DROP TABLE IF EXISTS "
                f"{_unscoped_qt(profile_delta.schema, stage_table)};"
            )
        except Exception:
            if capacity_admission is not None:
                raise
            LOGGER.warning(
                "Failed to clean Provider Directory Profile delta stage %s",
                stage_table,
                exc_info=True,
            )


async def _finalize_provider_directory_profile_delta_scratch(
    profile_delta: ProviderDirectoryPreparedProfileDelta,
) -> None:
    """Atomically remove admitted scratch before retiring its owner checkpoint."""

    expected_checkpoint = (
        profile_delta.schema,
        profile_delta.build_id,
    )
    if profile_delta.resume_checkpoint != expected_checkpoint:
        raise RuntimeError(
            "provider_directory_profile_delta_resume_checkpoint_invalid"
        )
    await _remove_provider_directory_profile_delta_stages(profile_delta)
    await _delete_provider_directory_profile_build_checkpoint(
        *expected_checkpoint
    )
    admission = _provider_directory_profile_capacity_admission()
    if admission is not None:
        await _assert_provider_directory_profile_wal_budget(admission)


def _ordered_provider_directory_artifact_bundle(
    stages: tuple[ProviderDirectoryPreparedArtifactStage, ...],
) -> tuple[ProviderDirectoryPreparedArtifactStage, ...]:
    """Validate and deterministically order one serving artifact bundle."""
    ordered_stages = tuple(
        sorted(stages, key=lambda stage: stage.target_relation)
    )
    schemas = {stage.schema for stage in ordered_stages}
    targets = [stage.target_relation for stage in ordered_stages]
    if len(schemas) > 1:
        raise ValueError("provider_directory_artifact_bundle_schema_mismatch")
    if len(targets) != len(set(targets)):
        raise ValueError("provider_directory_artifact_bundle_target_duplicate")
    return ordered_stages


def _provider_directory_artifact_bundle_context(
    ordered_stages: tuple[ProviderDirectoryPreparedArtifactStage, ...],
    profile_delta: ProviderDirectoryPreparedProfileDelta | None,
) -> tuple[str, tuple[str, ...], str, str]:
    """Validate a bundle and resolve its exact transaction coordinates."""
    schemas = {stage.schema for stage in ordered_stages}
    if profile_delta is not None:
        schemas.add(profile_delta.schema)
        ordinary_targets = {
            stage.target_relation for stage in ordered_stages
        }
        profile_targets = {
            profile_artifact.PROFILE_EVIDENCE_TABLE,
            profile_artifact.PROFILE_TABLE,
        }
        if ordinary_targets.intersection(profile_targets):
            raise ValueError(
                "provider_directory_profile_delta_target_duplicate"
            )
    if len(schemas) != 1:
        raise ValueError(
            "provider_directory_artifact_bundle_schema_mismatch"
        )
    if (
        profile_delta is not None
        and _PROVIDER_DIRECTORY_PROFILE_SELECTION_EXECUTION.get() is not None
        and _provider_directory_profile_capacity_admission() is None
    ):
        raise RuntimeError(
            "provider_directory_profile_capacity_admission_required"
        )
    relation_names = tuple(
        sorted(
            {
                relation_name
                for stage in ordered_stages
                for relation_name in _provider_directory_prepared_stage_relations(
                    stage
                )
            }
        )
    )
    if profile_delta is not None:
        return (
            next(iter(schemas)),
            relation_names,
            PROVIDER_DIRECTORY_PROFILE_DELTA_PROMOTION_LOCK_TIMEOUT,
            PROVIDER_DIRECTORY_PROFILE_DELTA_PROMOTION_STATEMENT_TIMEOUT,
        )
    return (
        next(iter(schemas)),
        relation_names,
        PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_LOCK_TIMEOUT,
        PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_STATEMENT_TIMEOUT,
    )


def _provider_directory_artifact_transaction_timeout_seconds(
    dataset_fence: ProviderDirectoryArtifactDatasetFence | None,
    *,
    profile_delta: ProviderDirectoryPreparedProfileDelta | None = None,
) -> float:
    """Return the outer wall for one exact publication transaction."""
    if profile_delta is not None:
        return PROVIDER_DIRECTORY_PROFILE_DELTA_PROMOTION_TIMEOUT_SECONDS
    if (
        dataset_fence is not None
        and dataset_fence.should_select_validated_candidates
    ):
        return (
            PROVIDER_DIRECTORY_ARTIFACT_CANDIDATE_TRANSACTION_TIMEOUT_SECONDS
        )
    return PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_TRANSACTION_TIMEOUT_SECONDS


def _tighten_provider_directory_artifact_cutover_timeout(
    cutover_timeout: asyncio.Timeout | None,
) -> None:
    """Restore the short live-cutover wall after candidate validation."""
    if cutover_timeout is None:
        return
    current_deadline = cutover_timeout.when()
    live_deadline = (
        asyncio.get_running_loop().time()
        + PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_TRANSACTION_TIMEOUT_SECONDS
    )
    if current_deadline is None or live_deadline < current_deadline:
        cutover_timeout.reschedule(live_deadline)


async def _configure_provider_directory_artifact_promotion(
    lock_timeout: str,
    statement_timeout: str,
) -> _ProviderDirectoryProfileCapacityAdmission | None:
    capacity_admission = _provider_directory_profile_capacity_admission()
    if capacity_admission is None:
        await db.status(
            "SET LOCAL lock_timeout = "
            f"'{lock_timeout}';"
        )
        await db.status(
            "SET LOCAL statement_timeout = "
            f"'{statement_timeout}';"
        )
    else:
        await _apply_provider_directory_profile_capacity_settings(
            capacity_admission
        )
    return capacity_admission


async def _lock_provider_directory_artifact_bundle_targets(
    ordered_stages: tuple[ProviderDirectoryPreparedArtifactStage, ...],
    schema: str,
    profile_delta: ProviderDirectoryPreparedProfileDelta | None,
) -> None:
    if profile_delta is None:
        for stage in ordered_stages:
            await _acquire_provider_directory_artifact_cutover_lock(stage)
        return
    target_relations = {
        stage.target_relation for stage in ordered_stages
    }
    target_relations.update(
        {
            profile_artifact.PROFILE_EVIDENCE_TABLE,
            profile_artifact.PROFILE_TABLE,
        }
    )
    for target_relation in sorted(target_relations):
        await _acquire_provider_directory_artifact_target_lock(
            schema,
            target_relation,
        )


async def _reserve_provider_directory_artifact_cutover_budget(
    profile_delta: ProviderDirectoryPreparedProfileDelta | None,
    capacity_admission: _ProviderDirectoryProfileCapacityAdmission | None,
) -> ProviderDirectoryArtifactDatasetFence | None:
    active_fence = _PROVIDER_DIRECTORY_ARTIFACT_DATASET_FENCE.get()
    if profile_delta is None or capacity_admission is None:
        return active_fence
    if active_fence is None:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_profile_cutover_fence_missing"
        )
    cutover_row_lock_count = (
        _provider_directory_profile_cutover_row_lock_count(active_fence)
    )
    if cutover_row_lock_count * PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_ATTEMPTS != (
        _provider_directory_profile_control_operation_count(
            capacity_admission,
            "cutover_row_lock",
        )
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_profile_cutover_row_lock_count_changed"
        )
    await _reserve_provider_directory_profile_wal_budget(
        capacity_admission,
        control_operation_counts={
            "cutover_row_lock": cutover_row_lock_count,
        },
    )
    return active_fence


async def _apply_locked_provider_directory_artifact_bundle(
    ordered_stages: tuple[ProviderDirectoryPreparedArtifactStage, ...],
    schema: str,
    relation_names: tuple[str, ...],
    profile_delta: ProviderDirectoryPreparedProfileDelta | None,
    active_fence: ProviderDirectoryArtifactDatasetFence | None,
    cutover_timeout: asyncio.Timeout | None = None,
) -> None:
    await _verify_active_profile_selection_at_cutover()
    if (
        profile_delta is not None
        and not ordered_stages
        and await _resolve_provider_directory_profile_delta_replay(
            profile_delta,
            active_fence,
        )
    ):
        return
    if active_fence is not None:
        await _lock_artifact_cutover_fence(
            active_fence,
            profile_delta=profile_delta,
        )
    if profile_delta is None:
        _tighten_provider_directory_artifact_cutover_timeout(
            cutover_timeout
        )
    for stage in ordered_stages:
        await _assert_provider_directory_artifact_build_fence(stage)
    if profile_delta is not None:
        await _assert_provider_directory_profile_delta_identity(profile_delta)
    await _lock_provider_directory_artifact_tables(schema, relation_names)
    for stage in ordered_stages:
        await _install_provider_directory_prepared_stage(stage)
    for stage in ordered_stages:
        await _finish_provider_directory_prepared_stage(stage)
    if active_fence is not None:
        await _promote_provider_directory_artifact_datasets(active_fence)
    if profile_delta is None:
        return
    await _apply_provider_directory_profile_delta(
        profile_delta,
        pending_commit_items=(
            len(relation_names)
            + (
                len(active_fence.datasets)
                if active_fence is not None
                else 0
            )
        ),
    )
    await _finalize_provider_directory_profile_delta_scratch(profile_delta)


async def _promote_provider_directory_artifact_bundle_transaction(
    stages: tuple[ProviderDirectoryPreparedArtifactStage, ...],
    *,
    profile_delta: ProviderDirectoryPreparedProfileDelta | None = None,
    cutover_timeout: asyncio.Timeout | None = None,
) -> None:
    """Publish relation swaps and an optional source delta atomically."""
    ordered_stages = _ordered_provider_directory_artifact_bundle(stages)
    if not ordered_stages and profile_delta is None:
        return
    schema, relation_names, lock_timeout, statement_timeout = (
        _provider_directory_artifact_bundle_context(
            ordered_stages,
            profile_delta,
        )
    )
    async with db.transaction():
        capacity_admission = await (
            _configure_provider_directory_artifact_promotion(
                lock_timeout,
                statement_timeout,
            )
        )
        await _lock_provider_directory_artifact_bundle_targets(
            ordered_stages,
            schema,
            profile_delta,
        )
        active_fence = (
            await _reserve_provider_directory_artifact_cutover_budget(
                profile_delta,
                capacity_admission,
            )
        )
        await _apply_locked_provider_directory_artifact_bundle(
            ordered_stages,
            schema,
            relation_names,
            profile_delta,
            active_fence,
            cutover_timeout,
        )


async def _is_artifact_bundle_promotion_committed(
    stages: tuple[ProviderDirectoryPreparedArtifactStage, ...],
    promotion_identities: tuple[Any, ...],
    dataset_fence: ProviderDirectoryArtifactDatasetFence | None,
    profile_delta: ProviderDirectoryPreparedProfileDelta | None,
) -> bool:
    """Verify all atomic cutover components after acknowledgement loss."""
    try:
        relation_swap_committed = (
            not stages
            or await _is_provider_directory_artifact_promotion_committed(
                promotion_identities,
                dataset_fence,
            )
        )
        delta_committed = (
            profile_delta is None
            or await _is_provider_directory_profile_delta_committed(
                profile_delta
            )
        )
        dataset_committed = (
            dataset_fence is None
            or await _is_provider_directory_dataset_cutover_committed(
                dataset_fence
            )
        )
    except Exception:
        LOGGER.warning(
            "Provider Directory artifact cutover acknowledgement was "
            "lost and committed-state verification also failed",
            exc_info=True,
        )
        return False
    return relation_swap_committed and delta_committed and dataset_committed


async def _promote_provider_directory_artifact_bundle(
    stages: tuple[ProviderDirectoryPreparedArtifactStage, ...],
    *,
    profile_delta: ProviderDirectoryPreparedProfileDelta | None = None,
) -> None:
    """Apply a hard wall-clock limit to one atomic artifact bundle cutover."""

    promotion_identities = (
        await _capture_provider_directory_artifact_promotion_identities(stages)
    )
    dataset_fence = _PROVIDER_DIRECTORY_ARTIFACT_DATASET_FENCE.get()
    transaction_timeout_seconds = (
        _provider_directory_artifact_transaction_timeout_seconds(
            dataset_fence,
            profile_delta=profile_delta,
        )
    )
    try:
        async with asyncio.timeout(
            transaction_timeout_seconds
        ) as cutover_timeout:
            await _promote_provider_directory_artifact_bundle_transaction(
                stages,
                profile_delta=profile_delta,
                cutover_timeout=(
                    None if profile_delta is not None else cutover_timeout
                ),
            )
    except Exception as promotion_error:
        if await _is_artifact_bundle_promotion_committed(
            stages,
            promotion_identities,
            dataset_fence,
            profile_delta,
        ):
            LOGGER.warning(
                "Provider Directory artifact cutover acknowledgement "
                "was lost after commit (%s); verified promoted targets "
                "by immutable identity: %s",
                type(promotion_error).__name__,
                ",".join(stage.target_relation for stage in stages),
            )
            return
        raise


async def _retry_provider_directory_artifact_bundle_promotion(
    stages: tuple[ProviderDirectoryPreparedArtifactStage, ...],
    *,
    profile_delta: ProviderDirectoryPreparedProfileDelta | None = None,
) -> None:
    """Retry transient lock conflicts without rebuilding immutable stages."""
    for attempt_index in range(PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_ATTEMPTS):
        try:
            if profile_delta is None:
                await _promote_provider_directory_artifact_bundle(stages)
            else:
                await _promote_provider_directory_artifact_bundle(
                    stages,
                    profile_delta=profile_delta,
                )
            return
        except Exception as exc:
            if not _is_provider_directory_artifact_cutover_retryable(exc):
                raise
            if attempt_index + 1 >= PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_ATTEMPTS:
                raise
            await asyncio.sleep(
                PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_BACKOFF_SECONDS
                * (attempt_index + 1)
            )


async def _remove_provider_directory_artifact_stage(
    stage: ProviderDirectoryPreparedArtifactStage,
) -> None:
    """Drop an unpromoted stage without masking the publication result."""
    stage_ref = _qt(stage.schema, stage.stage_table)
    try:
        await _provider_directory_profile_capacity_status(
            f"DROP TABLE IF EXISTS {stage_ref};"
        )
    except Exception:
        LOGGER.warning(
            "Failed to clean Provider Directory artifact stage %s",
            stage_ref,
            exc_info=True,
        )


async def _promote_provider_directory_artifact_stage(
    schema: str,
    stage_table: str,
    target_relation: str,
    rename_stage_indexes: Callable[[str, str], Awaitable[None]],
    build_fence: ProviderDirectoryArtifactBuildFence | None = None,
) -> None:
    """Apply a hard wall-clock deadline to the live artifact cutover."""

    stage = ProviderDirectoryPreparedArtifactStage(
        schema=schema,
        stage_table=stage_table,
        target_relation=target_relation,
        rename_stage_indexes=rename_stage_indexes,
        build_fence=build_fence,
    )
    promotion_identities = (
        await _capture_provider_directory_artifact_promotion_identities((stage,))
    )
    dataset_fence = _PROVIDER_DIRECTORY_ARTIFACT_DATASET_FENCE.get()
    try:
        async with asyncio.timeout(
            _provider_directory_artifact_transaction_timeout_seconds(
                dataset_fence,
            )
        ) as cutover_timeout:
            await _promote_provider_directory_artifact_stage_transaction(
                schema,
                stage_table,
                target_relation,
                rename_stage_indexes,
                build_fence,
                cutover_timeout,
            )
    except TimeoutError:
        if await _is_provider_directory_artifact_promotion_committed(
            promotion_identities,
            dataset_fence,
        ):
            LOGGER.warning(
                "Provider Directory artifact cutover timed out after commit; "
                "verified promoted target by relation identity: %s",
                target_relation,
            )
            return
        raise


async def _retry_provider_directory_artifact_promotion(
    schema: str,
    stage_table: str,
    target_relation: str,
    rename_stage_indexes: Callable[[str, str], Awaitable[None]],
    build_fence: ProviderDirectoryArtifactBuildFence | None,
) -> None:
    for attempt_index in range(PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_ATTEMPTS):
        try:
            await _promote_provider_directory_artifact_stage(
                schema,
                stage_table,
                target_relation,
                rename_stage_indexes,
                build_fence,
            )
            return
        except Exception as exc:
            if not _is_provider_directory_artifact_cutover_retryable(exc):
                raise
            if attempt_index + 1 >= PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_ATTEMPTS:
                raise
            await asyncio.sleep(PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_BACKOFF_SECONDS * (attempt_index + 1))


async def _cutover_provider_directory_artifact_stage(
    *,
    schema: str,
    stage_table: str,
    target_relation: str,
    rename_stage_indexes: Callable[[str, str], Awaitable[None]],
    build_fence: ProviderDirectoryArtifactBuildFence | None = None,
) -> None:
    """Promote a prepared stage without ever changing a live table's persistence."""

    stage_ref = _qt(schema, stage_table)
    try:
        await _prepare_provider_directory_artifact_stage(schema, stage_table)
        await _retry_provider_directory_artifact_promotion(
            schema,
            stage_table,
            target_relation,
            rename_stage_indexes,
            build_fence,
        )
        await _assert_provider_directory_logged_relation(schema, target_relation)
    except Exception:
        try:
            await db.status(f"DROP TABLE IF EXISTS {stage_ref};")
        except Exception:
            LOGGER.warning("Failed to clean Provider Directory artifact stage %s", stage_ref, exc_info=True)
        raise


async def _swap_address_corroboration_stage(
    schema: str,
    stage_table: str,
    stage_ref: str,
    target_relation: str,
    build_fence: ProviderDirectoryArtifactBuildFence | None = None,
) -> None:
    del stage_ref
    await _cutover_provider_directory_artifact_stage(
        schema=schema,
        stage_table=stage_table,
        target_relation=target_relation,
        rename_stage_indexes=_rename_address_corroboration_stage_indexes,
        build_fence=build_fence,
    )


async def _populate_address_corroboration_stage(
    schema: str,
    stage_ref: str,
    target_ref: str,
    select_sql: str,
    source_ids: list[str],
) -> int:
    """Create a stage while retaining corroboration outside a source scope."""
    target_kind = await _provider_directory_relation_attribute(
        schema,
        PROVIDER_DIRECTORY_ADDRESS_CORROBORATION_VIEW,
        "relkind",
    )
    if source_ids and target_kind is not None:
        await db.status(
            f"""
            CREATE UNLOGGED TABLE {stage_ref} AS
            SELECT *
              FROM {target_ref}
             WHERE NOT (
                 provider_directory_source_id = ANY(
                     CAST(:source_ids AS varchar[])
                 )
             );
            """,
            source_ids=source_ids,
        )
        copied_existing = int(
            await db.scalar(f"SELECT COUNT(*) FROM {stage_ref};") or 0
        )
        await db.status(f"INSERT INTO {stage_ref}\n{select_sql};")
        return copied_existing
    await db.status(f"CREATE UNLOGGED TABLE {stage_ref} AS\n{select_sql};")
    return 0


def _address_corroboration_publication_metrics(
    target_ref: str,
    row_count: int,
    network_catalog_metrics: dict[str, Any],
    source_ids: list[str],
    copied_existing: int,
) -> dict[str, Any]:
    metrics_by_field = {
        "published": True,
        "relation": target_ref,
        "rows": row_count,
        "storage": "table",
        "network_catalog": network_catalog_metrics,
    }
    if source_ids:
        metrics_by_field["copied_existing"] = copied_existing
        metrics_by_field["source_ids"] = source_ids
    return metrics_by_field


async def _address_corroboration_network_metrics(
    schema: str,
    source_ids: list[str],
    *,
    refresh_network_catalog: bool,
    metrics_override: dict[str, Any] | None,
) -> dict[str, Any]:
    """Return network metrics without rebuilding a prepared bundle stage."""
    if metrics_override is not None:
        return metrics_override
    if refresh_network_catalog:
        return await publish_provider_directory_network_catalog(
            schema,
            **({"source_ids": source_ids} if source_ids else {}),
        )
    return await _ensure_provider_directory_network_catalog_populated(schema)


async def _prepared_address_corroboration_result(
    schema: str,
    stage_table: str,
    publish_metrics: dict[str, Any],
    build_fence: ProviderDirectoryArtifactBuildFence,
) -> tuple[dict[str, Any], ProviderDirectoryPreparedArtifactStage]:
    """Mark a corroboration stage logged and package it for bundle cutover."""
    await _prepare_provider_directory_artifact_stage(schema, stage_table)
    return (
        publish_metrics,
        ProviderDirectoryPreparedArtifactStage(
            schema=schema,
            stage_table=stage_table,
            target_relation=PROVIDER_DIRECTORY_ADDRESS_CORROBORATION_VIEW,
            rename_stage_indexes=_rename_address_corroboration_stage_indexes,
            build_fence=build_fence,
        ),
    )


async def _best_effort_drop_address_corroboration_stage(stage_ref: str) -> None:
    """Clean a failed corroboration stage without masking its build error."""
    try:
        await db.status(f"DROP TABLE IF EXISTS {stage_ref};")
    except Exception:
        LOGGER.warning(
            "Failed to clean provider directory address stage table %s",
            stage_ref,
            exc_info=True,
        )


async def publish_provider_directory_address_corroboration_table(
    db_schema: str | None = None,
    *,
    refresh_network_catalog: bool = True,
    source_ids: list[str] | tuple[str, ...] | None = None,
    defer_cutover: bool = False,
    network_catalog_metrics_override: dict[str, Any] | None = None,
) -> Any:
    """Publish provider directory address corroboration table for provider-directory serving."""
    schema = db_schema or _schema()
    relation = PROVIDER_DIRECTORY_ADDRESS_CORROBORATION_VIEW
    effective_source_ids = _clean_source_id_list(source_ids)
    network_catalog_metrics = await _address_corroboration_network_metrics(
        schema, effective_source_ids,
        refresh_network_catalog=refresh_network_catalog,
        metrics_override=network_catalog_metrics_override,
    )
    async with _provider_directory_artifact_build_guard(schema, relation) as build_fence:
        stage_table = _stage_table_name()
        stage_ref = _qt(schema, stage_table)
        target_ref = _qt(schema, relation)
        select_sql = provider_directory_address_corroboration_select_sql(schema)
        try:
            await db.status(f"DROP TABLE IF EXISTS {stage_ref};")
            copied_existing = await _populate_address_corroboration_stage(
                schema,
                stage_ref,
                target_ref,
                select_sql,
                effective_source_ids,
            )
            row_count = int(await db.scalar(f"SELECT COUNT(*) FROM {stage_ref};") or 0)
            await _create_provider_directory_address_corroboration_indexes(schema, stage_table)
            await db.status(f"ANALYZE {stage_ref};")
            publish_result = _address_corroboration_publication_metrics(
                target_ref,
                row_count,
                network_catalog_metrics,
                effective_source_ids,
                copied_existing,
            )
            if defer_cutover:
                return await _prepared_address_corroboration_result(
                    schema,
                    stage_table,
                    publish_result,
                    build_fence,
                )
            await _swap_address_corroboration_stage(
                schema,
                stage_table,
                stage_ref,
                relation,
                build_fence,
            )
            await db.status(f"ANALYZE {_qt(schema, relation)};")
            return publish_result
        except Exception:
            await _best_effort_drop_address_corroboration_stage(stage_ref)
            raise


def _provider_directory_location_coordinate_sql_map(source_alias: str) -> dict[str, str]:
    location_country_expr = _country_restore_default_us_sql(f"{source_alias}.country_code")
    raw_lat = f"({source_alias}.latitude)::numeric"
    raw_long = f"({source_alias}.longitude)::numeric"
    numeric_re = r"^-?[0-9]+(\.[0-9]+)?$"
    numeric_guard = (
        f"{source_alias}.latitude ~ '{numeric_re}' "
        f"AND {source_alias}.longitude ~ '{numeric_re}'"
    )
    normalized_lat_expr = _coordinate_from_location_sql(
        f"{source_alias}.latitude",
        f"{source_alias}.longitude",
        location_country_expr,
        axis="lat",
    )
    normalized_long_expr = _coordinate_from_location_sql(
        f"{source_alias}.latitude",
        f"{source_alias}.longitude",
        location_country_expr,
        axis="long",
    )
    return {
        "location_country_expr": location_country_expr,
        "raw_lat": raw_lat,
        "raw_long": raw_long,
        "numeric_guard": numeric_guard,
        "normalized_lat_expr": normalized_lat_expr,
        "normalized_long_expr": normalized_long_expr,
    }


def _provider_directory_location_coordinate_scopes(
    source_alias: str,
    *,
    db_schema: str,
    run_id: str | None,
    source_ids: list[str] | tuple[str, ...] | None,
    seen_table: str | None,
) -> list[str]:
    scope_clause_list: list[str] = []
    if run_id is not None and not seen_table:
        scope_clause_list.append(f"{source_alias}.last_seen_run_id = CAST(:run_id AS varchar)")
    if source_ids:
        scope_clause_list.append(f"{source_alias}.source_id = ANY(CAST(:source_ids AS varchar[]))")
    if seen_table:
        seen_ref = _qt(db_schema, seen_table)
        seen_run_filter = "AND seen.run_id = CAST(:run_id AS varchar)" if run_id is not None else ""
        scope_clause_list.append(
            f"""EXISTS (
                SELECT 1
                  FROM {seen_ref} AS seen
                 WHERE seen.resource_type = 'Location'
                   {seen_run_filter}
                   AND seen.source_id = {source_alias}.source_id
                   AND seen.resource_id = {source_alias}.resource_id
            )"""
        )
    scope_clause_list.append(
        f"""(
            CAST(:after_source_id AS varchar) IS NULL
            OR ({source_alias}.source_id, {source_alias}.resource_id)
                > (CAST(:after_source_id AS varchar), CAST(:after_resource_id AS varchar))
        )"""
    )
    return scope_clause_list


def _provider_directory_location_coordinate_where_sql(
    source_alias: str,
    coordinate_expr_map: dict[str, str],
    scope_clause_list: list[str],
) -> str:
    where_clause_list = [
        f"NULLIF(BTRIM(COALESCE({source_alias}.latitude, '')), '') IS NOT NULL",
        f"NULLIF(BTRIM(COALESCE({source_alias}.longitude, '')), '') IS NOT NULL",
        coordinate_expr_map["numeric_guard"],
        "NOT ("
        + _coordinate_pair_plausible_sql(
            coordinate_expr_map["raw_lat"],
            coordinate_expr_map["raw_long"],
            coordinate_expr_map["location_country_expr"],
        )
        + ")",
        f"({coordinate_expr_map['normalized_lat_expr']}) IS NOT NULL",
        f"({coordinate_expr_map['normalized_long_expr']}) IS NOT NULL",
        *scope_clause_list,
    ]
    return " AND ".join(f"({clause})" for clause in where_clause_list)


def _provider_directory_location_coordinate_batch_body(
    source_alias: str,
    location_ref: str,
    coordinate_expr_map: dict[str, str],
    where_sql: str,
) -> str:
    normalized_latitude_sql = _coordinate_text_sql(coordinate_expr_map["normalized_lat_expr"])
    normalized_longitude_sql = _coordinate_text_sql(coordinate_expr_map["normalized_long_expr"])
    return f"""
    WITH candidates AS MATERIALIZED (
        SELECT
            {source_alias}.source_id,
            {source_alias}.resource_id,
            {normalized_latitude_sql} AS normalized_latitude,
            {normalized_longitude_sql} AS normalized_longitude
          FROM {location_ref} AS {source_alias}
         WHERE {where_sql}
         ORDER BY {source_alias}.source_id,
                  {source_alias}.resource_id
         LIMIT CAST(:batch_size AS integer)
    ),
    updated AS (
        UPDATE {location_ref} AS loc
           SET latitude = candidates.normalized_latitude,
               longitude = candidates.normalized_longitude,
               updated_at = now()
          FROM candidates
         WHERE loc.source_id = candidates.source_id
           AND loc.resource_id = candidates.resource_id
           AND candidates.normalized_latitude IS NOT NULL
           AND candidates.normalized_longitude IS NOT NULL
           AND (
                loc.latitude IS DISTINCT FROM candidates.normalized_latitude
             OR loc.longitude IS DISTINCT FROM candidates.normalized_longitude
           )
         RETURNING loc.source_id,
                   loc.resource_id
    )
    SELECT
        (SELECT COUNT(*) FROM candidates)::bigint AS candidate_rows,
        (SELECT COUNT(*) FROM updated)::bigint AS updated_rows,
        (SELECT source_id FROM candidates ORDER BY source_id DESC, resource_id DESC LIMIT 1)::varchar
            AS last_source_id,
        (SELECT resource_id FROM candidates ORDER BY source_id DESC, resource_id DESC LIMIT 1)::varchar
            AS last_resource_id;
    """


def provider_directory_location_coordinate_batch_sql(
    db_schema: str | None = None,
    *,
    run_id: str | None = None,
    source_ids: list[str] | tuple[str, ...] | None = None,
    seen_table: str | None = None,
) -> str:
    """Normalize stored FHIR Location coordinates in bounded keyset batches."""

    schema = db_schema or _schema()
    source_alias = "loc_src"
    location_ref = _qt(schema, "provider_directory_location")
    coordinate_expr_map = _provider_directory_location_coordinate_sql_map(source_alias)
    scope_clause_list = _provider_directory_location_coordinate_scopes(
        source_alias,
        db_schema=schema,
        run_id=run_id,
        source_ids=source_ids,
        seen_table=seen_table,
    )
    where_sql = _provider_directory_location_coordinate_where_sql(
        source_alias,
        coordinate_expr_map,
        scope_clause_list,
    )
    return _provider_directory_location_coordinate_batch_body(
        source_alias,
        location_ref,
        coordinate_expr_map,
        where_sql,
    )


async def backfill_provider_directory_location_coordinates(
    db_schema: str | None = None,
    *,
    run_id: str | None = None,
    source_ids: list[str] | tuple[str, ...] | None = None,
    seen_table: str | None = None,
    batch_size: int | None = None,
) -> int:
    """Repair stored Provider Directory coordinates that can be normalized safely."""

    schema = db_schema or _schema()
    if not await _is_table_present(schema, "provider_directory_location"):
        return 0
    query_param_dict: dict[str, Any] = {}
    if run_id is not None:
        query_param_dict["run_id"] = run_id
    if source_ids:
        query_param_dict["source_ids"] = list(source_ids)
    total_updated = 0
    after_source_id: str | None = None
    after_resource_id: str | None = None
    bounded_batch_size = max(int(batch_size or _location_coordinate_batch_size()), 1)
    coordinate_batch_sql = provider_directory_location_coordinate_batch_sql(
        schema,
        run_id=run_id,
        source_ids=source_ids,
        seen_table=seen_table,
    )
    while True:
        coordinate_batch_result = await db.first(
            coordinate_batch_sql,
            **query_param_dict,
            after_source_id=after_source_id,
            after_resource_id=after_resource_id,
            batch_size=bounded_batch_size,
        )
        batch_result_mapping = (
            coordinate_batch_result._mapping
            if hasattr(coordinate_batch_result, "_mapping")
            else dict(coordinate_batch_result or {})
        )
        candidate_rows = int(batch_result_mapping.get("candidate_rows") or 0)
        updated_rows = int(batch_result_mapping.get("updated_rows") or 0)
        total_updated += updated_rows
        next_source_id = _clean_text(batch_result_mapping.get("last_source_id"))
        next_resource_id = _clean_text(batch_result_mapping.get("last_resource_id"))
        if candidate_rows <= 0 or not next_source_id or not next_resource_id:
            break
        if next_source_id == after_source_id and next_resource_id == after_resource_id:
            break
        after_source_id = next_source_id
        after_resource_id = next_resource_id
    return total_updated


def provider_directory_location_address_key_sql(
    db_schema: str | None = None,
    *,
    restore_state_from_zip: bool = True,
    run_id: str | None = None,
    source_ids: list[str] | tuple[str, ...] | None = None,
    seen_table: str | None = None,
) -> str:
    """Stamp imported FHIR Location rows with the shared canonical address key."""

    schema = db_schema or _schema()
    qschema = _q(schema)
    location_ref = _qt(schema, "provider_directory_location")
    source_alias = "loc_src"
    raw_state_expr = f"COALESCE(NULLIF({source_alias}.state_name, ''), {source_alias}.state_code)"
    normalized_state_expr = _state_fips_restore_sql(raw_state_expr)
    normalized_country_expr = _country_restore_sql(f"{source_alias}.country_code")
    needs_country_normalization_expr = (
        f"(NULLIF({normalized_country_expr}, '') IS NOT NULL "
        f"AND {source_alias}.country_code IS DISTINCT FROM {normalized_country_expr})"
    )
    zip_state_select = "geo.state::varchar" if restore_state_from_zip else "NULL::varchar"
    zip_city_select = "geo.city::varchar" if restore_state_from_zip else "NULL::varchar"
    zip_state_join = (
        f"""
          LEFT JOIN {_qt(schema, "geo_zip_lookup")} AS geo
            ON geo.zip_code = normalized.source_zip5
        """
        if restore_state_from_zip
        else ""
    )
    needs_work_clauses = [
        f"{source_alias}.address_key IS NULL",
        f"{source_alias}.zip5 IS NULL",
        f"{source_alias}.city_name IS NULL",
        f"{source_alias}.state_code IS NULL",
        f"{source_alias}.city_norm IS NULL",
        f"{raw_state_expr} ~ '^[0-9]{{1,2}}$'",
        needs_country_normalization_expr,
    ]
    scope_clauses: list[str] = []
    from_sql = f"FROM {location_ref} AS {source_alias}"
    if run_id is not None and not seen_table:
        scope_clauses.append(f"{source_alias}.last_seen_run_id = CAST(:run_id AS varchar)")
    if source_ids:
        scope_clauses.append(f"{source_alias}.source_id = ANY(CAST(:source_ids AS varchar[]))")
    if seen_table:
        seen_ref = _qt(schema, seen_table)
        seen_run_filter = "AND seen.run_id = CAST(:run_id AS varchar)" if run_id is not None else ""
        from_sql = f"""
          FROM (
                SELECT DISTINCT seen.source_id,
                       seen.resource_id
                  FROM {seen_ref} AS seen
                 WHERE seen.resource_type = 'Location'
                   {seen_run_filter}
               ) AS seen_scope
          JOIN {location_ref} AS {source_alias}
            ON {source_alias}.source_id = seen_scope.source_id
           AND {source_alias}.resource_id = seen_scope.resource_id
        """
    where_clauses = [f"({' OR '.join(needs_work_clauses)})", *scope_clauses]
    where_sql = " AND ".join(where_clauses)
    return f"""
    WITH normalized AS (
        SELECT
            {source_alias}.source_id,
            {source_alias}.resource_id,
            {source_alias}.first_line,
            {source_alias}.second_line,
            {source_alias}.city_name,
            {source_alias}.postal_code,
            {source_alias}.country_code,
            {qschema}.addr_zip5_norm_v1({source_alias}.postal_code)::varchar AS source_zip5,
            {normalized_country_expr} AS normalized_country,
            {raw_state_expr} AS raw_state,
            {normalized_state_expr} AS normalized_state
          {from_sql}
         WHERE {where_sql}
    ),
    resolved AS (
        SELECT
            normalized.*,
            CASE
                WHEN NULLIF(BTRIM(COALESCE(normalized.normalized_state::varchar, '')), '') IS NULL
                    THEN {zip_state_select}
                ELSE NULL::varchar
            END AS zip_restored_state,
            CASE
                WHEN NULLIF(BTRIM(COALESCE(normalized.city_name::varchar, '')), '') IS NULL
                    THEN {zip_city_select}
                ELSE NULL::varchar
            END AS zip_restored_city,
            COALESCE(NULLIF(BTRIM(normalized.normalized_state::varchar), ''), {zip_state_select}) AS resolved_state,
            COALESCE(NULLIF(BTRIM(normalized.city_name::varchar), ''), {zip_city_select}) AS resolved_city
          FROM normalized
          {zip_state_join}
    ),
    keyed AS (
        SELECT
            source_id,
            resource_id,
            {qschema}.addr_key_v1(
                first_line,
                second_line,
                resolved_city,
                resolved_state,
                postal_code,
                COALESCE(NULLIF(normalized_country, ''), 'US')
            ) AS computed_address_key,
            source_zip5 AS computed_zip5,
            {qschema}.addr_state_code_v1(resolved_state)::varchar AS computed_state_code,
            {qschema}.addr_city_norm_v1(resolved_city)::varchar AS computed_city_norm,
            CASE
                WHEN NULLIF(BTRIM(COALESCE(city_name::varchar, '')), '') IS NULL
                 AND zip_restored_city IS NOT NULL
                    THEN zip_restored_city::varchar
                ELSE NULL::varchar
            END AS restored_city_name,
            CASE
                WHEN raw_state ~ '^[0-9]{{1,2}}$'
                    THEN {qschema}.addr_state_code_v1(resolved_state)::varchar
                WHEN NULLIF(BTRIM(COALESCE(raw_state::varchar, '')), '') IS NULL
                 AND zip_restored_state IS NOT NULL
                    THEN {qschema}.addr_state_code_v1(zip_restored_state)::varchar
                ELSE NULL::varchar
            END AS restored_state_name,
            normalized_country
          FROM resolved
    )
    UPDATE {location_ref} AS loc
       SET address_key = keyed.computed_address_key::text,
           zip5 = COALESCE(keyed.computed_zip5, loc.zip5),
           city_name = COALESCE(keyed.restored_city_name, loc.city_name),
           state_name = COALESCE(keyed.restored_state_name, loc.state_name),
           state_code = COALESCE(keyed.computed_state_code, loc.state_code),
           city_norm = COALESCE(keyed.computed_city_norm, loc.city_norm),
           country_code = COALESCE(keyed.normalized_country, loc.country_code),
           updated_at = now()
      FROM keyed
     WHERE loc.source_id = keyed.source_id
       AND loc.resource_id = keyed.resource_id
       AND keyed.computed_address_key IS NOT NULL
       AND (
            loc.address_key IS DISTINCT FROM keyed.computed_address_key::text
         OR loc.zip5 IS DISTINCT FROM COALESCE(keyed.computed_zip5, loc.zip5)
         OR loc.city_name IS DISTINCT FROM COALESCE(keyed.restored_city_name, loc.city_name)
         OR loc.state_name IS DISTINCT FROM COALESCE(keyed.restored_state_name, loc.state_name)
         OR loc.state_code IS DISTINCT FROM COALESCE(keyed.computed_state_code, loc.state_code)
         OR loc.city_norm IS DISTINCT FROM COALESCE(keyed.computed_city_norm, loc.city_norm)
         OR loc.country_code IS DISTINCT FROM COALESCE(keyed.normalized_country, loc.country_code)
       );
    """


def provider_directory_address_key_batch_sql(
    db_schema: str | None = None,
    *,
    restore_state_from_zip: bool = True,
    run_id: str | None = None,
    source_ids: list[str] | tuple[str, ...] | None = None,
    seen_table: str | None = None,
) -> str:
    """Stamp a bounded keyset batch of FHIR Location rows with address keys."""

    schema = db_schema or _schema()
    qschema = _q(schema)
    location_ref = _qt(schema, "provider_directory_location")
    source_alias = "loc_src"
    raw_state_expr = f"COALESCE(NULLIF({source_alias}.state_name, ''), {source_alias}.state_code)"
    normalized_state_expr = _state_fips_restore_sql(raw_state_expr)
    normalized_country_expr = _country_restore_sql(f"{source_alias}.country_code")
    needs_country_normalization_expr = (
        f"(NULLIF({normalized_country_expr}, '') IS NOT NULL "
        f"AND {source_alias}.country_code IS DISTINCT FROM {normalized_country_expr})"
    )
    zip_state_select = "geo.state::varchar" if restore_state_from_zip else "NULL::varchar"
    zip_city_select = "geo.city::varchar" if restore_state_from_zip else "NULL::varchar"
    zip_state_join = (
        f"""
          LEFT JOIN {_qt(schema, "geo_zip_lookup")} AS geo
            ON geo.zip_code = normalized.source_zip5
        """
        if restore_state_from_zip
        else ""
    )
    needs_work_clauses = [
        f"{source_alias}.address_key IS NULL",
        f"{source_alias}.zip5 IS NULL",
        f"{source_alias}.city_name IS NULL",
        f"{source_alias}.state_code IS NULL",
        f"{source_alias}.city_norm IS NULL",
        f"{raw_state_expr} ~ '^[0-9]{{1,2}}$'",
        needs_country_normalization_expr,
    ]
    scope_clauses: list[str] = []
    if run_id is not None and not seen_table:
        scope_clauses.append(f"{source_alias}.last_seen_run_id = CAST(:run_id AS varchar)")
    if source_ids:
        scope_clauses.append(f"{source_alias}.source_id = ANY(CAST(:source_ids AS varchar[]))")
    if seen_table:
        seen_ref = _qt(schema, seen_table)
        seen_run_filter = "AND seen.run_id = CAST(:run_id AS varchar)" if run_id is not None else ""
        scope_clauses.append(
            f"""EXISTS (
                SELECT 1
                  FROM {seen_ref} AS seen
                 WHERE seen.resource_type = 'Location'
                   {seen_run_filter}
                   AND seen.source_id = {source_alias}.source_id
                   AND seen.resource_id = {source_alias}.resource_id
            )"""
        )
    scope_clauses.append(
        f"""(
            CAST(:after_source_id AS varchar) IS NULL
            OR ({source_alias}.source_id, {source_alias}.resource_id)
                > (CAST(:after_source_id AS varchar), CAST(:after_resource_id AS varchar))
        )"""
    )
    where_clauses = [f"({' OR '.join(needs_work_clauses)})", *scope_clauses]
    where_sql = " AND ".join(where_clauses)
    return f"""
    WITH candidates AS MATERIALIZED (
        SELECT
            {source_alias}.source_id,
            {source_alias}.resource_id,
            {source_alias}.first_line,
            {source_alias}.second_line,
            {source_alias}.city_name,
            {source_alias}.postal_code,
            {source_alias}.country_code,
            {qschema}.addr_zip5_norm_v1({source_alias}.postal_code)::varchar AS source_zip5,
            {normalized_country_expr} AS normalized_country,
            {raw_state_expr} AS raw_state,
            {normalized_state_expr} AS normalized_state
          FROM {location_ref} AS {source_alias}
         WHERE {where_sql}
         ORDER BY {source_alias}.source_id,
                  {source_alias}.resource_id
         LIMIT CAST(:batch_size AS integer)
    ),
    normalized AS (
        SELECT * FROM candidates
    ),
    resolved AS (
        SELECT
            normalized.*,
            CASE
                WHEN NULLIF(BTRIM(COALESCE(normalized.normalized_state::varchar, '')), '') IS NULL
                    THEN {zip_state_select}
                ELSE NULL::varchar
            END AS zip_restored_state,
            CASE
                WHEN NULLIF(BTRIM(COALESCE(normalized.city_name::varchar, '')), '') IS NULL
                    THEN {zip_city_select}
                ELSE NULL::varchar
            END AS zip_restored_city,
            COALESCE(NULLIF(BTRIM(normalized.normalized_state::varchar), ''), {zip_state_select}) AS resolved_state,
            COALESCE(NULLIF(BTRIM(normalized.city_name::varchar), ''), {zip_city_select}) AS resolved_city
          FROM normalized
          {zip_state_join}
    ),
    keyed AS (
        SELECT
            source_id,
            resource_id,
            {qschema}.addr_key_v1(
                first_line,
                second_line,
                resolved_city,
                resolved_state,
                postal_code,
                COALESCE(NULLIF(normalized_country, ''), 'US')
            ) AS computed_address_key,
            source_zip5 AS computed_zip5,
            {qschema}.addr_state_code_v1(resolved_state)::varchar AS computed_state_code,
            {qschema}.addr_city_norm_v1(resolved_city)::varchar AS computed_city_norm,
            CASE
                WHEN NULLIF(BTRIM(COALESCE(city_name::varchar, '')), '') IS NULL
                 AND zip_restored_city IS NOT NULL
                    THEN zip_restored_city::varchar
                ELSE NULL::varchar
            END AS restored_city_name,
            CASE
                WHEN raw_state ~ '^[0-9]{{1,2}}$'
                    THEN {qschema}.addr_state_code_v1(resolved_state)::varchar
                WHEN NULLIF(BTRIM(COALESCE(raw_state::varchar, '')), '') IS NULL
                 AND zip_restored_state IS NOT NULL
                    THEN {qschema}.addr_state_code_v1(zip_restored_state)::varchar
                ELSE NULL::varchar
            END AS restored_state_name,
            normalized_country
          FROM resolved
    ),
    updated AS (
        UPDATE {location_ref} AS loc
           SET address_key = keyed.computed_address_key::text,
               zip5 = COALESCE(keyed.computed_zip5, loc.zip5),
               city_name = COALESCE(keyed.restored_city_name, loc.city_name),
               state_name = COALESCE(keyed.restored_state_name, loc.state_name),
               state_code = COALESCE(keyed.computed_state_code, loc.state_code),
               city_norm = COALESCE(keyed.computed_city_norm, loc.city_norm),
               country_code = COALESCE(keyed.normalized_country, loc.country_code),
               updated_at = now()
          FROM keyed
         WHERE loc.source_id = keyed.source_id
           AND loc.resource_id = keyed.resource_id
           AND keyed.computed_address_key IS NOT NULL
           AND (
                loc.address_key IS DISTINCT FROM keyed.computed_address_key::text
             OR loc.zip5 IS DISTINCT FROM COALESCE(keyed.computed_zip5, loc.zip5)
             OR loc.city_name IS DISTINCT FROM COALESCE(keyed.restored_city_name, loc.city_name)
             OR loc.state_name IS DISTINCT FROM COALESCE(keyed.restored_state_name, loc.state_name)
             OR loc.state_code IS DISTINCT FROM COALESCE(keyed.computed_state_code, loc.state_code)
             OR loc.city_norm IS DISTINCT FROM COALESCE(keyed.computed_city_norm, loc.city_norm)
             OR loc.country_code IS DISTINCT FROM COALESCE(keyed.normalized_country, loc.country_code)
           )
         RETURNING loc.source_id,
                   loc.resource_id
    )
    SELECT
        (SELECT COUNT(*) FROM candidates)::bigint AS candidate_rows,
        (SELECT COUNT(*) FROM updated)::bigint AS updated_rows,
        (SELECT source_id FROM candidates ORDER BY source_id DESC, resource_id DESC LIMIT 1)::varchar
            AS last_source_id,
        (SELECT resource_id FROM candidates ORDER BY source_id DESC, resource_id DESC LIMIT 1)::varchar
            AS last_resource_id;
    """


provider_directory_location_address_key_batch_sql = (
    provider_directory_address_key_batch_sql
)


async def _has_address_canon_functions(db_schema: str) -> bool:
    value = await db.scalar(
        "SELECT to_regprocedure(:signature);",
        signature=f"{db_schema}.addr_key_v1(text,text,text,text,text,text)",
    )
    return isinstance(value, str) and bool(value)


async def _is_table_present(db_schema: str, table_name: str) -> bool:
    return bool(
        await db.scalar(
            "SELECT to_regclass(:qualified_name) IS NOT NULL;",
            qualified_name=f"{db_schema}.{table_name}",
        )
    )


@dataclass(frozen=True)
class ProviderDirectoryArtifactDataset:
    source_id: str
    endpoint_id: str
    dataset_id: str
    evidence_run_id: str
    serving_endpoint_id: str | None = None
    selected_resources: tuple[str, ...] = ()
    retained_resources: tuple[str, ...] = ()
    expected_resources: tuple[str, ...] = ()
    recorded_expected_resources: tuple[str, ...] | None = None
    status: str = ENDPOINT_DATASET_PUBLISHED
    is_current: bool = True
    previous_dataset_id: str | None = None
    expected_incumbent_dataset_id: str | None = None
    promote_on_cutover: bool = False
    reconcile_source_alias_on_cutover: bool = False
    dataset_hash: str | None = None
    resource_count: int | None = None
    validated_at: str | None = None
    publication_metadata_hash: str | None = None
    completion_proof_required_version: int | None = None
    completion_proof_sha256: str | None = None
    completion_proof_cutoff: str | None = None
    verification_source_status: str | None = None
    verification_campaign_id: str | None = None
    verification_source_scope_hash: str | None = None
    verification_source_ids: tuple[str, ...] = ()
    reviewed_root_policy: ReviewedRootPolicy | None = None
    source_verification_contract: tuple[Any, ...] = ()
    source_verification_contract_hash: str | None = None
    dataset_scoped_ready: bool = False
    semantic_projection_as_of: str | None = None
    source_authority_id: str | None = None
    admission_id: str | None = None
    operation_key: str | None = None

    @property
    def artifact_resources(self) -> tuple[str, ...]:
        """Return every proven family available to serving artifacts."""

        return self.retained_resources or self.selected_resources


@dataclass(frozen=True)
class _ProviderDirectoryArtifactScopeBatchProjection:
    """One ordered source or immutable-dataset projection coordinate."""

    batch_number: int
    source_id: str
    dataset_id: str | None
    evidence_run_id: str | None
    resource_type: str
    after_resource_id: str | None
    last_resource_id: str | None
    projected_rows: int
    projected_logical_bytes: int

    def canonical_payload(self) -> dict[str, Any]:
        """Return this batch coordinate in deterministic hash form."""
        return {
            "batch_number": self.batch_number,
            "source_id": self.source_id,
            "dataset_id": self.dataset_id,
            "evidence_run_id": self.evidence_run_id,
            "resource_type": self.resource_type,
            "after_resource_id": self.after_resource_id,
            "last_resource_id": self.last_resource_id,
            "projected_rows": self.projected_rows,
            "projected_logical_bytes": self.projected_logical_bytes,
        }


@dataclass(frozen=True)
class _ProviderDirectoryArtifactScopeTableProjection:
    """Exact projected rows and logical tuple bytes for one scope table."""

    table_name: str
    resource_type: str
    projected_rows: int
    projected_logical_bytes: int
    batches: tuple[_ProviderDirectoryArtifactScopeBatchProjection, ...] = ()

    def canonical_payload(self) -> dict[str, Any]:
        """Return this table projection in deterministic hash form."""
        return {
            "table_name": self.table_name,
            "resource_type": self.resource_type,
            "projected_rows": self.projected_rows,
            "projected_logical_bytes": self.projected_logical_bytes,
            "batches": [
                batch.canonical_payload() for batch in self.batches
            ],
        }


@dataclass(frozen=True)
class _ProviderDirectoryArtifactScopeExactProjection:
    """Canonical exact projection for every materialized artifact table."""

    tables: tuple[_ProviderDirectoryArtifactScopeTableProjection, ...]

    @property
    def projected_rows(self) -> int:
        """Return total source and resource rows across all scope tables."""
        return sum(table.projected_rows for table in self.tables)

    @property
    def projected_logical_bytes(self) -> int:
        """Return total projected tuple bytes across all scope tables."""
        return sum(table.projected_logical_bytes for table in self.tables)

    def canonical_payload(self) -> dict[str, Any]:
        """Return the ordered exact projection payload used for hashing."""
        return {
            "projection_schema": (
                "provider-directory-artifact-scope-exact-v2"
            ),
            "projected_rows": self.projected_rows,
            "projected_logical_bytes": self.projected_logical_bytes,
            "tables": [
                table.canonical_payload() for table in self.tables
            ],
        }

    @property
    def projection_hash(self) -> str:
        """Return the deterministic identity of the exact projection."""
        return _identity_hash(self.canonical_payload())


@dataclass(frozen=True)
class ProviderDirectoryArtifactDatasetFence:
    datasets: tuple[ProviderDirectoryArtifactDataset, ...]
    should_select_validated_candidates: bool = False
    promotion_aliases: tuple[ProviderDirectoryArtifactDataset, ...] = ()

    @property
    def dataset_id_by_endpoint_id(self) -> dict[str, str]:
        """Return the immutable dataset selected for each endpoint."""
        return {
            dataset.endpoint_id: dataset.dataset_id
            for dataset in self.datasets
        }

    @property
    def incumbent_dataset_ids(
        self,
    ) -> dict[str, str | None]:
        """Return the current pointer expected before each cutover."""
        return {
            dataset.endpoint_id: (
                dataset.expected_incumbent_dataset_id
                if dataset.promote_on_cutover
                else dataset.dataset_id
            )
            for dataset in self.datasets
        }

    @property
    def promotion_datasets(self) -> list[ProviderDirectoryArtifactDataset]:
        """Return one promotion candidate per endpoint in lock order."""
        candidates_by_endpoint_id = {
            dataset.endpoint_id: dataset
            for dataset in self.datasets
            if dataset.promote_on_cutover
        }
        return [
            candidates_by_endpoint_id[endpoint_id]
            for endpoint_id in sorted(candidates_by_endpoint_id)
        ]

    @property
    def source_alias_cutover_datasets(
        self,
    ) -> list[ProviderDirectoryArtifactDataset]:
        """Return datasets whose proven source aliases must move at cutover."""

        return [
            dataset
            for dataset in self.datasets
            if (
                dataset.promote_on_cutover
                or dataset.reconcile_source_alias_on_cutover
            )
        ]

    @property
    def locked_alias_datasets(self) -> tuple[ProviderDirectoryArtifactDataset, ...]:
        """Return output aliases plus the full reviewed promotion alias set."""
        dataset_by_source_id = {
            dataset.source_id: dataset for dataset in self.datasets
        }
        for promotion_alias in self.promotion_aliases:
            incumbent = dataset_by_source_id.setdefault(
                promotion_alias.source_id,
                promotion_alias,
            )
            if (
                incumbent.dataset_id != promotion_alias.dataset_id
                or incumbent.endpoint_id != promotion_alias.endpoint_id
            ):
                raise RuntimeError(
                    "provider_directory_artifact_promotion_alias_ambiguous:"
                    + promotion_alias.source_id
                )
        return tuple(
            dataset_by_source_id[source_id]
            for source_id in sorted(dataset_by_source_id)
        )

    @property
    def source_endpoint_dataset_tuples(self) -> tuple[tuple[str, str, str], ...]:
        """Return the source alias mapping that must still hold at cutover."""
        return tuple(
            sorted(
                (
                    dataset.source_id,
                    dataset.endpoint_id,
                    dataset.dataset_id,
                )
                for dataset in self.locked_alias_datasets
            )
        )

    @property
    def source_endpoint_tuples(self) -> tuple[tuple[str, str], ...]:
        """Return the serving alias mapping that must hold before cutover."""
        return tuple(
            sorted(
                (
                    dataset.source_id,
                    dataset.serving_endpoint_id or dataset.endpoint_id,
                )
                for dataset in self.locked_alias_datasets
            )
        )

    @property
    def published_source_endpoint_tuples(self) -> tuple[tuple[str, str], ...]:
        """Return the alias mapping expected after atomic publication."""
        return tuple(
            sorted(
                (
                    dataset.source_id,
                    (
                        dataset.endpoint_id
                        if (
                            dataset.promote_on_cutover
                            or dataset.reconcile_source_alias_on_cutover
                        )
                        else dataset.serving_endpoint_id or dataset.endpoint_id
                    ),
                )
                for dataset in self.locked_alias_datasets
            )
        )

    @property
    def endpoint_ids(self) -> list[str]:
        """Return the endpoint rows that serialize artifact cutover."""
        return sorted(
            {
                endpoint_id
                for dataset in self.locked_alias_datasets
                for endpoint_id in (
                    dataset.endpoint_id,
                    dataset.serving_endpoint_id,
                )
                if endpoint_id
            }
        )

    @property
    def source_ids(self) -> list[str]:
        """Return only aliases included in materialized artifact output."""
        return sorted({dataset.source_id for dataset in self.datasets})

    @property
    def locked_source_ids(self) -> list[str]:
        """Return output and full reviewed promotion aliases to lock."""
        return sorted(
            {dataset.source_id for dataset in self.locked_alias_datasets}
        )


def _provider_directory_artifact_dataset_selection_sql(
    source_ids: list[str] | tuple[str, ...] | None,
    *,
    should_select_validated_candidates: bool = False,
) -> str:
    """Select one immutable dataset per endpoint with explicit fallback rules."""
    source_ref = _qt(_schema(), ProviderDirectorySource.__tablename__)
    dataset_ref = _qt(_schema(), ProviderDirectoryEndpointDataset.__tablename__)
    selection_sql = (
        _artifact_dataset_explicit_selection_sql(dataset_ref, source_ref)
        if source_ids
        else _artifact_dataset_all_source_selection_sql(
            dataset_ref,
            source_ref,
        )
    )
    options_sql = _artifact_dataset_options_cte(dataset_ref, source_ref)
    ranking_sql = _artifact_dataset_ranking_cte()
    projection_sql = _artifact_dataset_projection_sql()
    return f"""
        WITH {options_sql}, {ranking_sql}, {selection_sql}
        {projection_sql}
    """


def _artifact_profile_absence_sql(source_ref: str, metadata: str) -> str:
    source_ids = f"COALESCE({metadata} -> 'source_ids', 'null'::jsonb)"
    return f"""
        COALESCE(
            {metadata} ->> 'requires_twin_root_verification', 'false'
        ) = 'false'
        AND NULLIF(
            {metadata} ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}', ''
        ) IS NULL
        AND NULLIF(
            {metadata} ->> '{TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY}', ''
        ) IS NULL
        AND NULLIF(
            {metadata} ->> '{TWIN_ROOT_VERIFICATION_ROLE_KEY}', ''
        ) IS NULL
        AND NULLIF(
            {metadata} ->> '{TWIN_ROOT_VERIFICATION_BASELINE_DATASET_KEY}', ''
        ) IS NULL
        AND NOT ({metadata} ? '{TWIN_ROOT_VERIFICATION_METADATA_KEY}')
        AND NOT ({metadata} ? '{REVIEWED_ROOT_POLICY_METADATA_KEY}')
        AND NOT EXISTS (
            SELECT 1
              FROM {source_ref} AS profile_source
             WHERE (
                    {source_ids} @> jsonb_build_array(profile_source.source_id)
                    OR profile_source.endpoint_id = dataset.endpoint_id
                    OR profile_source.metadata_json::jsonb
                         ->> '{PROVIDER_DIRECTORY_CONFIGURED_ENDPOINT_METADATA_KEY}'
                         = dataset.endpoint_id
               )
               AND (
                    profile_source.metadata_json::jsonb
                        ? 'provider_directory_candidate_status'
                    OR profile_source.metadata_json::jsonb
                        ? '{PROVIDER_DIRECTORY_VERIFICATION_CAMPAIGN_METADATA_KEY}'
               )
        )
    """


def _artifact_normalized_resource_hash_contract_sql(metadata: str) -> str:
    """Decode markerless legacy rows without accepting an explicit null."""

    return f"""
        CASE
            WHEN {metadata} ? '{RESOURCE_HASH_CONTRACT_METADATA_KEY}'
            THEN {metadata} ->> '{RESOURCE_HASH_CONTRACT_METADATA_KEY}'
            ELSE '{LEGACY_RESOURCE_HASH_CONTRACT}'
        END
    """.strip()


def _artifact_proof_hash_identity_sql(metadata: str, proof: str) -> str:
    """Bind one twin proof to its immutable parent hash identity."""

    resource_hash_contract = _artifact_normalized_resource_hash_contract_sql(
        metadata
    )
    proof_scope_key = PROVIDER_DIRECTORY_PROOF_RESOURCE_SCOPE_METADATA_KEY
    projection_date_key = SEMANTIC_PROJECTION_AS_OF_METADATA_KEY
    return f"""
        ({resource_hash_contract}) IN (
            '{LEGACY_RESOURCE_HASH_CONTRACT}',
            '{TRANSPORT_NEUTRAL_RESOURCE_HASH_CONTRACT}',
            '{SEMANTIC_CONTENT_RESOURCE_HASH_CONTRACT}',
            '{SEMANTIC_CONTENT_V4_RESOURCE_HASH_CONTRACT}'
        )
        AND ({proof} -> '{proof_scope_key}') IS NOT DISTINCT FROM
            ({metadata} -> '{proof_scope_key}')
        AND ({proof} -> '{projection_date_key}') IS NOT DISTINCT FROM
            ({metadata} -> '{projection_date_key}')
        AND (
            (
                ({resource_hash_contract}) =
                    '{SEMANTIC_CONTENT_V4_RESOURCE_HASH_CONTRACT}'
                AND {proof} ->> '{RESOURCE_HASH_CONTRACT_METADATA_KEY}' =
                    '{SEMANTIC_CONTENT_V4_RESOURCE_HASH_CONTRACT}'
            )
            OR (
                ({resource_hash_contract}) IN (
                    '{LEGACY_RESOURCE_HASH_CONTRACT}',
                    '{TRANSPORT_NEUTRAL_RESOURCE_HASH_CONTRACT}',
                    '{SEMANTIC_CONTENT_RESOURCE_HASH_CONTRACT}'
                )
                AND NOT ({proof} ? '{RESOURCE_HASH_CONTRACT_METADATA_KEY}')
            )
        )
        AND (
            (
                ({resource_hash_contract}) IN (
                    '{SEMANTIC_CONTENT_RESOURCE_HASH_CONTRACT}',
                    '{SEMANTIC_CONTENT_V4_RESOURCE_HASH_CONTRACT}'
                )
                AND jsonb_typeof({metadata} -> '{proof_scope_key}') = 'array'
                AND jsonb_typeof({metadata} -> '{projection_date_key}') =
                    'string'
            )
            OR (
                ({resource_hash_contract}) IN (
                    '{LEGACY_RESOURCE_HASH_CONTRACT}',
                    '{TRANSPORT_NEUTRAL_RESOURCE_HASH_CONTRACT}'
                )
                AND NOT ({metadata} ? '{proof_scope_key}')
                AND NOT ({metadata} ? '{projection_date_key}')
            )
        )
    """


def _artifact_matched_proof_sql(
    metadata: str,
    verification: str,
    proof: str,
    dataset_alias: str = "dataset",
) -> str:
    return f"""
        COALESCE(
            {metadata} ->> 'requires_twin_root_verification', 'false'
        ) = 'true'
        AND NULLIF(
            {metadata} ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}', ''
        ) IS NOT NULL
        AND NULLIF(
            {metadata} ->> '{TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY}', ''
        ) IS NOT NULL
        AND {metadata} ->> '{TWIN_ROOT_VERIFICATION_ROLE_KEY}'
            = '{TWIN_ROOT_VERIFICATION_CANDIDATE_ROLE}'
        AND NULLIF(
            {metadata} ->> '{TWIN_ROOT_VERIFICATION_BASELINE_DATASET_KEY}', ''
        ) IS NOT NULL
        AND {verification} ->> 'role'
            = '{TWIN_ROOT_VERIFICATION_CANDIDATE_ROLE}'
        AND {verification} ->> 'admission_role'
            = '{TWIN_ROOT_VERIFICATION_CANDIDATE_ROLE}'
        AND {verification} ->> 'result' = 'matched'
        AND COALESCE(
            {verification} -> 'mismatch_fields', 'null'::jsonb
        ) = '[]'::jsonb
        AND {verification} ->> 'baseline_dataset_id'
            = {metadata} ->> '{TWIN_ROOT_VERIFICATION_BASELINE_DATASET_KEY}'
        AND {proof} ->> 'endpoint_id' = {dataset_alias}.endpoint_id
        AND {proof} ->> 'acquisition_root_run_id'
            = {dataset_alias}.acquisition_root_run_id
        AND {proof} -> 'source_ids' = {metadata} -> 'source_ids'
        AND {proof} -> 'selected_resources'
            = {metadata} -> 'selected_resources'
        AND {proof} -> 'expected_resources'
            = {metadata} -> 'expected_resources'
        AND jsonb_typeof({proof} -> 'resource_hashes') = 'object'
        AND jsonb_typeof({proof} -> 'resource_counts') = 'object'
        AND {proof} ->> 'dataset_hash' = {dataset_alias}.dataset_hash
        AND {proof} ->> 'resource_count'
            = {dataset_alias}.resource_count::text
        AND {proof} ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}'
            = {metadata} ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}'
        AND {proof} ->> '{TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY}'
            = {metadata} ->> '{TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY}'
        AND {_artifact_proof_hash_identity_sql(metadata, proof)}
    """


def _artifact_twin_proof_equality_sql(
    candidate_proof: str,
    baseline_proof: str,
    *,
    include_subset_completion: bool = False,
) -> str:
    fields = [
        "endpoint_id",
        "source_ids",
        "selected_resources",
        "expected_resources",
        TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY,
        TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY,
        "dataset_hash",
        "resource_count",
        "resource_hashes",
        "resource_counts",
    ]
    if include_subset_completion:
        fields.extend(("completion_proof", "completion_proof_sha256"))
    required_field_sql = "\n               AND ".join(
        f"{candidate_proof} -> '{field}' = {baseline_proof} -> '{field}'"
        for field in fields
    )
    optional_field_sql = "\n               AND ".join(
        f"({candidate_proof} -> '{field}') IS NOT DISTINCT FROM "
        f"({baseline_proof} -> '{field}')"
        for field in (
            RESOURCE_HASH_CONTRACT_METADATA_KEY,
            PROVIDER_DIRECTORY_PROOF_RESOURCE_SCOPE_METADATA_KEY,
            SEMANTIC_PROJECTION_AS_OF_METADATA_KEY,
        )
    )
    return f"{required_field_sql}\n               AND {optional_field_sql}"


def _artifact_subset_parent_pair_sql(sql_by_field: Mapping[str, str]) -> str:
    """Return atomic parent proof, replay, and fixed coverage predicates."""

    dataset = sql_by_field["dataset"]
    proof = sql_by_field["completion_proof"]
    proof_sha = sql_by_field["completion_sha256"]
    canonical_sha = sql_by_field["canonical_sha256_function"]
    replay = sql_by_field["replay_evidence"]
    replay_sha = sql_by_field["replay_sha256"]
    coverage = sql_by_field["coverage"]
    return f"""
        {dataset}.completion_proof_required_version =
            {SERVER_ISSUED_SUBSET_REQUIRED_VERSION}
        AND jsonb_typeof({proof}) = 'object'
        AND {proof_sha} ~ '^[0-9a-f]{{64}}$'
        AND {canonical_sha}({proof}) = {proof_sha}
        AND jsonb_typeof({replay}) = 'object'
        AND {replay_sha} ~ '^[0-9a-f]{{64}}$'
        AND {canonical_sha}({replay}) = {replay_sha}
        AND {replay} ->> 'completion_proof_sha256' = {proof_sha}
        AND jsonb_typeof({coverage}) = 'object'
        AND {coverage} ->> 'scope' = 'server_issued_traversal_subset'
        AND {coverage} ->> 'cutoff' = {proof} ->> 'cutoff'
        AND {coverage} ->> 'proof_sha256' = {proof_sha}
        AND {coverage} -> 'traversal_complete' = 'true'::jsonb
        AND {coverage} ->> 'absence_semantics' = 'unknown_under_subset'
        AND {coverage} ->> 'missing_target_semantics' =
            'preserved_not_synthesized'
        AND {coverage} ->> 'publication_state_at_completion' =
            'not_published'
    """


def _artifact_subset_parent_coverage_sql(
    sql_by_field: Mapping[str, str],
    *,
    bind_embedded_completion: bool = True,
) -> str:
    """Bind safe aggregate coverage and canonical dataset proof fields."""

    dataset = sql_by_field["dataset"]
    proof = sql_by_field["completion_proof"]
    proof_sha = sql_by_field["completion_sha256"]
    embedded = sql_by_field["embedded_proof"]
    metadata = sql_by_field["metadata"]
    coverage = sql_by_field["coverage"]
    embedded_completion_sql = (
        f"""
        AND {embedded} -> 'completion_proof' = {proof}
        AND {embedded} ->> 'completion_proof_sha256' = {proof_sha}
        """
        if bind_embedded_completion
        else ""
    )
    return f"""
        {coverage} -> 'resources' = (
            SELECT jsonb_object_agg(
                       resource_type,
                       {coverage} -> 'resources' -> resource_type
                   )
              FROM jsonb_each({proof} -> 'resources')
                   AS completion_resource(resource_type, resource_proof)
        )
        AND NOT EXISTS (
            SELECT 1
              FROM (VALUES ('advertised_pre'), ('advertised_post'),
                           ('returned_unique'), ('deficit'))
                   AS count_field(field_name)
             WHERE {coverage} -> count_field.field_name IS DISTINCT FROM (
                    SELECT to_jsonb(
                               sum((resource_proof
                                   ->> count_field.field_name)::bigint)
                           )
                      FROM jsonb_each({proof} -> 'resources')
                           AS resource(resource_type, resource_proof)
             )
        )
        {embedded_completion_sql}
        AND {proof} ->> 'campaign_id' =
            {metadata} ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}'
        AND {proof} -> 'dataset' ->> 'hash' = {dataset}.dataset_hash
        AND {proof} -> 'dataset' -> 'count' =
            to_jsonb({dataset}.resource_count)
        AND {proof} -> 'dataset' -> 'resource_hashes' =
            {embedded} -> 'resource_hashes'
        AND {proof} -> 'dataset' -> 'resource_counts' =
            {embedded} -> 'resource_counts'
    """


def _artifact_stored_content_proof_sql(
    dataset_alias: str,
    metadata: str,
    stored_proof: str,
) -> str:
    """Bind a canonical stored content proof to one finalized subset row."""

    content_proof_valid = _qt(
        _schema(), "provider_directory_subset_content_proof_valid"
    )
    completion_proof = f"{dataset_alias}.completion_proof_json"
    return f"""
        {content_proof_valid}(
            {stored_proof},
            {dataset_alias}.dataset_id,
            {dataset_alias}.endpoint_id,
            {dataset_alias}.acquisition_root_run_id,
            {metadata} -> 'source_ids',
            {metadata} -> 'selected_resources',
            {dataset_alias}.dataset_hash,
            {dataset_alias}.resource_count,
            {completion_proof} -> 'dataset' -> 'resource_hashes',
            {completion_proof} -> 'dataset' -> 'resource_counts'
        ) IS TRUE
    """


def _artifact_subset_single_root_proof_sql(
    dataset_alias: str,
    metadata: str,
    stored_proof: str,
) -> str:
    """Bind one direct completion/replay/coverage/content proof set."""

    sql_by_field = {
        "dataset": dataset_alias,
        "metadata": metadata,
        "embedded_proof": stored_proof,
        "completion_proof": f"{dataset_alias}.completion_proof_json",
        "completion_sha256": f"{dataset_alias}.completion_proof_sha256",
        "canonical_sha256_function": _qt(
            _schema(), "provider_directory_subset_canonical_sha256"
        ),
        "replay_evidence": (
            f"{metadata} -> '{SERVER_ISSUED_SUBSET_REPLAY_EVIDENCE_KEY}'"
        ),
        "replay_sha256": (
            f"{metadata} ->> '{SERVER_ISSUED_SUBSET_REPLAY_EVIDENCE_SHA256_KEY}'"
        ),
        "coverage": f"{metadata} -> '{SERVER_ISSUED_SUBSET_COVERAGE_KEY}'",
    }
    fragments = (
        _artifact_subset_parent_pair_sql(sql_by_field),
        _artifact_subset_parent_coverage_sql(
            sql_by_field,
            bind_embedded_completion=False,
        ),
        _artifact_subset_parent_diagnostics_sql(sql_by_field),
        _artifact_subset_parent_replay_sql(sql_by_field),
        _artifact_stored_content_proof_sql(
            dataset_alias,
            metadata,
            stored_proof,
        ),
    )
    return "\n        AND ".join(
        fragment.strip() for fragment in fragments
    )


def _artifact_subset_parent_diagnostics_sql(
    sql_by_field: Mapping[str, str],
) -> str:
    """Bind safe per-resource diagnostics to canonical resource counts."""

    metadata = sql_by_field["metadata"]
    proof = sql_by_field["completion_proof"]
    replay = sql_by_field["replay_evidence"]
    diagnostic = f"{metadata} -> 'resource_diagnostics'"
    return f"""
        jsonb_typeof({diagnostic}) = 'object'
        AND CASE WHEN jsonb_typeof({diagnostic}) = 'object'
                 THEN (SELECT count(*) FROM jsonb_object_keys({diagnostic}))
                 ELSE 0 END = 7
        AND jsonb_typeof({replay} -> 'resources') = 'object'
        AND CASE WHEN jsonb_typeof({replay} -> 'resources') = 'object'
                 THEN (SELECT count(*)
                         FROM jsonb_object_keys({replay} -> 'resources'))
                 ELSE 0 END = 7
        AND NOT EXISTS (
            SELECT 1
              FROM jsonb_each({proof} -> 'resources')
                   AS completion_resource(resource_type, resource_proof)
             WHERE {diagnostic} -> resource_type
                       -> 'server_issued_subset_completeness' ->> 'cutoff'
                       IS DISTINCT FROM {proof} ->> 'cutoff'
                OR {diagnostic} -> resource_type
                       -> 'server_issued_subset_completeness' -> 'page_count'
                       IS DISTINCT FROM {proof} -> 'page_count'
                OR {diagnostic} -> resource_type
                       -> 'server_issued_subset_completeness' ->> 'campaign_id'
                       IS DISTINCT FROM {proof} ->> 'campaign_id'
                OR {diagnostic} -> resource_type
                       -> 'server_issued_subset_completeness' -> 'advertised_pre'
                       IS DISTINCT FROM resource_proof -> 'advertised_pre'
                OR {diagnostic} -> resource_type
                       -> 'server_issued_subset_completeness' -> 'advertised_post'
                       IS DISTINCT FROM resource_proof -> 'advertised_post'
                OR {diagnostic} -> resource_type
                       -> 'server_issued_subset_completeness' -> 'returned_unique'
                       IS DISTINCT FROM resource_proof -> 'returned_unique'
                OR {diagnostic} -> resource_type
                       -> 'server_issued_subset_completeness' -> 'deficit'
                       IS DISTINCT FROM resource_proof -> 'deficit'
        )
    """


def _artifact_subset_parent_replay_sql(
    sql_by_field: Mapping[str, str],
) -> str:
    """Bind sealed per-root replay evidence to neutral page geometry."""

    proof = sql_by_field["completion_proof"]
    replay = sql_by_field["replay_evidence"]
    canonical_sha = sql_by_field["canonical_sha256_function"]
    return f"""
        NOT EXISTS (
            SELECT 1
              FROM jsonb_each({proof} -> 'resources')
                   AS completion_resource(resource_type, resource_proof)
             WHERE {replay} -> 'resources' -> resource_type -> 'pages'
                       IS DISTINCT FROM resource_proof -> 'pages'
                OR {replay} -> 'resources' -> resource_type
                       -> 'continuation_shape_sha256'
                       IS DISTINCT FROM resource_proof
                           -> 'continuation_shape_sha256'
                OR jsonb_typeof(
                       {replay} -> 'resources' -> resource_type
                           -> 'continuation_hop_sha256'
                   ) IS DISTINCT FROM 'array'
                OR CASE
                       WHEN jsonb_typeof(
                           {replay} -> 'resources' -> resource_type
                               -> 'continuation_hop_sha256'
                       ) = 'array'
                       THEN jsonb_array_length(
                           {replay} -> 'resources' -> resource_type
                               -> 'continuation_hop_sha256'
                       )
                       ELSE -1
                   END IS DISTINCT FROM
                       (resource_proof ->> 'pages')::integer - 1
                OR {canonical_sha}(
                       {replay} -> 'resources' -> resource_type
                           -> 'continuation_hop_sha256'
                   ) IS DISTINCT FROM
                       {replay} -> 'resources' -> resource_type
                           ->> 'continuation_hop_chain_sha256'
        )
    """


def _artifact_subset_parent_proof_sql(
    dataset_alias: str,
    metadata: str,
    embedded_proof: str,
) -> str:
    """Bind one direct marker/proof pair to its row and embedded twin proof."""

    sql_by_field = {
        "dataset": dataset_alias,
        "metadata": metadata,
        "embedded_proof": embedded_proof,
        "completion_proof": f"{dataset_alias}.completion_proof_json",
        "completion_sha256": f"{dataset_alias}.completion_proof_sha256",
        "canonical_sha256_function": _qt(
            _schema(), "provider_directory_subset_canonical_sha256"
        ),
        "replay_evidence": (
            f"{metadata} -> '{SERVER_ISSUED_SUBSET_REPLAY_EVIDENCE_KEY}'"
        ),
        "replay_sha256": (
            f"{metadata} ->> '{SERVER_ISSUED_SUBSET_REPLAY_EVIDENCE_SHA256_KEY}'"
        ),
        "coverage": f"{metadata} -> '{SERVER_ISSUED_SUBSET_COVERAGE_KEY}'",
    }
    fragments = (
        _artifact_subset_parent_pair_sql(sql_by_field),
        _artifact_subset_parent_coverage_sql(sql_by_field),
        _artifact_subset_parent_diagnostics_sql(sql_by_field),
        _artifact_subset_parent_replay_sql(sql_by_field),
    )
    return "\n        AND ".join(fragment.strip() for fragment in fragments)


def _artifact_subset_source_fixed_sql(
    source_metadata: str,
    completion_proof: str,
) -> str:
    """Bind one allowlisted reviewed-subset profile to its durable proof."""

    return f"""
        {source_metadata} -> 'provider_directory_manual_only'
            = 'true'::jsonb
        AND {source_metadata} -> '{CURRENT_VERSION_CENSUS_CONTRACT_VERSION_FIELD}'
            = '{SERVER_ISSUED_SUBSET_REQUIRED_VERSION}'::jsonb
        AND {source_metadata} ->> '{CURRENT_VERSION_CENSUS_METADATA_STRATEGY_FIELD}'
            = '{SERVER_ISSUED_SUBSET_SEMANTICS}'
        AND {source_metadata} ->> '{CURRENT_VERSION_CENSUS_STRATEGY_VERSION_FIELD}'
            = {completion_proof} ->> 'strategy_version'
        AND {source_metadata} ->> '{CURRENT_VERSION_CENSUS_TRAVERSAL_VERSION_FIELD}'
            = '{SERVER_ISSUED_SUBSET_TRAVERSAL_VERSION}'
        AND {source_metadata} ->> '{CURRENT_VERSION_CENSUS_CANONICALIZATION_VERSION_FIELD}'
            = '{SERVER_ISSUED_SUBSET_CANONICALIZATION_VERSION}'
        AND {source_metadata} -> '{CURRENT_VERSION_CENSUS_COMPLETION_SCOPES_FIELD}'
            = {completion_proof} -> 'completion_scopes'
        AND {source_metadata} ->> '{CURRENT_VERSION_CENSUS_CONTINUATION_STRATEGY_FIELD}'
            = '{SERVER_ISSUED_SUBSET_SMILE_CONTINUATION_STRATEGY}'
        AND {source_metadata} -> '{CURRENT_VERSION_CENSUS_PAGE_COUNT_FIELD}'
            = {completion_proof} -> 'page_count'
        AND {source_metadata} ->> '{PROVIDER_DIRECTORY_VERIFICATION_CAMPAIGN_METADATA_KEY}'
            = {completion_proof} ->> 'campaign_id'
    """


def _artifact_subset_source_resources_sql(
    source_metadata: str,
    allowed_resources_sql: str,
) -> str:
    """Return exact reviewed resource-set predicates."""

    return f"""
        AND jsonb_typeof(
                {source_metadata}
                    -> 'provider_directory_server_issued_subset_resources'
            ) = 'array'
        AND jsonb_array_length(
                {source_metadata}
                    -> 'provider_directory_server_issued_subset_resources'
            ) = 7
        AND NOT EXISTS (
            SELECT 1
              FROM jsonb_array_elements_text(
                       {source_metadata}
                         -> 'provider_directory_server_issued_subset_resources'
                   ) AS subset_resource(resource_type)
             WHERE subset_resource.resource_type
                   <> ALL(ARRAY[{allowed_resources_sql}]::text[])
        )
        AND (
            SELECT count(DISTINCT subset_resource.resource_type)
              FROM jsonb_array_elements_text(
                       {source_metadata}
                         -> 'provider_directory_server_issued_subset_resources'
                   ) AS subset_resource(resource_type)
        ) = 7
    """


def _artifact_subset_source_urls_sql(
    source_metadata: str,
    allowed_resources_sql: str,
) -> str:
    """Return exact reviewed start-URL key predicates."""

    return f"""
        AND jsonb_typeof(
                {source_metadata} -> '{CURRENT_VERSION_CENSUS_START_URLS_FIELD}'
            ) = 'object'
        AND CASE
                WHEN jsonb_typeof(
                    {source_metadata}
                        -> '{CURRENT_VERSION_CENSUS_START_URLS_FIELD}'
                ) = 'object'
                THEN (
                    SELECT count(*)
                      FROM jsonb_object_keys(
                          {source_metadata}
                              -> '{CURRENT_VERSION_CENSUS_START_URLS_FIELD}'
                      )
                )
                ELSE 0
            END = 7
        AND {source_metadata} -> '{CURRENT_VERSION_CENSUS_START_URLS_FIELD}'
            ?& ARRAY[{allowed_resources_sql}]::text[]
    """


def _artifact_subset_source_identity_sql(
    source_metadata: str,
    dataset_alias: str = "dataset",
) -> str:
    """Bind the reviewed source's fixed v3 identity to its parent proof."""

    allowed_resources_sql = ", ".join(
        f"'{resource_type}'"
        for resource_type in SERVER_ISSUED_SUBSET_RESOURCE_TYPES
    )
    fragments = (
        _artifact_subset_source_fixed_sql(
            source_metadata,
            f"{dataset_alias}.completion_proof_json",
        ),
        _artifact_subset_source_resources_sql(
            source_metadata, allowed_resources_sql
        ),
        _artifact_subset_source_urls_sql(
            source_metadata, allowed_resources_sql
        ),
    )
    return "\n".join(fragment.rstrip() for fragment in fragments)


def _artifact_source_id_list_sql(
    source_ids: str,
    safe_source_ids: str,
) -> str:
    """Require a nonempty, duplicate-free source-id array."""

    return f"""
        jsonb_typeof({source_ids}) = 'array'
        AND jsonb_array_length({safe_source_ids}) > 0
        AND jsonb_array_length({safe_source_ids}) = (
            SELECT count(DISTINCT attached_source.source_id)
              FROM jsonb_array_elements_text({safe_source_ids})
                   AS attached_source(source_id)
        )
    """


def _artifact_source_policy_sql(
    source_metadata: str,
    metadata: str,
    reviewed_root_count: int | None,
    require_policy_absent: bool,
) -> str:
    if reviewed_root_count is not None and require_policy_absent:
        raise ValueError("provider_directory_artifact_root_policy_ambiguous")
    if reviewed_root_count is not None:
        return f"""
                   AND {source_metadata} -> '{REVIEWED_ROOT_POLICY_METADATA_KEY}'
                         = {metadata} -> '{REVIEWED_ROOT_POLICY_METADATA_KEY}'
        """
    if require_policy_absent:
        return f"""
                   AND NOT ({source_metadata}
                         ? '{REVIEWED_ROOT_POLICY_METADATA_KEY}')
        """
    return ""


def _artifact_source_contract_body_sql(
    source_ref: str,
    metadata: str,
    required_status: str,
    safe_source_ids: str,
    source_id_list_sql: str,
    reviewed_root_policy_sql: str,
    subset_source_identity_sql: str,
) -> str:
    return f"""
        {source_id_list_sql}
        AND NOT EXISTS (
            SELECT 1
              FROM jsonb_array_elements_text({safe_source_ids})
                   AS attached_source(source_id)
             WHERE NOT EXISTS (
                SELECT 1
                  FROM {source_ref} AS current_source
                 WHERE current_source.source_id = attached_source.source_id
                   AND current_source.metadata_json::jsonb
                         ->> 'provider_directory_candidate_status'
                         = '{required_status}'
                   AND current_source.metadata_json::jsonb
                         ->> '{PROVIDER_DIRECTORY_VERIFICATION_CAMPAIGN_METADATA_KEY}'
                         = {metadata}
                             ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}'
                   AND current_source.metadata_json::jsonb
                         ->> '{PROVIDER_DIRECTORY_CONFIGURED_ENDPOINT_METADATA_KEY}'
                         = dataset.endpoint_id
                   {reviewed_root_policy_sql}
                   AND {subset_source_identity_sql}
             )
        )
        AND NOT EXISTS (
            SELECT 1
             FROM {source_ref} AS current_source
             WHERE (
                    current_source.endpoint_id = dataset.endpoint_id
                    OR current_source.metadata_json::jsonb
                         ->> '{PROVIDER_DIRECTORY_CONFIGURED_ENDPOINT_METADATA_KEY}'
                         = dataset.endpoint_id
               )
               AND NOT {safe_source_ids}
                       @> jsonb_build_array(current_source.source_id)
        )
    """


def _artifact_source_contract_sql(
    source_ref: str,
    metadata: str,
    required_status: str,
    *,
    require_subset_identity: bool = False,
    reviewed_root_count: int | None = None,
    require_reviewed_root_policy_absent: bool = False,
) -> str:
    """Require every attached source to retain its reviewed status and scope."""

    source_ids = f"COALESCE({metadata} -> 'source_ids', 'null'::jsonb)"
    safe_source_ids = (
        f"CASE WHEN jsonb_typeof({source_ids}) = 'array' "
        f"THEN {source_ids} ELSE '[]'::jsonb END"
    )
    subset_source_identity_sql = (
        _artifact_subset_source_identity_sql(
            "current_source.metadata_json::jsonb"
        )
        if require_subset_identity
        else "true"
    )
    source_metadata = "current_source.metadata_json::jsonb"
    reviewed_root_policy_sql = _artifact_source_policy_sql(
        source_metadata,
        metadata,
        reviewed_root_count,
        require_reviewed_root_policy_absent,
    )
    source_id_list_sql = _artifact_source_id_list_sql(
        source_ids, safe_source_ids
    )
    return _artifact_source_contract_body_sql(
        source_ref,
        metadata,
        required_status,
        safe_source_ids,
        source_id_list_sql,
        reviewed_root_policy_sql,
        subset_source_identity_sql,
    )


def _artifact_reviewed_root_policy_sql(
    metadata: str,
    required_root_count: int,
) -> str:
    """Bind a dataset to one exact closed reviewed-root policy."""

    policy = ReviewedRootPolicy(required_root_count)
    policy_version = str(policy.document()["policy_version"]).replace(
        "'", "''"
    )
    return (
        f"{metadata} -> '{REVIEWED_ROOT_POLICY_METADATA_KEY}' "
        "= pg_catalog.jsonb_build_object("
        f"'policy_version', '{policy_version}', "
        f"'required_root_count', {policy.required_root_count})"
    )


def _artifact_ordinary_proof_sql(metadata: str) -> str:
    completion_proof = f"{metadata} -> 'completion_proof_v1'"
    return f"""
        COALESCE(
            {metadata} ->> 'requires_twin_root_verification', 'false'
        ) = 'false'
        AND NULLIF(
            {metadata} ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}', ''
        ) IS NOT NULL
        AND NULLIF(
            {metadata} ->> '{TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY}', ''
        ) IS NOT NULL
        AND {metadata} ->> '{TWIN_ROOT_VERIFICATION_ROLE_KEY}' IS NULL
        AND {metadata} ->> '{TWIN_ROOT_VERIFICATION_BASELINE_DATASET_KEY}'
            IS NULL
        AND {metadata} ->> 'dataset_hash' = dataset.dataset_hash
        AND {metadata} ->> 'resource_count' = dataset.resource_count::text
        AND {completion_proof} ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}'
            = {metadata} ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}'
        AND {completion_proof} ->> '{TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY}'
            = {metadata} ->> '{TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY}'
    """


def _artifact_matched_anchor_sql(dataset_ref: str, metadata: str) -> str:
    anchor_metadata = "matched_anchor.publication_metadata_json::jsonb"
    anchor_verification = (
        f"{anchor_metadata} -> '{TWIN_ROOT_VERIFICATION_METADATA_KEY}'"
    )
    anchor_proof = f"{anchor_verification} -> 'proof'"
    matched_proof_sql = _artifact_matched_proof_sql(
        anchor_metadata,
        anchor_verification,
        anchor_proof,
        "matched_anchor",
    )
    baseline_proof_sql = _artifact_baseline_proof_sql(
        dataset_ref,
        anchor_metadata,
        anchor_verification,
        candidate_alias="matched_anchor",
        baseline_alias="anchor_baseline",
    )
    return f"""
        EXISTS (
            SELECT 1
              FROM {dataset_ref} AS matched_anchor
             WHERE matched_anchor.dataset_id <> dataset.dataset_id
               AND matched_anchor.endpoint_id = dataset.endpoint_id
               AND matched_anchor.status IN (
                    '{ENDPOINT_DATASET_VALIDATED}',
                    '{ENDPOINT_DATASET_PUBLISHED}',
                    '{ENDPOINT_DATASET_SUPERSEDED}'
               )
               AND COALESCE(
                    {anchor_metadata} ->> 'requires_twin_root_verification',
                    'false'
               ) = 'true'
               AND {anchor_metadata} ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}'
                    = {metadata} ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}'
               AND {anchor_metadata} ->> '{TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY}'
                    = {metadata} ->> '{TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY}'
               AND {anchor_metadata} ->> '{TWIN_ROOT_VERIFICATION_ROLE_KEY}'
                    = '{TWIN_ROOT_VERIFICATION_CANDIDATE_ROLE}'
               AND {anchor_metadata} -> 'source_ids'
                    = {metadata} -> 'source_ids'
               AND {matched_proof_sql}
               AND {baseline_proof_sql}
        )
    """


def _artifact_completion_marker_sql(
    candidate_alias: str,
    baseline_alias: str,
    completion_proof_required_version: int | None,
) -> str:
    """Return legacy-null or v3-required completion marker predicates."""

    if (
        completion_proof_required_version
        == SERVER_ISSUED_SUBSET_REQUIRED_VERSION
    ):
        return f"""
               AND {candidate_alias}.completion_proof_required_version =
                   {SERVER_ISSUED_SUBSET_REQUIRED_VERSION}
               AND {baseline_alias}.completion_proof_required_version =
                   {SERVER_ISSUED_SUBSET_REQUIRED_VERSION}
        """
    return f"""
               AND {candidate_alias}.completion_proof_required_version IS NULL
               AND {candidate_alias}.completion_proof_json IS NULL
               AND {candidate_alias}.completion_proof_sha256 IS NULL
               AND {baseline_alias}.completion_proof_required_version IS NULL
               AND {baseline_alias}.completion_proof_json IS NULL
               AND {baseline_alias}.completion_proof_sha256 IS NULL
    """


def _artifact_baseline_policy_sql(
    baseline_metadata: str,
    reviewed_root_count: int | None,
    require_policy_absent: bool,
) -> str:
    if reviewed_root_count is not None and require_policy_absent:
        raise ValueError("provider_directory_artifact_root_policy_ambiguous")
    if reviewed_root_count is not None:
        return _artifact_reviewed_root_policy_sql(
            baseline_metadata,
            reviewed_root_count,
        )
    if require_policy_absent:
        return (
            f"NOT ({baseline_metadata} ? "
            f"'{REVIEWED_ROOT_POLICY_METADATA_KEY}')"
        )
    return "true"


@dataclass(frozen=True, slots=True)
class _ArtifactBaselineProofFragments:
    dataset_ref: str
    metadata: str
    verification: str
    candidate_alias: str
    baseline_alias: str
    baseline_metadata: str
    completion_marker_sql: str
    baseline_policy_sql: str
    baseline_contract_sql: str
    hash_identity_sql: str
    exact_proof_sql: str


def _artifact_baseline_exists_sql(
    fragments: _ArtifactBaselineProofFragments,
) -> str:
    return f"""
        EXISTS (
            SELECT 1
              FROM {fragments.dataset_ref} AS {fragments.baseline_alias}
             WHERE {fragments.baseline_alias}.dataset_id =
                   {fragments.metadata}
                     ->> '{TWIN_ROOT_VERIFICATION_BASELINE_DATASET_KEY}'
               AND {fragments.baseline_alias}.endpoint_id =
                   {fragments.candidate_alias}.endpoint_id
               AND {fragments.baseline_alias}.is_current = false
               AND {fragments.baseline_alias}.status =
                   '{ENDPOINT_DATASET_VERIFICATION_BASELINE}'
               {fragments.completion_marker_sql}
               AND {fragments.baseline_policy_sql}
               AND {fragments.baseline_contract_sql}
               AND {fragments.hash_identity_sql}
               AND {fragments.baseline_metadata}
                     ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}'
                     = {fragments.metadata}
                         ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}'
               AND {fragments.baseline_metadata}
                     ->> '{TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY}'
                     = {fragments.metadata}
                         ->> '{TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY}'
               AND {fragments.verification}
                     ->> 'baseline_acquisition_root_run_id'
                     = {fragments.baseline_alias}.acquisition_root_run_id
               AND {fragments.exact_proof_sql}
        )
    """


def _artifact_baseline_hash_identity_sql(
    metadata: str,
    baseline_metadata: str,
) -> str:
    """Require the baseline and candidate to share one hash identity."""

    candidate_hash_contract = (
        _artifact_normalized_resource_hash_contract_sql(metadata)
    )
    baseline_hash_contract = (
        _artifact_normalized_resource_hash_contract_sql(baseline_metadata)
    )
    return f"""
        ({baseline_hash_contract}) = ({candidate_hash_contract})
        AND ({baseline_metadata}
             -> '{PROVIDER_DIRECTORY_PROOF_RESOURCE_SCOPE_METADATA_KEY}')
            IS NOT DISTINCT FROM
            ({metadata}
             -> '{PROVIDER_DIRECTORY_PROOF_RESOURCE_SCOPE_METADATA_KEY}')
        AND ({baseline_metadata}
             -> '{SEMANTIC_PROJECTION_AS_OF_METADATA_KEY}')
            IS NOT DISTINCT FROM
            ({metadata} -> '{SEMANTIC_PROJECTION_AS_OF_METADATA_KEY}')
    """


def _artifact_baseline_proof_fragments(
    dataset_ref: str,
    metadata: str,
    verification: str,
    candidate_alias: str,
    baseline_alias: str,
    completion_proof_required_version: int | None,
    reviewed_root_count: int | None,
    require_reviewed_root_policy_absent: bool,
) -> _ArtifactBaselineProofFragments:
    """Build the independently testable baseline-proof SQL fragments."""

    baseline_metadata = f"{baseline_alias}.publication_metadata_json::jsonb"
    baseline_verification = (
        f"{baseline_metadata} -> '{TWIN_ROOT_VERIFICATION_METADATA_KEY}'"
    )
    candidate_proof = f"{verification} -> 'proof'"
    baseline_proof = f"{baseline_verification} -> 'proof'"
    return _ArtifactBaselineProofFragments(
        dataset_ref=dataset_ref,
        metadata=metadata,
        verification=verification,
        candidate_alias=candidate_alias,
        baseline_alias=baseline_alias,
        baseline_metadata=baseline_metadata,
        completion_marker_sql=_artifact_completion_marker_sql(
            candidate_alias,
            baseline_alias,
            completion_proof_required_version,
        ),
        baseline_policy_sql=_artifact_baseline_policy_sql(
            baseline_metadata,
            reviewed_root_count,
            require_reviewed_root_policy_absent,
        ),
        baseline_contract_sql=_artifact_baseline_contract_sql(
            baseline_alias,
            baseline_metadata,
            baseline_verification,
            baseline_proof,
            completion_proof_required_version=(
                completion_proof_required_version
            ),
        ),
        hash_identity_sql=_artifact_baseline_hash_identity_sql(
            metadata,
            baseline_metadata,
        ),
        exact_proof_sql=_artifact_twin_proof_equality_sql(
            candidate_proof,
            baseline_proof,
            include_subset_completion=(
                completion_proof_required_version
                == SERVER_ISSUED_SUBSET_REQUIRED_VERSION
            ),
        ),
    )


def _artifact_baseline_proof_sql(
    dataset_ref: str,
    metadata: str,
    verification: str,
    *,
    candidate_alias: str = "dataset",
    baseline_alias: str = "verification_baseline",
    completion_proof_required_version: int | None = None,
    reviewed_root_count: int | None = None,
    require_reviewed_root_policy_absent: bool = False,
) -> str:
    """Require an immutable baseline whose full proof matches the candidate."""
    return _artifact_baseline_exists_sql(
        _artifact_baseline_proof_fragments(
            dataset_ref,
            metadata,
            verification,
            candidate_alias,
            baseline_alias,
            completion_proof_required_version,
            reviewed_root_count,
            require_reviewed_root_policy_absent,
        )
    )


def _artifact_baseline_contract_sql(
    baseline_alias: str,
    baseline_metadata: str,
    baseline_verification: str,
    baseline_proof: str,
    *,
    completion_proof_required_version: int | None = None,
) -> str:
    """Bind baseline proof fields to the immutable baseline dataset row."""
    subset_parent_proof_sql = (
        _artifact_subset_parent_proof_sql(
            baseline_alias,
            baseline_metadata,
            baseline_proof,
        )
        if completion_proof_required_version
        == SERVER_ISSUED_SUBSET_REQUIRED_VERSION
        else "true"
    )
    return f"""
        {baseline_metadata} ->> '{TWIN_ROOT_VERIFICATION_ROLE_KEY}'
            = '{TWIN_ROOT_BASELINE_CANDIDATE_ROLE}'
        AND {baseline_verification} ->> 'role' = 'baseline'
        AND {baseline_verification} ->> 'admission_role'
            = '{TWIN_ROOT_BASELINE_CANDIDATE_ROLE}'
        AND {baseline_verification} ->> 'result' = 'baseline_recorded'
        AND {baseline_proof} ->> 'endpoint_id' = {baseline_alias}.endpoint_id
        AND {baseline_proof} ->> 'acquisition_root_run_id'
            = {baseline_alias}.acquisition_root_run_id
        AND {baseline_proof} -> 'source_ids'
            = {baseline_metadata} -> 'source_ids'
        AND {baseline_proof} -> 'selected_resources'
            = {baseline_metadata} -> 'selected_resources'
        AND {baseline_proof} -> 'expected_resources'
            = {baseline_metadata} -> 'expected_resources'
        AND {baseline_proof} ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}'
            = {baseline_metadata} ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}'
        AND {baseline_proof} ->> '{TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY}'
            = {baseline_metadata} ->> '{TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY}'
        AND {baseline_proof} ->> 'dataset_hash' = {baseline_alias}.dataset_hash
        AND {baseline_proof} ->> 'resource_count'
            = {baseline_alias}.resource_count::text
        AND {_artifact_proof_hash_identity_sql(
            baseline_metadata,
            baseline_proof,
        )}
        AND {subset_parent_proof_sql}
    """


def _artifact_subset_twin_branch_sql(
    dataset_ref: str,
    source_ref: str,
    metadata: str,
    verification: str,
    proof: str,
    reviewed_root_count: int | None,
) -> str:
    is_legacy = reviewed_root_count is None
    baseline_proof_sql = _artifact_baseline_proof_sql(
        dataset_ref,
        metadata,
        verification,
        completion_proof_required_version=SERVER_ISSUED_SUBSET_REQUIRED_VERSION,
        reviewed_root_count=reviewed_root_count,
        require_reviewed_root_policy_absent=is_legacy,
    )
    matched_proof_sql = f"""
        {_artifact_matched_proof_sql(metadata, verification, proof)}
        AND {_artifact_subset_parent_proof_sql("dataset", metadata, proof)}
    """
    policy_sql = (
        f"NOT ({metadata} ? '{REVIEWED_ROOT_POLICY_METADATA_KEY}')"
        if is_legacy
        else _artifact_reviewed_root_policy_sql(metadata, reviewed_root_count)
    )
    required_status = (
        PROVIDER_DIRECTORY_SUBSET_TWIN_ROOT_VERIFIED
        if is_legacy
        else PROVIDER_DIRECTORY_ROOT_POLICY_VERIFIED
    )
    return f"""
        {policy_sql}
        AND {_artifact_source_contract_sql(
            source_ref,
            metadata,
            required_status,
            require_subset_identity=True,
            reviewed_root_count=reviewed_root_count,
            require_reviewed_root_policy_absent=is_legacy,
        )}
        AND {matched_proof_sql}
        AND {baseline_proof_sql}
    """


def _artifact_subset_single_branch_sql(
    source_ref: str,
    metadata: str,
) -> str:
    content_proof = (
        f"{metadata} -> '{PROVIDER_DIRECTORY_CONTENT_PROOF_METADATA_KEY}'"
    )
    coverage = f"{metadata} -> '{SERVER_ISSUED_SUBSET_COVERAGE_KEY}'"
    return f"""
        {_artifact_reviewed_root_policy_sql(metadata, 1)}
        AND {metadata} -> 'requires_twin_root_verification' = 'false'::jsonb
        AND NOT ({metadata} ? '{TWIN_ROOT_VERIFICATION_ROLE_KEY}')
        AND NOT ({metadata} ? '{TWIN_ROOT_VERIFICATION_BASELINE_DATASET_KEY}')
        AND NOT ({metadata} ? '{TWIN_ROOT_VERIFICATION_METADATA_KEY}')
        AND {_artifact_source_contract_sql(
            source_ref,
            metadata,
            PROVIDER_DIRECTORY_ROOT_POLICY_VERIFIED,
            require_subset_identity=True,
            reviewed_root_count=1,
        )}
        AND {_artifact_subset_single_root_proof_sql(
            "dataset", metadata, content_proof
        )}
        AND {coverage} ->> 'twin_state' = 'not_required'
        AND NOT EXISTS (
            SELECT 1
              FROM jsonb_each({coverage} -> 'resources')
                   AS covered_resource(resource_type, resource_coverage)
             WHERE resource_coverage ->> 'twin_state' <> 'not_required'
                OR resource_coverage ->> 'twin_state' IS NULL
        )
    """


def _artifact_subset_candidate_eligibility_sql(
    dataset_ref: str,
    source_ref: str,
    metadata: str,
    verification: str,
    proof: str,
) -> str:
    """Return exact legacy-twin and policy-bound v3 eligibility branches."""

    legacy_twin_sql = _artifact_subset_twin_branch_sql(
        dataset_ref, source_ref, metadata, verification, proof, None
    )
    policy_twin_sql = _artifact_subset_twin_branch_sql(
        dataset_ref, source_ref, metadata, verification, proof, 2
    )
    policy_single_sql = _artifact_subset_single_branch_sql(source_ref, metadata)
    return f"""
        (({legacy_twin_sql}) OR ({policy_twin_sql}) OR ({policy_single_sql}))
    """


def _artifact_reviewed_candidate_eligibility_sql(
    dataset_ref: str,
    source_ref: str,
    *,
    metadata: str = "dataset.publication_metadata_json::jsonb",
) -> str:
    """Return legacy and v3 twin-proof eligibility alternatives."""

    verification = f"{metadata} -> '{TWIN_ROOT_VERIFICATION_METADATA_KEY}'"
    proof = f"{verification} -> 'proof'"
    matched_proof_sql = _artifact_matched_proof_sql(
        metadata, verification, proof
    )
    baseline_proof_sql = _artifact_baseline_proof_sql(
        dataset_ref, metadata, verification
    )
    subset_eligibility_sql = _artifact_subset_candidate_eligibility_sql(
        dataset_ref, source_ref, metadata, verification, proof
    )
    return f"""
        (
            (
                dataset.completion_proof_required_version IS NULL
                AND dataset.completion_proof_json IS NULL
                AND dataset.completion_proof_sha256 IS NULL
                AND {_artifact_profile_absence_sql(source_ref, metadata)}
            )
            OR (
                dataset.completion_proof_required_version IS NULL
                AND dataset.completion_proof_json IS NULL
                AND dataset.completion_proof_sha256 IS NULL
                AND NOT ({metadata} ? '{REVIEWED_ROOT_POLICY_METADATA_KEY}')
                AND
                {_artifact_source_contract_sql(
                    source_ref,
                    metadata,
                    PROVIDER_DIRECTORY_TWIN_ROOT_VERIFIED,
                    require_reviewed_root_policy_absent=True,
                )}
                AND (
                    ({matched_proof_sql} AND {baseline_proof_sql})
                    OR (
                        {_artifact_ordinary_proof_sql(metadata)}
                        AND {_artifact_matched_anchor_sql(dataset_ref, metadata)}
                    )
                )
            )
            OR (
                {subset_eligibility_sql}
            )
        )
    """


def _artifact_candidate_eligibility_metadata_columns() -> str:
    """Return the compact JSON record fields used by candidate admission."""
    metadata_key = TWIN_ROOT_VERIFICATION_METADATA_KEY
    return f"""
        requires_twin_root_verification jsonb,
        {TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY} text,
        {TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY} text,
        {TWIN_ROOT_VERIFICATION_ROLE_KEY} text,
        {TWIN_ROOT_VERIFICATION_BASELINE_DATASET_KEY} text,
        {metadata_key} jsonb,
        {REVIEWED_ROOT_POLICY_METADATA_KEY} jsonb,
        {PROVIDER_DIRECTORY_CONTENT_PROOF_METADATA_KEY} jsonb,
        source_ids jsonb,
        dataset_hash text,
        resource_count text,
        completion_proof_v1 jsonb,
        resource_diagnostics jsonb,
        {SERVER_ISSUED_SUBSET_REPLAY_EVIDENCE_KEY} jsonb,
        {SERVER_ISSUED_SUBSET_REPLAY_EVIDENCE_SHA256_KEY} text,
        {SERVER_ISSUED_SUBSET_COVERAGE_KEY} jsonb,
        selected_resources jsonb,
        expected_resources jsonb
    """


def _artifact_optional_metadata_sql(
    metadata_key: str,
    *,
    materialize_null_record: bool = False,
) -> str:
    null_record_sql = (
        f"WHEN candidate.full_metadata_jsonb IS NULL THEN "
        f"jsonb_build_object('{metadata_key}', NULL::jsonb)"
        if materialize_null_record
        else ""
    )
    return f"""
        CASE
            {null_record_sql}
            WHEN candidate.full_metadata_jsonb ? '{metadata_key}' THEN
                jsonb_build_object(
                    '{metadata_key}',
                    candidate.full_metadata_jsonb -> '{metadata_key}'
                )
            ELSE '{{}}'::jsonb
        END
    """


def _artifact_optional_metadata_fields_sql() -> str:
    return " || ".join(
        (
            _artifact_optional_metadata_sql(TWIN_ROOT_VERIFICATION_ROLE_KEY),
            _artifact_optional_metadata_sql(
                TWIN_ROOT_VERIFICATION_BASELINE_DATASET_KEY
            ),
            _artifact_optional_metadata_sql(
                TWIN_ROOT_VERIFICATION_METADATA_KEY,
                materialize_null_record=True,
            ),
            _artifact_optional_metadata_sql(REVIEWED_ROOT_POLICY_METADATA_KEY),
            _artifact_optional_metadata_sql(
                PROVIDER_DIRECTORY_CONTENT_PROOF_METADATA_KEY
            ),
            _artifact_optional_metadata_sql(
                RESOURCE_HASH_CONTRACT_METADATA_KEY
            ),
            _artifact_optional_metadata_sql(
                PROVIDER_DIRECTORY_PROOF_RESOURCE_SCOPE_METADATA_KEY
            ),
            _artifact_optional_metadata_sql(
                SEMANTIC_PROJECTION_AS_OF_METADATA_KEY
            ),
        )
    )


def _artifact_candidate_eligibility_ctes(dataset_ref: str) -> str:
    """Parse large candidate proofs once and retain only eligibility fields."""
    metadata_key = TWIN_ROOT_VERIFICATION_METADATA_KEY
    metadata_columns = _artifact_candidate_eligibility_metadata_columns()
    optional_metadata_sql = _artifact_optional_metadata_fields_sql()
    return f"""
        artifact_candidate_json AS MATERIALIZED (
        SELECT dataset.dataset_id,
               dataset.endpoint_id,
               dataset.acquisition_root_run_id,
               dataset.dataset_hash,
               dataset.resource_count,
               dataset.completion_proof_required_version,
               dataset.completion_proof_json,
               dataset.completion_proof_sha256,
               dataset.publication_metadata_json::jsonb
                   AS full_metadata_jsonb
          FROM {dataset_ref} AS dataset
         WHERE dataset.endpoint_id = ANY(CAST(:endpoint_ids AS varchar[]))
           AND dataset.is_current = false
           AND dataset.status = :validated_status
           AND dataset.superseded_at IS NULL
        ), artifact_candidate_metadata AS MATERIALIZED (
        SELECT candidate.dataset_id,
               candidate.endpoint_id,
               candidate.acquisition_root_run_id,
               candidate.dataset_hash,
               candidate.resource_count,
               candidate.completion_proof_required_version,
               candidate.completion_proof_json,
               candidate.completion_proof_sha256,
               (
                   to_jsonb(metadata_fields)
                       - '{TWIN_ROOT_VERIFICATION_ROLE_KEY}'
                       - '{TWIN_ROOT_VERIFICATION_BASELINE_DATASET_KEY}'
                       - '{metadata_key}'
                       - '{REVIEWED_ROOT_POLICY_METADATA_KEY}'
                       - '{PROVIDER_DIRECTORY_CONTENT_PROOF_METADATA_KEY}'
               ) || {optional_metadata_sql} AS eligibility_metadata_jsonb
          FROM artifact_candidate_json AS candidate
          CROSS JOIN LATERAL jsonb_to_record(
               CASE
                   WHEN jsonb_typeof(candidate.full_metadata_jsonb) = 'object'
                   THEN candidate.full_metadata_jsonb
                   ELSE '{{}}'::jsonb
               END
          ) AS metadata_fields({metadata_columns})
        )
    """


def _artifact_dataset_options_cte(
    dataset_ref: str,
    source_ref: str | None = None,
    *,
    scope_endpoint_ids: bool = False,
) -> str:
    validated_candidate_gate = (
        _artifact_reviewed_candidate_eligibility_sql(dataset_ref, source_ref)
        if source_ref
        else "true"
    )
    endpoint_scope = (
        "dataset.endpoint_id = ANY(CAST(:endpoint_ids AS varchar[]))\n"
        "           AND "
        if scope_endpoint_ids
        else ""
    )
    return f"""
        dataset_options AS MATERIALIZED (
        SELECT dataset.*,
               count(*) FILTER (
                   WHERE dataset.is_current = true
                     AND dataset.status = :published_status
                     AND dataset.superseded_at IS NULL
               ) OVER (PARTITION BY dataset.endpoint_id)
                   AS current_dataset_count,
               max(dataset.dataset_id) FILTER (
                   WHERE dataset.is_current = true
                     AND dataset.status = :published_status
                     AND dataset.superseded_at IS NULL
               ) OVER (PARTITION BY dataset.endpoint_id)
                   AS current_dataset_id,
               count(*) FILTER (
                   WHERE dataset.is_current = false
                     AND dataset.status = :validated_status
                     AND dataset.superseded_at IS NULL
               ) OVER (PARTITION BY dataset.endpoint_id)
                   AS validated_candidate_count
          FROM {dataset_ref} AS dataset
         WHERE {endpoint_scope}(
            (
                    dataset.is_current = true
                AND dataset.status = :published_status
                AND dataset.superseded_at IS NULL
            ) OR (
                    dataset.is_current = false
                AND dataset.status = :validated_status
                AND dataset.superseded_at IS NULL
                AND {validated_candidate_gate}
            )
         )
        )
    """


def _artifact_dataset_ranking_cte() -> str:
    return """
        ranked_datasets AS MATERIALIZED (
        SELECT dataset_options.*,
               row_number() OVER (
                   PARTITION BY dataset_options.endpoint_id
                   ORDER BY
                       CASE
                           WHEN CAST(:select_validated_candidates AS boolean)
                            AND dataset_options.is_current = false
                            AND dataset_options.status = :validated_status
                           THEN 0
                           ELSE 1
                       END,
                       dataset_options.dataset_id
               ) AS selection_rank
          FROM dataset_options
         WHERE (
                dataset_options.is_current = true
            AND dataset_options.status = :published_status
            AND dataset_options.superseded_at IS NULL
         ) OR (
                CAST(:select_validated_candidates AS boolean)
            AND dataset_options.is_current = false
            AND dataset_options.status = :validated_status
            AND dataset_options.superseded_at IS NULL
         )
        )
    """


def _artifact_dataset_projection_sql() -> str:
    return """
        SELECT selected.source_id,
               selected.endpoint_id,
               selected.serving_endpoint_id,
               selected.reconcile_source_alias_on_cutover,
               selected.source_record_json,
               dataset.dataset_id,
               COALESCE(
                   dataset.acquisition_root_run_id,
                   dataset.import_run_id
               ) AS evidence_run_id,
               COALESCE(
                   dataset.publication_metadata_json::jsonb -> 'selected_resources',
                   '[]'::jsonb
               ) AS selected_resources,
               dataset.publication_metadata_json::jsonb -> 'expected_resources'
                   AS recorded_expected_resources,
               dataset.status,
               dataset.is_current,
               dataset.previous_dataset_id,
               dataset.dataset_hash,
               dataset.resource_count,
               dataset.validated_at,
               dataset.completion_proof_required_version,
               dataset.completion_proof_json,
               dataset.completion_proof_sha256,
               dataset.publication_metadata_json,
               dataset.current_dataset_count,
               dataset.current_dataset_id,
               dataset.validated_candidate_count,
               (
                   CAST(:select_validated_candidates AS boolean)
                   AND dataset.is_current = false
                   AND dataset.status = :validated_status
               ) AS promote_on_cutover
          FROM selected_sources AS selected
          LEFT JOIN ranked_datasets AS dataset
            ON dataset.endpoint_id = selected.endpoint_id
           AND dataset.selection_rank = 1
         ORDER BY selected.source_id, dataset.dataset_id;
    """


def _artifact_dataset_explicit_selection_sql(
    dataset_ref: str,
    source_ref: str,
) -> str:
    """Select only caller-requested aliases while retaining endpoint datasets."""
    return f"""
        selected_sources AS MATERIALIZED (
            SELECT source.source_id,
                   COALESCE(
                       candidate.endpoint_id,
                       published_alias.endpoint_id,
                       source.endpoint_id
                   )
                       AS endpoint_id,
                   source.endpoint_id AS serving_endpoint_id,
                   (
                       candidate.endpoint_id IS NULL
                       AND published_alias.endpoint_id IS NOT NULL
                   ) AS reconcile_source_alias_on_cutover,
                   to_jsonb(source) AS source_record_json
              FROM {source_ref} AS source
              {_artifact_validated_candidate_alias_join_sql()}
              {_artifact_published_alias_reconciliation_join_sql(
                  dataset_ref,
                  source_ref,
              )}
             WHERE source.source_id = ANY(CAST(:source_ids AS varchar[]))
        )
    """


def _artifact_dataset_all_source_selection_sql(
    dataset_ref: str,
    source_ref: str,
) -> str:
    return f"""
        selected_endpoints AS MATERIALIZED (
            SELECT dataset.endpoint_id
              FROM ranked_datasets AS dataset
             WHERE dataset.selection_rank = 1
        ), selected_sources AS MATERIALIZED (
            SELECT source.source_id,
                   COALESCE(
                       candidate.endpoint_id,
                       published_alias.endpoint_id,
                       source.endpoint_id
                   )
                       AS endpoint_id,
                   source.endpoint_id AS serving_endpoint_id,
                   (
                       candidate.endpoint_id IS NULL
                       AND published_alias.endpoint_id IS NOT NULL
                   ) AS reconcile_source_alias_on_cutover,
                   to_jsonb(source) AS source_record_json
              FROM {source_ref} AS source
              {_artifact_validated_candidate_alias_join_sql()}
              {_artifact_published_alias_reconciliation_join_sql(
                  dataset_ref,
                  source_ref,
              )}
             WHERE source.endpoint_id IN (
                       SELECT endpoint_id FROM selected_endpoints
                   )
                OR candidate.endpoint_id IS NOT NULL
                OR published_alias.endpoint_id IS NOT NULL
        )
    """


def _artifact_validated_candidate_alias_join_sql() -> str:
    """Match a validated replacement without moving the serving alias."""
    return """
        LEFT JOIN dataset_options AS candidate
          ON CAST(:select_validated_candidates AS boolean)
         AND candidate.is_current = false
         AND candidate.status = :validated_status
         AND candidate.superseded_at IS NULL
         AND COALESCE(
                 candidate.publication_metadata_json::jsonb -> 'source_ids',
                 '[]'::jsonb
             ) @> jsonb_build_array(source.source_id)
    """


def _artifact_published_alias_reconciliation_join_sql(
    dataset_ref: str,
    source_ref: str,
) -> str:
    """Match a proven publication only when its serving alias is orphaned."""

    reviewed_dataset_gate = _artifact_reviewed_candidate_eligibility_sql(
        dataset_ref,
        source_ref,
    )
    return f"""
        LEFT JOIN (
            SELECT dataset.endpoint_id
              FROM {dataset_ref} AS dataset
             WHERE dataset.is_current = true
               AND dataset.status = :published_status
               AND dataset.published_at IS NOT NULL
               AND dataset.superseded_at IS NULL
               AND {reviewed_dataset_gate}
        ) AS published_alias
          ON published_alias.endpoint_id = NULLIF(
                 source.metadata_json::jsonb
                     ->> '{PROVIDER_DIRECTORY_CONFIGURED_ENDPOINT_METADATA_KEY}',
                 ''
             )
         AND published_alias.endpoint_id IS DISTINCT FROM source.endpoint_id
         AND NOT EXISTS (
                SELECT 1
                  FROM {dataset_ref} AS serving_dataset
                 WHERE serving_dataset.endpoint_id = source.endpoint_id
                   AND serving_dataset.is_current = true
                   AND serving_dataset.status = :published_status
                   AND serving_dataset.published_at IS NOT NULL
                   AND serving_dataset.superseded_at IS NULL
             )
         AND EXISTS (
                SELECT 1
                  FROM {dataset_ref} AS published_dataset
                 WHERE published_dataset.endpoint_id = published_alias.endpoint_id
                   AND published_dataset.is_current = true
                   AND published_dataset.status = :published_status
                   AND published_dataset.published_at IS NOT NULL
                   AND published_dataset.superseded_at IS NULL
                   AND jsonb_typeof(
                           published_dataset.publication_metadata_json::jsonb
                               -> 'source_ids'
                       ) = 'array'
                   AND published_dataset.publication_metadata_json::jsonb
                           -> 'source_ids'
                       @> jsonb_build_array(source.source_id)
             )
    """


def _artifact_dataset_resource_profile(
    raw_profile: Any,
    *,
    dataset_id: str,
    field_name: str,
) -> tuple[str, ...]:
    decoded_profile = raw_profile
    if isinstance(decoded_profile, str):
        try:
            decoded_profile = json.loads(decoded_profile)
        except json.JSONDecodeError as exc:
            raise RuntimeError(
                f"provider_directory_artifact_dataset_profile_invalid:{dataset_id}:{field_name}"
            ) from exc
    if not isinstance(decoded_profile, list):
        raise RuntimeError(
            f"provider_directory_artifact_dataset_profile_invalid:{dataset_id}:{field_name}"
        )
    resource_types = [_clean_text(entry) for entry in decoded_profile]
    if (
        any(resource_type not in DEFAULT_RESOURCES for resource_type in resource_types)
        or len(set(resource_types)) != len(resource_types)
    ):
        raise RuntimeError(
            f"provider_directory_artifact_dataset_profile_invalid:{dataset_id}:{field_name}"
        )
    return tuple(sorted(resource_types))


def _artifact_dataset_row_identity(
    dataset_row_map: Mapping[str, Any],
) -> tuple[dict[str, str | None], str] | None:
    """Return required artifact identifiers and its serving endpoint."""

    value_by_name = {
        key: _clean_text(dataset_row_map.get(key))
        for key in ("source_id", "endpoint_id", "dataset_id", "evidence_run_id")
    }
    if not all(value_by_name.values()):
        return None
    serving_endpoint_id = (
        _clean_text(dataset_row_map.get("serving_endpoint_id"))
        or value_by_name["endpoint_id"]
        or ""
    )
    return value_by_name, serving_endpoint_id


@dataclass(frozen=True)
class _ArtifactContentProofIdentity:
    resource_hash_contract: str
    semantic_projection_as_of: str | None
    proof_resource_scope: tuple[str, ...] | None


def _artifact_content_proof_identity(
    publication_metadata: dict[str, Any],
    selected_resources: tuple[str, ...],
    dataset_id: str,
) -> _ArtifactContentProofIdentity:
    """Recover one artifact's persisted hash, date, and resource scope."""

    try:
        resource_hash_contract = _dataset_resource_hash_contract(
            {"publication_metadata_json": publication_metadata}
        )
        semantic_projection_as_of = _dataset_semantic_projection_as_of(
            {"publication_metadata_json": publication_metadata},
            resource_hash_contract,
        )
        proof_resource_scope = _dataset_proof_resource_scope(
            {"publication_metadata_json": publication_metadata},
            selected_resources,
            resource_hash_contract,
        )
    except RuntimeError as error:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_content_proof_invalid:"
            + dataset_id
        ) from error
    return _ArtifactContentProofIdentity(
        resource_hash_contract=resource_hash_contract,
        semantic_projection_as_of=semantic_projection_as_of,
        proof_resource_scope=proof_resource_scope,
    )


def _artifact_content_proof_source_ids(
    publication_metadata: dict[str, Any],
    source_id: str,
    dataset_id: str,
) -> tuple[str, ...]:
    """Return the canonical nonempty source scope committed by a proof."""

    raw_source_ids = publication_metadata.get("source_ids")
    source_ids = (
        tuple(sorted(raw_source_ids))
        if isinstance(raw_source_ids, list)
        and all(
            isinstance(source_id_value, str)
            and bool(source_id_value)
            and source_id_value == source_id_value.strip()
            for source_id_value in raw_source_ids
        )
        else ()
    )
    if (
        not source_ids
        or len(source_ids) != len(set(source_ids))
        or source_id not in source_ids
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_content_proof_invalid:"
            + dataset_id
        )
    return source_ids


def _artifact_content_proof_resources(
    raw_content_proof: Any,
    *,
    dataset_id: str,
    endpoint_id: str,
    evidence_run_id: str,
    source_ids: tuple[str, ...],
    selected_resources: tuple[str, ...],
    proof_identity: _ArtifactContentProofIdentity,
) -> tuple[str, ...]:
    """Validate a sealed content proof and return every proven family."""

    try:
        stored_proof = validate_stored_dataset_proof_metadata(
            raw_content_proof,
            dataset_id=dataset_id,
            endpoint_id=endpoint_id,
            acquisition_root_run_id=evidence_run_id,
            source_ids=source_ids,
            selected_resources=selected_resources,
            options=ProviderDirectoryStoredProofOptions(
                proof_resource_scope=proof_identity.proof_resource_scope,
                expected_resource_hash_contract=(
                    proof_identity.resource_hash_contract
                ),
                expected_semantic_projection_as_of=(
                    proof_identity.semantic_projection_as_of
                ),
            ),
        )
    except ProviderDirectoryProofStoreError as error:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_content_proof_invalid:"
            + dataset_id
        ) from error
    return tuple(sorted(stored_proof["resource_counts"]))


def _artifact_flex_retained_resources(
    *,
    endpoint_id: str,
    dataset_id: str,
    evidence_run_id: str,
    selected_resources: tuple[str, ...],
    publication_metadata: Mapping[str, Any],
    dataset_scoped_ready: bool,
) -> tuple[str, ...]:
    """Return exact-cohort resources only under dedicated readiness metadata."""

    if not (
        dataset_scoped_ready
        and selected_resources == (UHC_FLEX_OFFICIAL_RESOURCE_TYPE,)
        and is_uhc_flex_publication_metadata_valid(
            publication_metadata,
            dataset_id=dataset_id,
            endpoint_id=endpoint_id,
            evidence_run_id=evidence_run_id,
        )
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_dataset_scoped_proof_invalid:"
            + dataset_id
        )
    return selected_resources


def _artifact_dataset_retained_resources(
    *,
    source_id: str,
    endpoint_id: str,
    dataset_id: str,
    evidence_run_id: str,
    selected_resources: tuple[str, ...],
    publication_metadata: dict[str, Any],
    dataset_scoped_ready: bool = False,
) -> tuple[str, ...]:
    """Return the exact proof-bearing families available to artifacts."""

    if source_id == UHC_FLEX_PRACTITIONER_SOURCE_ID:
        return _artifact_flex_retained_resources(
            endpoint_id=endpoint_id,
            dataset_id=dataset_id,
            evidence_run_id=evidence_run_id,
            selected_resources=selected_resources,
            publication_metadata=publication_metadata,
            dataset_scoped_ready=dataset_scoped_ready,
        )
    return _artifact_standard_retained_resources(
        source_id=source_id,
        endpoint_id=endpoint_id,
        dataset_id=dataset_id,
        evidence_run_id=evidence_run_id,
        selected_resources=selected_resources,
        publication_metadata=publication_metadata,
    )


def _artifact_standard_retained_resources(
    *,
    source_id: str,
    endpoint_id: str,
    dataset_id: str,
    evidence_run_id: str,
    selected_resources: tuple[str, ...],
    publication_metadata: dict[str, Any],
) -> tuple[str, ...]:
    """Return proof-bearing resources for ordinary or retained-file datasets."""

    proof_identity = _artifact_content_proof_identity(
        publication_metadata,
        selected_resources,
        dataset_id,
    )
    if source_id == UHC_RETAINED_SOURCE_ID:
        if (
            is_semantic_resource_hash_contract(
                proof_identity.resource_hash_contract
            )
            or proof_identity.proof_resource_scope is not None
        ):
            raise ProviderDirectoryArtifactBuildStale(
                "provider_directory_artifact_content_proof_invalid:"
                + dataset_id
            )
        return selected_resources
    raw_content_proof = publication_metadata.get(
        PROVIDER_DIRECTORY_CONTENT_PROOF_METADATA_KEY
    )
    if raw_content_proof is None:
        if (
            is_semantic_resource_hash_contract(
                proof_identity.resource_hash_contract
            )
        ):
            raise ProviderDirectoryArtifactBuildStale(
                "provider_directory_artifact_content_proof_invalid:"
                + dataset_id
            )
        return selected_resources
    source_ids = _artifact_content_proof_source_ids(
        publication_metadata,
        source_id,
        dataset_id,
    )
    return _artifact_content_proof_resources(
        raw_content_proof,
        dataset_id=dataset_id,
        endpoint_id=endpoint_id,
        evidence_run_id=evidence_run_id,
        source_ids=source_ids,
        selected_resources=selected_resources,
        proof_identity=proof_identity,
    )


def _artifact_dataset_row_verification_fields(
    dataset_row_map: Mapping[str, Any],
    source_record: dict[str, Any],
    publication_metadata: dict[str, Any],
    recorded_expected_resources: tuple[str, ...],
    selection_state: dict[str, Any],
    dataset_id: str,
) -> dict[str, Any]:
    """Build verification fields from one already-validated dataset row."""

    completion_proof = _json_object(
        dataset_row_map.get("completion_proof_json")
    )
    return _artifact_dataset_verification_fields(
        source_record,
        publication_metadata,
        recorded_expected_resources,
        dataset_id,
        should_repoint_source_alias=(
            selection_state["promote_on_cutover"]
            or selection_state["reconcile_source_alias_on_cutover"]
        ),
        completion_proof_required_version=selection_state[
            "completion_proof_required_version"
        ],
        completion_proof_cutoff=_clean_text(completion_proof.get("cutoff")),
    )


def _validate_artifact_finalized_content_proof(
    dataset_row_map: Mapping[str, Any],
    publication_metadata: Mapping[str, Any],
    evidence_run_id: str,
    dataset_id: str,
    *,
    source_id: str,
    dataset_scoped_ready: bool = False,
) -> None:
    """Bind an artifact row to the same finalized proof used by replay."""

    if (
        source_id == UHC_FLEX_PRACTITIONER_SOURCE_ID
        and dataset_scoped_ready
    ):
        return
    finalized_dataset_by_field = dict(dataset_row_map)
    finalized_dataset_by_field["acquisition_root_run_id"] = evidence_run_id
    try:
        _validate_finalized_content_proof(
            finalized_dataset_by_field,
            publication_metadata,
        )
    except RuntimeError as error:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_content_proof_invalid:"
            + dataset_id
        ) from error


def _artifact_retained_resources_from_row(
    dataset_row_map: Mapping[str, Any],
    value_by_name: Mapping[str, str | None],
    dataset_id: str,
    selected_resources: tuple[str, ...],
    publication_metadata: dict[str, Any],
) -> tuple[str, ...]:
    """Validate one selected row and return its exact retained resource set."""

    source_id = value_by_name["source_id"] or ""
    evidence_run_id = value_by_name["evidence_run_id"] or ""
    is_dataset_scoped_ready = (
        dataset_row_map.get("dataset_scoped_ready") is True
    )
    retained_resources = _artifact_dataset_retained_resources(
        source_id=source_id,
        endpoint_id=value_by_name["endpoint_id"] or "",
        dataset_id=dataset_id,
        evidence_run_id=evidence_run_id,
        selected_resources=selected_resources,
        publication_metadata=publication_metadata,
        dataset_scoped_ready=is_dataset_scoped_ready,
    )
    _validate_artifact_finalized_content_proof(
        dataset_row_map,
        publication_metadata,
        evidence_run_id,
        dataset_id,
        source_id=source_id,
        dataset_scoped_ready=is_dataset_scoped_ready,
    )
    return retained_resources


def _provider_directory_artifact_dataset_from_row(
    dataset_row: Any,
) -> ProviderDirectoryArtifactDataset | None:
    """Build one immutable artifact selection from a query result."""
    dataset_row_map = _pagination_checkpoint_row_mapping(dataset_row)
    identity = _artifact_dataset_row_identity(dataset_row_map)
    if identity is None:
        return None
    value_by_name, serving_endpoint_id = identity
    dataset_id = value_by_name["dataset_id"] or ""
    selected_resources, expected_resources, recorded_expected_resources = (
        _artifact_dataset_profiles_from_row(dataset_row_map, dataset_id)
    )
    selection_state = _artifact_dataset_state_from_row(
        dataset_row_map,
        dataset_id,
        value_by_name["endpoint_id"] or "",
    )
    source_record = _json_object(dataset_row_map.get("source_record_json"))
    publication_metadata = _json_object(
        dataset_row_map.get("publication_metadata_json")
    )
    retained_resources = _artifact_retained_resources_from_row(
        dataset_row_map,
        value_by_name,
        dataset_id=dataset_id,
        selected_resources=selected_resources,
        publication_metadata=publication_metadata,
    )
    verification_fields_by_name = _artifact_dataset_row_verification_fields(
        dataset_row_map,
        source_record,
        publication_metadata,
        recorded_expected_resources,
        selection_state,
        dataset_id,
    )
    return ProviderDirectoryArtifactDataset(
        source_id=value_by_name["source_id"] or "",
        endpoint_id=value_by_name["endpoint_id"] or "",
        dataset_id=dataset_id,
        evidence_run_id=value_by_name["evidence_run_id"] or "",
        serving_endpoint_id=serving_endpoint_id,
        selected_resources=selected_resources,
        retained_resources=retained_resources,
        expected_resources=expected_resources,
        recorded_expected_resources=recorded_expected_resources,
        **verification_fields_by_name,
        **selection_state,
    )


def _artifact_verification_field_map(
    source_record: dict[str, Any],
    should_repoint_source_alias: bool,
    verification_campaign_id: str | None,
    verification_source_scope_hash: str | None,
    verification_source_ids: tuple[str, ...],
    reviewed_root_policy: ReviewedRootPolicy | None,
    source_contract: tuple[Any, ...],
) -> dict[str, Any]:
    return {
        "verification_campaign_id": verification_campaign_id,
        "verification_source_scope_hash": verification_source_scope_hash,
        "verification_source_status": (
            _clean_text(
                _source_metadata(source_record).get(
                    "provider_directory_candidate_status"
                )
            )
            if should_repoint_source_alias
            else None
        ),
        "verification_source_ids": verification_source_ids,
        "reviewed_root_policy": reviewed_root_policy,
        "source_verification_contract": source_contract,
        "source_verification_contract_hash": (
            _identity_hash(source_contract) if source_contract else None
        ),
    }


def _artifact_dataset_verification_fields(
    source_record: dict[str, Any],
    publication_metadata: dict[str, Any],
    recorded_expected_resources: tuple[str, ...],
    dataset_id: str,
    *,
    should_repoint_source_alias: bool,
    completion_proof_required_version: int | None,
    completion_proof_cutoff: str | None,
) -> dict[str, Any]:
    """Freeze the reviewed source contract attached to alias cutover."""
    reviewed_root_policy = (
        _artifact_reviewed_root_policy(
            source_record,
            publication_metadata,
            dataset_id,
        )
        if should_repoint_source_alias
        else _artifact_dataset_root_policy(publication_metadata, dataset_id)
    )
    verification_campaign_id = _clean_text(
        publication_metadata.get(TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY)
    )
    verification_source_scope_hash = _clean_text(
        publication_metadata.get(TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY)
    )
    verification_source_ids, source_contract = ((), ())
    if should_repoint_source_alias:
        verification_source_ids, source_contract = (
            _artifact_promotion_source_contract(
                source_record,
                publication_metadata,
                recorded_expected_resources,
                _ArtifactPromotionEvidence(
                    dataset_id=dataset_id,
                    verification_campaign_id=verification_campaign_id,
                    verification_source_scope_hash=(
                        verification_source_scope_hash
                    ),
                    completion_proof_required_version=(
                        completion_proof_required_version
                    ),
                    completion_proof_cutoff=completion_proof_cutoff,
                    reviewed_root_policy=reviewed_root_policy,
                ),
            )
        )
    return _artifact_verification_field_map(
        source_record,
        should_repoint_source_alias,
        verification_campaign_id,
        verification_source_scope_hash,
        verification_source_ids,
        reviewed_root_policy,
        source_contract,
    )


def _artifact_source_contract_metadata_value(
    metadata: dict[str, Any],
    key: str,
) -> tuple[str, bool, str | None]:
    """Preserve key presence as well as its normalized string value."""
    return key, key in metadata, _clean_text(metadata.get(key))


def _artifact_source_contract_json_value(
    metadata: dict[str, Any],
    key: str,
) -> tuple[str, bool, str | None]:
    """Preserve one source configuration value with stable JSON identity."""
    return (
        key,
        key in metadata,
        _stable_identity_json(metadata.get(key)) if key in metadata else None,
    )


def _artifact_verification_source_ids(
    publication_metadata: dict[str, Any],
    dataset_id: str,
    source_record: dict[str, Any],
    *,
    is_required: bool,
) -> tuple[str, ...]:
    raw_source_ids = publication_metadata.get("source_ids")
    source_ids = (
        tuple(
            sorted(_clean_text(value) or "" for value in raw_source_ids)
        )
        if isinstance(raw_source_ids, list)
        else ()
    )
    is_valid = bool(
        source_ids
        and all(source_ids)
        and len(source_ids) == len(set(source_ids))
    )
    if is_valid:
        return source_ids
    if is_required:
        raise RuntimeError(
            "provider_directory_artifact_candidate_source_ids_invalid:"
            + dataset_id
        )
    source_id = _clean_text(source_record.get("source_id"))
    return (source_id,) if source_id else ()


def _is_artifact_source_verification_profile_present(
    source_record: dict[str, Any],
) -> bool:
    source_metadata = _source_metadata(source_record)
    return bool(
        "provider_directory_candidate_status" in source_metadata
        or PROVIDER_DIRECTORY_VERIFICATION_CAMPAIGN_METADATA_KEY
        in source_metadata
    )


def _source_contract_metadata_keys(
    metadata: Mapping[str, Any],
    *,
    artifact: bool,
) -> tuple[str, ...]:
    """Preserve legacy tuples while extending only shaped v3 identities."""

    base_keys = (
        ARTIFACT_SOURCE_CONTRACT_METADATA_KEYS
        if artifact
        else TWIN_ROOT_ACQUISITION_METADATA_KEYS
    )
    is_subset_shape = bool(
        metadata.get(CURRENT_VERSION_CENSUS_CONTRACT_VERSION_FIELD)
        == SERVER_ISSUED_SUBSET_REQUIRED_VERSION
        and metadata.get(CURRENT_VERSION_CENSUS_METADATA_STRATEGY_FIELD)
        == SERVER_ISSUED_SUBSET_SEMANTICS
    )
    if not is_subset_shape:
        return base_keys
    subset_keys = (
        SERVER_ISSUED_SUBSET_ARTIFACT_METADATA_KEYS
        if artifact
        else SERVER_ISSUED_SUBSET_ACQUISITION_METADATA_KEYS
    )
    if REVIEWED_ROOT_POLICY_METADATA_KEY in metadata:
        subset_keys = subset_keys + (REVIEWED_ROOT_POLICY_METADATA_KEY,)
    return base_keys + subset_keys


def _is_reviewed_subset_source_metadata(metadata: Mapping[str, Any]) -> bool:
    resources = metadata.get(
        "provider_directory_server_issued_subset_resources"
    )
    start_urls = metadata.get(CURRENT_VERSION_CENSUS_START_URLS_FIELD)
    return bool(
        metadata.get("provider_directory_manual_only") is True
        and type(resources) is list
        and len(resources) == len(SERVER_ISSUED_SUBSET_RESOURCE_TYPES)
        and set(resources) == set(SERVER_ISSUED_SUBSET_RESOURCE_TYPES)
        and isinstance(start_urls, Mapping)
        and set(start_urls) == set(SERVER_ISSUED_SUBSET_RESOURCE_TYPES)
        and metadata.get(CURRENT_VERSION_CENSUS_CONTRACT_VERSION_FIELD)
        == SERVER_ISSUED_SUBSET_REQUIRED_VERSION
        and metadata.get(CURRENT_VERSION_CENSUS_METADATA_STRATEGY_FIELD)
        == SERVER_ISSUED_SUBSET_SEMANTICS
        and reviewed_subset_max_advertised_count_decrease(
            metadata.get(CURRENT_VERSION_CENSUS_STRATEGY_VERSION_FIELD),
            tuple(metadata[CURRENT_VERSION_CENSUS_COMPLETION_SCOPES_FIELD])
            if type(
                metadata.get(CURRENT_VERSION_CENSUS_COMPLETION_SCOPES_FIELD)
            )
            is list
            else None,
        )
        is not None
        and metadata.get(CURRENT_VERSION_CENSUS_TRAVERSAL_VERSION_FIELD)
        == SERVER_ISSUED_SUBSET_TRAVERSAL_VERSION
        and metadata.get(CURRENT_VERSION_CENSUS_CANONICALIZATION_VERSION_FIELD)
        == SERVER_ISSUED_SUBSET_CANONICALIZATION_VERSION
        and metadata.get(CURRENT_VERSION_CENSUS_CONTINUATION_STRATEGY_FIELD)
        == SERVER_ISSUED_SUBSET_SMILE_CONTINUATION_STRATEGY
        and type(metadata.get(CURRENT_VERSION_CENSUS_PAGE_COUNT_FIELD)) is int
        and 1 <= metadata[CURRENT_VERSION_CENSUS_PAGE_COUNT_FIELD] <= 1000
        and bool(
            _clean_text(
                metadata.get(
                    PROVIDER_DIRECTORY_VERIFICATION_CAMPAIGN_METADATA_KEY
                )
            )
        )
    )


def _artifact_expected_verified_status(
    source_metadata: dict[str, Any],
    dataset_id: str,
    completion_proof_required_version: int | None,
    reviewed_root_policy: ReviewedRootPolicy | None,
) -> tuple[ReviewedRootPolicy | None, str]:
    if (
        reviewed_root_policy is None
        and REVIEWED_ROOT_POLICY_METADATA_KEY in source_metadata
    ):
        try:
            reviewed_root_policy = reviewed_root_policy_from_document(
                source_metadata.get(REVIEWED_ROOT_POLICY_METADATA_KEY)
            )
        except ValueError as exc:
            raise RuntimeError(
                "provider_directory_artifact_reviewed_root_policy_invalid:"
                + dataset_id
            ) from exc
    expected_status = (
        PROVIDER_DIRECTORY_ROOT_POLICY_VERIFIED
        if reviewed_root_policy is not None
        else (
            PROVIDER_DIRECTORY_SUBSET_TWIN_ROOT_VERIFIED
            if completion_proof_required_version
            == SERVER_ISSUED_SUBSET_REQUIRED_VERSION
            else PROVIDER_DIRECTORY_TWIN_ROOT_VERIFIED
        )
    )
    return reviewed_root_policy, expected_status


def _has_validated_artifact_verification_profile(
    source_record: dict[str, Any],
    dataset_id: str,
    verification_campaign_id: str | None,
    completion_proof_required_version: int | None,
    reviewed_root_policy: ReviewedRootPolicy | None = None,
) -> bool:
    """Validate status and reviewed identity; return profile presence."""

    has_verification_profile = _is_artifact_source_verification_profile_present(
        source_record
    )
    source_metadata = _source_metadata(source_record)
    _, expected_verified_status = _artifact_expected_verified_status(
        source_metadata,
        dataset_id,
        completion_proof_required_version,
        reviewed_root_policy,
    )
    if has_verification_profile and _clean_text(
        source_metadata.get("provider_directory_candidate_status")
    ) != expected_verified_status:
        raise RuntimeError(
            "provider_directory_artifact_candidate_status_not_verified:"
            + dataset_id
        )
    is_subset = (
        completion_proof_required_version
        == SERVER_ISSUED_SUBSET_REQUIRED_VERSION
    )
    campaign = _clean_text(
        source_metadata.get(
            PROVIDER_DIRECTORY_VERIFICATION_CAMPAIGN_METADATA_KEY
        )
    )
    if is_subset and (
        not _is_reviewed_subset_source_metadata(source_metadata)
        or campaign != verification_campaign_id
    ):
        raise RuntimeError(
            "provider_directory_artifact_subset_contract_invalid:" + dataset_id
        )
    if completion_proof_required_version not in (
        None,
        SERVER_ISSUED_SUBSET_REQUIRED_VERSION,
    ):
        raise RuntimeError(
            "provider_directory_artifact_subset_contract_invalid:" + dataset_id
        )
    return has_verification_profile


def _artifact_reviewed_root_policy(
    source_record: Mapping[str, Any],
    publication_metadata: Mapping[str, Any],
    dataset_id: str,
) -> ReviewedRootPolicy | None:
    """Validate the explicit policy shared by source and dataset evidence."""

    source_metadata = _source_metadata(dict(source_record))
    has_source_policy = REVIEWED_ROOT_POLICY_METADATA_KEY in source_metadata
    has_dataset_policy = (
        REVIEWED_ROOT_POLICY_METADATA_KEY in publication_metadata
    )
    if has_source_policy != has_dataset_policy:
        raise RuntimeError(
            "provider_directory_artifact_reviewed_root_policy_changed:"
            + dataset_id
        )
    if not has_source_policy:
        return None
    try:
        source_policy = reviewed_root_policy_from_document(
            source_metadata.get(REVIEWED_ROOT_POLICY_METADATA_KEY)
        )
        dataset_policy = reviewed_root_policy_from_document(
            publication_metadata.get(REVIEWED_ROOT_POLICY_METADATA_KEY)
        )
    except ValueError as exc:
        raise RuntimeError(
            "provider_directory_artifact_reviewed_root_policy_invalid:"
            + dataset_id
        ) from exc
    if source_policy != dataset_policy:
        raise RuntimeError(
            "provider_directory_artifact_reviewed_root_policy_changed:"
            + dataset_id
        )
    return source_policy


def _artifact_dataset_root_policy(
    publication_metadata: Mapping[str, Any],
    dataset_id: str,
) -> ReviewedRootPolicy | None:
    """Parse only the immutable dataset policy for an incumbent artifact."""

    if REVIEWED_ROOT_POLICY_METADATA_KEY not in publication_metadata:
        return None
    try:
        return reviewed_root_policy_from_document(
            publication_metadata.get(REVIEWED_ROOT_POLICY_METADATA_KEY)
        )
    except ValueError as exc:
        raise RuntimeError(
            "provider_directory_artifact_reviewed_root_policy_invalid:"
            + dataset_id
        ) from exc


def _artifact_scope_source(
    source_record: dict[str, Any],
    completion_proof_cutoff: str | None,
    recorded_expected_resources: tuple[str, ...] | None,
    dataset_id: str,
    *,
    profile_required: bool,
) -> dict[str, Any]:
    """Reconstruct the source contract and validate its resource profile."""

    scope_source = _artifact_source_with_subset_contract(
        source_record, completion_proof_cutoff
    )
    current_expected_resources = _endpoint_dataset_expected_resources(
        [scope_source]
    )
    if profile_required and (
        recorded_expected_resources is None
        or current_expected_resources != recorded_expected_resources
    ):
        raise RuntimeError(
            "provider_directory_artifact_candidate_resource_profile_changed:"
            + dataset_id
        )
    return scope_source


@dataclass(frozen=True, slots=True)
class _ArtifactPromotionEvidence:
    dataset_id: str
    verification_campaign_id: str | None
    verification_source_scope_hash: str | None
    completion_proof_required_version: int | None = None
    completion_proof_cutoff: str | None = None
    reviewed_root_policy: ReviewedRootPolicy | None = None


def _artifact_promotion_source_contract(
    source_record: dict[str, Any],
    publication_metadata: dict[str, Any],
    recorded_expected_resources: tuple[str, ...] | None,
    evidence: _ArtifactPromotionEvidence,
) -> tuple[tuple[str, ...], tuple[Any, ...]]:
    """Build and validate the current source contract for one promotion."""
    has_verification_profile = _has_validated_artifact_verification_profile(
        source_record,
        evidence.dataset_id,
        evidence.verification_campaign_id,
        evidence.completion_proof_required_version,
        evidence.reviewed_root_policy,
    )
    source_ids = _artifact_verification_source_ids(
        publication_metadata,
        evidence.dataset_id,
        source_record,
        is_required=has_verification_profile,
    )
    scope_source = _artifact_scope_source(
        source_record,
        evidence.completion_proof_cutoff,
        recorded_expected_resources,
        evidence.dataset_id,
        profile_required=has_verification_profile,
    )
    contract = _artifact_source_verification_contract(
        scope_source,
        verification_campaign_id=evidence.verification_campaign_id,
        verification_source_scope_hash=evidence.verification_source_scope_hash,
        source_ids=source_ids,
        completion_proof_cutoff=evidence.completion_proof_cutoff,
    )
    current_scope_hash = contract[-1][1]
    if has_verification_profile and (
        not evidence.verification_campaign_id
        or not evidence.verification_source_scope_hash
        or current_scope_hash != evidence.verification_source_scope_hash
    ):
        raise RuntimeError(
            "provider_directory_artifact_candidate_source_scope_changed:"
            + evidence.dataset_id
        )
    return source_ids, contract


def _artifact_subset_contract_from_metadata(
    source_id: str,
    source_metadata: Mapping[str, Any],
    completion_proof_cutoff: str,
) -> CurrentVersionCensusContract:
    """Reconstruct one reviewed v3 contract from durable metadata."""

    resources = tuple(
        source_metadata["provider_directory_server_issued_subset_resources"]
    )
    expected_nonempty_resources = tuple(
        source_metadata.get(
            "provider_directory_expected_nonempty_resources",
            (),
        )
    )
    start_url_by_resource = source_metadata[
        CURRENT_VERSION_CENSUS_START_URLS_FIELD
    ]
    return CurrentVersionCensusContract(
        source_id=source_id,
        cutoff=completion_proof_cutoff,
        resources=resources,
        expected_nonempty_resources=expected_nonempty_resources,
        start_urls=tuple(
            (resource_type, start_url_by_resource[resource_type])
            for resource_type in resources
        ),
        continuation_strategy=source_metadata[
            CURRENT_VERSION_CENSUS_CONTINUATION_STRATEGY_FIELD
        ],
        strategy_version=source_metadata[
            CURRENT_VERSION_CENSUS_STRATEGY_VERSION_FIELD
        ],
        contract_version=source_metadata[
            CURRENT_VERSION_CENSUS_CONTRACT_VERSION_FIELD
        ],
        semantics=source_metadata[
            CURRENT_VERSION_CENSUS_METADATA_STRATEGY_FIELD
        ],
        page_count=source_metadata[CURRENT_VERSION_CENSUS_PAGE_COUNT_FIELD],
        traversal_version=source_metadata[
            CURRENT_VERSION_CENSUS_TRAVERSAL_VERSION_FIELD
        ],
        canonicalization_version=source_metadata[
            CURRENT_VERSION_CENSUS_CANONICALIZATION_VERSION_FIELD
        ],
        completion_scopes=tuple(
            source_metadata[CURRENT_VERSION_CENSUS_COMPLETION_SCOPES_FIELD]
        ),
        campaign_id=_clean_text(
            source_metadata.get(
                PROVIDER_DIRECTORY_VERIFICATION_CAMPAIGN_METADATA_KEY
            )
        ),
    )


def _artifact_source_with_subset_contract(
    source_record: dict[str, Any],
    completion_proof_cutoff: str | None,
) -> dict[str, Any]:
    """Reconstruct the admitted v3 contract from durable neutral identity."""

    if completion_proof_cutoff is None:
        return source_record
    source_metadata = _source_metadata(source_record)
    if not _is_reviewed_subset_source_metadata(source_metadata):
        raise RuntimeError(
            "provider_directory_artifact_subset_contract_invalid"
        )
    contract = _artifact_subset_contract_from_metadata(
        _clean_text(source_record.get("source_id")) or "",
        source_metadata,
        completion_proof_cutoff,
    )
    if not contract.is_server_issued_subset_v3:
        raise RuntimeError(
            "provider_directory_artifact_subset_contract_invalid"
        )
    scoped_source_by_field = dict(source_record)
    scoped_source_by_field[CURRENT_VERSION_CENSUS_CONTRACT_FIELD] = contract
    return scoped_source_by_field


def _artifact_current_source_scope_hashes(
    source_record: dict[str, Any],
    source_ids: tuple[str, ...],
    completion_proof_cutoff: str | None,
) -> tuple[str | None, str | None]:
    """Return legacy checkpoint and reviewed verification scope hashes."""
    scope_source = _artifact_source_with_subset_contract(
        source_record,
        completion_proof_cutoff,
    )
    checkpoint_identity = _pagination_checkpoint_scope_identity(
        scope_source,
        list(source_ids),
    )
    checkpoint_scope_hash = (
        checkpoint_identity[1] if checkpoint_identity else None
    )
    if not (
        _is_artifact_source_verification_profile_present(source_record)
        and checkpoint_scope_hash
    ):
        return checkpoint_scope_hash, checkpoint_scope_hash
    subset_scope_hash = _server_issued_subset_source_scope_hash(
        [scope_source],
        list(source_ids),
    )
    if subset_scope_hash is not None:
        return checkpoint_scope_hash, subset_scope_hash
    reviewed_scope_hash = _twin_root_verification_scope_hash(
        [scope_source],
        list(source_ids),
        checkpoint_scope_hash,
    )
    return checkpoint_scope_hash, reviewed_scope_hash


def _artifact_source_identity_fields(
    source_metadata: dict[str, Any],
) -> tuple[Any, ...]:
    """Return the legacy-or-v3 source configuration identity fields."""

    return tuple(
        _artifact_source_contract_json_value(source_metadata, key)
        for key in _source_contract_metadata_keys(
            source_metadata,
            artifact=True,
        )
    )


def _artifact_source_verification_contract(
    source_record: dict[str, Any],
    *,
    verification_campaign_id: str | None,
    verification_source_scope_hash: str | None,
    source_ids: tuple[str, ...],
    completion_proof_cutoff: str | None,
) -> tuple[Any, ...]:
    """Freeze source admission and acquisition config used by an artifact."""
    contract_source = _artifact_source_with_subset_contract(
        source_record,
        completion_proof_cutoff,
    )
    source_metadata = _source_metadata(contract_source)
    checkpoint_scope_hash, current_verification_scope_hash = (
        _artifact_current_source_scope_hashes(
            contract_source,
            source_ids,
            completion_proof_cutoff,
        )
    )
    return (
        "provider-directory-artifact-source-contract-v1",
        _artifact_source_contract_metadata_value(
            source_metadata,
            "provider_directory_candidate_status",
        ),
        _artifact_source_contract_metadata_value(
            source_metadata,
            PROVIDER_DIRECTORY_VERIFICATION_CAMPAIGN_METADATA_KEY,
        ),
        _artifact_source_contract_metadata_value(
            source_metadata,
            PROVIDER_DIRECTORY_CONFIGURED_ENDPOINT_METADATA_KEY,
        ),
        ("dataset_verification_campaign_id", verification_campaign_id),
        (
            "dataset_verification_source_scope_hash",
            verification_source_scope_hash,
        ),
        (
            "current_expected_resources",
            _endpoint_dataset_expected_resources([contract_source]),
        ),
        *_artifact_source_identity_fields(source_metadata),
        ("acquisition_config", _resource_import_group_key(contract_source)),
        (
            "current_checkpoint_source_scope_hash",
            checkpoint_scope_hash,
        ),
        (
            "current_verification_source_scope_hash",
            current_verification_scope_hash,
        ),
    )


def _artifact_dataset_profiles_from_row(
    dataset_row_map: dict[str, Any],
    dataset_id: str,
) -> tuple[tuple[str, ...], tuple[str, ...], tuple[str, ...] | None]:
    selected_resources = _artifact_dataset_resource_profile(
        dataset_row_map.get("selected_resources"),
        dataset_id=dataset_id,
        field_name="selected_resources",
    )
    raw_recorded_expected_resources = dataset_row_map.get(
        "recorded_expected_resources"
    )
    if raw_recorded_expected_resources is None:
        source_record = _json_object(dataset_row_map.get("source_record_json"))
        expected_resources = _endpoint_dataset_expected_resources([source_record])
        recorded_expected_resources = None
    else:
        recorded_expected_resources = _artifact_dataset_resource_profile(
            raw_recorded_expected_resources,
            dataset_id=dataset_id,
            field_name="expected_resources",
        )
        expected_resources = recorded_expected_resources
    return (
        selected_resources,
        expected_resources,
        recorded_expected_resources,
    )


def _artifact_candidate_proof_fields(
    dataset_row_map: Mapping[str, Any],
    dataset_id: str,
    *,
    promotion_required: bool,
) -> tuple[str | None, str | None, dict[str, Any]]:
    """Validate and return the row proof fields required for promotion."""

    publication_metadata = _json_object(
        dataset_row_map.get("publication_metadata_json")
    )
    dataset_hash = _clean_text(dataset_row_map.get("dataset_hash"))
    validated_at_value = dataset_row_map.get("validated_at")
    validated_at = (
        str(validated_at_value) if validated_at_value is not None else None
    )
    if promotion_required and (
        not dataset_hash or validated_at is None or not publication_metadata
    ):
        raise RuntimeError(
            "provider_directory_artifact_validated_candidate_proof_invalid:"
            + dataset_id
        )
    return dataset_hash, validated_at, publication_metadata


def _artifact_completion_state_from_row(
    dataset_row_map: Mapping[str, Any],
) -> dict[str, Any]:
    """Return the direct completion marker and proof identity fields."""

    marker = dataset_row_map.get("completion_proof_required_version")
    completion_proof = _json_object(
        dataset_row_map.get("completion_proof_json")
    )
    return {
        "completion_proof_required_version": (
            int(marker) if marker is not None else None
        ),
        "completion_proof_sha256": _clean_text(
            dataset_row_map.get("completion_proof_sha256")
        ),
        "completion_proof_cutoff": _clean_text(completion_proof.get("cutoff")),
    }


def _artifact_dataset_scoped_state_from_row(
    dataset_row_map: Mapping[str, Any],
) -> dict[str, Any]:
    """Return exact dataset admission identity fields used only by Profile."""

    return {
        "dataset_scoped_ready": (
            dataset_row_map.get("dataset_scoped_ready") is True
        ),
        "semantic_projection_as_of": _clean_text(
            dataset_row_map.get("dataset_scoped_projection_as_of")
        ),
        "source_authority_id": _clean_text(
            dataset_row_map.get("dataset_scoped_authority_id")
        ),
        "admission_id": _clean_text(
            dataset_row_map.get("dataset_scoped_admission_id")
        ),
        "operation_key": _clean_text(
            dataset_row_map.get("dataset_scoped_operation_key")
        ),
    }


def _artifact_dataset_state_from_row(
    dataset_row_map: dict[str, Any],
    dataset_id: str,
    endpoint_id: str,
) -> dict[str, Any]:
    """Validate and project artifact lifecycle and completion state."""

    selection_state = _artifact_dataset_selection_from_row(
        dataset_row_map,
        dataset_id,
        endpoint_id,
    )
    should_promote_on_cutover = selection_state[
        "should_promote_on_cutover"
    ]
    should_reconcile_source_alias = selection_state[
        "should_reconcile_source_alias"
    ]
    dataset_hash, validated_at, publication_metadata = (
        _artifact_candidate_proof_fields(
            dataset_row_map,
            dataset_id,
            promotion_required=should_promote_on_cutover,
        )
    )
    return {
        "status": selection_state["status"],
        "is_current": selection_state["is_current"],
        "previous_dataset_id": selection_state["previous_dataset_id"],
        "expected_incumbent_dataset_id": (
            selection_state["current_dataset_id"]
            if should_promote_on_cutover
            else None
        ),
        "promote_on_cutover": should_promote_on_cutover,
        "reconcile_source_alias_on_cutover": (
            should_reconcile_source_alias
        ),
        "dataset_hash": dataset_hash,
        "resource_count": (
            int(dataset_row_map.get("resource_count"))
            if dataset_row_map.get("resource_count") is not None
            else None
        ),
        "validated_at": validated_at,
        "publication_metadata_hash": _identity_hash(publication_metadata),
        **_artifact_dataset_scoped_state_from_row(dataset_row_map),
        **_artifact_completion_state_from_row(dataset_row_map),
    }


def _artifact_dataset_selection_from_row(
    dataset_row_map: dict[str, Any],
    dataset_id: str,
    endpoint_id: str,
) -> dict[str, Any]:
    status = (
        _clean_text(dataset_row_map.get("status"))
        or ENDPOINT_DATASET_PUBLISHED
    )
    is_current = dataset_row_map.get("is_current")
    if not isinstance(is_current, bool):
        is_current = status == ENDPOINT_DATASET_PUBLISHED
    should_promote_on_cutover = bool(
        dataset_row_map.get("promote_on_cutover")
    )
    should_reconcile_source_alias = bool(
        dataset_row_map.get("reconcile_source_alias_on_cutover")
    )
    current_dataset_count = int(
        dataset_row_map.get("current_dataset_count")
        if dataset_row_map.get("current_dataset_count") is not None
        else (1 if is_current else 0)
    )
    current_dataset_id = _clean_text(
        dataset_row_map.get("current_dataset_id")
    )
    if current_dataset_id is None and is_current:
        current_dataset_id = dataset_id
    validated_candidate_count = int(
        dataset_row_map.get("validated_candidate_count")
        if dataset_row_map.get("validated_candidate_count") is not None
        else (1 if should_promote_on_cutover else 0)
    )
    previous_dataset_id = _clean_text(
        dataset_row_map.get("previous_dataset_id")
    )
    selection_state_map = {
        "status": status,
        "is_current": is_current,
        "should_promote_on_cutover": should_promote_on_cutover,
        "should_reconcile_source_alias": should_reconcile_source_alias,
        "current_dataset_count": current_dataset_count,
        "current_dataset_id": current_dataset_id,
        "validated_candidate_count": validated_candidate_count,
        "previous_dataset_id": previous_dataset_id,
    }
    _assert_artifact_dataset_selection_state(
        selection_state_map,
        dataset_id,
        endpoint_id,
    )
    return selection_state_map


def _assert_artifact_dataset_selection_state(
    selection_state: dict[str, Any],
    dataset_id: str,
    endpoint_id: str,
) -> None:
    should_reconcile_source_alias = bool(
        selection_state.get("should_reconcile_source_alias")
    )
    if selection_state["should_promote_on_cutover"]:
        if should_reconcile_source_alias:
            raise RuntimeError(
                "provider_directory_artifact_alias_cutover_ambiguous:"
                + dataset_id
            )
        if selection_state["validated_candidate_count"] != 1:
            raise RuntimeError(
                "provider_directory_artifact_validated_candidate_ambiguous:"
                + endpoint_id
            )
        if (
            selection_state["status"] != ENDPOINT_DATASET_VALIDATED
            or selection_state["is_current"]
        ):
            raise RuntimeError(
                "provider_directory_artifact_validated_candidate_invalid:"
                + dataset_id
            )
        if (
            selection_state["current_dataset_count"] > 1
            or selection_state["previous_dataset_id"]
            != selection_state["current_dataset_id"]
        ):
            raise RuntimeError(
                "provider_directory_artifact_expected_incumbent_mismatch:"
                + dataset_id
            )
        return
    if should_reconcile_source_alias and (
        selection_state["status"] != ENDPOINT_DATASET_PUBLISHED
        or not selection_state["is_current"]
        or selection_state["current_dataset_count"] != 1
        or selection_state["current_dataset_id"] != dataset_id
    ):
        raise RuntimeError(
            "provider_directory_artifact_alias_reconciliation_invalid:"
            + dataset_id
        )
    if (
        selection_state["status"] != ENDPOINT_DATASET_PUBLISHED
        or not selection_state["is_current"]
        or selection_state["current_dataset_count"] != 1
        or selection_state["current_dataset_id"] != dataset_id
    ):
        raise RuntimeError(
            "provider_directory_artifact_current_dataset_invalid:" + dataset_id
        )


def _validate_provider_directory_artifact_datasets(
    dataset_rows: list[Any],
    requested_source_ids: list[str],
    *,
    should_select_validated_candidates: bool = False,
) -> ProviderDirectoryArtifactDatasetFence:
    """Turn a current-dataset query result into one exact alias fence."""
    rows_by_source_id = _artifact_dataset_rows_by_source(dataset_rows)
    selected_source_ids = _artifact_dataset_source_ids(
        rows_by_source_id,
        requested_source_ids,
    )
    selected_datasets = [
        _artifact_dataset_for_source(source_id, rows_by_source_id[source_id])
        for source_id in selected_source_ids
    ]
    _assert_artifact_endpoint_consistency(selected_datasets)
    return ProviderDirectoryArtifactDatasetFence(
        tuple(selected_datasets),
        should_select_validated_candidates=(
            should_select_validated_candidates
        ),
    )


def _artifact_dataset_rows_by_source(
    dataset_rows: list[Any],
) -> dict[str, list[Any]]:
    rows_by_source_id: dict[str, list[Any]] = {}
    for dataset_row in dataset_rows:
        source_id = _clean_text(
            _pagination_checkpoint_row_mapping(dataset_row).get("source_id")
        )
        if source_id:
            rows_by_source_id.setdefault(source_id, []).append(dataset_row)
    return rows_by_source_id


def _artifact_dataset_source_ids(
    rows_by_source_id: dict[str, list[Any]],
    requested_source_ids: list[str],
) -> list[str]:
    missing_requested_aliases = [
        source_id
        for source_id in requested_source_ids
        if source_id not in rows_by_source_id
    ]
    if missing_requested_aliases:
        raise RuntimeError(
            "provider_directory_artifact_source_alias_missing:"
            + ",".join(missing_requested_aliases)
        )
    selected_source_ids = (
        list(requested_source_ids)
        if requested_source_ids
        else sorted(rows_by_source_id)
    )
    if not selected_source_ids:
        raise RuntimeError("provider_directory_artifact_source_aliases_empty")
    return selected_source_ids


def _artifact_dataset_for_source(
    source_id: str,
    dataset_rows: list[Any],
) -> ProviderDirectoryArtifactDataset:
    """Build a promotion candidate only after full proof validation."""

    candidates = [
        dataset
        for dataset_row in dataset_rows
        if (dataset := _provider_directory_artifact_dataset_from_row(dataset_row))
        is not None
    ]
    if not candidates:
        raise RuntimeError(
            f"provider_directory_artifact_current_dataset_missing:{source_id}"
        )
    if len({candidate.dataset_id for candidate in candidates}) != 1 or len(candidates) != 1:
        raise RuntimeError(
            f"provider_directory_artifact_current_dataset_ambiguous:{source_id}"
        )
    return candidates[0]


def _assert_artifact_endpoint_consistency(
    selected_datasets: list[ProviderDirectoryArtifactDataset],
) -> None:
    """Require every alias of an endpoint to carry one exact selection."""
    identity_by_endpoint_id: dict[str, tuple[Any, ...]] = {}
    for dataset in selected_datasets:
        selection_identity = _artifact_endpoint_selection_identity(dataset)
        incumbent_identity = identity_by_endpoint_id.setdefault(
            dataset.endpoint_id,
            selection_identity,
        )
        if incumbent_identity == selection_identity:
            continue
        if incumbent_identity[0] != dataset.dataset_id:
            raise RuntimeError(
                "provider_directory_artifact_endpoint_dataset_ambiguous:"
                + dataset.endpoint_id
            )
        raise RuntimeError(
            "provider_directory_artifact_endpoint_metadata_ambiguous:"
            + dataset.endpoint_id
        )


def _artifact_endpoint_selection_identity(
    dataset: ProviderDirectoryArtifactDataset,
) -> tuple[Any, ...]:
    return (
        dataset.dataset_id,
        dataset.selected_resources,
        dataset.artifact_resources,
        dataset.expected_resources,
        dataset.recorded_expected_resources,
        dataset.status,
        dataset.is_current,
        dataset.previous_dataset_id,
        dataset.expected_incumbent_dataset_id,
        dataset.promote_on_cutover,
        dataset.reconcile_source_alias_on_cutover,
        dataset.dataset_hash,
        dataset.resource_count,
        dataset.validated_at,
        dataset.publication_metadata_hash,
        dataset.completion_proof_required_version,
        dataset.completion_proof_sha256,
        dataset.completion_proof_cutoff,
        dataset.source_verification_contract_hash,
        dataset.dataset_scoped_ready,
        dataset.semantic_projection_as_of,
        dataset.source_authority_id,
        dataset.admission_id,
        dataset.operation_key,
    )


async def _resolve_provider_directory_artifact_datasets(
    source_ids: list[str] | tuple[str, ...] | None,
    *,
    should_select_validated_candidates: bool = False,
) -> ProviderDirectoryArtifactDatasetFence:
    cleaned_source_ids = _clean_source_id_list(source_ids)
    dataset_rows = await db.all(
        _provider_directory_artifact_dataset_selection_sql(
            cleaned_source_ids,
            should_select_validated_candidates=(
                should_select_validated_candidates
            ),
        ),
        published_status=ENDPOINT_DATASET_PUBLISHED,
        validated_status=ENDPOINT_DATASET_VALIDATED,
        select_validated_candidates=should_select_validated_candidates,
        **({"source_ids": cleaned_source_ids} if cleaned_source_ids else {}),
    )
    dataset_rows = await annotate_uhc_flex_profile_dataset_readiness(
        dataset_rows,
        database=db,
        row_mapping=_pagination_checkpoint_row_mapping,
    )
    fence = _validate_provider_directory_artifact_datasets(
        dataset_rows,
        cleaned_source_ids,
        should_select_validated_candidates=should_select_validated_candidates,
    )
    return await _expand_reviewed_artifact_promotion_aliases(fence)


async def ensure_provider_directory_published_source_alias(
    *,
    source_id: str,
    expected_dataset_id: str,
    expected_root_run_id: str,
) -> None:
    """Reconcile one proven published alias under its exact dataset fence."""

    fence = await _resolve_provider_directory_artifact_datasets(
        [source_id],
        should_select_validated_candidates=False,
    )
    if len(fence.datasets) != 1:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_published_source_alias_fence_changed"
        )
    dataset = fence.datasets[0]
    if (
        dataset.source_id != source_id
        or dataset.dataset_id != expected_dataset_id
        or dataset.evidence_run_id != expected_root_run_id
        or dataset.status != ENDPOINT_DATASET_PUBLISHED
        or dataset.is_current is not True
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_published_source_alias_fence_changed"
        )
    if dataset.reconcile_source_alias_on_cutover:
        async with db.transaction():
            await _lock_and_verify_artifact_dataset_fence(fence)
            await _cutover_provider_directory_artifact_sources(fence)


def _reviewed_promotion_dataset_by_source_id(
    fence: ProviderDirectoryArtifactDatasetFence,
) -> dict[str, ProviderDirectoryArtifactDataset]:
    dataset_by_source_id: dict[str, ProviderDirectoryArtifactDataset] = {}
    for dataset in fence.source_alias_cutover_datasets:
        expected_verified_status = (
            PROVIDER_DIRECTORY_ROOT_POLICY_VERIFIED
            if dataset.reviewed_root_policy is not None
            else (
                PROVIDER_DIRECTORY_SUBSET_TWIN_ROOT_VERIFIED
                if dataset.completion_proof_required_version
                == SERVER_ISSUED_SUBSET_REQUIRED_VERSION
                else PROVIDER_DIRECTORY_TWIN_ROOT_VERIFIED
            )
        )
        if not (
            dataset.verification_source_status
            == expected_verified_status
            and dataset.verification_campaign_id
            and dataset.verification_source_scope_hash
            and dataset.verification_source_ids
            and (
                (
                    dataset.completion_proof_required_version
                    == SERVER_ISSUED_SUBSET_REQUIRED_VERSION
                    and dataset.completion_proof_sha256 is not None
                )
                or (
                    dataset.completion_proof_required_version is None
                    and dataset.completion_proof_sha256 is None
                )
            )
        ):
            continue
        for source_id in dataset.verification_source_ids:
            incumbent = dataset_by_source_id.setdefault(source_id, dataset)
            if incumbent.dataset_id != dataset.dataset_id:
                raise RuntimeError(
                    "provider_directory_artifact_promotion_source_ambiguous:"
                    + source_id
                )
    return dataset_by_source_id


def _validated_artifact_promotion_source(
    dataset: ProviderDirectoryArtifactDataset,
    source_row: Any,
) -> tuple[str, str, dict[str, Any]]:
    source_row_map = _pagination_checkpoint_row_mapping(source_row)
    source_id = _clean_text(source_row_map.get("source_id"))
    serving_endpoint_id = _clean_text(source_row_map.get("endpoint_id"))
    source_record = _json_object(source_row_map.get("source_record_json"))
    source_metadata = _source_metadata(source_record)
    source_root_policy = _artifact_reviewed_root_policy(
        source_record,
        (
            {
                REVIEWED_ROOT_POLICY_METADATA_KEY:
                    dataset.reviewed_root_policy.document()
            }
            if dataset.reviewed_root_policy is not None
            else {}
        ),
        dataset.dataset_id,
    )
    scope_source = _artifact_source_with_subset_contract(
        source_record,
        dataset.completion_proof_cutoff,
    )
    if (
        not source_id
        or not serving_endpoint_id
        or _clean_text(
            source_metadata.get("provider_directory_candidate_status")
        )
        != dataset.verification_source_status
        or _clean_text(
            source_metadata.get(
                PROVIDER_DIRECTORY_VERIFICATION_CAMPAIGN_METADATA_KEY
            )
        )
        != dataset.verification_campaign_id
        or _clean_text(
            source_metadata.get(
                PROVIDER_DIRECTORY_CONFIGURED_ENDPOINT_METADATA_KEY
            )
        )
        != dataset.endpoint_id
        or _endpoint_dataset_expected_resources([scope_source])
        != dataset.recorded_expected_resources
        or source_root_policy != dataset.reviewed_root_policy
    ):
        raise RuntimeError(
            "provider_directory_artifact_promotion_source_contract_invalid:"
            + (source_id or "missing")
        )
    return source_id, serving_endpoint_id, scope_source


def _artifact_promotion_alias_from_row(
    dataset: ProviderDirectoryArtifactDataset,
    source_row: Any,
) -> ProviderDirectoryArtifactDataset:
    """Bind one locked source alias to its reviewed promotion contract."""

    source_id, serving_endpoint_id, scope_source = (
        _validated_artifact_promotion_source(dataset, source_row)
    )
    source_contract = _artifact_source_verification_contract(
        scope_source,
        verification_campaign_id=dataset.verification_campaign_id,
        verification_source_scope_hash=dataset.verification_source_scope_hash,
        source_ids=dataset.verification_source_ids,
        completion_proof_cutoff=dataset.completion_proof_cutoff,
    )
    if source_contract[-1][1] != dataset.verification_source_scope_hash:
        raise RuntimeError(
            "provider_directory_artifact_promotion_source_scope_changed:"
            + source_id
        )
    return replace(
        dataset,
        source_id=source_id,
        serving_endpoint_id=serving_endpoint_id,
        source_verification_contract=source_contract,
        source_verification_contract_hash=_identity_hash(source_contract),
    )


async def _expand_reviewed_artifact_promotion_aliases(
    fence: ProviderDirectoryArtifactDatasetFence,
) -> ProviderDirectoryArtifactDatasetFence:
    dataset_by_source_id = _reviewed_promotion_dataset_by_source_id(fence)
    if not dataset_by_source_id:
        return fence
    source_ref = _qt(_schema(), ProviderDirectorySource.__tablename__)
    source_rows = await db.all(
        f"""
        SELECT source_id, endpoint_id, to_jsonb(source) AS source_record_json
          FROM {source_ref} AS source
         WHERE source_id = ANY(CAST(:source_ids AS varchar[]))
         ORDER BY source_id;
        """,
        source_ids=sorted(dataset_by_source_id),
    )
    promotion_aliases = tuple(
        _artifact_promotion_alias_from_row(
            dataset_by_source_id[source_id],
            source_row,
        )
        for source_row in source_rows
        if (source_id := _clean_text(
            _pagination_checkpoint_row_mapping(source_row).get("source_id")
        ))
        and source_id in dataset_by_source_id
    )
    if {alias.source_id for alias in promotion_aliases} != set(
        dataset_by_source_id
    ):
        raise RuntimeError(
            "provider_directory_artifact_promotion_source_alias_missing"
        )
    return replace(fence, promotion_aliases=promotion_aliases)


def _should_select_validated_artifacts(
    publish_artifacts_targets: set[str] | None,
) -> bool:
    """Select validated data only for a complete non-Profile serving bundle.

    Profile publication uses its separately attested global selection and
    capacity contract. Corroboration is an optional consumer of the serving
    bundle, so neither target may prevent the bundle from making a reviewed
    dataset current.
    """
    if publish_artifacts_targets is None:
        return True
    required_targets = set(PROVIDER_DIRECTORY_PUBLISH_ARTIFACT_TARGETS) - {
        "corroboration",
        "profile",
    }
    return required_targets.issubset(publish_artifacts_targets)


def _provider_directory_dataset_artifact_targets(
    publish_artifacts_targets: set[str] | None,
    *,
    publish_corroboration: bool,
) -> tuple[str, ...]:
    targets = [
        target
        for target in PROVIDER_DIRECTORY_PUBLISH_ARTIFACT_TARGETS
        if is_provider_directory_publish_target_enabled(publish_artifacts_targets, target)
        and (target != "corroboration" or publish_corroboration)
    ]
    return tuple(targets)


def _assert_provider_directory_artifact_target_dependencies(
    fence: ProviderDirectoryArtifactDatasetFence,
    *,
    publish_artifacts_targets: set[str] | None,
    publish_corroboration: bool,
) -> None:
    """Reject a target before scoped rows could omit its required evidence."""
    enabled_targets = _provider_directory_dataset_artifact_targets(
        publish_artifacts_targets,
        publish_corroboration=publish_corroboration,
    )
    if "corroboration" in enabled_targets:
        missing_prerequisites = [
            prerequisite_target
            for prerequisite_target in ("address_overlay", "network_catalog")
            if prerequisite_target not in enabled_targets
        ]
        if missing_prerequisites:
            raise RuntimeError(
                "provider_directory_artifact_corroboration_prerequisites_missing:"
                + ",".join(missing_prerequisites)
            )
    violations = _artifact_dataset_profile_violations(fence)
    violations.extend(
        _collect_artifact_target_dependency_violations(fence, enabled_targets)
    )
    if violations:
        raise RuntimeError(
            "provider_directory_artifact_target_dependencies_missing:"
            + ";".join(violations)
        )


def _artifact_dataset_profile_violations(
    fence: ProviderDirectoryArtifactDatasetFence,
) -> list[str]:
    """Return current datasets that cover less than their source profile."""
    violations: list[str] = []
    for dataset in fence.datasets:
        if dataset.selected_resources != dataset.expected_resources:
            violations.append(
                ":".join(
                    (
                        "dataset_profile",
                        dataset.source_id,
                        dataset.endpoint_id,
                        dataset.dataset_id,
                        ",".join(dataset.selected_resources),
                        ",".join(dataset.expected_resources),
                    )
                )
            )
        if (
            dataset.recorded_expected_resources is not None
            and dataset.recorded_expected_resources != dataset.expected_resources
        ):
            violations.append(
                ":".join(
                    (
                        "dataset_recorded_profile",
                        dataset.source_id,
                        dataset.endpoint_id,
                        dataset.dataset_id,
                        ",".join(dataset.recorded_expected_resources),
                        ",".join(dataset.expected_resources),
                    )
                )
            )
    return violations


def _provider_directory_artifact_resource_types(
    publish_artifacts_targets: set[str] | None,
    *,
    publish_corroboration: bool,
) -> frozenset[str]:
    """Return the immutable resource types read by enabled artifact targets."""
    enabled_targets = _provider_directory_dataset_artifact_targets(
        publish_artifacts_targets,
        publish_corroboration=publish_corroboration,
    )
    return frozenset().union(
        *(
            PROVIDER_DIRECTORY_ARTIFACT_TARGET_RESOURCE_TYPES[target]
            for target in enabled_targets
        )
    )


def _collect_artifact_target_dependency_violations(
    fence: ProviderDirectoryArtifactDatasetFence,
    enabled_targets: tuple[str, ...],
) -> list[str]:
    """Return source-specific artifact paths missing a complete alternative."""
    violations: list[str] = []
    sorted_datasets = sorted(
        fence.datasets,
        key=lambda dataset: (
            dataset.source_id,
            dataset.endpoint_id,
            dataset.dataset_id,
        ),
    )
    for artifact_target in enabled_targets:
        for dataset in sorted_datasets:
            violation = _artifact_target_dependency_violation(
                artifact_target,
                dataset,
            )
            if violation:
                violations.append(violation)
    return violations


def _artifact_target_dependency_violation(
    artifact_target: str,
    dataset: ProviderDirectoryArtifactDataset,
) -> str | None:
    """Return one missing artifact dependency or None when not applicable."""
    alternatives = PROVIDER_DIRECTORY_ARTIFACT_TARGET_RESOURCE_ALTERNATIVES[
        artifact_target
    ]
    selected_resources = set(dataset.selected_resources)
    if (
        artifact_target == "corroboration"
        and "InsurancePlan" not in selected_resources
    ):
        return None
    if not selected_resources.intersection(set().union(*alternatives)):
        return None
    if any(alternative.issubset(selected_resources) for alternative in alternatives):
        return None
    required_alternatives = "|".join(
        ",".join(sorted(alternative)) for alternative in alternatives
    )
    return ":".join(
        (
            artifact_target,
            dataset.source_id,
            dataset.endpoint_id,
            dataset.dataset_id,
            required_alternatives,
        )
    )


def _provider_directory_artifact_scope_row_limit() -> int:
    configured = _positive_int(
        os.getenv("HLTHPRT_PROVIDER_DIRECTORY_ARTIFACT_SCOPE_MAX_PROJECTED_ROWS")
    )
    return configured or DEFAULT_PROVIDER_DIRECTORY_ARTIFACT_SCOPE_MAX_PROJECTED_ROWS


def _provider_directory_artifact_scope_batch_size() -> int:
    configured = _positive_int(
        os.getenv("HLTHPRT_PROVIDER_DIRECTORY_ARTIFACT_SCOPE_BATCH_SIZE")
    )
    return (
        configured
        or DEFAULT_PROVIDER_DIRECTORY_ARTIFACT_SCOPE_BATCH_SIZE
    )


def _provider_directory_positive_config(
    env_name: str,
    default_value: int,
) -> tuple[int, bool]:
    raw_value = os.getenv(env_name)
    if raw_value is None or raw_value == "":
        return default_value, False
    configured_value = _positive_int(raw_value)
    if configured_value is None:
        raise RuntimeError(
            "provider_directory_positive_config_invalid:" + env_name
        )
    return configured_value, True


def _provider_directory_database_pool_capacity() -> int:
    capacity, _ = _provider_directory_positive_config(
        "HLTHPRT_DB_POOL_MAX_SIZE",
        5,
    )
    return capacity


def _provider_directory_artifact_scope_workers() -> int:
    capacity_admission = (
        _PROVIDER_DIRECTORY_PROFILE_CAPACITY_ADMISSION.get()
    )
    if capacity_admission is not None:
        return int(
            capacity_admission.geometry.artifact_scope_worker_count
        )
    requested_workers, explicitly_configured = (
        _provider_directory_positive_config(
            "HLTHPRT_PROVIDER_DIRECTORY_ARTIFACT_SCOPE_WORKERS",
            DEFAULT_PROVIDER_DIRECTORY_ARTIFACT_SCOPE_WORKERS,
        )
    )
    admitted_workers = min(
        MAX_PROVIDER_DIRECTORY_ARTIFACT_SCOPE_WORKERS,
        _provider_directory_database_pool_capacity() - 2,
    )
    if admitted_workers < 1 or (
        explicitly_configured and requested_workers > admitted_workers
    ):
        raise RuntimeError(
            "provider_directory_artifact_scope_worker_capacity_exceeded"
        )
    return min(requested_workers, admitted_workers)


def _artifact_scope_alias_counts(
    fence: ProviderDirectoryArtifactDatasetFence,
) -> dict[str, int]:
    """Count source aliases represented by each immutable dataset."""
    alias_count_by_dataset_id: dict[str, int] = {}
    for dataset in fence.datasets:
        alias_count_by_dataset_id[dataset.dataset_id] = (
            alias_count_by_dataset_id.get(dataset.dataset_id, 0) + 1
        )
    return alias_count_by_dataset_id


def _artifact_scope_resource_pairs(
    fence: ProviderDirectoryArtifactDatasetFence,
    resource_types: frozenset[str],
) -> list[tuple[str, str]]:
    """Return validated dataset and resource pairs needed by this publish."""
    return sorted(
        {
            (dataset.dataset_id, resource_type)
            for dataset in fence.datasets
            for resource_type in dataset.artifact_resources
            if resource_type in resource_types
        }
    )


async def _artifact_scope_resource_rows(
    dataset_resource_pairs: list[tuple[str, str]],
) -> list[Any]:
    """Count immutable rows for the exact validated dataset profile."""
    if not dataset_resource_pairs:
        return []
    return await db.all(
        f"""
        WITH selected(dataset_id, resource_type) AS (
            SELECT *
              FROM unnest(
                    CAST(:dataset_ids AS varchar[]),
                    CAST(:resource_types AS varchar[])
              )
        )
        SELECT resource.dataset_id,
               resource.resource_type,
               COUNT(*)::bigint AS resource_rows
          FROM {_qt(_schema(), ProviderDirectoryDatasetResource.__tablename__)}
               AS resource
          JOIN selected
            ON selected.dataset_id = resource.dataset_id
           AND selected.resource_type = resource.resource_type
         GROUP BY resource.dataset_id, resource.resource_type
         ORDER BY resource.dataset_id, resource.resource_type;
        """,
        dataset_ids=[pair[0] for pair in dataset_resource_pairs],
        resource_types=[pair[1] for pair in dataset_resource_pairs],
    )


def _artifact_scope_projection_summary(
    fence: ProviderDirectoryArtifactDatasetFence,
    resource_types: frozenset[str],
    alias_count_by_dataset_id: dict[str, int],
    resource_rows: list[Any],
) -> dict[str, Any]:
    """Summarize row and alias amplification before materialization."""
    dataset_rows = 0
    projected_rows = 0
    projected_rows_by_resource: dict[str, int] = {}
    for resource_row in resource_rows:
        resource_row_map = _pagination_checkpoint_row_mapping(resource_row)
        dataset_id = _clean_text(resource_row_map.get("dataset_id"))
        resource_type = _clean_text(resource_row_map.get("resource_type"))
        resource_count = int(resource_row_map.get("resource_rows") or 0)
        if not dataset_id or not resource_type:
            continue
        dataset_rows += resource_count
        projected_count = resource_count * alias_count_by_dataset_id.get(dataset_id, 0)
        projected_rows += projected_count
        projected_rows_by_resource[resource_type] = (
            projected_rows_by_resource.get(resource_type, 0) + projected_count
        )
    return {
        "dataset_count": len(alias_count_by_dataset_id),
        "alias_count": len(fence.datasets),
        "dataset_rows": dataset_rows,
        "projected_rows": projected_rows,
        "resource_types": sorted(resource_types),
        "alias_amplification": (
            projected_rows / dataset_rows if dataset_rows else 0.0
        ),
        "aliases_by_dataset": dict(sorted(alias_count_by_dataset_id.items())),
        "projected_rows_by_resource": dict(
            sorted(projected_rows_by_resource.items())
        ),
    }


async def _provider_directory_artifact_scope_projection(
    fence: ProviderDirectoryArtifactDatasetFence,
    resource_types: frozenset[str] | None = None,
) -> dict[str, Any]:
    """Project bounded immutable scope size for selected artifact targets."""
    scoped_resource_types = (
        resource_types
        if resource_types is not None
        else PROVIDER_DIRECTORY_ARTIFACT_RESOURCE_TYPES
    )
    alias_count_by_dataset_id = _artifact_scope_alias_counts(fence)
    resource_rows = await _artifact_scope_resource_rows(
        _artifact_scope_resource_pairs(fence, scoped_resource_types)
    )
    return _artifact_scope_projection_summary(
        fence,
        scoped_resource_types,
        alias_count_by_dataset_id,
        resource_rows,
    )


def _assert_provider_directory_artifact_scope_capacity(
    projection: dict[str, Any],
) -> None:
    projected_rows = int(projection["projected_rows"])
    capacity_admission = (
        _PROVIDER_DIRECTORY_PROFILE_CAPACITY_ADMISSION.get()
    )
    capacity = (
        int(capacity_admission.geometry.max_artifact_scope_rows)
        if capacity_admission is not None
        else _provider_directory_artifact_scope_row_limit()
    )
    if capacity_admission is not None and projected_rows != capacity:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_profile_artifact_projection_changed:"
            f"projected={projected_rows}:admitted={capacity}"
        )
    if projected_rows > capacity:
        raise RuntimeError(
            "provider_directory_artifact_scope_projected_rows_exceeded:"
            f"projected={projected_rows}:capacity={capacity}"
        )


def _assert_artifact_scope_projection(
    projection: _ProviderDirectoryArtifactScopeExactProjection,
) -> None:
    """Bind the exact typed scope projection to the signed admission."""

    admission = _provider_directory_profile_capacity_admission()
    if admission is None:
        if (
            projection.projected_rows
            > _provider_directory_artifact_scope_row_limit()
        ):
            raise RuntimeError(
                "provider_directory_artifact_scope_projected_rows_exceeded"
            )
        return
    geometry = admission.geometry
    if (
        projection.projected_rows != geometry.max_artifact_scope_rows
        or projection.projected_logical_bytes
        != geometry.artifact_scope_projected_logical_bytes
        or projection.projection_hash
        != geometry.artifact_scope_projection_hash
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_profile_artifact_projection_changed"
        )


async def _discover_provider_directory_artifact_scope_tables(
    schema: str,
) -> list[str]:
    """Return prior scratch tables without mutating admitted state."""

    prefixes = tuple(
        sorted(
            {
                _provider_directory_artifact_scope_table_prefix(
                    model.__tablename__
                )
                + "_"
                for model in (ProviderDirectorySource, *RESOURCE_MODELS)
            }
        )
    )
    table_rows = await db.all(
        """
        SELECT tablename
          FROM pg_tables
         WHERE schemaname = :schema_name
           AND tablename LIKE ANY(CAST(:scope_patterns AS text[]))
         ORDER BY tablename;
        """,
        schema_name=schema,
        scope_patterns=[f"{prefix}%" for prefix in prefixes],
    )
    table_names = sorted(
        table_name
        for table_row in table_rows
        if (table_name := _clean_text(
            _pagination_checkpoint_row_mapping(table_row).get("tablename")
        ))
        and any(table_name.startswith(prefix) for prefix in prefixes)
    )
    return table_names


async def _reap_provider_directory_artifact_scope_tables(schema: str) -> list[str]:
    table_names = await _discover_provider_directory_artifact_scope_tables(
        schema
    )
    for table_name in table_names:
        await _provider_directory_profile_capacity_status(
            f"DROP TABLE IF EXISTS {_qt(schema, table_name)};"
        )
    return table_names


@contextlib.asynccontextmanager
async def _provider_directory_artifact_scope_guard(schema: str) -> AsyncIterator[None]:
    """Serialize scoped table ownership so prefix cleanup cannot reap live work."""
    async with _provider_directory_artifact_build_guard(
        schema,
        "provider_directory_artifact_scope",
    ):
        yield


def _provider_directory_artifact_scope_table_name(
    table_name: str,
    run_id: str | None,
) -> str:
    admission = _provider_directory_profile_capacity_admission()
    if admission is not None:
        if run_id != admission.run_id:
            raise RuntimeError(
                "provider_directory_artifact_scope_owner_run_changed"
            )
        return _owned_artifact_scope_name(
            table_name,
            run_id=admission.run_id,
        )
    identity = (
        f"{table_name}:{run_id or 'artifact'}:{os.getpid()}:"
        f"{time.time_ns()}:{os.urandom(8).hex()}"
    )
    digest = hashlib.sha1(identity.encode("utf-8")).hexdigest()[:16]
    return (
        _provider_directory_artifact_scope_table_prefix(table_name)
        + "_"
        + digest
    )


def _provider_directory_artifact_scope_table_prefix(
    table_name: str,
) -> str:
    """Return one stable, discoverable prefix with room for owner identity."""

    raw_prefix = f"{table_name}_artifact_scope"
    maximum_prefix_length = POSTGRES_IDENTIFIER_MAX_LENGTH - 33
    if len(raw_prefix) <= maximum_prefix_length:
        return raw_prefix
    digest = hashlib.sha1(table_name.encode("utf-8")).hexdigest()[:8]
    readable_length = maximum_prefix_length - len(digest) - 1
    return f"{raw_prefix[:readable_length]}_{digest}"


def _owned_artifact_scope_name(
    table_name: str,
    *,
    run_id: str,
) -> str:
    """Bind one scratch name to its exact immutable control-run owner."""

    owner_match = re.fullmatch(r"run_([0-9a-f]{32})", run_id)
    if owner_match is None:
        raise RuntimeError(
            "provider_directory_artifact_scope_owner_identity_invalid"
        )
    return (
        _provider_directory_artifact_scope_table_prefix(table_name)
        + "_"
        + owner_match.group(1)
    )


@dataclass(frozen=True)
class _ArtifactScopeConsumptionOwner:
    run_id: str
    build_id: str
    capacity_geometry_hash: str
    status: str
    finished_at: Any
    consumption: dict[str, Any]


def _artifact_scope_owner_from_row(
    owner_row: Any,
) -> _ArtifactScopeConsumptionOwner:
    """Validate one immutable scratch-owner ledger row."""

    owner_map = dict(_pagination_checkpoint_row_mapping(owner_row))
    run_id = _clean_text(owner_map.get("run_id"))
    build_id = _clean_text(owner_map.get("build_id"))
    geometry_hash = _clean_text(
        owner_map.get("capacity_geometry_hash")
    )
    status = _clean_text(owner_map.get("status"))
    if (
        run_id is None
        or build_id is None
        or geometry_hash is None
        or status is None
        or _clean_text(owner_map.get("importer"))
        != "provider-directory-fhir"
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_scope_owner_invalid"
        )
    return _ArtifactScopeConsumptionOwner(
        run_id=run_id,
        build_id=build_id,
        capacity_geometry_hash=geometry_hash,
        status=status,
        finished_at=owner_map.get("finished_at"),
        consumption=owner_map,
    )


def _artifact_scope_owner_relation_names(
    owner: _ArtifactScopeConsumptionOwner,
) -> dict[str, str]:
    """Return every exact relation name owned by one consumed lease."""

    return {
        model.__tablename__: _owned_artifact_scope_name(
            model.__tablename__,
            run_id=owner.run_id,
        )
        for model in (ProviderDirectorySource, *RESOURCE_MODELS)
    }


async def _artifact_scope_owner_rows(
    schema: str,
    owner_run_ids: tuple[str, ...],
) -> tuple[_ArtifactScopeConsumptionOwner, ...]:
    """Load a bounded exact set of scratch owners from immutable capacity use."""
    consumption_ref = _unscoped_qt(
        schema,
        ProviderDirectoryProfileCapacityLeaseConsumption.__tablename__,
    )
    import_run_ref = _unscoped_qt(schema, ImportRun.__tablename__)
    owner_rows = await db.all(
        f"""
        SELECT consumption.attestation_id,
               consumption.lease_digest,
               consumption.capacity_geometry_hash,
               consumption.executable_plan_hash,
               consumption.selection_proof_id,
               consumption.source_vector_hash,
               consumption.source_context_vector_hash,
               consumption.run_id,
               consumption.build_id,
               consumption.profile_as_of,
               control.importer,
               control.status,
               control.finished_at
          FROM {consumption_ref} AS consumption
          LEFT JOIN {import_run_ref} AS control
            ON control.run_id = consumption.run_id
         WHERE consumption.run_id = ANY(CAST(:owner_run_ids AS varchar[]))
         ORDER BY consumption.run_id;
        """,
        owner_run_ids=list(owner_run_ids),
    )
    return tuple(
        _artifact_scope_owner_from_row(owner_row)
        for owner_row in owner_rows
    )


def _current_artifact_scope_owner(
    owners: tuple[_ArtifactScopeConsumptionOwner, ...],
    admission: _ProviderDirectoryProfileCapacityAdmission,
) -> _ArtifactScopeConsumptionOwner:
    """Return the one exact current run owner or refuse ledger drift."""
    current_owners = tuple(
        owner for owner in owners if owner.run_id == admission.run_id
    )
    expected_consumption = _expected_profile_capacity_consumption(admission)
    if len(current_owners) != 1 or {
        field_name: current_owners[0].consumption.get(field_name)
        for field_name in expected_consumption
    } != expected_consumption:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_scope_current_owner_invalid"
        )
    if current_owners[0].status != "running":
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_scope_current_owner_inactive"
        )
    return current_owners[0]


def _assert_prior_artifact_scope_owners_terminal(
    owners: tuple[_ArtifactScopeConsumptionOwner, ...],
    current_run_id: str,
) -> None:
    terminal_statuses = {
        "succeeded",
        "failed",
        "canceled",
        "cancelled",
        "dead_letter",
    }
    if any(
        owner.status not in terminal_statuses
        or owner.finished_at is None
        for owner in owners
        if owner.run_id != current_run_id
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_profile_capacity_competing_owner"
        )


async def _artifact_scope_consumption_owners(
    schema: str,
    admission: _ProviderDirectoryProfileCapacityAdmission,
    prior_run_ids: Iterable[str],
) -> tuple[_ArtifactScopeConsumptionOwner, ...]:
    """Validate current and exact prior owners of one bounded scratch set."""
    owner_run_ids = tuple(
        sorted({admission.run_id, *prior_run_ids})
    )
    if len(owner_run_ids) > 2:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_scope_owner_ambiguous"
        )
    owners = await _artifact_scope_owner_rows(schema, owner_run_ids)
    if {owner.run_id for owner in owners} != set(owner_run_ids):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_scope_owner_invalid"
        )
    _current_artifact_scope_owner(owners, admission)
    _assert_prior_artifact_scope_owners_terminal(
        owners,
        admission.run_id,
    )
    return owners


def _provider_directory_artifact_scope_table_sql(
    model: Any,
    schema: str,
    table_name: str,
) -> str:
    dialect = postgresql.dialect()
    column_definitions = [
        str(CreateColumn(column).compile(dialect=dialect)).strip()
        for column in model.__table__.columns
    ]
    return (
        f"CREATE UNLOGGED TABLE {_qt(schema, table_name)} (\n    "
        + ",\n    ".join(column_definitions)
        + "\n);"
    )


def _artifact_scope_pk_names(
    table_name: str,
) -> tuple[str, str]:
    return (
        _bounded_identifier(f"{table_name}_pk_build_idx"),
        _bounded_identifier(f"{table_name}_pkey"),
    )


def _artifact_scope_pk_sql(
    model: Any,
    schema: str,
    table_name: str,
) -> tuple[str, ...]:
    primary_key_columns = [
        _q(column.name) for column in model.__table__.primary_key.columns
    ]
    if not primary_key_columns:
        return ()
    index_name, constraint_name = _artifact_scope_pk_names(table_name)
    column_sql = ", ".join(primary_key_columns)
    return (
        f"CREATE UNIQUE INDEX {_q(index_name)} "
        f"ON {_qt(schema, table_name)} ({column_sql});",
        f"ALTER TABLE {_qt(schema, table_name)} "
        f"ADD CONSTRAINT {_q(constraint_name)} PRIMARY KEY "
        f"USING INDEX {_q(index_name)};",
    )


async def _build_artifact_scope_pk(
    model: Any,
    schema: str,
    table_name: str,
    *,
    status_executor: Callable[..., Awaitable[Any]] | None = None,
) -> None:
    execute_status = (
        status_executor
        or _provider_directory_profile_capacity_status
    )
    for statement in _artifact_scope_pk_sql(
        model,
        schema,
        table_name,
    ):
        await execute_status(statement)


async def _create_provider_directory_artifact_scope_layout(
    model: Any,
    schema: str,
    table_name: str,
    *,
    status_executor: Callable[..., Awaitable[Any]] | None = None,
) -> None:
    """Create the complete empty layout before any scope payload write."""

    execute_status = (
        status_executor
        or _provider_directory_profile_capacity_status
    )
    await execute_status(
        _provider_directory_artifact_scope_table_sql(
            model,
            schema,
            table_name,
        )
    )
    await _build_artifact_scope_pk(
        model,
        schema,
        table_name,
        status_executor=execute_status,
    )
    if model in {
        ProviderDirectoryPractitionerRole,
        ProviderDirectoryOrganizationAffiliation,
    }:
        _index_name, index_sql = (
            _provider_directory_profile_bucket_index_sql(
                schema,
                table_name,
            )
        )
        await execute_status(index_sql)


def _provider_directory_artifact_payload_column_sql(column: Any) -> str:
    column_name = column.name
    if column_name == "source_id":
        return "selected.source_id"
    if column_name == "resource_id":
        return "resource.resource_id"
    if column_name == "last_seen_run_id":
        return "selected.evidence_run_id"
    if column_name in {"observed_at", "updated_at"}:
        return (
            "COALESCE(dataset.published_at, dataset.validated_at, "
            "dataset.created_at)"
        )
    json_key = _sql_string_literal(column_name)
    payload_expr = f"resource.payload_json::jsonb -> {json_key}"
    if isinstance(column.type, SQLAlchemyJSON):
        return f"CAST({payload_expr} AS json)"
    column_type = column.type.compile(dialect=postgresql.dialect())
    return (
        f"CAST(resource.payload_json::jsonb ->> {json_key} AS {column_type})"
    )


def _provider_directory_artifact_source_select_sql(
    model: Any,
    schema: str,
) -> str:
    """Select the exact typed source rows used by count and insert."""

    columns = ", ".join(
        f"source.{_q(column.name)}" for column in model.__table__.columns
    )
    return f"""
        SELECT {columns}
          FROM {_qt(schema, model.__tablename__)} AS source
         WHERE source.source_id = ANY(CAST(:source_ids AS varchar[]))
         ORDER BY source.source_id
    """.strip()


def _provider_directory_artifact_source_insert_sql(
    model: Any,
    schema: str,
    table_name: str,
) -> str:
    """Insert the exact typed source-row SELECT used by projection."""

    columns = ", ".join(_q(column.name) for column in model.__table__.columns)
    select_sql = _provider_directory_artifact_source_select_sql(
        model,
        schema,
    )
    return f"""
        INSERT INTO {_qt(schema, table_name)} ({columns})
        {select_sql};
    """


def _provider_directory_artifact_projection_count_sql(
    select_sql: str,
    *,
    cursor_column: str | None = None,
) -> str:
    """Measure one exact projected SELECT without materializing its payload."""

    cursor_projection = (
        f",\n               MAX({_q(cursor_column)})::varchar AS last_cursor"
        if cursor_column is not None
        else ""
    )
    return f"""
        WITH projected_rows AS MATERIALIZED (
            {select_sql}
        )
        SELECT COUNT(*)::bigint AS projected_rows,
               COALESCE(
                   SUM(pg_column_size(projected_rows)),
                   0
               )::bigint AS projected_logical_bytes{cursor_projection}
          FROM projected_rows;
    """


def _provider_directory_artifact_source_projection_sql(
    model: Any,
    schema: str,
) -> str:
    """Measure the same typed source-row SELECT used by materialization."""

    return _provider_directory_artifact_projection_count_sql(
        _provider_directory_artifact_source_select_sql(model, schema)
    )


def _provider_directory_artifact_resource_select_sql(
    model: Any,
    schema: str,
) -> str:
    """Select the exact typed resource rows used by the unbounded insert."""

    columns = list(model.__table__.columns)
    selected_columns = ",\n            ".join(
        _provider_directory_artifact_payload_column_sql(column)
        for column in columns
    )
    return f"""
        WITH selected(source_id, dataset_id, evidence_run_id) AS (
            SELECT *
              FROM unnest(
                    CAST(:source_ids AS varchar[]),
                    CAST(:dataset_ids AS varchar[]),
                    CAST(:evidence_run_ids AS varchar[])
              )
        )
        SELECT {selected_columns}
          FROM selected
          JOIN {_qt(schema, ProviderDirectoryEndpointDataset.__tablename__)} AS dataset
            ON dataset.dataset_id = selected.dataset_id
          JOIN {_qt(schema, ProviderDirectoryDatasetResource.__tablename__)} AS resource
            ON resource.dataset_id = selected.dataset_id
           AND resource.resource_type = :resource_type
    """.strip()


def _provider_directory_artifact_resource_insert_sql(
    model: Any,
    schema: str,
    table_name: str,
) -> str:
    columns = list(model.__table__.columns)
    column_names = ", ".join(_q(column.name) for column in columns)
    select_sql = _provider_directory_artifact_resource_select_sql(
        model,
        schema,
    )
    return f"""
        INSERT INTO {_qt(schema, table_name)} ({column_names})
        {select_sql};
    """


def _artifact_resource_batch_select_sql(
    model: Any,
    schema: str,
) -> str:
    """Select the exact typed keyset batch used by count and insert."""

    columns = list(model.__table__.columns)
    selected_columns = ",\n            ".join(
        _provider_directory_artifact_payload_column_sql(column)
        for column in columns
    )
    return f"""
        WITH selected(source_id, dataset_id, evidence_run_id) AS (
            VALUES (
                CAST(:source_id AS varchar),
                CAST(:dataset_id AS varchar),
                CAST(:evidence_run_id AS varchar)
            )
        ), resource_batch AS MATERIALIZED (
            SELECT resource.*
              FROM {_qt(schema, ProviderDirectoryDatasetResource.__tablename__)}
                   AS resource
             WHERE resource.dataset_id = CAST(:dataset_id AS varchar)
               AND resource.resource_type = CAST(:resource_type AS varchar)
               AND (
                    CAST(:after_resource_id AS varchar) IS NULL
                    OR resource.resource_id
                       > CAST(:after_resource_id AS varchar)
               )
             ORDER BY resource.resource_id
             LIMIT CAST(:scope_batch_size AS integer)
        )
        SELECT {selected_columns}
          FROM selected
          JOIN {_qt(schema, ProviderDirectoryEndpointDataset.__tablename__)}
               AS dataset
            ON dataset.dataset_id = selected.dataset_id
          JOIN resource_batch AS resource
            ON resource.dataset_id = selected.dataset_id
         ORDER BY resource.resource_id
    """.strip()


def _artifact_resource_batch_insert_sql(
    model: Any,
    schema: str,
    table_name: str,
) -> str:
    """Build one keyset-bounded immutable dataset projection insert."""

    columns = list(model.__table__.columns)
    column_names = ", ".join(_q(column.name) for column in columns)
    select_sql = _artifact_resource_batch_select_sql(
        model,
        schema,
    )
    return f"""
        INSERT INTO {_qt(schema, table_name)} ({column_names})
        {select_sql};
    """


def _artifact_resource_batch_projection_sql(
    model: Any,
    schema: str,
) -> str:
    """Measure the same typed resource batch used by materialization."""

    return _provider_directory_artifact_projection_count_sql(
        _artifact_resource_batch_select_sql(
            model,
            schema,
        ),
        cursor_column="resource_id",
    )


def _provider_directory_artifact_projection_values(
    row: Any,
) -> tuple[int, int, str | None]:
    """Normalize one exact projection result and reject invalid counters."""

    row_map = _pagination_checkpoint_row_mapping(row)
    projected_rows = int(row_map.get("projected_rows") or 0)
    projected_logical_bytes = int(
        row_map.get("projected_logical_bytes") or 0
    )
    if projected_rows < 0 or projected_logical_bytes < 0:
        raise RuntimeError(
            "provider_directory_artifact_scope_projection_invalid"
        )
    return (
        projected_rows,
        projected_logical_bytes,
        _clean_text(row_map.get("last_cursor")),
    )


async def _provider_directory_artifact_source_exact_projection(
    schema: str,
    source_ids: list[str],
) -> _ProviderDirectoryArtifactScopeTableProjection:
    """Project the exact ProviderDirectorySource rows and logical bytes."""

    model = ProviderDirectorySource
    projection_sql = _provider_directory_artifact_source_projection_sql(
        model,
        schema,
    )
    batches: list[_ProviderDirectoryArtifactScopeBatchProjection] = []
    for batch_number, source_id in enumerate(
        sorted(set(source_ids)),
        start=1,
    ):
        projection_row = await db.first(
            projection_sql,
            source_ids=[source_id],
        )
        batch_rows, batch_logical_bytes, _ = (
            _provider_directory_artifact_projection_values(projection_row)
        )
        if batch_rows != 1:
            raise ProviderDirectoryArtifactBuildStale(
                "provider_directory_artifact_source_projection_changed"
            )
        batches.append(
            _ProviderDirectoryArtifactScopeBatchProjection(
                batch_number=batch_number,
                source_id=source_id,
                dataset_id=None,
                evidence_run_id=None,
                resource_type="source",
                after_resource_id=None,
                last_resource_id=None,
                projected_rows=batch_rows,
                projected_logical_bytes=batch_logical_bytes,
            )
        )
    return _ProviderDirectoryArtifactScopeTableProjection(
        table_name=model.__tablename__,
        resource_type="source",
        projected_rows=sum(batch.projected_rows for batch in batches),
        projected_logical_bytes=sum(
            batch.projected_logical_bytes for batch in batches
        ),
        batches=tuple(batches),
    )


async def _artifact_resource_projection_batch(
    schema: str,
    model: Any,
    dataset: ProviderDirectoryArtifactDataset,
    resource_type: str,
    *,
    batch_size: int,
    after_resource_id: str | None,
    batch_number: int,
) -> _ProviderDirectoryArtifactScopeBatchProjection:
    """Project and validate one typed resource keyset batch."""

    projection_row = await db.first(
        _artifact_resource_batch_projection_sql(model, schema),
        source_id=dataset.source_id,
        dataset_id=dataset.dataset_id,
        evidence_run_id=dataset.evidence_run_id,
        resource_type=resource_type,
        after_resource_id=after_resource_id,
        scope_batch_size=batch_size,
    )
    batch_rows, batch_logical_bytes, next_resource_id = (
        _provider_directory_artifact_projection_values(projection_row)
    )
    if batch_rows > batch_size:
        raise RuntimeError(
            "provider_directory_artifact_scope_batch_row_count_invalid"
        )
    if batch_rows == 0 and (
        batch_logical_bytes != 0 or next_resource_id is not None
    ):
        raise RuntimeError(
            "provider_directory_artifact_scope_terminal_projection_invalid"
        )
    if batch_rows > 0 and (
        next_resource_id is None
        or next_resource_id == after_resource_id
    ):
        raise RuntimeError(
            "provider_directory_artifact_scope_batch_cursor_invalid"
        )
    return _ProviderDirectoryArtifactScopeBatchProjection(
        batch_number=batch_number,
        source_id=dataset.source_id,
        dataset_id=dataset.dataset_id,
        evidence_run_id=dataset.evidence_run_id,
        resource_type=resource_type,
        after_resource_id=after_resource_id,
        last_resource_id=next_resource_id,
        projected_rows=batch_rows,
        projected_logical_bytes=batch_logical_bytes,
    )


async def _artifact_resource_dataset_exact_projection(
    schema: str,
    model: Any,
    dataset: ProviderDirectoryArtifactDataset,
    resource_type: str,
    *,
    batch_size: int,
) -> tuple[
    int,
    int,
    tuple[_ProviderDirectoryArtifactScopeBatchProjection, ...],
]:
    """Project one alias-aware resource dataset in exact keyset batches."""

    batches: list[_ProviderDirectoryArtifactScopeBatchProjection] = []
    after_resource_id: str | None = None
    while True:
        batch = await _artifact_resource_projection_batch(
            schema,
            model,
            dataset,
            resource_type,
            batch_size=batch_size,
            after_resource_id=after_resource_id,
            batch_number=len(batches) + 1,
        )
        batches.append(batch)
        if batch.projected_rows == 0:
            break
        after_resource_id = batch.last_resource_id
    return (
        sum(batch.projected_rows for batch in batches),
        sum(batch.projected_logical_bytes for batch in batches),
        tuple(batches),
    )


async def _provider_directory_artifact_resource_exact_projection(
    schema: str,
    model: Any,
    fence: ProviderDirectoryArtifactDatasetFence,
    resource_types: frozenset[str],
    *,
    batch_size: int,
) -> _ProviderDirectoryArtifactScopeTableProjection:
    """Project one resource scope table across all selected aliases."""

    resource_type = RESOURCE_TYPES_BY_MODEL[model]
    projected_rows = 0
    projected_logical_bytes = 0
    batches: list[_ProviderDirectoryArtifactScopeBatchProjection] = []
    selected_datasets = sorted(
        (
            dataset
            for dataset in fence.datasets
            if resource_type in resource_types
            and resource_type in dataset.artifact_resources
        ),
        key=lambda item: (item.source_id, item.dataset_id),
    )
    for dataset in selected_datasets:
        dataset_rows, dataset_logical_bytes, dataset_batches = (
            await _artifact_resource_dataset_exact_projection(
                schema,
                model,
                dataset,
                resource_type,
                batch_size=batch_size,
            )
        )
        projected_rows += dataset_rows
        projected_logical_bytes += dataset_logical_bytes
        batches.extend(dataset_batches)
    return _ProviderDirectoryArtifactScopeTableProjection(
        table_name=model.__tablename__,
        resource_type=resource_type,
        projected_rows=projected_rows,
        projected_logical_bytes=projected_logical_bytes,
        batches=tuple(batches),
    )


async def _provider_directory_artifact_scope_exact_projection(
    schema: str,
    fence: ProviderDirectoryArtifactDatasetFence,
    resource_types: frozenset[str],
    *,
    source_fence: ProviderDirectoryArtifactDatasetFence | None = None,
    batch_size: int | None = None,
) -> _ProviderDirectoryArtifactScopeExactProjection:
    """Return a canonical exact projection for source and resource tables."""

    resolved_batch_size = (
        batch_size or _provider_directory_artifact_scope_batch_size()
    )
    resolved_source_fence = source_fence or fence
    source_projection = (
        await _provider_directory_artifact_source_exact_projection(
            schema,
            [
                dataset.source_id
                for dataset in resolved_source_fence.datasets
            ],
        )
    )
    resource_projections: list[
        _ProviderDirectoryArtifactScopeTableProjection
    ] = []
    for model in RESOURCE_MODELS:
        resource_projections.append(
            await _provider_directory_artifact_resource_exact_projection(
                schema,
                model,
                fence,
                resource_types,
                batch_size=resolved_batch_size,
            )
        )
    return _ProviderDirectoryArtifactScopeExactProjection(
        tables=(source_projection, *tuple(resource_projections))
    )


def _assert_artifact_source_batches(
    source_ids: list[str],
    projection: _ProviderDirectoryArtifactScopeTableProjection,
) -> None:
    """Refuse an incomplete or reordered signed source write plan."""

    expected_source_ids = sorted(set(source_ids))
    if (
        projection.resource_type != "source"
        or len(projection.batches) != len(expected_source_ids)
    ):
        raise RuntimeError(
            "provider_directory_artifact_scope_batch_projection_invalid"
        )
    for batch_number, (source_id, batch) in enumerate(
        zip(
            expected_source_ids,
            projection.batches,
            strict=True,
        ),
        start=1,
    ):
        if (
            batch.batch_number != batch_number
            or batch.source_id != source_id
            or batch.dataset_id is not None
            or batch.evidence_run_id is not None
            or batch.resource_type != "source"
            or batch.after_resource_id is not None
            or batch.last_resource_id is not None
            or batch.projected_rows != 1
            or batch.projected_logical_bytes < 1
        ):
            raise RuntimeError(
                "provider_directory_artifact_scope_batch_projection_invalid"
            )


def _assert_artifact_resource_batches(
    dataset: ProviderDirectoryArtifactDataset,
    resource_type: str,
    projection_batches: tuple[
        _ProviderDirectoryArtifactScopeBatchProjection,
        ...,
    ],
    *,
    batch_size: int,
) -> None:
    """Require a complete ordered plan ending in one signed zero probe."""

    if not projection_batches:
        raise RuntimeError(
            "provider_directory_artifact_scope_batch_projection_invalid"
        )
    after_resource_id: str | None = None
    for batch_number, batch in enumerate(projection_batches, start=1):
        is_terminal = batch_number == len(projection_batches)
        if (
            batch.batch_number != batch_number
            or batch.source_id != dataset.source_id
            or batch.dataset_id != dataset.dataset_id
            or batch.evidence_run_id != dataset.evidence_run_id
            or batch.resource_type != resource_type
            or batch.after_resource_id != after_resource_id
        ):
            raise RuntimeError(
                "provider_directory_artifact_scope_batch_projection_invalid"
            )
        if is_terminal:
            if (
                batch.projected_rows != 0
                or batch.projected_logical_bytes != 0
                or batch.last_resource_id is not None
            ):
                raise RuntimeError(
                    "provider_directory_artifact_scope_terminal_projection_invalid"
                )
            continue
        if (
            not 1 <= batch.projected_rows <= batch_size
            or batch.projected_logical_bytes < 1
            or batch.last_resource_id is None
            or batch.last_resource_id == after_resource_id
        ):
            raise RuntimeError(
                "provider_directory_artifact_scope_batch_projection_invalid"
            )
        after_resource_id = batch.last_resource_id


def _artifact_source_scope_batches(
    source_ids: Iterable[str],
    projection: _ProviderDirectoryArtifactScopeTableProjection | None,
) -> tuple[_ProviderDirectoryArtifactScopeBatchProjection, ...]:
    """Return frozen or synthetic source-scope batches."""
    if projection is not None:
        return projection.batches
    return tuple(
        _ProviderDirectoryArtifactScopeBatchProjection(
            batch_number=batch_number,
            source_id=source_id,
            dataset_id=None,
            evidence_run_id=None,
            resource_type="source",
            after_resource_id=None,
            last_resource_id=None,
            projected_rows=-1,
            projected_logical_bytes=0,
        )
        for batch_number, source_id in enumerate(
            sorted(set(source_ids)),
            start=1,
        )
    )


def _validate_artifact_source_batch(
    batch: _ProviderDirectoryArtifactScopeBatchProjection,
    expected_batch_number: int,
) -> None:
    """Require one source batch to retain its frozen coordinate."""
    if (
        batch.batch_number != expected_batch_number
        or batch.resource_type != "source"
        or batch.dataset_id is not None
        or batch.evidence_run_id is not None
        or batch.after_resource_id is not None
        or batch.last_resource_id is not None
    ):
        raise RuntimeError(
            "provider_directory_artifact_scope_batch_projection_invalid"
        )


async def _insert_artifact_source_batch(
    batch: _ProviderDirectoryArtifactScopeBatchProjection,
    projection: _ProviderDirectoryArtifactScopeTableProjection | None,
    projection_sql: str,
    insert_sql: str,
) -> int:
    """Validate and insert one source-scope batch under admission."""
    if projection is not None:
        projection_row = await db.first(
            projection_sql,
            source_ids=[batch.source_id],
        )
        observed_rows, observed_bytes, observed_cursor = (
            _provider_directory_artifact_projection_values(projection_row)
        )
        if (
            observed_rows != batch.projected_rows
            or observed_bytes != batch.projected_logical_bytes
            or observed_cursor is not None
        ):
            raise ProviderDirectoryArtifactBuildStale(
                "provider_directory_artifact_source_projection_changed"
            )
    return _coerce_rowcount(
        await db.status(insert_sql, source_ids=[batch.source_id])
    )


async def _execute_artifact_source_batch(
    batch: _ProviderDirectoryArtifactScopeBatchProjection,
    projection: _ProviderDirectoryArtifactScopeTableProjection | None,
    projection_sql: str,
    insert_sql: str,
) -> int:
    """Execute one source batch through its capacity-safe path."""
    admission = _provider_directory_profile_capacity_admission()
    if projection is None:
        return _coerce_rowcount(
            await _provider_directory_profile_capacity_status(
                insert_sql,
                source_ids=[batch.source_id],
            )
        )
    if admission is not None:
        await _reserve_provider_directory_profile_wal_budget(
            admission,
            control_operation_counts={"artifact_scope_payload": 1},
        )
        async with _provider_directory_profile_capacity_transaction():
            return await _insert_artifact_source_batch(
                batch, projection, projection_sql, insert_sql
            )
    return await _insert_artifact_source_batch(
        batch, projection, projection_sql, insert_sql
    )


async def _analyze_artifact_scope_table(
    schema: str,
    table_name: str,
) -> None:
    """Analyze one artifact-scope table under its signed WAL budget."""
    admission = _provider_directory_profile_capacity_admission()
    if admission is not None:
        await _reserve_provider_directory_profile_wal_budget(
            admission,
            control_operation_counts={"artifact_scope_analyze": 1},
        )
    await _provider_directory_profile_capacity_status(
        f"ANALYZE {_qt(schema, table_name)};"
    )


async def _materialize_provider_directory_artifact_source_scope(
    schema: str,
    table_name: str,
    source_ids: list[str],
    *,
    projection: (
        _ProviderDirectoryArtifactScopeTableProjection | None
    ) = None,
) -> int:
    """Materialize the exact bounded source rows for an artifact scope."""

    model = ProviderDirectorySource
    insert_sql = _provider_directory_artifact_source_insert_sql(
        model,
        schema,
        table_name,
    )
    projection_sql = _provider_directory_artifact_source_projection_sql(
        model,
        schema,
    )
    if projection is not None:
        _assert_provider_directory_artifact_source_projection_batches(
            source_ids,
            projection,
        )
    batches = _artifact_source_scope_batches(source_ids, projection)
    total_rows = 0
    for expected_batch_number, batch in enumerate(batches, start=1):
        if projection is not None:
            _validate_artifact_source_batch(batch, expected_batch_number)
        inserted_rows = await _execute_artifact_source_batch(
            batch,
            projection,
            projection_sql,
            insert_sql,
        )
        if (
            inserted_rows < 0
            or (
                projection is not None
                and inserted_rows != batch.projected_rows
            )
        ):
            raise ProviderDirectoryArtifactBuildStale(
                "provider_directory_artifact_source_projection_changed"
            )
        total_rows += inserted_rows
    if (
        projection is not None
        and total_rows != projection.projected_rows
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_source_projection_changed"
        )
    await _analyze_artifact_scope_table(schema, table_name)
    return total_rows


@dataclass
class _ArtifactResourceMaterializationState:
    after_resource_id: str | None = None
    total_rows: int = 0
    batch_number: int = 0
    expected_batch_number: int = 0
    is_terminal_projection_observed: bool = False


@dataclass(frozen=True)
class _ArtifactResourceMaterializationContext:
    schema: str
    table_name: str
    model: Any
    dataset: ProviderDirectoryArtifactDataset
    resource_type: str
    insert_sql: str
    batch_size: int


_ArtifactScopeBatchProjectionPlan = tuple[
    _ProviderDirectoryArtifactScopeBatchProjection,
    ...,
]


def _validate_artifact_resource_batch_coordinate(
    expected_batch: _ProviderDirectoryArtifactScopeBatchProjection | None,
    state: _ArtifactResourceMaterializationState,
    dataset: ProviderDirectoryArtifactDataset,
    resource_type: str,
) -> None:
    """Require one projected batch to retain its immutable coordinate."""
    if expected_batch is not None and (
        expected_batch.batch_number != state.expected_batch_number
        or expected_batch.source_id != dataset.source_id
        or expected_batch.dataset_id != dataset.dataset_id
        or expected_batch.evidence_run_id != dataset.evidence_run_id
        or expected_batch.resource_type != resource_type
        or expected_batch.after_resource_id != state.after_resource_id
    ):
        raise RuntimeError(
            "provider_directory_artifact_scope_batch_projection_invalid"
        )


async def _insert_projected_artifact_resource_batch(
    model: Any,
    schema: str,
    insert_sql: str,
    insert_params_by_name: Mapping[str, Any],
    expected_batch: _ProviderDirectoryArtifactScopeBatchProjection,
) -> int:
    """Insert one projected resource batch after exact preflight."""
    projection_row = await db.first(
        _artifact_resource_batch_projection_sql(model, schema),
        **insert_params_by_name,
    )
    observed_rows, observed_bytes, observed_cursor = (
        _provider_directory_artifact_projection_values(projection_row)
    )
    if (
        observed_rows != expected_batch.projected_rows
        or observed_bytes != expected_batch.projected_logical_bytes
        or observed_cursor != expected_batch.last_resource_id
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_resource_projection_changed"
        )
    if observed_rows == 0:
        return 0
    return _coerce_rowcount(
        await db.status(insert_sql, **insert_params_by_name)
    )


async def _execute_artifact_resource_batch(
    model: Any,
    schema: str,
    insert_sql: str,
    insert_params_by_name: Mapping[str, Any],
    expected_batch: (
        _ProviderDirectoryArtifactScopeBatchProjection | None
    ),
) -> int:
    """Execute one resource batch through projected or legacy admission."""
    admission = _provider_directory_profile_capacity_admission()
    if expected_batch is not None and admission is not None:
        if expected_batch.projected_rows > 0:
            await _reserve_provider_directory_profile_wal_budget(
                admission,
                control_operation_counts={"artifact_scope_payload": 1},
            )
        async with _provider_directory_profile_capacity_transaction():
            return await _insert_projected_artifact_resource_batch(
                model,
                schema,
                insert_sql,
                insert_params_by_name,
                expected_batch,
            )
    if expected_batch is not None:
        return await _insert_projected_artifact_resource_batch(
            model,
            schema,
            insert_sql,
            insert_params_by_name,
            expected_batch,
        )
    return _coerce_rowcount(
        await _provider_directory_profile_capacity_status(
            insert_sql,
            **insert_params_by_name,
        )
    )


async def _next_artifact_resource_id(
    schema: str,
    table_name: str,
    dataset: ProviderDirectoryArtifactDataset,
    previous_resource_id: str | None,
) -> str:
    """Return the next strict keyset cursor for a legacy batch."""
    next_resource_id = _clean_text(
        await db.scalar(
            f"SELECT MAX(resource_id) FROM {_qt(schema, table_name)} "
            "WHERE source_id = :source_id;",
            source_id=dataset.source_id,
        )
    )
    if (
        next_resource_id is None
        or next_resource_id == previous_resource_id
    ):
        raise RuntimeError(
            "provider_directory_artifact_scope_batch_cursor_invalid"
        )
    return next_resource_id


def _log_artifact_resource_batch(
    context: _ArtifactResourceMaterializationContext,
    state: _ArtifactResourceMaterializationState,
    inserted_rows: int,
    batch_started_at: float,
) -> None:
    """Log one completed artifact resource batch."""
    LOGGER.info(
        "Materialized Provider Directory artifact scope batch "
        "table=%s source_id=%s dataset_id=%s resource_type=%s "
        "batch=%d rows=%d total_rows=%d elapsed_seconds=%.3f",
        context.table_name,
        context.dataset.source_id,
        context.dataset.dataset_id,
        context.resource_type,
        state.batch_number,
        inserted_rows,
        state.total_rows,
        time.monotonic() - batch_started_at,
    )


async def _is_artifact_resource_iteration_continuing(
    context: _ArtifactResourceMaterializationContext,
    state: _ArtifactResourceMaterializationState,
    expected_batch: _ProviderDirectoryArtifactScopeBatchProjection | None,
) -> bool:
    """Execute one resource batch and advance its bounded cursor."""
    _validate_artifact_resource_batch_coordinate(
        expected_batch,
        state,
        context.dataset,
        context.resource_type,
    )
    batch_started_at = time.monotonic()
    insert_params_by_name = {
        "source_id": context.dataset.source_id,
        "dataset_id": context.dataset.dataset_id,
        "evidence_run_id": context.dataset.evidence_run_id,
        "resource_type": context.resource_type,
        "after_resource_id": state.after_resource_id,
        "scope_batch_size": context.batch_size,
    }
    inserted_rows = await _execute_artifact_resource_batch(
        context.model,
        context.schema,
        context.insert_sql,
        insert_params_by_name,
        expected_batch,
    )
    _validate_artifact_resource_inserted_rows(
        inserted_rows,
        context.batch_size,
        expected_batch,
    )
    if inserted_rows == 0:
        state.is_terminal_projection_observed = expected_batch is not None
        return False
    state.total_rows += inserted_rows
    state.batch_number += 1
    _log_artifact_resource_batch(
        context,
        state,
        inserted_rows,
        batch_started_at,
    )
    if expected_batch is not None:
        if expected_batch.last_resource_id is None:
            raise RuntimeError(
                "provider_directory_artifact_scope_batch_projection_invalid"
            )
        state.after_resource_id = expected_batch.last_resource_id
        return True
    if inserted_rows < context.batch_size:
        return False
    state.after_resource_id = await _next_artifact_resource_id(
        context.schema,
        context.table_name,
        context.dataset,
        state.after_resource_id,
    )
    return True


def _validate_artifact_resource_inserted_rows(
    inserted_rows: int,
    batch_size: int,
    expected_batch: (
        _ProviderDirectoryArtifactScopeBatchProjection | None
    ),
) -> None:
    """Require observed rows to fit both batch and signed projection."""
    if inserted_rows < 0 or inserted_rows > batch_size:
        raise RuntimeError(
            "provider_directory_artifact_scope_batch_row_count_invalid"
        )
    if expected_batch is not None and (
        inserted_rows != expected_batch.projected_rows
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_resource_projection_changed"
        )


def _artifact_resource_materialization_context(
    schema: str,
    table_name: str,
    model: Any,
    dataset: ProviderDirectoryArtifactDataset,
    resource_type: str,
    batch_size: int,
) -> _ArtifactResourceMaterializationContext:
    """Return immutable inputs shared by every resource batch."""
    return _ArtifactResourceMaterializationContext(
        schema=schema,
        table_name=table_name,
        model=model,
        dataset=dataset,
        resource_type=resource_type,
        insert_sql=_artifact_resource_batch_insert_sql(
            model,
            schema,
            table_name,
        ),
        batch_size=batch_size,
    )


async def _materialize_provider_directory_artifact_resource_dataset(
    schema: str,
    table_name: str,
    model: Any,
    dataset: ProviderDirectoryArtifactDataset,
    resource_type: str,
    *,
    batch_size: int,
    projection_batches: _ArtifactScopeBatchProjectionPlan | None = None,
) -> int:
    """Project one immutable source/dataset pair in bounded keyset batches."""
    context = _artifact_resource_materialization_context(
        schema,
        table_name,
        model,
        dataset,
        resource_type,
        batch_size,
    )
    if projection_batches is not None:
        _assert_provider_directory_artifact_resource_projection_batches(
            dataset,
            resource_type,
            projection_batches,
            batch_size=batch_size,
        )
    expected_batches = iter(projection_batches or ())
    state = _ArtifactResourceMaterializationState()
    while True:
        expected_batch = (
            next(expected_batches, None)
            if projection_batches is not None
            else None
        )
        if projection_batches is not None and expected_batch is None:
            if not state.is_terminal_projection_observed:
                raise ProviderDirectoryArtifactBuildStale(
                    "provider_directory_artifact_resource_projection_changed"
                )
            break
        state.expected_batch_number += 1
        should_continue = await _is_artifact_resource_iteration_continuing(
            context,
            state,
            expected_batch,
        )
        if not should_continue:
            break
    if (
        projection_batches is not None
        and (
            not state.is_terminal_projection_observed
            or next(expected_batches, None) is not None
        )
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_resource_projection_changed"
        )
    return state.total_rows


def _artifact_scope_resource_datasets(
    fence: ProviderDirectoryArtifactDatasetFence,
    resource_types: frozenset[str],
    resource_type: str,
) -> list[ProviderDirectoryArtifactDataset]:
    """Return selected datasets that contribute one resource relation."""
    return sorted(
        (
            dataset
            for dataset in fence.datasets
            if resource_type in resource_types
            and resource_type in dataset.artifact_resources
        ),
        key=lambda dataset: (dataset.source_id, dataset.dataset_id),
    )


def _artifact_dataset_projection_batches(
    projection: _ProviderDirectoryArtifactScopeTableProjection | None,
    dataset: ProviderDirectoryArtifactDataset,
) -> tuple[_ProviderDirectoryArtifactScopeBatchProjection, ...] | None:
    """Return the frozen projection batches for one selected dataset."""
    if projection is None:
        return None
    return tuple(
        batch
        for batch in projection.batches
        if batch.source_id == dataset.source_id
        and batch.dataset_id == dataset.dataset_id
        and batch.evidence_run_id == dataset.evidence_run_id
    )


async def _materialize_provider_directory_artifact_resource_scope(
    schema: str,
    table_name: str,
    model: Any,
    fence: ProviderDirectoryArtifactDatasetFence,
    resource_types: frozenset[str],
    *,
    batch_size: int | None = None,
    projection: (
        _ProviderDirectoryArtifactScopeTableProjection | None
    ) = None,
) -> int:
    """Materialize one bounded resource relation from the fenced datasets."""
    resource_type = RESOURCE_TYPES_BY_MODEL[model]
    resolved_batch_size = (
        batch_size or _provider_directory_artifact_scope_batch_size()
    )
    total_rows = 0
    for dataset in _artifact_scope_resource_datasets(
        fence, resource_types, resource_type
    ):
        total_rows += await _materialize_provider_directory_artifact_resource_dataset(
            schema,
            table_name,
            model,
            dataset,
            resource_type,
            batch_size=resolved_batch_size,
            projection_batches=_artifact_dataset_projection_batches(
                projection,
                dataset,
            ),
        )
    if projection is not None and total_rows != projection.projected_rows:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_resource_projection_changed"
        )
    capacity_admission = _provider_directory_profile_capacity_admission()
    if capacity_admission is not None:
        await _reserve_provider_directory_profile_wal_budget(
            capacity_admission,
            control_operation_counts={"artifact_scope_analyze": 1},
        )
    await _provider_directory_profile_capacity_status(
        f"ANALYZE {_qt(schema, table_name)};"
    )
    return total_rows


async def _verify_provider_directory_artifact_dataset_fence(
    fence: ProviderDirectoryArtifactDatasetFence,
) -> None:
    dataset_rows = await _artifact_fence_dataset_rows(
        fence,
        db,
        for_update=False,
    )
    eligible_ids_by_endpoint = await _artifact_eligible_validated_ids(
        fence,
        db,
    )
    _assert_locked_artifact_fence_datasets(
        fence,
        dataset_rows,
        eligible_ids_by_endpoint,
    )
    await _assert_uhc_flex_profile_fence_ready(fence, db)


async def _lock_and_verify_artifact_dataset_fence(
    fence: ProviderDirectoryArtifactDatasetFence,
    executor: Any | None = None,
) -> None:
    """Fence alias and dataset identity while an artifact becomes live."""
    if not fence.datasets:
        return
    query_executor = executor or db
    if any(
        dataset.source_id == UHC_FLEX_PRACTITIONER_SOURCE_ID
        for dataset in fence.datasets
    ):
        await lock_uhc_flex_profile_publication(query_executor)
    await _lock_artifact_fence_endpoint_advisories(fence, query_executor)
    await _lock_artifact_fence_endpoints(fence, query_executor)
    locked_alias_rows = await _lock_artifact_fence_aliases(
        fence,
        query_executor,
    )
    _assert_locked_artifact_fence_aliases(fence, locked_alias_rows)
    locked_dataset_rows = await _artifact_fence_dataset_rows(
        fence,
        query_executor,
        for_update=True,
    )
    eligible_ids_by_endpoint = await _artifact_eligible_validated_ids(
        fence,
        query_executor,
    )
    _assert_locked_artifact_fence_datasets(
        fence,
        locked_dataset_rows,
        eligible_ids_by_endpoint,
    )
    await _assert_uhc_flex_profile_fence_ready(fence, query_executor)


async def _assert_uhc_flex_profile_fence_ready(
    fence: ProviderDirectoryArtifactDatasetFence,
    executor: Any,
) -> None:
    """Recheck the exact admission-backed cohort inside every fence."""

    from process.uhc_flex_practitioner_publication import (
        load_uhc_flex_practitioner_dataset_readiness,
    )

    for dataset in fence.datasets:
        if dataset.source_id != UHC_FLEX_PRACTITIONER_SOURCE_ID:
            continue
        readiness = await load_uhc_flex_practitioner_dataset_readiness(
            dataset.dataset_id,
            database=executor,
        )
        if not is_uhc_flex_fence_dataset_ready(dataset, readiness):
            raise ProviderDirectoryArtifactBuildStale(
                "provider_directory_artifact_dataset_scoped_readiness_changed:"
                + dataset.dataset_id
            )


async def _lock_artifact_fence_endpoint_advisories(
    fence: ProviderDirectoryArtifactDatasetFence,
    executor: Any,
) -> None:
    """Serialize each endpoint before taking source or dataset row locks."""

    for endpoint_id in fence.endpoint_ids:
        await executor.status(
            "SELECT pg_catalog.pg_advisory_xact_lock("
            "pg_catalog.hashtextextended(:endpoint_id, 0));",
            endpoint_id=endpoint_id,
        )


async def _lock_artifact_cutover_fence(
    fence: ProviderDirectoryArtifactDatasetFence,
    *,
    profile_delta: ProviderDirectoryPreparedProfileDelta | None = None,
) -> None:
    """Give candidate metadata validation its own pre-cutover budget."""
    use_candidate_budget = (
        profile_delta is None
        and fence.should_select_validated_candidates
    )
    if use_candidate_budget:
        await db.status(
            "SET LOCAL statement_timeout = "
            f"'{PROVIDER_DIRECTORY_ARTIFACT_FENCE_STATEMENT_TIMEOUT}';"
        )
    await _lock_and_verify_artifact_dataset_fence(fence)
    if use_candidate_budget:
        await db.status(
            "SET LOCAL statement_timeout = "
            f"'{PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_STATEMENT_TIMEOUT}';"
        )


async def _lock_artifact_fence_endpoints(
    fence: ProviderDirectoryArtifactDatasetFence,
    executor: Any,
) -> None:
    """Serialize cutover with endpoint dataset promotion."""
    endpoint_ref = _unscoped_qt(
        _schema(),
        ProviderDirectoryAPIEndpoint.__tablename__,
    )
    endpoint_rows = await executor.all(
        f"""
        SELECT endpoint_id
          FROM {endpoint_ref}
         WHERE endpoint_id = ANY(CAST(:endpoint_ids AS varchar[]))
         ORDER BY endpoint_id
         FOR UPDATE;
        """,
        endpoint_ids=fence.endpoint_ids,
    )
    locked_endpoint_ids = sorted(
        endpoint_id
        for endpoint_row in endpoint_rows
        if (endpoint_id := _clean_text(
            _pagination_checkpoint_row_mapping(endpoint_row).get("endpoint_id")
        ))
    )
    if locked_endpoint_ids != fence.endpoint_ids:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_api_endpoint_changed"
        )


async def _lock_artifact_fence_aliases(
    fence: ProviderDirectoryArtifactDatasetFence,
    executor: Any,
) -> list[Any]:
    """Lock and return the source aliases explicitly selected by the fence."""
    source_ref = _unscoped_qt(_schema(), ProviderDirectorySource.__tablename__)
    return await executor.all(
        f"""
        SELECT source.source_id,
               source.endpoint_id,
               to_jsonb(source) AS source_record_json
          FROM {source_ref} AS source
         WHERE source.source_id = ANY(CAST(:source_ids AS varchar[]))
         ORDER BY source.source_id, source.endpoint_id
         FOR SHARE OF source;
        """,
        source_ids=fence.locked_source_ids,
    )


def _assert_locked_artifact_fence_aliases(
    fence: ProviderDirectoryArtifactDatasetFence,
    locked_alias_rows: list[Any],
) -> None:
    """Ensure the held publication source scope remains exact."""
    alias_rows_by_source_id = {
        source_id: alias_row_map
        for alias_row in locked_alias_rows
        if (
            alias_row_map := _pagination_checkpoint_row_mapping(alias_row)
        )
        and (source_id := _clean_text(alias_row_map.get("source_id")))
    }
    actual_source_endpoint_tuples = tuple(
        sorted(
            (
                source_id,
                _clean_text(alias_row_map.get("endpoint_id")) or "",
            )
            for source_id, alias_row_map in alias_rows_by_source_id.items()
        )
    )
    if actual_source_endpoint_tuples != fence.source_endpoint_tuples:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_source_endpoint_dataset_changed"
        )
    for dataset in fence.locked_alias_datasets:
        alias_row_map = alias_rows_by_source_id[dataset.source_id]
        source_record = _json_object(alias_row_map.get("source_record_json"))
        _assert_locked_artifact_source_contract(dataset, source_record)
        if dataset.recorded_expected_resources is not None:
            continue
        if (
            _endpoint_dataset_expected_resources([source_record])
            != dataset.expected_resources
        ):
            raise ProviderDirectoryArtifactBuildStale(
                "provider_directory_endpoint_dataset_expected_metadata_changed"
            )


def _assert_locked_artifact_source_contract(
    dataset: ProviderDirectoryArtifactDataset,
    source_record: dict[str, Any],
) -> None:
    """Reject source admission or acquisition drift before artifact cutover."""
    expected_contract = dataset.source_verification_contract
    expected_hash = dataset.source_verification_contract_hash
    if not expected_contract and expected_hash is None:
        return
    if (
        not expected_contract
        or expected_hash != _identity_hash(expected_contract)
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_source_verification_contract_invalid"
        )
    current_contract = _artifact_source_verification_contract(
        source_record,
        verification_campaign_id=dataset.verification_campaign_id,
        verification_source_scope_hash=(
            dataset.verification_source_scope_hash
        ),
        source_ids=dataset.verification_source_ids,
        completion_proof_cutoff=dataset.completion_proof_cutoff,
    )
    if (
        current_contract != expected_contract
        or _identity_hash(current_contract) != expected_hash
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_source_verification_contract_changed"
        )


def _artifact_fence_dataset_rows_sql(*, for_update: bool) -> str:
    dataset_ref = _unscoped_qt(
        _schema(),
        ProviderDirectoryEndpointDataset.__tablename__,
    )
    if for_update:
        scope_sql = (
            "dataset.dataset_id = ANY(CAST(:dataset_ids AS varchar[]))"
        )
        current_ids_sql = f"""
               ARRAY(
                   SELECT current_dataset.dataset_id
                     FROM {dataset_ref} AS current_dataset
                    WHERE current_dataset.endpoint_id = dataset.endpoint_id
                      AND current_dataset.is_current = true
                      AND current_dataset.status = :published_status
                      AND current_dataset.superseded_at IS NULL
                    ORDER BY current_dataset.dataset_id
               )::varchar[] AS locked_current_dataset_ids,
        """
        lock_sql = "FOR UPDATE OF dataset"
    else:
        scope_sql = (
            "dataset.endpoint_id = ANY(CAST(:endpoint_ids AS varchar[]))"
        )
        current_ids_sql = ""
        lock_sql = ""
    return f"""
        SELECT dataset.dataset_id,
               dataset.endpoint_id,
               dataset.import_run_id,
               dataset.acquisition_root_run_id,
               dataset.previous_dataset_id,
               dataset.dataset_hash,
               dataset.status,
               dataset.is_current,
               dataset.resource_count,
               dataset.validated_at,
               dataset.published_at,
               dataset.superseded_at,
               dataset.completion_proof_required_version,
               dataset.completion_proof_sha256,
               {current_ids_sql}
               dataset.publication_metadata_json
          FROM {dataset_ref} AS dataset
         WHERE {scope_sql}
         ORDER BY dataset.dataset_id
         {lock_sql};
    """


def _locked_artifact_dataset_ids(
    fence: ProviderDirectoryArtifactDatasetFence,
) -> list[str]:
    """Return the exact selected and incumbent dataset rows locked at cutover."""

    return sorted(
        {
            dataset_id
            for dataset in _unique_artifact_datasets(fence)
            for dataset_id in (
                dataset.dataset_id,
                dataset.expected_incumbent_dataset_id,
                dataset.previous_dataset_id,
            )
            if dataset_id
        }
    )


def _profile_cutover_lock_count(
    fence: ProviderDirectoryArtifactDatasetFence,
) -> int:
    """Count every bounded tuple-lock statement in one admitted cutover."""

    return (
        len(fence.endpoint_ids)
        + len(fence.locked_source_ids)
        + len(
            _provider_directory_artifact_fence_locked_dataset_ids(fence)
        )
        + PROVIDER_DIRECTORY_PROFILE_CUTOVER_FIXED_ROW_LOCK_COUNT
    )


async def _artifact_fence_dataset_rows(
    fence: ProviderDirectoryArtifactDatasetFence,
    executor: Any,
    *,
    for_update: bool,
) -> list[Any]:
    query_params_by_name: dict[str, Any]
    if for_update:
        locked_dataset_ids = (
            _provider_directory_artifact_fence_locked_dataset_ids(fence)
        )
        query_params_by_name = {
            "dataset_ids": locked_dataset_ids,
            "published_status": ENDPOINT_DATASET_PUBLISHED,
        }
    else:
        query_params_by_name = {"endpoint_ids": fence.endpoint_ids}
    return await executor.all(
        _artifact_fence_dataset_rows_sql(for_update=for_update),
        **query_params_by_name,
    )


async def _artifact_eligible_validated_ids(
    fence: ProviderDirectoryArtifactDatasetFence,
    executor: Any,
) -> dict[str, list[str]]:
    if not fence.should_select_validated_candidates:
        return {}
    selected_endpoint_ids = sorted(
        {dataset.endpoint_id for dataset in fence.datasets}
    )
    if not selected_endpoint_ids:
        return {}
    dataset_ref = _unscoped_qt(
        _schema(),
        ProviderDirectoryEndpointDataset.__tablename__,
    )
    source_ref = _unscoped_qt(
        _schema(),
        ProviderDirectorySource.__tablename__,
    )
    reviewed_candidate_gate = _artifact_reviewed_candidate_eligibility_sql(
        dataset_ref,
        source_ref,
        metadata="dataset.eligibility_metadata_jsonb",
    )
    option_rows = await executor.all(
        f"""
        WITH {_artifact_candidate_eligibility_ctes(dataset_ref)}
        SELECT dataset.endpoint_id, dataset.dataset_id
          FROM artifact_candidate_metadata AS dataset
         WHERE {reviewed_candidate_gate}
         ORDER BY dataset.endpoint_id, dataset.dataset_id;
        """,
        endpoint_ids=selected_endpoint_ids,
        validated_status=ENDPOINT_DATASET_VALIDATED,
    )
    eligible_ids_by_endpoint: dict[str, list[str]] = {}
    for option_row in option_rows:
        option_row_map = _pagination_checkpoint_row_mapping(option_row)
        endpoint_id = _clean_text(option_row_map.get("endpoint_id"))
        dataset_id = _clean_text(option_row_map.get("dataset_id"))
        if endpoint_id and dataset_id:
            eligible_ids_by_endpoint.setdefault(endpoint_id, []).append(
                dataset_id
            )
    return eligible_ids_by_endpoint


def _artifact_fence_dataset_row_identity(
    dataset_row_map: dict[str, Any],
) -> tuple[Any, ...]:
    validated_at = dataset_row_map.get("validated_at")
    return (
        _clean_text(dataset_row_map.get("endpoint_id")),
        _clean_text(dataset_row_map.get("acquisition_root_run_id"))
        or _clean_text(dataset_row_map.get("import_run_id")),
        _clean_text(dataset_row_map.get("status")),
        dataset_row_map.get("is_current") is True,
        _clean_text(dataset_row_map.get("previous_dataset_id")),
        _clean_text(dataset_row_map.get("dataset_hash")),
        (
            int(dataset_row_map.get("resource_count"))
            if dataset_row_map.get("resource_count") is not None
            else None
        ),
        str(validated_at) if validated_at is not None else None,
        _identity_hash(
            _json_object(dataset_row_map.get("publication_metadata_json"))
        ),
        dataset_row_map.get("completion_proof_required_version"),
        _clean_text(dataset_row_map.get("completion_proof_sha256")),
    )


def _expected_artifact_fence_dataset_identity(
    dataset: ProviderDirectoryArtifactDataset,
) -> tuple[Any, ...]:
    return (
        dataset.endpoint_id,
        dataset.evidence_run_id,
        dataset.status,
        dataset.is_current,
        dataset.previous_dataset_id,
        dataset.dataset_hash,
        dataset.resource_count,
        dataset.validated_at,
        dataset.publication_metadata_hash,
        dataset.completion_proof_required_version,
        dataset.completion_proof_sha256,
    )


def _is_artifact_fence_dataset_row_exact(
    dataset: ProviderDirectoryArtifactDataset,
    dataset_row_map: dict[str, Any],
) -> bool:
    actual_identity = _artifact_fence_dataset_row_identity(dataset_row_map)
    expected_identity_by_name = _expected_artifact_fence_dataset_identity(dataset)
    for field_index, (actual_value, expected_value) in enumerate(
        zip(actual_identity, expected_identity_by_name)
    ):
        if field_index in {5, 6, 7, 8} and expected_value is None:
            continue
        if actual_value != expected_value:
            return False
    return True


def _current_published_artifact_dataset_ids(
    dataset_row_maps: Iterable[dict[str, Any]],
    endpoint_id: str,
) -> list[str]:
    return sorted(
        _clean_text(dataset_row_map.get("dataset_id")) or ""
        for dataset_row_map in dataset_row_maps
        if _clean_text(dataset_row_map.get("endpoint_id")) == endpoint_id
        and dataset_row_map.get("is_current") is True
        and _clean_text(dataset_row_map.get("status"))
        == ENDPOINT_DATASET_PUBLISHED
        and dataset_row_map.get("superseded_at") is None
    )


def _validated_artifact_dataset_ids(
    dataset_row_maps: Iterable[dict[str, Any]],
) -> list[str]:
    return sorted(
        _clean_text(dataset_row_map.get("dataset_id")) or ""
        for dataset_row_map in dataset_row_maps
        if dataset_row_map.get("is_current") is not True
        and _clean_text(dataset_row_map.get("status"))
        == ENDPOINT_DATASET_VALIDATED
        and dataset_row_map.get("superseded_at") is None
    )


def _locked_dataset_rows_by_id(
    locked_dataset_rows: list[Any],
) -> dict[str, Mapping[str, Any]]:
    """Index locked dataset rows by their exact nonempty identifier."""
    return {
        dataset_id: dataset_row_map
        for dataset_row in locked_dataset_rows
        if (
            dataset_row_map := _pagination_checkpoint_row_mapping(dataset_row)
        )
        and (dataset_id := _clean_text(dataset_row_map.get("dataset_id")))
    }


def _assert_locked_artifact_fence_datasets(
    fence: ProviderDirectoryArtifactDatasetFence,
    locked_dataset_rows: list[Any],
    eligible_ids_by_endpoint: dict[str, list[str]] | None = None,
) -> None:
    """Reverify selected datasets, candidates, and expected incumbents."""
    dataset_rows_by_id = _locked_dataset_rows_by_id(locked_dataset_rows)
    rows_by_endpoint_id: dict[str, list[dict[str, Any]]] = {}
    current_ids_by_endpoint_id: dict[str, list[str]] = {}
    for dataset_row_map in dataset_rows_by_id.values():
        endpoint_id = _clean_text(dataset_row_map.get("endpoint_id"))
        if endpoint_id:
            rows_by_endpoint_id.setdefault(endpoint_id, []).append(
                dataset_row_map
            )
            raw_current_ids = dataset_row_map.get(
                "locked_current_dataset_ids"
            )
            if raw_current_ids is not None:
                current_ids = sorted(
                    dataset_id
                    for candidate in raw_current_ids
                    if (dataset_id := _clean_text(candidate))
                )
                prior_current_ids = current_ids_by_endpoint_id.setdefault(
                    endpoint_id,
                    current_ids,
                )
                if prior_current_ids != current_ids:
                    raise ProviderDirectoryArtifactBuildStale(
                        "provider_directory_endpoint_dataset_current_changed"
                    )
    for dataset in _unique_artifact_datasets(fence):
        _assert_locked_artifact_endpoint_state(
            dataset,
            rows_by_endpoint_id.get(dataset.endpoint_id, []),
            actual_current_ids=current_ids_by_endpoint_id.get(
                dataset.endpoint_id
            ),
            should_select_validated_candidates=(
                fence.should_select_validated_candidates
            ),
            eligible_dataset_ids=(
                eligible_ids_by_endpoint.get(dataset.endpoint_id, [])
                if eligible_ids_by_endpoint is not None
                else None
            ),
        )
        selected_dataset_row = dataset_rows_by_id.get(dataset.dataset_id)
        if (
            selected_dataset_row is None
            or not _is_artifact_fence_dataset_row_exact(
                dataset, selected_dataset_row
            )
        ):
            raise ProviderDirectoryArtifactBuildStale(
                "provider_directory_endpoint_dataset_metadata_changed"
            )


def _assert_locked_artifact_endpoint_state(
    dataset: ProviderDirectoryArtifactDataset,
    endpoint_dataset_rows: list[dict[str, Any]],
    *,
    actual_current_ids: list[str] | None = None,
    should_select_validated_candidates: bool,
    eligible_dataset_ids: list[str] | None,
) -> None:
    """Require the locked endpoint to retain its selected candidate set."""
    if actual_current_ids is None:
        actual_current_ids = _current_published_artifact_dataset_ids(
            endpoint_dataset_rows,
            dataset.endpoint_id,
        )
    expected_incumbent_id = (
        dataset.expected_incumbent_dataset_id
        if dataset.promote_on_cutover
        else dataset.dataset_id
    )
    expected_current_ids = (
        [expected_incumbent_id] if expected_incumbent_id else []
    )
    if actual_current_ids != expected_current_ids:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_endpoint_dataset_current_changed"
        )
    if not should_select_validated_candidates:
        return
    actual_validated_ids = (
        sorted(eligible_dataset_ids)
        if eligible_dataset_ids is not None
        else _validated_artifact_dataset_ids(endpoint_dataset_rows)
    )
    expected_validated_ids = (
        [dataset.dataset_id] if dataset.promote_on_cutover else []
    )
    if actual_validated_ids != expected_validated_ids:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_endpoint_dataset_candidate_changed"
        )


@contextlib.asynccontextmanager
async def _provider_directory_active_artifact_dataset_transaction() -> AsyncIterator[None]:
    """Keep endpoint dataset identity stable during additive archive mutation."""
    fence = _PROVIDER_DIRECTORY_ARTIFACT_DATASET_FENCE.get()
    if fence is None:
        yield
        return
    async with db.transaction():
        await _lock_and_verify_artifact_dataset_fence(fence, db)
        yield


async def _artifact_scope_projection_plan(
    schema: str,
    fence: ProviderDirectoryArtifactDatasetFence,
    resource_fence: ProviderDirectoryArtifactDatasetFence,
    resource_types: frozenset[str],
    admission: _ProviderDirectoryProfileCapacityAdmission | None,
) -> tuple[
    dict[str, Any] | _ProviderDirectoryArtifactScopeExactProjection,
    _ProviderDirectoryArtifactScopeExactProjection | None,
    list[str],
]:
    """Resolve and validate either legacy or exact artifact-scope projection."""
    if admission is None:
        projection = await _provider_directory_artifact_scope_projection(
            resource_fence,
            resource_types,
        )
        _assert_provider_directory_artifact_scope_capacity(projection)
        reaped_tables = (
            await _reap_provider_directory_artifact_scope_tables(schema)
        )
        return projection, None, reaped_tables
    exact_projection = (
        await _provider_directory_artifact_scope_exact_projection(
            schema,
            resource_fence,
            resource_types,
            source_fence=fence,
            batch_size=admission.geometry.artifact_scope_batch_size,
        )
    )
    _assert_provider_directory_artifact_scope_exact_capacity(exact_projection)
    return exact_projection, exact_projection, []


async def _materialize_artifact_scope_plan(
    schema: str,
    run_id: str | None,
    fence: ProviderDirectoryArtifactDatasetFence,
    resource_fence: ProviderDirectoryArtifactDatasetFence,
    resource_types: frozenset[str],
    projection: _ProviderDirectoryArtifactScopeExactProjection | None,
    admission: _ProviderDirectoryProfileCapacityAdmission | None,
) -> tuple[dict[str, str], list[str]]:
    """Materialize one projection under its signed worker geometry."""
    return await _materialize_artifact_scope_tables(
        schema,
        run_id,
        fence,
        resource_types,
        resource_fence=resource_fence,
        projection=projection,
        batch_size=(
            admission.geometry.artifact_scope_batch_size
            if admission is not None
            else None
        ),
        worker_count=(
            admission.geometry.artifact_scope_worker_count
            if admission is not None
            else None
        ),
    )


@contextlib.contextmanager
def _artifact_scope_tokens(
    fence: ProviderDirectoryArtifactDatasetFence,
    resource_fence: ProviderDirectoryArtifactDatasetFence,
    relation_overrides: Mapping[str, str],
) -> Iterator[None]:
    """Install and restore artifact-scope context variables together."""
    relation_token = _PROVIDER_DIRECTORY_ARTIFACT_RELATION_OVERRIDES.set(
        dict(relation_overrides)
    )
    fence_token = _PROVIDER_DIRECTORY_ARTIFACT_DATASET_FENCE.set(fence)
    resource_scope_token = (
        _PROVIDER_DIRECTORY_ARTIFACT_RESOURCE_SCOPE_SOURCE_IDS.set(
            tuple(resource_fence.source_ids)
        )
    )
    try:
        yield
    finally:
        _PROVIDER_DIRECTORY_ARTIFACT_RESOURCE_SCOPE_SOURCE_IDS.reset(
            resource_scope_token
        )
        _PROVIDER_DIRECTORY_ARTIFACT_DATASET_FENCE.reset(fence_token)
        _PROVIDER_DIRECTORY_ARTIFACT_RELATION_OVERRIDES.reset(relation_token)


@contextlib.asynccontextmanager
async def _yield_artifact_dataset_scope(
    schema: str,
    fence: ProviderDirectoryArtifactDatasetFence,
    resource_fence: ProviderDirectoryArtifactDatasetFence,
    relation_overrides: Mapping[str, str],
    created_tables: list[str],
) -> AsyncIterator[ProviderDirectoryArtifactDatasetFence]:
    """Yield one scoped artifact fence and always drain its scratch tables."""
    try:
        with _artifact_scope_tokens(
            fence,
            resource_fence,
            relation_overrides,
        ):
            yield fence
    except BaseException as scope_error:
        try:
            await _drain_artifact_scope_cleanup(schema, created_tables)
        except BaseException as cleanup_error:
            if not (
                isinstance(scope_error, asyncio.CancelledError)
                and isinstance(cleanup_error, asyncio.CancelledError)
            ):
                raise BaseExceptionGroup(
                    "provider_directory_artifact_scope_and_cleanup_failed",
                    [scope_error, cleanup_error],
                ) from scope_error
        raise
    else:
        await _drain_artifact_scope_cleanup(schema, created_tables)


def _resolved_artifact_scope_resource_types(
    resource_types: frozenset[str] | None,
) -> frozenset[str]:
    """Keep an explicit empty resource selection distinct from the default."""
    if resource_types is not None:
        return resource_types
    return PROVIDER_DIRECTORY_ARTIFACT_RESOURCE_TYPES


@contextlib.asynccontextmanager
async def _provider_directory_artifact_dataset_scope(
    *,
    run_id: str | None,
    source_ids: list[str] | tuple[str, ...] | None,
    fence: ProviderDirectoryArtifactDatasetFence | None = None,
    resource_fence: ProviderDirectoryArtifactDatasetFence | None = None,
    metrics: dict[str, Any] | None = None,
    resource_types: frozenset[str] | None = None,
) -> AsyncIterator[ProviderDirectoryArtifactDatasetFence]:
    """Materialize and clean one bounded alias-aware artifact source scope."""
    schema = _schema()
    fence = fence or await _resolve_provider_directory_artifact_datasets(source_ids)
    materialized_resource_fence = resource_fence or fence
    async with _provider_directory_artifact_scope_guard(schema):
        scoped_resource_types = _resolved_artifact_scope_resource_types(
            resource_types
        )
        capacity_admission = _provider_directory_profile_capacity_admission()
        projection, exact_projection, reaped_tables = (
            await _artifact_scope_projection_plan(
                schema,
                fence,
                materialized_resource_fence,
                scoped_resource_types,
                capacity_admission,
            )
        )
        _record_artifact_scope_metrics(metrics, projection, reaped_tables)
        relation_overrides, created_tables = await _materialize_artifact_scope_plan(
            schema,
            run_id,
            fence,
            materialized_resource_fence,
            scoped_resource_types,
            exact_projection,
            capacity_admission,
        )
        if capacity_admission is not None:
            assert exact_projection is not None
            try:
                await _assert_provider_directory_artifact_scope_observed_capacity(
                    schema,
                    relation_overrides,
                    exact_projection,
                )
            except BaseException as capacity_error:
                await _cleanup_failed_artifact_scope(
                    schema,
                    created_tables,
                    capacity_error,
                )
                raise
        async with _yield_artifact_dataset_scope(
            schema,
            fence,
            materialized_resource_fence,
            relation_overrides,
            created_tables,
        ) as scoped_fence:
            yield scoped_fence


def _record_artifact_scope_metrics(
    metrics: dict[str, Any] | None,
    projection: (
        dict[str, Any]
        | _ProviderDirectoryArtifactScopeExactProjection
    ),
    reaped_tables: list[str],
) -> None:
    if metrics is None:
        return
    if isinstance(
        projection,
        _ProviderDirectoryArtifactScopeExactProjection,
    ):
        metrics["artifact_scope_projected_rows"] = (
            projection.projected_rows
        )
        metrics["artifact_scope_projected_logical_bytes"] = (
            projection.projected_logical_bytes
        )
        metrics["artifact_scope_projection_hash"] = (
            projection.projection_hash
        )
        metrics["artifact_scope_projected_rows_by_resource"] = {
            table.resource_type: table.projected_rows
            for table in projection.tables
        }
        metrics["artifact_scope_projected_bytes_by_resource"] = {
            table.resource_type: table.projected_logical_bytes
            for table in projection.tables
        }
        metrics["artifact_scope_reaped_table_count"] = len(reaped_tables)
        return
    metrics["artifact_scope_dataset_count"] = projection["dataset_count"]
    metrics["artifact_scope_alias_count"] = projection["alias_count"]
    metrics["artifact_scope_dataset_rows"] = projection["dataset_rows"]
    metrics["artifact_scope_projected_rows"] = projection["projected_rows"]
    metrics["artifact_scope_resource_types"] = projection["resource_types"]
    metrics["artifact_scope_alias_amplification"] = projection[
        "alias_amplification"
    ]
    metrics["artifact_scope_projected_rows_by_resource"] = projection[
        "projected_rows_by_resource"
    ]
    metrics["artifact_scope_aliases_by_dataset"] = projection[
        "aliases_by_dataset"
    ]
    metrics["artifact_scope_reaped_table_count"] = len(reaped_tables)


async def _artifact_scope_scratch_projection(
    schema: str,
    scope_table_name: str,
    table_projection: _ProviderDirectoryArtifactScopeTableProjection,
    admission: _ProviderDirectoryProfileCapacityAdmission,
) -> tuple[
    str,
    profile_capacity.ProviderDirectoryProfileScratchProjection,
]:
    """Project one exact unlogged artifact-scope relation."""
    relation_ref = _unscoped_qt(schema, scope_table_name)
    relation_oid = int(
        await db.scalar(
            "SELECT to_regclass(:relation_ref)::oid::bigint;",
            relation_ref=relation_ref,
        )
        or 0
    )
    if relation_oid <= 0:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_profile_capacity_scratch_oid_changed"
        )
    layout = await _provider_directory_profile_relation_storage_fingerprint(
        relation_oid,
        expected_persistence="u",
    )
    if layout.effective_tablespace_oids != (
        admission.geometry.tablespace_oid,
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_profile_capacity_scratch_tablespace_changed"
        )
    scratch_projection = profile_capacity.project_profile_scratch_capacity(
        admission.geometry,
        profile_capacity.ProviderDirectoryProfileScratchInput(
            relation_name="artifact_scope",
            inserted_rows=table_projection.projected_rows,
            inserted_logical_bytes=table_projection.projected_logical_bytes,
            toastable_column_count=len(layout.toastable_columns),
            main_index_pages=layout.main_index_pages,
            toast_index_pages=layout.toast_index_pages,
        ),
    )
    return relation_ref, scratch_projection


async def _admit_artifact_scope_totals(
    admission: _ProviderDirectoryProfileCapacityAdmission,
    projected_relations: list[
        tuple[
            str,
            profile_capacity.ProviderDirectoryProfileScratchProjection,
        ]
    ],
) -> None:
    """Admit aggregate artifact-scope data and WAL across all relations."""
    relation_refs = [
        relation_ref for relation_ref, _projection in projected_relations
    ]
    scratch_projections = [
        scratch_projection
        for _relation_ref, scratch_projection in projected_relations
    ]
    relation_cap = _provider_directory_profile_capacity_relation_cap(
        admission,
        "artifact_scope",
    )
    base_bytes = (
        await _provider_directory_profile_capacity_relation_bytes(
            relation_refs
        )
    )
    projected_growth_bytes = sum(
        scratch_projection.growth_bytes
        for scratch_projection in scratch_projections
    )
    projected_wal_bytes = sum(
        scratch_projection.wal_bytes
        for scratch_projection in scratch_projections
    )
    if (
        projected_growth_bytes > relation_cap.max_scratch_bytes
        or base_bytes + projected_growth_bytes
        > relation_cap.max_scratch_bytes
    ):
        raise RuntimeError(
            "provider_directory_profile_capacity_artifact_growth_projected"
        )
    if projected_wal_bytes > relation_cap.max_wal_bytes:
        raise RuntimeError(
            "provider_directory_profile_capacity_artifact_wal_projected"
        )
    await _reserve_provider_directory_profile_wal_budget(
        admission,
        relation_wal_bytes={"artifact_scope": projected_wal_bytes},
    )


async def _preflight_provider_directory_artifact_scope_capacity(
    schema: str,
    relation_by_table: Mapping[str, str],
    projection: _ProviderDirectoryArtifactScopeExactProjection,
) -> None:
    """Admit the complete nine-table scratch scope before payload DML."""
    admission = _provider_directory_profile_capacity_admission()
    if admission is None:
        return
    projections_by_table = {
        table_projection.table_name: table_projection
        for table_projection in projection.tables
    }
    if set(projections_by_table) != set(relation_by_table):
        raise RuntimeError(
            "provider_directory_artifact_scope_projection_tables_invalid"
        )
    projected_relations = [
        await _artifact_scope_scratch_projection(
            schema,
            scope_table_name,
            projections_by_table[base_table_name],
            admission,
        )
        for base_table_name, scope_table_name in sorted(
            relation_by_table.items()
        )
    ]
    await _admit_artifact_scope_totals(admission, projected_relations)


async def _assert_artifact_scope_usage(
    schema: str,
    relation_by_table: Mapping[str, str],
    projection: _ProviderDirectoryArtifactScopeExactProjection,
) -> None:
    """Verify actual aggregate rows, bytes, and WAL after one worker wave."""

    admission = _provider_directory_profile_capacity_admission()
    if admission is None:
        return
    relation_refs = [
        _unscoped_qt(schema, scope_table_name)
        for scope_table_name in relation_by_table.values()
    ]
    actual_rows = 0
    for relation_ref in relation_refs:
        actual_rows += int(
            await db.scalar(f"SELECT count(*) FROM {relation_ref};")
            or 0
        )
    if actual_rows > projection.projected_rows:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_scope_observed_rows_exceeded"
        )
    relation_cap = _provider_directory_profile_capacity_relation_cap(
        admission,
        "artifact_scope",
    )
    actual_bytes = (
        await _provider_directory_profile_capacity_relation_bytes(
            relation_refs
        )
    )
    if actual_bytes > relation_cap.max_scratch_bytes:
        raise RuntimeError(
            "provider_directory_profile_capacity_artifact_bytes_exceeded"
        )
    await _assert_provider_directory_profile_wal_budget(admission)


@dataclass(frozen=True)
class _ArtifactScopeMaterializationPlan:
    source_table: str
    created_tables: list[str]
    relation_by_table: dict[str, str]
    resource_scope_jobs: tuple[tuple[Any, str], ...]
    model_by_table_name: dict[str, Any]


def _artifact_scope_materialization_plan(
    run_id: str | None,
) -> _ArtifactScopeMaterializationPlan:
    """Return all deterministic scratch relation coordinates."""
    source_table = _provider_directory_artifact_scope_table_name(
        ProviderDirectorySource.__tablename__,
        run_id,
    )
    created_tables: list[str] = []
    relation_by_table = {ProviderDirectorySource.__tablename__: source_table}
    resource_scope_jobs: list[tuple[Any, str]] = []
    for model in RESOURCE_MODELS:
        scope_table = _provider_directory_artifact_scope_table_name(
            model.__tablename__,
            run_id,
        )
        relation_by_table[model.__tablename__] = scope_table
        resource_scope_jobs.append((model, scope_table))
    return _ArtifactScopeMaterializationPlan(
        source_table=source_table,
        created_tables=created_tables,
        relation_by_table=relation_by_table,
        resource_scope_jobs=tuple(resource_scope_jobs),
        model_by_table_name={
            model.__tablename__: model
            for model in (ProviderDirectorySource, *RESOURCE_MODELS)
        },
    )


async def _create_artifact_scope_layouts(
    schema: str,
    plan: _ArtifactScopeMaterializationPlan,
) -> None:
    """Create every admitted artifact-scope scratch layout."""
    await _reserve_artifact_scope_layout_wal()
    for base_table_name, scope_table_name in sorted(
        plan.relation_by_table.items()
    ):
        plan.created_tables.append(scope_table_name)
        await _create_provider_directory_artifact_scope_layout(
            plan.model_by_table_name[base_table_name],
            schema,
            scope_table_name,
        )


async def _reserve_artifact_scope_layout_wal() -> None:
    """Reserve the full empty-layout catalog envelope before any DDL."""

    admission = _provider_directory_profile_capacity_admission()
    if admission is not None:
        await _reserve_provider_directory_profile_wal_budget(
            admission,
            control_operation_counts={
                "artifact_scope_layout": (
                    _provider_directory_profile_control_operation_count(
                        admission,
                        "artifact_scope_layout",
                    )
                ),
            },
        )


@dataclass(frozen=True)
class _ArtifactScopeRecoveryCoordinate:
    base_table_name: str
    prior_table_name: str
    current_table_name: str


def _artifact_scope_prior_owner(
    relation_name: str,
) -> tuple[str, str]:
    """Parse one exact base relation and run owner from a scratch name."""
    matches: list[tuple[str, str]] = []
    for model in (ProviderDirectorySource, *RESOURCE_MODELS):
        base_name = model.__tablename__
        prefix = (
            _provider_directory_artifact_scope_table_prefix(base_name) + "_"
        )
        if not relation_name.startswith(prefix):
            continue
        owner_suffix = relation_name.removeprefix(prefix)
        if re.fullmatch(r"[0-9a-f]{32}", owner_suffix):
            matches.append((base_name, "run_" + owner_suffix))
    if len(matches) != 1:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_profile_artifact_stale_scope_present"
        )
    return matches[0]


def _artifact_scope_prior_coordinates(
    relation_names: Iterable[str],
) -> dict[str, tuple[str, str]]:
    """Return one complete, unambiguous prior scratch family."""
    coordinates_by_base: dict[str, tuple[str, str]] = {}
    for relation_name in relation_names:
        base_name, owner_run_id = _artifact_scope_prior_owner(
            relation_name
        )
        if base_name in coordinates_by_base:
            raise ProviderDirectoryArtifactBuildStale(
                "provider_directory_artifact_scope_owner_collision"
            )
        coordinates_by_base[base_name] = (
            relation_name,
            owner_run_id,
        )
    expected_bases = {
        model.__tablename__
        for model in (ProviderDirectorySource, *RESOURCE_MODELS)
    }
    if set(coordinates_by_base) != expected_bases:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_profile_artifact_stale_scope_present"
        )
    return coordinates_by_base


def _assert_artifact_scope_prior_owner(
    prior_by_base: Mapping[str, tuple[str, str]],
    owners: tuple[_ArtifactScopeConsumptionOwner, ...],
    admission: _ProviderDirectoryProfileCapacityAdmission,
) -> str:
    """Return the sole terminal prior run and refuse current-run replay."""
    prior_run_ids = {
        owner_run_id
        for _relation_name, owner_run_id in prior_by_base.values()
    }
    if prior_run_ids == {admission.run_id}:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_scope_current_owner_present"
        )
    if len(prior_run_ids) != 1:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_scope_owner_ambiguous"
        )
    prior_run_id = next(iter(prior_run_ids))
    prior_owner = next(
        owner for owner in owners if owner.run_id == prior_run_id
    )
    if {
        base_name: relation_name
        for base_name, (relation_name, _run_id) in prior_by_base.items()
    } != _artifact_scope_owner_relation_names(prior_owner):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_scope_owner_invalid"
        )
    return prior_run_id


async def _artifact_scope_recovery_coordinates(
    schema: str,
    plan: _ArtifactScopeMaterializationPlan,
    admission: _ProviderDirectoryProfileCapacityAdmission,
) -> tuple[_ArtifactScopeRecoveryCoordinate, ...]:
    """Resolve only prior terminal-owner names from the immutable ledger."""
    discovered_names = (
        await _discover_provider_directory_artifact_scope_tables(schema)
    )
    if not discovered_names:
        return ()
    prior_by_base = _artifact_scope_prior_coordinates(discovered_names)
    prior_run_ids = {
        owner_run_id
        for _relation_name, owner_run_id in prior_by_base.values()
    }
    owners = await _artifact_scope_consumption_owners(
        schema,
        admission,
        prior_run_ids,
    )
    _assert_artifact_scope_prior_owner(
        prior_by_base,
        owners,
        admission,
    )
    return tuple(
        _ArtifactScopeRecoveryCoordinate(
            base_table_name=base_name,
            prior_table_name=prior_by_base[base_name][0],
            current_table_name=plan.relation_by_table[base_name],
        )
        for base_name in sorted(prior_by_base)
    )


async def _artifact_scope_relation_identities(
    schema: str,
    relation_names: Iterable[str],
) -> dict[str, tuple[int, str, str]]:
    """Return exact table OID, kind, and persistence for named scratch."""

    names = sorted(set(relation_names))
    if not names:
        return {}
    identity_rows = await db.all(
        """
        SELECT relation.relname::text AS relation_name,
               relation.oid::bigint AS relation_oid,
               relation.relkind::text AS relkind,
               relation.relpersistence::text AS relpersistence
          FROM pg_class AS relation
          JOIN pg_namespace AS namespace
            ON namespace.oid = relation.relnamespace
         WHERE namespace.nspname = :schema_name
           AND relation.relname = ANY(CAST(:relation_names AS text[]))
         ORDER BY relation.relname;
        """,
        schema_name=schema,
        relation_names=names,
    )
    return {
        str(row_map["relation_name"]): (
            int(row_map["relation_oid"]),
            str(row_map["relkind"]),
            str(row_map["relpersistence"]),
        )
        for row_map in (
            _pagination_checkpoint_row_mapping(identity_row)
            for identity_row in identity_rows
        )
    }


async def _assert_artifact_scope_recovery_unreferenced(
    schema: str,
    relation_oids: list[int],
    admission: _ProviderDirectoryProfileCapacityAdmission,
) -> None:
    """Refuse scratch that is protected by serving or checkpoint identity."""

    geometry = admission.geometry
    protected_oids = {
        geometry.evidence_target_oid,
        geometry.profile_target_oid,
        geometry.build_checkpoint_oid,
        geometry.serving_generation_oid,
        geometry.delta_receipt_oid,
        geometry.import_run_oid,
        geometry.capacity_consumption_oid,
    }
    if protected_oids.intersection(relation_oids):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_scope_protected_oid"
        )
    if await _is_artifact_scope_recovery_referenced(
        schema,
        relation_oids,
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_scope_referenced"
        )


async def _is_artifact_scope_recovery_referenced(
    schema: str,
    relation_oids: list[int],
) -> bool:
    """Return whether serving or checkpoint state retains any scratch OID."""

    checkpoint_ref = _provider_directory_profile_checkpoint_ref(schema)
    serving_ref = _provider_directory_profile_serving_generation_ref(schema)
    receipt_ref = _provider_directory_profile_delta_receipt_ref(schema)
    return bool(
        await db.scalar(
            f"""
            SELECT EXISTS (
                SELECT 1
                  FROM {checkpoint_ref}
                 WHERE evidence_stage_oid = ANY(
                           CAST(:relation_oids AS bigint[])
                       )
                    OR profile_stage_oid = ANY(
                           CAST(:relation_oids AS bigint[])
                       )
                    OR affected_npi_stage_oid = ANY(
                           CAST(:relation_oids AS bigint[])
                       )
                    OR evidence_target_oid = ANY(
                           CAST(:relation_oids AS bigint[])
                       )
                    OR profile_target_oid = ANY(
                           CAST(:relation_oids AS bigint[])
                       )
                UNION ALL
                SELECT 1
                  FROM {serving_ref}
                 WHERE evidence_target_oid = ANY(
                           CAST(:relation_oids AS bigint[])
                       )
                    OR profile_target_oid = ANY(
                           CAST(:relation_oids AS bigint[])
                       )
                UNION ALL
                SELECT 1
                  FROM {receipt_ref}
                 WHERE evidence_target_oid = ANY(
                           CAST(:relation_oids AS bigint[])
                       )
                    OR profile_target_oid = ANY(
                           CAST(:relation_oids AS bigint[])
                       )
            );
            """,
            relation_oids=relation_oids,
        )
    )


def _assert_artifact_scope_recovery_identity(
    expected_names: Iterable[str],
    observed: Mapping[str, tuple[int, str, str]],
) -> None:
    """Require every recovery relation to remain one unlogged heap."""

    names = set(expected_names)
    if set(observed) != names or any(
        identity[1:] != ("r", "u")
        for identity in observed.values()
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_scope_recovery_identity_changed"
        )


async def _create_recovery_artifact_scope_layouts(
    schema: str,
    plan: _ArtifactScopeMaterializationPlan,
) -> None:
    """Create current-run layouts inside the atomic ownership takeover."""

    for base_name, current_name in sorted(
        plan.relation_by_table.items()
    ):
        plan.created_tables.append(current_name)
        await _create_provider_directory_artifact_scope_layout(
            plan.model_by_table_name[base_name],
            schema,
            current_name,
            status_executor=db.status,
        )


async def _assert_artifact_scope_recovery_layouts(
    schema: str,
    coordinates: tuple[_ArtifactScopeRecoveryCoordinate, ...],
    prior_identities: Mapping[str, tuple[int, str, str]],
    admission: _ProviderDirectoryProfileCapacityAdmission,
) -> None:
    """Match each old layout to its freshly generated model layout."""

    current_identities = await _artifact_scope_relation_identities(
        schema,
        (coordinate.current_table_name for coordinate in coordinates),
    )
    _assert_artifact_scope_recovery_identity(
        (coordinate.current_table_name for coordinate in coordinates),
        current_identities,
    )
    for coordinate in coordinates:
        prior_layout = (
            await _provider_directory_profile_relation_storage_fingerprint(
                prior_identities[coordinate.prior_table_name][0],
                expected_persistence="u",
            )
        )
        current_layout = (
            await _provider_directory_profile_relation_storage_fingerprint(
                current_identities[coordinate.current_table_name][0],
                expected_persistence="u",
            )
        )
        if (
            prior_layout.structural_fingerprint
            != current_layout.structural_fingerprint
            or prior_layout.effective_tablespace_oids
            != (admission.geometry.tablespace_oid,)
            or current_layout.effective_tablespace_oids
            != (admission.geometry.tablespace_oid,)
        ):
            raise ProviderDirectoryArtifactBuildStale(
                "provider_directory_artifact_scope_recovery_layout_changed"
            )


async def _recover_provider_directory_artifact_scope(
    schema: str,
    plan: _ArtifactScopeMaterializationPlan,
) -> tuple[str, ...]:
    """Atomically replace exact hard-crash residue with current-run layouts."""

    admission = _provider_directory_profile_capacity_admission()
    if admission is None:
        return ()
    coordinates = await _artifact_scope_recovery_coordinates(
        schema,
        plan,
        admission,
    )
    if not coordinates:
        return ()
    prior_names = tuple(
        coordinate.prior_table_name for coordinate in coordinates
    )
    initial_identities = await _artifact_scope_relation_identities(
        schema,
        prior_names,
    )
    _assert_artifact_scope_recovery_identity(
        prior_names,
        initial_identities,
    )
    await _reserve_provider_directory_profile_wal_budget(
        admission,
        control_operation_counts={
            "artifact_scope_recovery_drop": len(coordinates),
        },
    )
    await _reserve_artifact_scope_layout_wal()
    await _replace_terminal_artifact_scope(
        schema,
        plan,
        coordinates,
        prior_names,
        initial_identities,
        admission,
    )
    if await _artifact_scope_relation_identities(schema, prior_names):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_scope_recovery_postimage_changed"
        )
    LOGGER.warning(
        "Recovered terminal Provider Directory artifact scope build_id=%s "
        "relations=%d",
        admission.build_id,
        len(prior_names),
    )
    return prior_names


async def _replace_terminal_artifact_scope(
    schema: str,
    plan: _ArtifactScopeMaterializationPlan,
    coordinates: tuple[_ArtifactScopeRecoveryCoordinate, ...],
    prior_names: tuple[str, ...],
    initial_identities: Mapping[str, tuple[int, str, str]],
    admission: _ProviderDirectoryProfileCapacityAdmission,
) -> None:
    """Replace locked prior scratch with current layouts in one transaction."""

    async with _provider_directory_profile_capacity_transaction():
        await db.status(
            "LOCK TABLE "
            + ", ".join(
                _qt(schema, prior_name)
                for prior_name in sorted(prior_names)
            )
            + " IN ACCESS EXCLUSIVE MODE NOWAIT;"
        )
        locked_identities = await _artifact_scope_relation_identities(
            schema,
            prior_names,
        )
        if locked_identities != initial_identities:
            raise ProviderDirectoryArtifactBuildStale(
                "provider_directory_artifact_scope_recovery_oid_changed"
            )
        await _assert_artifact_scope_recovery_unreferenced(
            schema,
            [
                identity[0]
                for identity in locked_identities.values()
            ],
            admission,
        )
        await _create_recovery_artifact_scope_layouts(schema, plan)
        await _assert_artifact_scope_recovery_layouts(
            schema,
            coordinates,
            locked_identities,
            admission,
        )
        for prior_name in reversed(sorted(prior_names)):
            await db.status(f"DROP TABLE {_qt(schema, prior_name)};")


async def _materialize_artifact_resource_waves(
    schema: str,
    plan: _ArtifactScopeMaterializationPlan,
    fence: ProviderDirectoryArtifactDatasetFence,
    resource_types: frozenset[str],
    projection: _ProviderDirectoryArtifactScopeExactProjection | None,
    projection_by_table: Mapping[
        str,
        _ProviderDirectoryArtifactScopeTableProjection,
    ],
    batch_size: int | None,
    worker_count: int | None,
) -> None:
    """Materialize resource relations in bounded worker waves."""
    resolved_worker_count = min(
        worker_count or _provider_directory_artifact_scope_workers(),
        len(plan.resource_scope_jobs),
    )
    wave_width = max(resolved_worker_count, 1)
    for wave_start in range(0, len(plan.resource_scope_jobs), wave_width):
        wave_jobs = plan.resource_scope_jobs[
            wave_start : wave_start + wave_width
        ]
        await _gather_provider_directory_profile_tasks(
            [
                asyncio.create_task(
                    _materialize_provider_directory_artifact_resource_scope(
                        schema,
                        scope_table,
                        model,
                        fence,
                        resource_types,
                        batch_size=batch_size,
                        projection=projection_by_table.get(
                            model.__tablename__
                        ),
                    )
                )
                for model, scope_table in wave_jobs
            ]
        )
        if projection is not None:
            await _assert_provider_directory_artifact_scope_observed_capacity(
                schema,
                plan.relation_by_table,
                projection,
            )


async def _materialize_artifact_scope_payload(
    schema: str,
    plan: _ArtifactScopeMaterializationPlan,
    fence: ProviderDirectoryArtifactDatasetFence,
    resource_fence: ProviderDirectoryArtifactDatasetFence,
    resource_types: frozenset[str],
    projection: _ProviderDirectoryArtifactScopeExactProjection | None,
    batch_size: int | None,
    worker_count: int | None,
) -> None:
    """Materialize source and resource payloads under one exact projection."""
    if not plan.created_tables:
        await _create_artifact_scope_layouts(schema, plan)
    if projection is not None:
        await _preflight_provider_directory_artifact_scope_capacity(
            schema,
            plan.relation_by_table,
            projection,
        )
    projection_by_table = (
        {
            table_projection.table_name: table_projection
            for table_projection in projection.tables
        }
        if projection is not None
        else {}
    )
    await _materialize_provider_directory_artifact_source_scope(
        schema,
        plan.source_table,
        [dataset.source_id for dataset in fence.datasets],
        projection=projection_by_table.get(
            ProviderDirectorySource.__tablename__
        ),
    )
    if projection is not None:
        await _assert_provider_directory_artifact_scope_observed_capacity(
            schema,
            plan.relation_by_table,
            projection,
        )
    await _materialize_artifact_resource_waves(
        schema,
        plan,
        resource_fence,
        resource_types,
        projection,
        projection_by_table,
        batch_size,
        worker_count,
    )


async def _cleanup_failed_artifact_scope(
    schema: str,
    created_tables: list[str],
    materialization_error: BaseException,
) -> None:
    """Drain partial scratch tables or combine materialization failures."""
    try:
        await _drain_artifact_scope_cleanup(schema, created_tables)
    except BaseException as cleanup_error:
        if not (
            isinstance(materialization_error, asyncio.CancelledError)
            and isinstance(cleanup_error, asyncio.CancelledError)
        ):
            raise BaseExceptionGroup(
                "provider_directory_artifact_materialization_and_cleanup_failed",
                [materialization_error, cleanup_error],
            ) from materialization_error


async def _materialize_artifact_scope_tables(
    schema: str,
    run_id: str | None,
    fence: ProviderDirectoryArtifactDatasetFence,
    resource_types: frozenset[str],
    *,
    resource_fence: ProviderDirectoryArtifactDatasetFence | None = None,
    projection: (
        _ProviderDirectoryArtifactScopeExactProjection | None
    ) = None,
    batch_size: int | None = None,
    worker_count: int | None = None,
) -> tuple[dict[str, str], list[str]]:
    """Materialize all fenced artifact-scope tables for one build."""
    plan = _artifact_scope_materialization_plan(run_id)
    try:
        await _recover_provider_directory_artifact_scope(
            schema,
            plan,
        )
        await _materialize_artifact_scope_payload(
            schema,
            plan,
            fence,
            resource_fence or fence,
            resource_types,
            projection,
            batch_size,
            worker_count,
        )
    except BaseException as materialization_error:
        await _cleanup_failed_artifact_scope(
            schema,
            plan.created_tables,
            materialization_error,
        )
        raise
    return plan.relation_by_table, plan.created_tables


async def _drain_artifact_scope_cleanup(
    schema: str,
    table_names: list[str],
) -> None:
    """Finish exact scope cleanup before propagating repeated cancellation."""

    cleanup_task = asyncio.create_task(
        _drop_artifact_scope_tables(schema, table_names)
    )
    cancellation_error: asyncio.CancelledError | None = None
    while not cleanup_task.done():
        try:
            await asyncio.shield(cleanup_task)
        except asyncio.CancelledError as exc:
            cancellation_error = exc
            continue
    cleanup_task.result()
    if cancellation_error is not None:
        raise cancellation_error


async def _drop_artifact_scope_tables(
    schema: str,
    table_names: list[str],
) -> None:
    capacity_admission = _provider_directory_profile_capacity_admission()
    for table_name in reversed(table_names):
        try:
            if capacity_admission is not None:
                await _reserve_provider_directory_profile_wal_budget(
                    capacity_admission,
                    control_operation_counts={"artifact_scope_drop": 1},
                )
            await _provider_directory_profile_capacity_status(
                f"DROP TABLE IF EXISTS {_qt(schema, table_name)};"
            )
        except Exception:
            LOGGER.warning(
                "Failed to clean Provider Directory artifact scope %s",
                table_name,
                exc_info=True,
            )
            if capacity_admission is not None:
                raise


async def publish_provider_directory_location_address_keys(
    db_schema: str | None = None,
    *,
    run_id: str | None = None,
    source_ids: list[str] | tuple[str, ...] | None = None,
    seen_table: str | None = None,
    batch_size: int | None = None,
) -> int:
    """Publish provider directory location address keys for provider-directory serving."""
    schema = db_schema or _schema()
    if not await _has_address_canon_functions(schema):
        return 0
    restore_state_from_zip = await _is_table_present(schema, "geo_zip_lookup")
    params_by_name: dict[str, Any] = {}
    if run_id is not None:
        params_by_name["run_id"] = run_id
    if source_ids:
        params_by_name["source_ids"] = list(source_ids)
    total_updated = 0
    after_source_id: str | None = None
    after_resource_id: str | None = None
    bounded_batch_size = max(int(batch_size or _location_address_key_batch_size()), 1)
    sql = provider_directory_location_address_key_batch_sql(
        schema,
        restore_state_from_zip=restore_state_from_zip,
        run_id=run_id,
        source_ids=source_ids,
        seen_table=seen_table,
    )
    while True:
        result_row = await db.first(
            sql,
            **params_by_name,
            after_source_id=after_source_id,
            after_resource_id=after_resource_id,
            batch_size=bounded_batch_size,
        )
        result_by_field = (
            result_row._mapping
            if hasattr(result_row, "_mapping")
            else dict(result_row or {})
        )
        candidate_rows = int(result_by_field.get("candidate_rows") or 0)
        updated_rows = int(result_by_field.get("updated_rows") or 0)
        total_updated += updated_rows
        next_source_id = _clean_text(result_by_field.get("last_source_id"))
        next_resource_id = _clean_text(
            result_by_field.get("last_resource_id")
        )
        if candidate_rows <= 0 or not next_source_id or not next_resource_id:
            break
        if next_source_id == after_source_id and next_resource_id == after_resource_id:
            break
        after_source_id = next_source_id
        after_resource_id = next_resource_id
    return total_updated


async def backfill_provider_directory_resource_id_npis(
    db_schema: str | None = None,
    *,
    run_id: str | None = None,
    source_ids: list[str] | tuple[str, ...] | None = None,
    seen_table: str | None = None,
) -> dict[str, int]:
    """Backfill payer rows that use the FHIR resource id as the NPI."""
    schema = db_schema or _schema()
    cleaned_source_ids = _clean_source_id_list(source_ids)
    query_params_by_name: dict[str, Any] = {}
    scope_clauses: list[str] = []
    if cleaned_source_ids:
        scope_clauses.append("resource.source_id = ANY(CAST(:source_ids AS varchar[]))")
        query_params_by_name["source_ids"] = cleaned_source_ids
    if seen_table:
        seen_run_filter = "AND seen.run_id = CAST(:run_id AS varchar)" if run_id else ""
        if run_id:
            query_params_by_name["run_id"] = run_id
        seen_ref = _qt(schema, seen_table)
        scope_clauses.append(
            f"""EXISTS (
                SELECT 1
                  FROM {seen_ref} AS seen
                 WHERE seen.resource_type = :resource_type
                   {seen_run_filter}
                   AND seen.source_id = resource.source_id
                   AND seen.resource_id = resource.resource_id
            )"""
        )
    elif run_id:
        scope_clauses.append("resource.last_seen_run_id = CAST(:run_id AS varchar)")
        query_params_by_name["run_id"] = run_id
    scope_sql = "".join(f"\n               AND {clause}" for clause in scope_clauses)
    updated_counts_by_resource: dict[str, int] = {}
    for resource_type, table_name in (
        ("Practitioner", "provider_directory_practitioner"),
        ("Organization", "provider_directory_organization"),
    ):
        updated_counts_by_resource[resource_type] = _coerce_rowcount(
            await db.status(
                f"""
                UPDATE {_qt(schema, table_name)} AS resource
                   SET npi = resource.resource_id::bigint,
                       updated_at = now()
                 WHERE resource.npi IS NULL
                   AND resource.resource_id ~ '^[0-9]{{10}}$'
                   {scope_sql};
                """,
                **query_params_by_name,
                resource_type=resource_type,
            )
        )
    return updated_counts_by_resource


async def _assert_no_resource_npi_candidates(
    schema: str,
    source_ids: list[str] | tuple[str, ...],
) -> None:
    """Refuse admitted publication if canonical NPI repair is still required."""

    cleaned_source_ids = _clean_source_id_list(source_ids)
    if not cleaned_source_ids:
        return
    for resource_type, table_name in (
        ("Practitioner", "provider_directory_practitioner"),
        ("Organization", "provider_directory_organization"),
    ):
        candidate_exists = bool(
            await db.scalar(
                f"""
                SELECT EXISTS (
                    SELECT 1
                      FROM {_qt(schema, table_name)} AS resource
                     WHERE resource.source_id = ANY(
                               CAST(:source_ids AS varchar[])
                           )
                       AND resource.npi IS NULL
                       AND resource.resource_id ~ '^[0-9]{{10}}$'
                     LIMIT 1
                );
                """,
                source_ids=cleaned_source_ids,
            )
        )
        if candidate_exists:
            raise RuntimeError(
                "provider_directory_profile_resource_id_npi_backfill_"
                "required_before_capacity_admission:"
                + resource_type
            )


def _unique_artifact_datasets(
    fence: ProviderDirectoryArtifactDatasetFence,
) -> list[ProviderDirectoryArtifactDataset]:
    datasets_by_id: dict[str, ProviderDirectoryArtifactDataset] = {}
    for dataset in fence.datasets:
        incumbent = datasets_by_id.setdefault(dataset.dataset_id, dataset)
        if incumbent.endpoint_id != dataset.endpoint_id:
            raise RuntimeError(
                "provider_directory_artifact_dataset_endpoint_ambiguous:"
                + dataset.dataset_id
            )
    return [datasets_by_id[dataset_id] for dataset_id in sorted(datasets_by_id)]


def _artifact_fence_for_dataset(
    fence: ProviderDirectoryArtifactDatasetFence,
    dataset_id: str,
) -> ProviderDirectoryArtifactDatasetFence:
    return ProviderDirectoryArtifactDatasetFence(
        datasets=tuple(
            dataset
            for dataset in fence.datasets
            if dataset.dataset_id == dataset_id
        ),
        should_select_validated_candidates=(
            fence.should_select_validated_candidates
        ),
        promotion_aliases=tuple(
            alias
            for alias in fence.promotion_aliases
            if alias.dataset_id == dataset_id
        ),
    )


async def _lock_dataset_serving_relation_build(
    executor: Any,
    dataset_id: str,
) -> None:
    await executor.scalar(
        "SELECT pg_advisory_xact_lock(hashtextextended(:lock_key, 0));",
        lock_key=f"provider-directory-dataset-serving-relations:{dataset_id}",
    )


async def _record_current_dataset_serving_relation_proof(
    dataset: ProviderDirectoryArtifactDataset,
    metadata_key: str,
    proof: dict[str, Any],
) -> None:
    await _record_current_dataset_publication_proof(
        dataset,
        metadata_key,
        proof,
    )


async def _record_current_dataset_publication_proof(
    dataset: ProviderDirectoryArtifactDataset,
    metadata_key: str,
    proof: dict[str, Any],
) -> None:
    """Write one additive proof while the exact dataset row is locked."""
    dataset_ref = _qt(
        _schema(),
        ProviderDirectoryEndpointDataset.__tablename__,
    )
    updated = await db.status(
        f"""
        UPDATE {dataset_ref}
           SET publication_metadata_json = jsonb_set(
               COALESCE(publication_metadata_json::jsonb, '{{}}'::jsonb),
               '{{{metadata_key}}}',
               CAST(:proof_json AS jsonb),
               true
           )
         WHERE dataset_id = :dataset_id
           AND endpoint_id = :endpoint_id
           AND COALESCE(acquisition_root_run_id, import_run_id)
               IS NOT DISTINCT FROM :evidence_run_id
           AND previous_dataset_id IS NOT DISTINCT FROM :previous_dataset_id
           AND dataset_hash IS NOT DISTINCT FROM :dataset_hash
           AND is_current = :is_current
           AND status = :expected_status
           AND superseded_at IS NULL;
        """,
        proof_json=json.dumps(proof, sort_keys=True, default=_json_default),
        dataset_id=dataset.dataset_id,
        endpoint_id=dataset.endpoint_id,
        evidence_run_id=dataset.evidence_run_id,
        previous_dataset_id=dataset.previous_dataset_id,
        dataset_hash=dataset.dataset_hash,
        is_current=dataset.is_current,
        expected_status=dataset.status,
    )
    if _coerce_rowcount(updated) != 1:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_endpoint_dataset_metadata_changed"
        )


def _artifact_dataset_source_summary_source_ids(
    publication_metadata: dict[str, Any],
    dataset: ProviderDirectoryArtifactDataset,
    required_source_ids: tuple[str, ...],
) -> tuple[str, ...]:
    raw_source_ids = publication_metadata.get("source_ids")
    normalized_source_ids = (
        tuple(sorted(raw_source_ids))
        if isinstance(raw_source_ids, list)
        and all(
            isinstance(source_id, str)
            and bool(source_id)
            and source_id == source_id.strip()
            for source_id in raw_source_ids
        )
        else ()
    )
    if (
        not normalized_source_ids
        or len(normalized_source_ids) != len(set(normalized_source_ids))
        or not set(required_source_ids).issubset(normalized_source_ids)
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_source_summary_source_ids_invalid:"
            + dataset.dataset_id
        )
    return normalized_source_ids


def _artifact_source_summary_candidate_sql() -> str:
    dataset_ref = _unscoped_qt(
        _schema(),
        ProviderDirectoryEndpointDataset.__tablename__,
    )
    return f"""
        SELECT acquisition_root_run_id, publication_metadata_json
          FROM {dataset_ref}
         WHERE dataset_id = :dataset_id
           AND endpoint_id = :endpoint_id
           AND COALESCE(acquisition_root_run_id, import_run_id)
               IS NOT DISTINCT FROM :evidence_run_id
           AND previous_dataset_id IS NOT DISTINCT FROM :previous_dataset_id
           AND dataset_hash IS NOT DISTINCT FROM :dataset_hash
           AND is_current = :is_current
           AND status = :expected_status
           AND superseded_at IS NULL;
    """


async def _current_artifact_dataset_source_summary_candidate(
    executor: Any,
    dataset: ProviderDirectoryArtifactDataset,
    required_source_ids: tuple[str, ...],
) -> tuple[EndpointDatasetCandidate, dict[str, Any]]:
    """Load one exact locked dataset binding for retained summary work."""
    metadata_record = await executor.first(
        _artifact_source_summary_candidate_sql(),
        dataset_id=dataset.dataset_id,
        endpoint_id=dataset.endpoint_id,
        evidence_run_id=dataset.evidence_run_id,
        previous_dataset_id=dataset.previous_dataset_id,
        dataset_hash=dataset.dataset_hash,
        is_current=dataset.is_current,
        expected_status=dataset.status,
    )
    return _source_summary_candidate_from_metadata_record(
        metadata_record,
        dataset,
        required_source_ids,
    )


def _source_summary_candidate_from_metadata_record(
    metadata_record: Any,
    dataset: ProviderDirectoryArtifactDataset,
    required_source_ids: tuple[str, ...],
) -> tuple[EndpointDatasetCandidate, dict[str, Any]]:
    """Validate lineage and preserve the dataset's complete source scope."""
    metadata_record_map = _pagination_checkpoint_row_mapping(metadata_record)
    publication_metadata = _json_object(
        metadata_record_map.get("publication_metadata_json")
    )
    acquisition_root_run_id = _clean_text(
        metadata_record_map.get("acquisition_root_run_id")
    )
    if acquisition_root_run_id != dataset.evidence_run_id:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_source_summary_lineage_missing:"
            + dataset.dataset_id
        )
    source_ids = _artifact_dataset_source_summary_source_ids(
        publication_metadata,
        dataset,
        required_source_ids,
    )
    try:
        resource_hash_contract = _dataset_resource_hash_contract(
            {"publication_metadata_json": publication_metadata}
        )
        semantic_projection_as_of = _dataset_semantic_projection_as_of(
            {"publication_metadata_json": publication_metadata},
            resource_hash_contract,
        )
        proof_resource_scope = _dataset_proof_resource_scope(
            {"publication_metadata_json": publication_metadata},
            dataset.selected_resources,
            resource_hash_contract,
        )
    except RuntimeError as error:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_source_summary_hash_identity_invalid:"
            + dataset.dataset_id
        ) from error
    return (
        EndpointDatasetCandidate(
            endpoint_id=dataset.endpoint_id,
            dataset_id=dataset.dataset_id,
            acquisition_root_run_id=acquisition_root_run_id,
            source_ids=source_ids,
            selected_resources=dataset.selected_resources,
            import_run_id=dataset.evidence_run_id,
            previous_dataset_id=dataset.previous_dataset_id,
            resource_hash_contract=resource_hash_contract,
            semantic_projection_as_of=semantic_projection_as_of,
            proof_resource_scope=proof_resource_scope,
            expected_resources=dataset.expected_resources,
        ),
        publication_metadata,
    )


def _assert_artifact_dataset_content_proof(
    dataset: ProviderDirectoryArtifactDataset,
    content_proof: EndpointDatasetContentProof,
) -> None:
    if (
        dataset.dataset_hash is None
        or dataset.resource_count is None
        or content_proof.dataset_hash != dataset.dataset_hash
        or content_proof.resource_count != dataset.resource_count
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_endpoint_dataset_content_changed"
        )


def _validated_existing_artifact_dataset_source_summary(
    publication_metadata: dict[str, Any],
    dataset: ProviderDirectoryArtifactDataset,
    candidate: EndpointDatasetCandidate,
) -> dict[str, Any] | None:
    """Validate a retained summary without changing its semantic type."""
    raw_source_summary = publication_metadata.get(
        SOURCE_SUMMARY_METADATA_KEY
    )
    if raw_source_summary is None:
        return None
    try:
        source_summary = validate_semantic_source_summary(
            raw_source_summary,
            expected_by_field={
                "dataset_id": dataset.dataset_id,
                "endpoint_id": dataset.endpoint_id,
                "acquisition_root_run_id": dataset.evidence_run_id,
                "dataset_hash": dataset.dataset_hash,
                "source_ids": list(candidate.source_ids),
                "selected_resources": list(candidate.selected_resources),
                "total_resources": dataset.resource_count,
            },
        )
    except ProviderDirectorySourceSummaryError as error:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_source_summary_invalid:"
            + dataset.dataset_id
        ) from error
    return source_summary


def _is_summary_relation_proof_exact(
    source_summary: dict[str, Any],
    relation_proof_by_name: dict[str, dict[str, Any]],
) -> bool:
    expected_relation_count_by_field = {
        "network_plan_links": _source_summary_relation_edge_count(
            relation_proof_by_name,
            PROVIDER_DIRECTORY_DATASET_NETWORK_PLAN_METADATA_KEY,
        ),
        "organization_affiliation_links": (
            _source_summary_relation_edge_count(
                relation_proof_by_name,
                PROVIDER_DIRECTORY_DATASET_AFFILIATION_ORGANIZATION_METADATA_KEY,
            )
        ),
    }
    return all(
        source_summary.get(field_name) == expected_count
        for field_name, expected_count in expected_relation_count_by_field.items()
    )


def _existing_artifact_dataset_source_summary(
    publication_metadata: dict[str, Any],
    dataset: ProviderDirectoryArtifactDataset,
    candidate: EndpointDatasetCandidate,
    relation_proof_by_name: dict[str, dict[str, Any]],
) -> dict[str, Any] | None:
    """Reuse one exact FHIR or UHC summary without semantic retyping."""
    source_summary = _validated_existing_artifact_dataset_source_summary(
        publication_metadata,
        dataset,
        candidate,
    )
    if source_summary is None:
        return None
    outcome_proof = publication_metadata.get(
        PROVIDER_DIRECTORY_OUTCOME_RESOURCE_COUNTS_METADATA_KEY
    )
    if not _is_existing_source_summary_outcome_proof(
        outcome_proof,
        dataset,
        candidate,
        source_summary,
    ):
        if (
            source_summary["semantic_contract_id"]
            == SOURCE_SUMMARY_UHC_SEMANTIC_CONTRACT_ID
        ):
            raise ProviderDirectoryArtifactBuildStale(
                "provider_directory_uhc_source_summary_outcome_invalid:"
                + dataset.dataset_id
            )
        return None
    if (
        source_summary["semantic_contract_id"]
        != SOURCE_SUMMARY_FHIR_SEMANTIC_CONTRACT_ID
    ):
        return source_summary
    return (
        source_summary
        if _is_summary_relation_proof_exact(
            source_summary,
            relation_proof_by_name,
        )
        else None
    )


def _is_existing_source_summary_outcome_proof(
    raw_proof: Any,
    dataset: ProviderDirectoryArtifactDataset,
    candidate: EndpointDatasetCandidate,
    source_summary: dict[str, Any],
) -> bool:
    return bool(
        isinstance(raw_proof, dict)
        and raw_proof.get("complete") is True
        and type(raw_proof.get("version")) is int
        and raw_proof.get("version") == 1
        and raw_proof.get("dataset_id") == dataset.dataset_id
        and raw_proof.get("endpoint_id") == dataset.endpoint_id
        and raw_proof.get("acquisition_root_run_id")
        == dataset.evidence_run_id
        and raw_proof.get("dataset_hash") == dataset.dataset_hash
        and raw_proof.get("source_ids") == list(candidate.source_ids)
        and raw_proof.get("selected_resources")
        == list(candidate.selected_resources)
        and raw_proof.get("resource_count") == dataset.resource_count
        and raw_proof.get("resource_counts")
        == source_summary.get("resource_counts")
    )


def _dataset_network_plan_aggregate_proof(
    dataset_proofs: list[dict[str, Any]],
    *,
    build_run_id: str | None,
) -> dict[str, Any]:
    count_fields = (
        "insurance_plan_resource_count",
        "insurance_plan_with_network_refs_count",
        "zero_network_reference_plan_count",
        "malformed_network_refs_payload_count",
        "network_reference_value_count",
        "valid_network_reference_count",
        "invalid_network_reference_count",
        "expected_edge_count",
        "edge_count",
        "duplicate_network_reference_count",
        "replaced_edge_count",
        "plan_projection_count",
        "replaced_plan_projection_count",
        "inserted_plan_projection_count",
    )
    return {
        "complete": True,
        "version": PROVIDER_DIRECTORY_DATASET_NETWORK_PLAN_VERSION,
        "build_run_id": build_run_id,
        "dataset_count": len(dataset_proofs),
        "dataset_ids": [proof["dataset_id"] for proof in dataset_proofs],
        **{
            field_name: sum(int(proof[field_name]) for proof in dataset_proofs)
            for field_name in count_fields
        },
        "datasets": dataset_proofs,
    }


def _dataset_affiliation_organization_aggregate_proof(
    dataset_proofs: list[dict[str, Any]],
    *,
    build_run_id: str | None,
) -> dict[str, Any]:
    count_fields = (
        "affiliation_resource_count",
        "affiliation_with_participating_organization_count",
        "empty_participating_organization_reference_count",
        "malformed_reference_payload_count",
        "valid_reference_count",
        "invalid_reference_count",
        "expected_edge_count",
        "edge_count",
        "replaced_edge_count",
    )
    return {
        "complete": True,
        "version": (
            PROVIDER_DIRECTORY_DATASET_AFFILIATION_ORGANIZATION_VERSION
        ),
        "build_run_id": build_run_id,
        "dataset_count": len(dataset_proofs),
        "dataset_ids": [proof["dataset_id"] for proof in dataset_proofs],
        **{
            field_name: sum(int(proof[field_name]) for proof in dataset_proofs)
            for field_name in count_fields
        },
        "datasets": dataset_proofs,
    }


async def _rebuild_one_current_dataset_relation_set(
    dataset: ProviderDirectoryArtifactDataset,
    *,
    build_run_id: str | None,
    should_rebuild_network_plan: bool,
    should_rebuild_affiliation_organization: bool,
) -> dict[str, dict[str, Any]]:
    proof_by_relation: dict[str, dict[str, Any]] = {}
    if should_rebuild_network_plan:
        network_proof = await _build_provider_directory_dataset_network_plan(
            db,
            dataset.dataset_id,
            build_run_id=build_run_id,
            expected_acquisition_root_run_id=dataset.evidence_run_id,
        )
        proof_by_relation[
            PROVIDER_DIRECTORY_DATASET_NETWORK_PLAN_METADATA_KEY
        ] = network_proof
    if should_rebuild_affiliation_organization:
        affiliation_proof = (
            await _build_provider_directory_dataset_affiliation_organization(
                db,
                dataset.dataset_id,
                build_run_id=build_run_id,
                expected_acquisition_root_run_id=dataset.evidence_run_id,
            )
        )
        proof_by_relation[
            PROVIDER_DIRECTORY_DATASET_AFFILIATION_ORGANIZATION_METADATA_KEY
        ] = affiliation_proof
    for metadata_key, relation_proof in proof_by_relation.items():
        await _record_current_dataset_serving_relation_proof(
            dataset,
            metadata_key,
            relation_proof,
        )
    return proof_by_relation


def _aggregate_dataset_serving_relation_proofs(
    proof_list_by_relation: dict[str, list[dict[str, Any]]],
    *,
    build_run_id: str | None,
) -> dict[str, dict[str, Any]]:
    aggregate_by_relation: dict[str, dict[str, Any]] = {}
    network_key = PROVIDER_DIRECTORY_DATASET_NETWORK_PLAN_METADATA_KEY
    affiliation_key = (
        PROVIDER_DIRECTORY_DATASET_AFFILIATION_ORGANIZATION_METADATA_KEY
    )
    if network_key in proof_list_by_relation:
        aggregate_by_relation[network_key] = (
            _dataset_network_plan_aggregate_proof(
                proof_list_by_relation[network_key],
                build_run_id=build_run_id,
            )
        )
    if affiliation_key in proof_list_by_relation:
        aggregate_by_relation[affiliation_key] = (
            _dataset_affiliation_organization_aggregate_proof(
                proof_list_by_relation[affiliation_key],
                build_run_id=build_run_id,
            )
        )
    return aggregate_by_relation


def _uhc_artifact_content_proof(
    dataset: ProviderDirectoryArtifactDataset,
    publication_metadata: dict[str, Any],
) -> EndpointDatasetContentProof:
    try:
        uhc_proof = validate_uhc_canonical_content_proof(
            publication_metadata.get(
                UHC_CANONICAL_CONTENT_PROOF_METADATA_KEY
            ),
            dataset_id=dataset.dataset_id,
            endpoint_id=dataset.endpoint_id,
            acquisition_root_run_id=dataset.evidence_run_id,
        )
    except UhcCanonicalProofError as error:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_uhc_canonical_proof_invalid"
        ) from error
    return EndpointDatasetContentProof(
        dataset_hash=uhc_proof["dataset_hash"],
        resource_count=uhc_proof["resource_count"],
        resource_hashes=dict(uhc_proof["resource_hashes"]),
        resource_counts=dict(uhc_proof["resource_counts"]),
    )


async def _generic_artifact_content_proof(
    dataset: ProviderDirectoryArtifactDataset,
    candidate: EndpointDatasetCandidate,
    publication_metadata: dict[str, Any],
) -> EndpointDatasetContentProof:
    proof_resource_scope = _candidate_proof_resource_scope(candidate)
    content_resource_scope = (
        proof_resource_scope or dataset.selected_resources
    )
    raw_content_proof = publication_metadata.get(
        PROVIDER_DIRECTORY_CONTENT_PROOF_METADATA_KEY
    )
    if raw_content_proof is None:
        return await _endpoint_dataset_content_proof(
            db,
            dataset.dataset_id,
            content_resource_scope,
            verify_payload_hashes=True,
            resource_hash_contract=candidate.resource_hash_contract,
        )
    try:
        stored_proof = validate_stored_dataset_proof_metadata(
            raw_content_proof,
            dataset_id=dataset.dataset_id,
            endpoint_id=dataset.endpoint_id,
            acquisition_root_run_id=dataset.evidence_run_id,
            source_ids=candidate.source_ids,
            selected_resources=dataset.selected_resources,
            options=ProviderDirectoryStoredProofOptions(
                proof_resource_scope=proof_resource_scope,
                expected_resource_hash_contract=(
                    candidate.resource_hash_contract
                ),
                expected_semantic_projection_as_of=(
                    candidate.semantic_projection_as_of
                ),
            ),
        )
    except ProviderDirectoryProofStoreError as error:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_content_proof_invalid"
        ) from error
    return EndpointDatasetContentProof(
        dataset_hash=stored_proof["dataset_hash"],
        resource_count=stored_proof["resource_count"],
        resource_hashes=dict(stored_proof["resource_hashes"]),
        resource_counts=dict(stored_proof["resource_counts"]),
        source_metrics=dict(stored_proof["source_metrics"]),
        proof_metadata=stored_proof,
    )


async def _artifact_content_proof(
    dataset: ProviderDirectoryArtifactDataset,
    candidate: EndpointDatasetCandidate,
    publication_metadata: dict[str, Any],
) -> EndpointDatasetContentProof:
    if dataset.source_id == UHC_RETAINED_SOURCE_ID:
        return _uhc_artifact_content_proof(dataset, publication_metadata)
    return await _generic_artifact_content_proof(
        dataset,
        candidate,
        publication_metadata,
    )


async def _refresh_current_artifact_dataset_source_summary(
    dataset: ProviderDirectoryArtifactDataset,
    candidate: EndpointDatasetCandidate,
    publication_metadata: dict[str, Any],
    relation_proof_by_name: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    """Reuse a sealed summary or rebuild it from verified retained rows."""
    source_summary = _existing_artifact_dataset_source_summary(
        publication_metadata,
        dataset,
        candidate,
        relation_proof_by_name,
    )
    if source_summary is not None:
        return source_summary
    content_proof = await _artifact_content_proof(
        dataset,
        candidate,
        publication_metadata,
    )
    _assert_artifact_dataset_content_proof(dataset, content_proof)
    await _record_current_dataset_publication_proof(
        dataset,
        PROVIDER_DIRECTORY_OUTCOME_RESOURCE_COUNTS_METADATA_KEY,
        _outcome_resource_count_proof(candidate, content_proof),
    )
    source_summary = await _endpoint_dataset_source_summary(
        db,
        candidate,
        content_proof,
        relation_proof_by_name,
    )
    if source_summary is None:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_source_summary_lineage_missing"
        )
    await _record_current_dataset_publication_proof(
        dataset,
        SOURCE_SUMMARY_METADATA_KEY,
        source_summary,
    )
    return source_summary


async def _rebuild_one_current_dataset_artifacts(
    dataset: ProviderDirectoryArtifactDataset,
    dataset_fence: ProviderDirectoryArtifactDatasetFence,
    *,
    build_run_id: str | None,
    should_rebuild_network_plan: bool,
    should_rebuild_affiliation_organization: bool,
    should_rebuild_source_summary: bool,
) -> tuple[dict[str, dict[str, Any]], dict[str, Any] | None]:
    """Rebuild one dataset's proofs in a single stable transaction."""
    async with db.transaction():
        if should_rebuild_source_summary:
            await db.status(
                "SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;"
            )
        await _lock_and_verify_artifact_dataset_fence(dataset_fence, db)
        await _lock_dataset_serving_relation_build(db, dataset.dataset_id)
        summary_context = None
        if should_rebuild_source_summary:
            required_source_ids = tuple(
                sorted(alias.source_id for alias in dataset_fence.datasets)
            )
            summary_context = (
                await _current_artifact_dataset_source_summary_candidate(
                    db,
                    dataset,
                    required_source_ids,
                )
            )
        relation_proof_by_name = (
            await _rebuild_one_current_dataset_relation_set(
                dataset,
                build_run_id=build_run_id,
                should_rebuild_network_plan=should_rebuild_network_plan,
                should_rebuild_affiliation_organization=(
                    should_rebuild_affiliation_organization
                ),
            )
        )
        source_summary = (
            await _refresh_current_artifact_dataset_source_summary(
                dataset,
                summary_context[0],
                summary_context[1],
                relation_proof_by_name,
            )
            if summary_context is not None
            else None
        )
        return relation_proof_by_name, source_summary


def _attach_aggregate_source_summary_proof(
    aggregate_proof_by_name: dict[str, dict[str, Any]],
    source_summaries: list[dict[str, Any]],
) -> None:
    """Attach the aggregate identity of rebuilt dataset source summaries."""
    if not source_summaries:
        return
    aggregate_proof_by_name[SOURCE_SUMMARY_METADATA_KEY] = {
        "complete": True,
        "version": 1,
        "dataset_count": len(source_summaries),
        "dataset_ids": [
            summary["dataset_id"] for summary in source_summaries
        ],
        "summary_sha256_by_dataset": {
            summary["dataset_id"]: summary["summary_sha256"]
            for summary in source_summaries
        },
    }


async def _rebuild_current_dataset_serving_relations(
    fence: ProviderDirectoryArtifactDatasetFence,
    *,
    build_run_id: str | None,
    should_rebuild_network_plan: bool,
    should_rebuild_affiliation_organization: bool,
    should_rebuild_source_summary: bool = False,
) -> dict[str, dict[str, Any]]:
    """Refresh selected dataset relations without global-table cutover."""
    selected_datasets = _unique_artifact_datasets(fence)
    proof_list_by_relation: dict[str, list[dict[str, Any]]] = {}
    source_summaries: list[dict[str, Any]] = []
    for dataset in selected_datasets:
        dataset_fence = _artifact_fence_for_dataset(fence, dataset.dataset_id)
        relation_proof_by_name, source_summary = (
            await _rebuild_one_current_dataset_artifacts(
                dataset,
                dataset_fence,
                build_run_id=build_run_id,
                should_rebuild_network_plan=should_rebuild_network_plan,
                should_rebuild_affiliation_organization=(
                    should_rebuild_affiliation_organization
                ),
                should_rebuild_source_summary=should_rebuild_source_summary,
            )
        )
        if source_summary is not None:
            source_summaries.append(source_summary)
        for relation_name, relation_proof in relation_proof_by_name.items():
            proof_list_by_relation.setdefault(
                relation_name,
                [],
            ).append(relation_proof)
    for relation_name, should_rebuild in (
        (
            PROVIDER_DIRECTORY_DATASET_NETWORK_PLAN_METADATA_KEY,
            should_rebuild_network_plan,
        ),
        (
            PROVIDER_DIRECTORY_DATASET_AFFILIATION_ORGANIZATION_METADATA_KEY,
            should_rebuild_affiliation_organization,
        ),
    ):
        if should_rebuild:
            proof_list_by_relation.setdefault(relation_name, [])
    aggregate_proof_by_name = _aggregate_dataset_serving_relation_proofs(
        proof_list_by_relation,
        build_run_id=build_run_id,
    )
    _attach_aggregate_source_summary_proof(
        aggregate_proof_by_name,
        source_summaries,
    )
    return aggregate_proof_by_name


async def _publish_current_dataset_relation_artifacts(
    fence: ProviderDirectoryArtifactDatasetFence,
    *,
    run_id: str | None,
    metrics: dict[str, Any],
    publish_artifacts_targets: set[str] | None,
) -> None:
    should_rebuild_network_plan = is_provider_directory_publish_target_enabled(
        publish_artifacts_targets,
        "dataset_network_plan",
    )
    should_rebuild_affiliation_organization = (
        is_provider_directory_publish_target_enabled(
            publish_artifacts_targets,
            "dataset_affiliation_organization",
        )
    )
    relation_proof_by_name: dict[str, dict[str, Any]] = {}
    if should_rebuild_network_plan or should_rebuild_affiliation_organization:
        relation_proof_by_name = (
            await _rebuild_current_dataset_serving_relations(
                fence,
                build_run_id=run_id,
                should_rebuild_network_plan=should_rebuild_network_plan,
                should_rebuild_affiliation_organization=(
                    should_rebuild_affiliation_organization
                ),
                should_rebuild_source_summary=(
                    should_rebuild_network_plan
                    and should_rebuild_affiliation_organization
                ),
            )
        )
    metrics.update(relation_proof_by_name)
    if not should_rebuild_network_plan:
        metrics[PROVIDER_DIRECTORY_DATASET_NETWORK_PLAN_METADATA_KEY] = (
            _provider_directory_publish_target_skipped()
        )
    if not should_rebuild_affiliation_organization:
        metrics[
            PROVIDER_DIRECTORY_DATASET_AFFILIATION_ORGANIZATION_METADATA_KEY
        ] = _provider_directory_publish_target_skipped()


def _is_dataset_relation_only_artifact_target(
    publish_artifacts_targets: set[str] | None,
) -> bool:
    dataset_relation_targets = {
        "dataset_network_plan",
        "dataset_affiliation_organization",
    }
    return (
        publish_artifacts_targets is not None
        and publish_artifacts_targets.issubset(dataset_relation_targets)
    )


def _artifact_fence_selection_identity(
    fence: ProviderDirectoryArtifactDatasetFence,
) -> tuple[Any, ...]:
    """Return immutable selection fields that relation-proof refresh may not alter."""
    return (
        fence.should_select_validated_candidates,
        tuple(
            sorted(
                (
                    dataset.source_id,
                    dataset.endpoint_id,
                    dataset.dataset_id,
                    dataset.evidence_run_id,
                    dataset.selected_resources,
                    dataset.artifact_resources,
                    dataset.expected_resources,
                    dataset.recorded_expected_resources,
                    dataset.status,
                    dataset.is_current,
                    dataset.previous_dataset_id,
                    dataset.expected_incumbent_dataset_id,
                    dataset.promote_on_cutover,
                    dataset.dataset_hash,
                    dataset.resource_count,
                    dataset.validated_at,
                )
                for dataset in fence.datasets
            )
        ),
    )


def _assert_artifact_fence_selection_unchanged(
    expected_fence: ProviderDirectoryArtifactDatasetFence,
    refreshed_fence: ProviderDirectoryArtifactDatasetFence,
) -> None:
    if (
        _artifact_fence_selection_identity(expected_fence)
        != _artifact_fence_selection_identity(refreshed_fence)
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_artifact_dataset_selection_changed"
        )


async def _publish_provider_directory_dataset_artifacts(
    *,
    run_id: str | None,
    metrics: dict[str, Any],
    source_ids: list[str] | tuple[str, ...] | None,
    publish_corroboration: bool,
    publish_artifacts_targets: set[str] | None,
    require_complete_global_profile_fence: bool = False,
) -> dict[str, Any]:
    """Build one selected dataset bundle and atomically publish its pointers."""
    if require_complete_global_profile_fence and not (
        is_provider_directory_publish_target_enabled(
            publish_artifacts_targets,
            "profile",
        )
    ):
        raise RuntimeError(
            "provider_directory_profile_global_target_required"
        )
    if (
        require_complete_global_profile_fence
        and _clean_source_id_list(source_ids)
    ):
        raise RuntimeError(
            "provider_directory_profile_global_fence_required"
        )
    should_select_validated_candidates = (
        _should_select_validated_artifacts(publish_artifacts_targets)
    )
    fence = await _prepare_artifact_publication_fence(
        source_ids,
        run_id=run_id,
        metrics=metrics,
        publish_artifacts_targets=publish_artifacts_targets,
        publish_corroboration=publish_corroboration,
        should_select_validated_candidates=should_select_validated_candidates,
    )
    if _is_dataset_relation_only_artifact_target(publish_artifacts_targets):
        metrics["publish_artifacts_targets"] = sorted(
            publish_artifacts_targets or ()
        )
        return metrics
    artifact_resource_types = _provider_directory_artifact_resource_types(
        publish_artifacts_targets,
        publish_corroboration=publish_corroboration,
    )
    return await _publish_artifact_bundle_from_fence(
        fence,
        run_id=run_id,
        metrics=metrics,
        source_ids=source_ids,
        publish_corroboration=publish_corroboration,
        publish_artifacts_targets=publish_artifacts_targets,
        artifact_resource_types=artifact_resource_types,
    )


def _assert_profile_selection_matches_artifact_fence(
    execution: ProviderDirectoryProfileExecution,
    fence: ProviderDirectoryArtifactDatasetFence,
) -> None:
    """Bind the artifact scope to every authoritative proof pair exactly."""

    expected_pairs = [
        (
            pair["source_id"],
            pair["endpoint_id"],
            pair["dataset_id"],
            pair["dataset_hash"],
            pair["acquisition_root_run_id"],
            pair["publication_status"],
            pair["is_current"],
        )
        for pair in execution.attestation.pairs
    ]
    actual_pairs = sorted(
        (
            dataset.source_id,
            dataset.endpoint_id,
            dataset.dataset_id,
            dataset.dataset_hash,
            dataset.evidence_run_id,
            dataset.status,
            dataset.is_current,
        )
        for dataset in fence.datasets
    )
    if expected_pairs != actual_pairs:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_profile_selection_fence_changed"
        )


def _provider_directory_global_profile_followup(
    *,
    source_id: str,
    dataset_id: str,
    parent_run_id: str,
) -> dict[str, Any]:
    """Return the source-local descriptor consumed by global orchestration."""

    return {
        "status": "required",
        "kind": "provider_directory_global_profile",
        "intent": "ensure_desired_generation_observed",
        "importer": "provider-directory-fhir",
        "source_id": source_id,
        "dataset_id": dataset_id,
        "parent_run_id": parent_run_id,
        "idempotency_key": "provider-directory-global-profile:" + dataset_id,
        "triggered_by": "pd_profile_followup",
        "params": {
            "publish_artifacts_only": True,
            "publish_artifacts_targets": ["profile"],
            "source_ids": [],
            "require_complete_global_profile_fence": True,
            "publish_corroboration": False,
            "probe": False,
            "import_resources": False,
            "provider_directory_profile_parent_run_id": parent_run_id,
            "provider_directory_profile_dataset_id": dataset_id,
        },
    }


def _provider_directory_dataset_followup(
    *,
    source_id: str,
    endpoint_id: str,
    dataset_id: str,
    dataset_hash: str,
    parent_run_id: str,
) -> dict[str, Any]:
    """Describe the source-local serving work required after publication."""

    return {
        "version": 1,
        "status": "required",
        "kind": "provider_directory_dataset_publication",
        "intent": "ensure_address_overlay_then_unified_address",
        "importer": "provider-directory-fhir",
        "source_id": source_id,
        "endpoint_id": endpoint_id,
        "dataset_id": dataset_id,
        "dataset_hash": dataset_hash,
        "parent_run_id": parent_run_id,
        "idempotency_key": "provider-directory-dataset-followup:" + dataset_id,
        "triggered_by": "pd_dataset_followup",
    }


async def _current_profile_dataset_map(source_id: str) -> dict[str, Any]:
    database_row = await db.first(
        f"""
        SELECT dataset.dataset_id,
               dataset.endpoint_id,
               dataset.acquisition_root_run_id,
               dataset.dataset_hash,
               dataset.status,
               dataset.is_current,
               dataset.superseded_at,
               dataset.publication_metadata_json
          FROM {_qt(_schema(), ProviderDirectorySource.__tablename__)} AS source
          JOIN {_qt(_schema(), ProviderDirectoryEndpointDataset.__tablename__)} AS dataset
            ON dataset.endpoint_id = source.endpoint_id
         WHERE source.source_id = :source_id
           AND dataset.status = :published_status
           AND dataset.is_current = true
           AND dataset.superseded_at IS NULL
         ORDER BY dataset.published_at DESC, dataset.dataset_id DESC
         LIMIT 2;
        """,
        source_id=source_id,
        published_status=ENDPOINT_DATASET_PUBLISHED,
    )
    if database_row is None:
        return {}
    return dict(_pagination_checkpoint_row_mapping(database_row))


async def _source_local_dataset_followup_if_current(
    *,
    source_ids: list[str],
    expected_acquisition_root_run_id: str | None,
) -> dict[str, Any] | None:
    """Return a follow-up only for one exact current published dataset."""

    if len(source_ids) != 1:
        return None
    source_id = source_ids[0]
    dataset_fence = await _resolve_provider_directory_artifact_datasets(
        [source_id],
        should_select_validated_candidates=False,
    )
    if len(dataset_fence.datasets) != 1:
        return None
    dataset = dataset_fence.datasets[0]
    acquisition_root_run_id = _clean_text(dataset.evidence_run_id)
    expected_root_run_id = (
        expected_acquisition_root_run_id or acquisition_root_run_id
    )
    if (
        expected_root_run_id is None
        or acquisition_root_run_id != expected_root_run_id
        or dataset.source_id != source_id
        or dataset.status != ENDPOINT_DATASET_PUBLISHED
        or dataset.is_current is not True
    ):
        return None
    endpoint_id = _clean_text(dataset.endpoint_id)
    dataset_id = _clean_text(dataset.dataset_id)
    dataset_hash = _clean_text(dataset.dataset_hash)
    if endpoint_id is None or dataset_id is None or dataset_hash is None:
        return None
    return _provider_directory_dataset_followup(
        source_id=source_id,
        endpoint_id=endpoint_id,
        dataset_id=dataset_id,
        dataset_hash=dataset_hash,
        parent_run_id=expected_root_run_id,
    )


def _has_dataset_publication_followup_trigger(
    metrics: Mapping[str, Any],
    source_ids: list[str],
    importable_sources: list[dict[str, Any]],
) -> bool:
    """Recognize only a completed atomic source-dataset publication path."""

    if len(source_ids) != 1 or len(importable_sources) != 1:
        return False
    resource_fetch_stats = metrics.get("resource_fetch_stats")
    if isinstance(resource_fetch_stats, Mapping) and any(
        isinstance(resource_stats, Mapping)
        and type(resource_stats.get("official_provider_file_sources")) is int
        and resource_stats["official_provider_file_sources"] == 1
        and type(resource_stats.get("collection_complete_sources")) is int
        and resource_stats["collection_complete_sources"] == 1
        for resource_stats in resource_fetch_stats.values()
    ):
        return True
    dataset_ids = metrics.get("artifact_dataset_ids")
    evidence_run_ids = metrics.get("artifact_dataset_evidence_run_ids")
    return bool(
        isinstance(dataset_ids, list)
        and len(dataset_ids) == 1
        and _clean_text(dataset_ids[0]) is not None
        and isinstance(evidence_run_ids, list)
        and len(evidence_run_ids) == 1
        and _clean_text(evidence_run_ids[0]) is not None
    )


def _is_expected_profile_followup_dataset(
    dataset_state_map: Mapping[str, Any],
    *,
    source_id: str,
    expected_acquisition_root_run_id: str,
) -> bool:
    acquisition_root_run_id = _clean_text(
        dataset_state_map.get("acquisition_root_run_id")
    )
    publication_metadata = _json_object(
        dataset_state_map.get("publication_metadata_json")
    )
    publication_source_ids = _clean_source_id_list(
        publication_metadata.get("source_ids")
    )
    return not (
        _clean_text(dataset_state_map.get("dataset_id")) is None
        or acquisition_root_run_id != expected_acquisition_root_run_id
        or _clean_text(dataset_state_map.get("dataset_hash")) is None
        or source_id not in publication_source_ids
        or _clean_text(dataset_state_map.get("status"))
        != ENDPOINT_DATASET_PUBLISHED
        or dataset_state_map.get("is_current") is not True
        or dataset_state_map.get("superseded_at") is not None
    )


async def _source_local_profile_followup_if_current(
    *,
    source_ids: list[str],
    expected_acquisition_root_run_id: str | None,
) -> dict[str, Any] | None:
    """Describe only an exact source-local dataset that is now current."""

    if (
        len(source_ids) != 1
        or expected_acquisition_root_run_id is None
        or source_ids[0] not in set(profile_artifact.configured_profile_source_ids())
    ):
        return None
    source_id = source_ids[0]
    dataset_state_map = await _current_profile_dataset_map(source_id)
    if not _is_expected_profile_followup_dataset(
        dataset_state_map,
        source_id=source_id,
        expected_acquisition_root_run_id=expected_acquisition_root_run_id,
    ):
        return None
    return _provider_directory_global_profile_followup(
        source_id=source_id,
        dataset_id=str(dataset_state_map["dataset_id"]),
        parent_run_id=expected_acquisition_root_run_id,
    )


async def _attested_profile_publication_fence(
    *,
    run_id: str | None,
    metrics: dict[str, Any],
    execution: ProviderDirectoryProfileExecution,
    source_ids: list[str],
) -> ProviderDirectoryArtifactDatasetFence:
    if execution.attestation.operation == "purge":
        return ProviderDirectoryArtifactDatasetFence(())
    return await _prepare_artifact_publication_fence(
        source_ids,
        run_id=run_id,
        metrics=metrics,
        publish_artifacts_targets={"profile"},
        publish_corroboration=False,
        should_select_validated_candidates=False,
    )


def _attach_profile_selection_result(
    execution: ProviderDirectoryProfileExecution,
    published_metrics_by_name: dict[str, Any],
) -> None:
    profile_metrics = published_metrics_by_name.get("profile")
    if not isinstance(profile_metrics, dict):
        raise RuntimeError("provider_directory_profile_selection_result_missing")
    profile_generation_id = _clean_text(profile_metrics.get("generation_id"))
    profile_as_of = _clean_text(profile_metrics.get("profile_as_of"))
    if profile_generation_id is None:
        raise RuntimeError(
            "provider_directory_profile_selection_generation_missing"
        )
    if profile_as_of is None:
        raise RuntimeError(
            "provider_directory_profile_selection_as_of_missing"
        )
    profile_rows = int(profile_metrics.get("profile_rows") or 0)
    evidence_rows = int(profile_metrics.get("evidence_rows") or 0)
    selected_evidence_rows = int(
        profile_metrics.get("selected_evidence_rows") or 0
    )
    if evidence_rows != selected_evidence_rows:
        raise RuntimeError(
            "provider_directory_profile_selection_evidence_scope_incomplete"
        )
    published_metrics_by_name[PROFILE_SELECTION_RESULT_METRIC] = profile_selection_result(
        execution,
        profile_generation_id=profile_generation_id,
        profile_as_of=profile_as_of,
        profile_rows=profile_rows,
        profile_source_evidence_rows=evidence_rows,
    )


async def _provider_directory_profile_replay_publish_metrics(
    metrics: dict[str, Any],
    fence: ProviderDirectoryArtifactDatasetFence,
    profile_metrics: dict[str, Any],
) -> dict[str, Any]:
    published_metrics_by_name = dict(metrics)
    published_metrics_by_name["profile"] = profile_metrics
    published_metrics_by_name["artifact_dataset_ids"] = sorted(
        {dataset.dataset_id for dataset in fence.datasets}
    )
    published_metrics_by_name["artifact_dataset_evidence_run_ids"] = sorted(
        {dataset.evidence_run_id for dataset in fence.datasets}
    )
    return await _record_artifact_promotion_metrics(
        fence,
        published_metrics_by_name,
        0,
    )


async def _publish_attested_provider_directory_profile_build(
    *,
    run_id: str | None,
    control_run_id: str | None,
    metrics: dict[str, Any],
    execution: ProviderDirectoryProfileExecution,
    fence: ProviderDirectoryArtifactDatasetFence,
    source_ids: list[str],
) -> dict[str, Any]:
    """Publish a profile build only while its attestation remains current."""
    if run_id is None:
        raise RuntimeError(
            "provider_directory_profile_capacity_run_id_invalid"
        )
    async with suppress_control_run_heartbeat_persistence(run_id):
        publish_targets = {"profile"}
        artifact_resource_types = _provider_directory_artifact_resource_types(
            publish_targets,
            publish_corroboration=False,
        )
        resource_fence = await _provider_directory_profile_resource_scope_fence(
            fence,
            publish_targets,
        )
        if execution.attestation.operation == "publish":
            await _assert_no_provider_directory_resource_id_npi_backfill_candidates(
                _schema(),
                source_ids,
            )
        capacity_admission = await _admit_provider_directory_profile_capacity(
            run_id=run_id,
            control_run_id=control_run_id,
            execution=execution,
            fence=fence,
            resource_fence=resource_fence,
            artifact_resource_types=artifact_resource_types,
        )
        capacity_token = _PROVIDER_DIRECTORY_PROFILE_CAPACITY_ADMISSION.set(
            capacity_admission
        )
        try:
            return await _publish_artifact_bundle_from_fence(
                fence,
                run_id=run_id,
                metrics=metrics,
                source_ids=source_ids,
                publish_corroboration=False,
                publish_artifacts_targets=publish_targets,
                artifact_resource_types=artifact_resource_types,
                resource_fence=resource_fence,
            )
        finally:
            _PROVIDER_DIRECTORY_PROFILE_CAPACITY_ADMISSION.reset(
                capacity_token
            )


async def _publish_attested_provider_directory_profile(
    *,
    run_id: str | None,
    control_run_id: str | None,
    metrics: dict[str, Any],
    execution: ProviderDirectoryProfileExecution,
) -> dict[str, Any]:
    """Stage and atomically publish or purge one proof-bound global Profile."""
    catalog = _provider_directory_profile_selection_catalog()
    await assert_registered_profile_selection_current(
        execution.attestation,
        catalog,
    )
    source_ids = [pair["source_id"] for pair in execution.attestation.pairs]
    execution_token = _PROVIDER_DIRECTORY_PROFILE_SELECTION_EXECUTION.set(
        execution
    )
    try:
        await _bootstrap_provider_directory_profile_serving_generation(
            _schema()
        )
        fence = await _attested_profile_publication_fence(
            run_id=run_id,
            metrics=metrics,
            execution=execution,
            source_ids=source_ids,
        )
        _assert_profile_selection_matches_artifact_fence(execution, fence)
        replayed_profile = (
            await _provider_directory_profile_committed_run_replay(
                run_id=run_id,
                control_run_id=control_run_id,
                execution=execution,
                fence=fence,
            )
        )
        if replayed_profile is not None:
            published_metrics_by_name = (
                await _provider_directory_profile_replay_publish_metrics(
                    metrics,
                    fence,
                    replayed_profile,
                )
            )
        else:
            published_metrics_by_name = (
                await _publish_attested_provider_directory_profile_build(
                    run_id=run_id,
                    control_run_id=control_run_id,
                    metrics=metrics,
                    execution=execution,
                    fence=fence,
                    source_ids=source_ids,
                )
            )
    finally:
        _PROVIDER_DIRECTORY_PROFILE_SELECTION_EXECUTION.reset(execution_token)
    _attach_profile_selection_result(execution, published_metrics_by_name)
    return published_metrics_by_name


async def _prepare_artifact_publication_fence(
    source_ids: list[str] | tuple[str, ...] | None,
    *,
    run_id: str | None,
    metrics: dict[str, Any],
    publish_artifacts_targets: set[str] | None,
    publish_corroboration: bool,
    should_select_validated_candidates: bool,
) -> ProviderDirectoryArtifactDatasetFence:
    fence = await _resolve_provider_directory_artifact_datasets(
        source_ids,
        should_select_validated_candidates=should_select_validated_candidates,
    )
    _assert_provider_directory_artifact_target_dependencies(
        fence,
        publish_artifacts_targets=publish_artifacts_targets,
        publish_corroboration=publish_corroboration,
    )
    await _publish_current_dataset_relation_artifacts(
        fence,
        run_id=run_id,
        metrics=metrics,
        publish_artifacts_targets=publish_artifacts_targets,
    )
    refreshed_fence = await _resolve_provider_directory_artifact_datasets(
        source_ids,
        should_select_validated_candidates=should_select_validated_candidates,
    )
    _assert_artifact_fence_selection_unchanged(fence, refreshed_fence)
    return refreshed_fence


_CANDIDATE_ARTIFACT_METRIC_BY_TARGET = {
    "dataset_network_plan": PROVIDER_DIRECTORY_DATASET_NETWORK_PLAN_METADATA_KEY,
    "dataset_affiliation_organization": (
        PROVIDER_DIRECTORY_DATASET_AFFILIATION_ORGANIZATION_METADATA_KEY
    ),
    "location_contacts": "location_contacts_backfilled",
    "location_coordinates": "location_coordinates_backfilled",
    "resource_id_npis": "resource_id_npis_backfilled",
    "location_address_keys": "location_address_keys_stamped",
    "location_archive": "location_archive",
    "address_overlay": "address_overlay",
    "profile": "profile",
    "network_catalog": "network_catalog",
}


def _candidate_artifact_skip_reason(value: Any) -> str | None:
    if not isinstance(value, dict) or value.get("skipped") is not True:
        return None
    return _clean_text(value.get("reason")) or "unspecified"


def _candidate_artifact_deferred_relations(
    enabled_targets: set[str],
    publish_metrics_by_name: dict[str, Any],
) -> set[str]:
    relations: set[str] = set()
    if "address_overlay" in enabled_targets:
        relations.add(PROVIDER_DIRECTORY_ADDRESS_OVERLAY_TABLE)
    if (
        "profile" in enabled_targets
        and _candidate_artifact_skip_reason(
            publish_metrics_by_name.get("profile")
        )
        is None
    ):
        relations.update(
            {
                profile_artifact.PROFILE_EVIDENCE_TABLE,
                profile_artifact.PROFILE_TABLE,
            }
        )
    if "network_catalog" in enabled_targets:
        relations.add(PROVIDER_DIRECTORY_NETWORK_CATALOG_TABLE)
    if "corroboration" in enabled_targets:
        relations.add(PROVIDER_DIRECTORY_ADDRESS_CORROBORATION_VIEW)
    return relations


def _assert_candidate_artifact_metrics_complete(
    enabled_targets: set[str],
    publish_metrics_by_name: dict[str, Any],
) -> None:
    for artifact_target_name in sorted(enabled_targets - {"corroboration"}):
        metric_name = _CANDIDATE_ARTIFACT_METRIC_BY_TARGET.get(
            artifact_target_name
        )
        if metric_name is None or metric_name not in publish_metrics_by_name:
            raise RuntimeError(
                "provider_directory_candidate_artifact_metric_missing:"
                + artifact_target_name
            )
        skip_reason = _candidate_artifact_skip_reason(
            publish_metrics_by_name[metric_name]
        )
        if skip_reason is None:
            continue
        if (
            artifact_target_name == "profile"
            and skip_reason == "no_profile_enabled_sources_in_scope"
        ):
            continue
        raise RuntimeError(
            "provider_directory_candidate_artifact_skipped:"
            f"{artifact_target_name}:{skip_reason}"
        )
    if "corroboration" in enabled_targets and publish_metrics_by_name.get(
        "ptg_corroboration_view_published"
    ) is not True:
        raise RuntimeError(
            "provider_directory_candidate_artifact_skipped:corroboration"
        )


def _assert_candidate_artifact_stage_relations_complete(
    enabled_targets: set[str],
    publish_metrics_by_name: dict[str, Any],
    artifact_bundle: ProviderDirectoryArtifactBundle,
) -> None:
    expected_relations = _candidate_artifact_deferred_relations(
        enabled_targets,
        publish_metrics_by_name,
    )
    actual_relations = artifact_bundle.target_relations
    if actual_relations != expected_relations:
        missing_relations = sorted(expected_relations - actual_relations)
        unexpected_relations = sorted(actual_relations - expected_relations)
        raise RuntimeError(
            "provider_directory_candidate_artifact_bundle_incomplete:"
            f"missing={','.join(missing_relations) or '-'}:"
            f"unexpected={','.join(unexpected_relations) or '-'}"
        )


def _assert_candidate_artifact_bundle_complete(
    fence: ProviderDirectoryArtifactDatasetFence,
    publish_metrics_by_name: dict[str, Any],
    artifact_bundle: ProviderDirectoryArtifactBundle,
    *,
    publish_corroboration: bool,
    publish_artifacts_targets: set[str] | None,
) -> None:
    """Fail closed before a validated dataset can outpace its serving bundle."""
    if not fence.promotion_datasets:
        return
    enabled_targets = set(
        _provider_directory_dataset_artifact_targets(
            publish_artifacts_targets,
            publish_corroboration=publish_corroboration,
        )
    )
    _assert_candidate_artifact_metrics_complete(
        enabled_targets,
        publish_metrics_by_name,
    )
    _assert_candidate_artifact_stage_relations_complete(
        enabled_targets,
        publish_metrics_by_name,
        artifact_bundle,
    )


async def _record_artifact_promotion_metrics(
    fence: ProviderDirectoryArtifactDatasetFence,
    publish_metrics_by_name: dict[str, Any],
    promoted_stage_count: int,
) -> dict[str, Any]:
    """Record pointer promotion and best-effort retry-state cleanup."""
    promoted_dataset_ids = (
        sorted({dataset.dataset_id for dataset in fence.promotion_datasets})
        if promoted_stage_count > 0
        else []
    )
    publish_metrics_by_name["artifact_promoted_dataset_ids"] = promoted_dataset_ids
    retry_cleanup_expected_ids = (
        promoted_dataset_ids
        if fence.should_select_validated_candidates
        else []
    )
    retry_cleanup_cleared_ids = (
        await _clear_promoted_endpoint_dataset_retry_state(
            retry_cleanup_expected_ids
        )
        if retry_cleanup_expected_ids
        else []
    )
    publish_metrics_by_name["artifact_retry_state_cleared_dataset_ids"] = (
        retry_cleanup_cleared_ids
    )
    publish_metrics_by_name["artifact_retry_state_pending_dataset_ids"] = (
        sorted(
            set(retry_cleanup_expected_ids)
            - set(retry_cleanup_cleared_ids)
        )
    )
    return publish_metrics_by_name


async def _provider_directory_profile_resource_scope_fence(
    fence: ProviderDirectoryArtifactDatasetFence,
    publish_artifacts_targets: set[str] | None,
) -> ProviderDirectoryArtifactDatasetFence:
    """Narrow typed-resource scratch to changed Profile sources only."""

    execution = _PROVIDER_DIRECTORY_PROFILE_SELECTION_EXECUTION.get()
    if (
        execution is None
        or publish_artifacts_targets != {"profile"}
        or not await _has_provider_directory_profile_artifacts(_schema())
    ):
        return fence
    desired_source_vector = _provider_directory_profile_source_vector(
        (
            str(pair["source_id"]),
            str(pair["dataset_id"]),
        )
        for pair in execution.attestation.pairs
    )
    (
        _selected_source_ids,
        _retained_source_ids,
        desired_source_contexts,
    ) = await _provider_directory_profile_scope_source_ids(
        _schema(),
        {source_id for source_id, _dataset_id in desired_source_vector},
    )
    desired_source_context_vector = (
        _provider_directory_profile_source_context_vector(
            desired_source_contexts
        )
    )
    serving_state = await _provider_directory_profile_delta_serving_state(
        _schema(),
        allow_adoption=False,
    )
    refresh_source_ids, _removed_source_ids = (
        _provider_directory_profile_delta_sources(
            serving_state,
            desired_source_vector,
            desired_source_context_vector,
        )
    )
    refresh_source_id_set = set(refresh_source_ids)
    return ProviderDirectoryArtifactDatasetFence(
        datasets=tuple(
            dataset
            for dataset in fence.datasets
            if dataset.source_id in refresh_source_id_set
        ),
        should_select_validated_candidates=(
            fence.should_select_validated_candidates
        ),
    )


def _attach_artifact_fence_metrics(
    metrics: dict[str, Any],
    fence: ProviderDirectoryArtifactDatasetFence,
) -> None:
    """Attach immutable dataset lineage to one publication metric set."""
    metrics["artifact_dataset_ids"] = sorted(
        {dataset.dataset_id for dataset in fence.datasets}
    )
    metrics["artifact_dataset_evidence_run_ids"] = sorted(
        {dataset.evidence_run_id for dataset in fence.datasets}
    )


async def _refresh_bundle_profile_delta_metrics(
    artifact_bundle: ProviderDirectoryArtifactBundle,
    publish_metrics: Mapping[str, Any],
) -> None:
    """Replace staged profile estimates after a committed source delta."""
    if artifact_bundle.profile_delta is None:
        return
    profile_metrics = publish_metrics.get("profile")
    if not isinstance(profile_metrics, dict):
        raise RuntimeError("provider_directory_profile_metrics_missing")
    await _refresh_provider_directory_profile_delta_metrics(
        profile_metrics,
        artifact_bundle.profile_delta,
    )


async def _publish_artifact_bundle_from_fence(
    fence: ProviderDirectoryArtifactDatasetFence,
    *,
    run_id: str | None,
    metrics: dict[str, Any],
    source_ids: list[str] | tuple[str, ...] | None,
    publish_corroboration: bool,
    publish_artifacts_targets: set[str] | None,
    artifact_resource_types: frozenset[str],
    resource_fence: ProviderDirectoryArtifactDatasetFence | None = None,
) -> dict[str, Any]:
    """Build one immutable serving bundle and publish it behind its fence."""
    resource_fence = (
        resource_fence
        or await _provider_directory_profile_resource_scope_fence(
            fence,
            publish_artifacts_targets,
        )
    )
    async with _provider_directory_artifact_dataset_scope(
        run_id=run_id,
        source_ids=source_ids,
        fence=fence,
        resource_fence=resource_fence,
        metrics=metrics,
        resource_types=artifact_resource_types,
    ):
        async with _provider_directory_artifact_bundle_scope() as artifact_bundle:
            _attach_artifact_fence_metrics(metrics, fence)
            publish_metrics = await _publish_provider_directory_artifacts(
                run_id=run_id,
                metrics=metrics,
                address_key_run_id=None,
                publish_scope_run_id=None,
                source_ids=[dataset.source_id for dataset in fence.datasets],
                publish_corroboration=publish_corroboration,
                publish_artifacts_targets=publish_artifacts_targets,
            )
            _assert_candidate_artifact_bundle_complete(
                fence,
                publish_metrics,
                artifact_bundle,
                publish_corroboration=publish_corroboration,
                publish_artifacts_targets=publish_artifacts_targets,
            )
            promoted_stage_count = await artifact_bundle.promote()
            await _refresh_bundle_profile_delta_metrics(
                artifact_bundle,
                publish_metrics,
            )
            return await _record_artifact_promotion_metrics(
                fence,
                publish_metrics,
                promoted_stage_count,
            )


async def _publish_selected_provider_directory_artifacts(
    *,
    run_id: str | None,
    metrics: dict[str, Any],
    source_ids: list[str],
    seen_table: str | None,
    publish_after_acquisition: bool,
    publish_corroboration: bool,
    publish_artifacts_targets: set[str] | None,
) -> dict[str, Any]:
    if publish_after_acquisition:
        return await _publish_provider_directory_dataset_artifacts(
            run_id=run_id,
            metrics=metrics,
            source_ids=source_ids,
            publish_corroboration=publish_corroboration,
            publish_artifacts_targets=publish_artifacts_targets,
        )
    return await _publish_provider_directory_artifacts(
        run_id=run_id,
        metrics=metrics,
        seen_table=seen_table,
        address_key_run_id=run_id,
        publish_scope_run_id=run_id,
        source_ids=source_ids,
        publish_corroboration=publish_corroboration,
        publish_artifacts_targets=publish_artifacts_targets,
    )


def _normalize_provider_directory_artifact_stages(
    raw_stages: Any,
) -> tuple[ProviderDirectoryPreparedArtifactStage, ...] | None:
    stages = (
        (raw_stages,)
        if isinstance(raw_stages, ProviderDirectoryPreparedArtifactStage)
        else raw_stages
    )
    if (
        isinstance(stages, (list, tuple))
        and stages
        and all(
            isinstance(stage, ProviderDirectoryPreparedArtifactStage)
            for stage in stages
        )
    ):
        return tuple(stages)
    return None


def _collect_provider_directory_artifact_stage(
    publish_result: Any,
    artifact_bundle: ProviderDirectoryArtifactBundle | None,
) -> dict[str, Any]:
    """Register a deferred stage and return its serializable metrics."""
    if isinstance(publish_result, dict):
        return publish_result
    if (
        artifact_bundle is not None
        and isinstance(publish_result, tuple)
        and len(publish_result) == 2
    ):
        metrics, raw_stages = publish_result
        if (
            isinstance(metrics, dict)
            and isinstance(
                raw_stages,
                ProviderDirectoryPreparedProfileDelta,
            )
        ):
            artifact_bundle.add_profile_delta(raw_stages)
            return metrics
        stages = _normalize_provider_directory_artifact_stages(raw_stages)
        if isinstance(metrics, dict) and stages is not None:
            for stage in stages:
                artifact_bundle.add(stage)
            return metrics
    raise RuntimeError("provider_directory_artifact_stage_result_invalid")


async def _locked_finalized_retry_cleanup_dataset_ids(
    selected_dataset_ids: list[str],
) -> list[str]:
    finalized_rows = await db.all(
        f"""
        SELECT dataset_id
          FROM {_qt(_schema(), ProviderDirectoryEndpointDataset.__tablename__)}
         WHERE dataset_id = ANY(CAST(:dataset_ids AS varchar[]))
           AND status = ANY(CAST(:finalized_statuses AS varchar[]))
         ORDER BY dataset_id
         FOR UPDATE;
        """,
        dataset_ids=selected_dataset_ids,
        finalized_statuses=[
            ENDPOINT_DATASET_PUBLISHED,
            ENDPOINT_DATASET_SUPERSEDED,
        ],
    )
    return sorted(
        dataset_id
        for finalized_row in finalized_rows
        if (
            dataset_id := _clean_text(
                _pagination_checkpoint_row_mapping(finalized_row).get(
                    "dataset_id"
                )
            )
        )
    )


async def _delete_endpoint_dataset_retry_state(
    selected_dataset_ids: list[str],
) -> None:
    """Delete non-content retry rows after finalized parents are locked."""
    retry_resource_types = _last_updated_partition_retry_resource_types()
    await db.status(
        f"""
        DELETE FROM {_qt(_schema(), ProviderDirectoryDatasetResource.__tablename__)}
         WHERE dataset_id = ANY(CAST(:dataset_ids AS varchar[]))
           AND resource_type = ANY(CAST(:retry_resource_types AS varchar[]));
        """,
        dataset_ids=selected_dataset_ids,
        retry_resource_types=retry_resource_types,
    )
    await db.status(
        f"""
        DELETE FROM {_pagination_checkpoint_table_ref()}
         WHERE dataset_id = ANY(CAST(:dataset_ids AS varchar[]));
        """,
        dataset_ids=selected_dataset_ids,
    )


async def _clear_promoted_endpoint_dataset_retry_state(
    dataset_ids: Iterable[str],
) -> list[str]:
    """Atomically clear retry state for exact promoted datasets once finalized."""
    selected_dataset_ids = sorted(
        {
            cleaned_dataset_id
            for dataset_id in dataset_ids
            if (cleaned_dataset_id := _clean_text(dataset_id))
        }
    )
    if not selected_dataset_ids:
        return []
    try:
        async with asyncio.timeout(
            PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_TRANSACTION_TIMEOUT_SECONDS
        ):
            async with db.transaction():
                await db.status(
                    "SET LOCAL lock_timeout = "
                    f"'{PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_LOCK_TIMEOUT}';"
                )
                await db.status(
                    "SET LOCAL statement_timeout = "
                    f"'{PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_STATEMENT_TIMEOUT}';"
                )
                finalized_dataset_ids = (
                    await _locked_finalized_retry_cleanup_dataset_ids(
                        selected_dataset_ids
                    )
                )
                if finalized_dataset_ids != selected_dataset_ids:
                    return []
                await _delete_endpoint_dataset_retry_state(selected_dataset_ids)
    except Exception:
        LOGGER.warning(
            "Provider Directory retry-state cleanup remains pending for %s",
            ",".join(selected_dataset_ids),
            exc_info=True,
        )
        return []
    return selected_dataset_ids


async def _is_provider_directory_corroboration_artifact_published(
    *,
    source_ids: list[str] | tuple[str, ...] | None,
    network_catalog_metrics: dict[str, Any],
    artifact_bundle: ProviderDirectoryArtifactBundle | None,
) -> bool:
    """Build corroboration from either live artifacts or prepared bundle stages."""
    if artifact_bundle is None:
        return await _is_address_corroboration_published(
            refresh_network_catalog=False,
            source_ids=source_ids,
        )
    schema = _schema()
    if not await _is_table_present(schema, "entity_address_unified"):
        return False
    cleaned_source_ids = _clean_source_id_list(source_ids)
    with _provider_directory_artifact_relation_scope(
        artifact_bundle.relation_overrides
    ):
        publish_result = (
            await publish_provider_directory_address_corroboration_table(
                schema,
                refresh_network_catalog=False,
                source_ids=cleaned_source_ids,
                defer_cutover=True,
                network_catalog_metrics_override=network_catalog_metrics,
            )
        )
    _collect_provider_directory_artifact_stage(
        publish_result,
        artifact_bundle,
    )
    return True


def _profile_source_authority_from_row(
    source_id: str,
    source_row_map: Mapping[str, Any],
) -> str | None:
    """Validate the optional reviewed authority projected by source SQL."""

    authority_id = source_row_map.get("authority_id")
    expected_authority_id = (
        profile_artifact.profile_reviewed_source_authority_id(source_id)
    )
    if (
        authority_id is not None
        and (
            not isinstance(authority_id, str)
            or authority_id != authority_id.strip()
            or not authority_id
        )
    ) or authority_id != expected_authority_id:
        raise RuntimeError(
            "provider_directory_profile_source_context_invalid:"
            + source_id
            + ":authority_id"
        )
    return authority_id


def _profile_source_context_from_row(
    source_row: Any,
) -> _ProviderDirectoryProfileSourceContext | None:
    """Decode the exact source columns emitted into Profile evidence."""
    source_row_map = _pagination_checkpoint_row_mapping(source_row)
    source_id = _clean_text(source_row_map.get("source_id"))
    if not source_id:
        return None
    endpoint_id = _clean_text(source_row_map.get("endpoint_id"))
    if endpoint_id is None:
        raise RuntimeError(
            "provider_directory_profile_source_context_invalid:"
            + source_id
            + ":endpoint_id"
        )
    context_value_by_field: dict[str, str | None] = {}
    for field_name in ("canonical_api_base", "org_name", "plan_name"):
        if field_name not in source_row_map:
            raise RuntimeError(
                "provider_directory_profile_source_context_missing:"
                + source_id
                + ":"
                + field_name
            )
        raw_value = source_row_map.get(field_name)
        if (
            (field_name == "org_name" and raw_value is None)
            or (
                raw_value is not None
                and not isinstance(raw_value, str)
            )
        ):
            raise RuntimeError(
                "provider_directory_profile_source_context_invalid:"
                + source_id
                + ":"
                + field_name
            )
        context_value_by_field[field_name] = raw_value
    authority_id = _profile_source_authority_from_row(
        source_id,
        source_row_map,
    )
    return _ProviderDirectoryProfileSourceContext(
        source_id=source_id,
        endpoint_id=endpoint_id,
        canonical_api_base=context_value_by_field["canonical_api_base"],
        org_name=context_value_by_field["org_name"],
        plan_name=context_value_by_field["plan_name"],
        authority_id=authority_id,
    )


async def _provider_directory_profile_scope_source_ids(
    schema: str,
    allowed_source_ids: set[str],
    *,
    expected_source_context_digest: str | None = None,
) -> tuple[
    list[str],
    list[str],
    tuple[_ProviderDirectoryProfileSourceContext, ...],
]:
    """Resolve retained aliases and exact emitted context for selected ones."""
    configured_source_ids = list(profile_artifact.configured_profile_source_ids())
    source_rows = await db.all(
        profile_artifact.profile_scope_source_ids_sql(
            _qt(schema, ProviderDirectorySource.__tablename__)
        ),
        configured_source_ids=configured_source_ids,
    )
    source_context_by_id: dict[
        str,
        _ProviderDirectoryProfileSourceContext,
    ] = {}
    for source_row in source_rows:
        source_context = _profile_source_context_from_row(source_row)
        if source_context is None:
            continue
        if source_context.source_id in source_context_by_id:
            raise RuntimeError(
                "provider_directory_profile_source_context_ambiguous:"
                + source_context.source_id
            )
        source_context_by_id[source_context.source_id] = source_context
    retained_source_ids = sorted(source_context_by_id)
    selected_source_ids = [
        source_id
        for source_id in retained_source_ids
        if source_id in allowed_source_ids
    ]
    selected_source_contexts = tuple(
        source_context_by_id[source_id]
        for source_id in selected_source_ids
    )
    if expected_source_context_digest is None:
        _assert_attested_profile_source_contexts(
            selected_source_contexts
        )
    elif (
        _source_context_digest(
            [asdict(source_context) for source_context in selected_source_contexts]
        )
        != expected_source_context_digest
    ):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_profile_source_context_adoption_changed"
        )
    return (
        selected_source_ids,
        retained_source_ids,
        selected_source_contexts,
    )


def _assert_attested_profile_source_contexts(
    source_contexts: tuple[_ProviderDirectoryProfileSourceContext, ...],
) -> None:
    """Reject staged source labels that do not match the active proof."""

    execution = _PROVIDER_DIRECTORY_PROFILE_SELECTION_EXECUTION.get()
    if execution is None:
        return
    source_context_digest = _source_context_digest(
        [asdict(source_context) for source_context in source_contexts]
    )
    if source_context_digest != execution.attestation.source_context_digest:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_profile_source_context_attestation_changed"
        )


async def _rename_provider_directory_profile_indexes(
    schema: str,
    stage_table: str,
    *,
    target_table: str,
    evidence: bool,
) -> None:
    suffixes = (
        profile_artifact.PROFILE_EVIDENCE_INDEX_SUFFIXES
        if evidence
        else profile_artifact.PROFILE_INDEX_SUFFIXES
    )
    for suffix in suffixes:
        stage_index = profile_artifact.profile_index_name(
            stage_table,
            suffix,
        )
        target_index = profile_artifact.profile_index_name(
            target_table,
            suffix,
        )
        await db.status(
            f"ALTER INDEX {_unscoped_qt(schema, stage_index)} "
            f"RENAME TO {_q(target_index)};"
        )


async def _rename_provider_directory_profile_table_indexes(
    schema: str,
    stage_table: str,
) -> None:
    await _rename_provider_directory_profile_indexes(
        schema,
        stage_table,
        target_table=profile_artifact.PROFILE_TABLE,
        evidence=False,
    )


async def _rename_provider_directory_profile_evidence_indexes(
    schema: str,
    stage_table: str,
) -> None:
    await _rename_provider_directory_profile_indexes(
        schema,
        stage_table,
        target_table=profile_artifact.PROFILE_EVIDENCE_TABLE,
        evidence=True,
    )


async def _provider_directory_profile_stage_metrics(
    schema: str,
    evidence_stage: str,
    profile_stage: str,
    source_ids: list[str],
) -> dict[str, Any]:
    evidence_ref = _unscoped_qt(schema, evidence_stage)
    profile_ref = _unscoped_qt(schema, profile_stage)
    return {
        "enabled_source_ids": source_ids,
        "evidence_rows": int(
            await db.scalar(f"SELECT count(*) FROM {evidence_ref};") or 0
        ),
        "selected_evidence_rows": int(
            await db.scalar(
                f"""
                SELECT count(*)
                  FROM {evidence_ref}
                 WHERE source_id = ANY(CAST(:source_ids AS varchar[]));
                """,
                source_ids=source_ids,
            )
            or 0
        ),
        "profile_rows": int(
            await db.scalar(f"SELECT count(*) FROM {profile_ref};") or 0
        ),
    }


async def _remove_provider_directory_profile_stage_table(
    schema: str,
    stage_table: str,
) -> None:
    stage_ref = _unscoped_qt(schema, stage_table)
    try:
        await db.status(f"DROP TABLE IF EXISTS {stage_ref};")
    except Exception:
        LOGGER.warning(
            "Failed to clean Provider Directory profile stage %s",
            stage_ref,
            exc_info=True,
        )


