def _endpoint_dataset_publication_metadata(
    candidate: EndpointDatasetCandidate,
    diagnostics: dict[str, dict[str, Any]],
    **extra: Any,
) -> dict[str, Any]:
    stored_diagnostics = _sanitized_resource_diagnostics(diagnostics)
    metadata = {
        **_endpoint_dataset_candidate_metadata(candidate),
        "resource_diagnostics": stored_diagnostics,
        "reused_from_checkpoint": candidate.reused_from_checkpoint,
        **extra,
    }
    metadata["completion_proof_v1"] = {
        "acquisition_root_run_id": candidate.acquisition_root_run_id,
        "terminal_run_id": candidate.import_run_id,
        "source_ids": list(candidate.source_ids),
        "selected_resources": list(candidate.selected_resources),
        "resource_diagnostics": stored_diagnostics,
        **(
            {
                SEMANTIC_PROJECTION_AS_OF_METADATA_KEY: (
                    candidate.semantic_projection_as_of
                )
            }
            if candidate.semantic_projection_as_of is not None
            else {}
        ),
        **(
            {
                TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY: (
                    candidate.verification_campaign_id
                ),
                TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY: (
                    candidate.verification_source_scope_hash
                ),
            }
            if candidate.verification_campaign_id
            or candidate.verification_source_scope_hash
            else {}
        ),
    }
    return metadata


def _sanitized_resource_diagnostics(
    diagnostics: Mapping[str, Any],
) -> dict[str, Any]:
    """Remove internal replay evidence from operational/status payloads."""

    return {
        resource_type: {
            field_name: field_value
            for field_name, field_value in diagnostic.items()
            if field_name != _SERVER_ISSUED_SUBSET_INTERNAL_REPLAY_KEY
        }
        for resource_type, diagnostic in diagnostics.items()
        if isinstance(diagnostic, Mapping)
    }


def _is_endpoint_dataset_publishable(
    candidate: EndpointDatasetCandidate,
    diagnostics: dict[str, dict[str, Any]],
) -> bool:
    if (
        candidate.expected_resources
        and candidate.selected_resources != candidate.expected_resources
    ):
        return False
    for resource_type in candidate.selected_resources:
        diagnostic = diagnostics.get(resource_type)
        if (
            not diagnostic
            or diagnostic.get("complete") is not True
            or diagnostic.get("error")
            or diagnostic.get("bounded")
            or diagnostic.get("next_url_remaining")
        ):
            return False
    return True


async def _mark_endpoint_dataset_candidate(
    candidate: EndpointDatasetCandidate,
    status: str,
    diagnostics: dict[str, dict[str, Any]],
    *,
    error: str | None = None,
) -> None:
    metadata = _endpoint_dataset_publication_metadata(
        candidate,
        diagnostics,
        **({"error": error} if error else {}),
    )
    await db.status(
        f"""
        UPDATE {_qt(_schema(), ProviderDirectoryEndpointDataset.__tablename__)} AS dataset
           SET status = :status,
               resource_count = (
                    SELECT count(*)
                     FROM {_qt(_schema(), ProviderDirectoryDatasetResource.__tablename__)} AS resource
                     WHERE resource.dataset_id = dataset.dataset_id
                       AND resource.resource_type NOT LIKE 'LU:%:pass:%'
               ),
               publication_metadata_json = CAST(:publication_metadata_json AS jsonb)
         WHERE dataset.dataset_id = :dataset_id
           AND dataset.endpoint_id = :endpoint_id
           AND dataset.acquisition_root_run_id IS NOT DISTINCT FROM :acquisition_root_run_id
           AND dataset.is_current = false
           AND NOT dataset.status = ANY(
               CAST(:immutable_statuses AS varchar[])
           );
        """,
        status=status,
        publication_metadata_json=json.dumps(metadata, sort_keys=True, default=_json_default),
        dataset_id=candidate.dataset_id,
        endpoint_id=candidate.endpoint_id,
        acquisition_root_run_id=candidate.acquisition_root_run_id,
        immutable_statuses=list(IMMUTABLE_ENDPOINT_DATASET_STATUSES),
    )


def _endpoint_dataset_hash_identity(resource_row: Any) -> tuple[str, str, str]:
    resource_map = _pagination_checkpoint_row_mapping(resource_row)
    return (
        _clean_text(resource_map.get("resource_type")) or "",
        _clean_text(resource_map.get("resource_id")) or "",
        _clean_text(resource_map.get("payload_hash")) or "",
    )


def _endpoint_dataset_hash_page_sql(
    has_cursor: bool,
    *,
    include_payload_json: bool = False,
) -> str:
    cursor_filter = ""
    if has_cursor:
        cursor_filter = """
           AND (
                resource_type > :after_resource_type
                OR (
                    resource_type = :after_resource_type
                    AND resource_id > :after_resource_id
                )
           )
        """
    payload_projection = (
        ", payload_json, acquired_resource_sha256"
        if include_payload_json
        else ""
    )
    return f"""
        SELECT resource_type, resource_id, payload_hash{payload_projection}
          FROM {_qt(_schema(), ProviderDirectoryDatasetResource.__tablename__)}
         WHERE dataset_id = :dataset_id
           AND resource_type NOT LIKE 'LU:%:pass:%'
           {cursor_filter}
         ORDER BY resource_type, resource_id
         LIMIT :batch_size;
    """


async def _endpoint_dataset_content_proof(
    connection: Any,
    dataset_id: str,
    resource_types: tuple[str, ...] = (),
    *,
    verify_payload_hashes: bool = False,
    resource_hash_contract: str | None = None,
) -> EndpointDatasetContentProof:
    """Hash an ordered dataset and each resource family with bounded pages."""
    content_hash = hashlib.sha256()
    resource_count = 0
    resource_hasher_by_type = {
        resource_type: hashlib.sha256() for resource_type in resource_types
    }
    resource_count_by_type = dict.fromkeys(resource_types, 0)
    after_resource_type: str | None = None
    after_resource_id: str | None = None
    batch_size = max(1, ENDPOINT_DATASET_HASH_BATCH_SIZE)
    while True:
        resource_rows = await _endpoint_dataset_content_page(
            connection,
            dataset_id,
            batch_size,
            after_resource_type,
            after_resource_id,
            include_payload_json=verify_payload_hashes,
        )
        if not resource_rows:
            break
        for resource_row in resource_rows:
            if verify_payload_hashes:
                _assert_endpoint_dataset_resource_payload_hash(
                    resource_row,
                    resource_hash_contract=resource_hash_contract,
                )
            if resource_count:
                content_hash.update(b"\n")
            identity = _endpoint_dataset_hash_identity(resource_row)
            identity_bytes = _stable_identity_json(identity).encode("utf-8")
            content_hash.update(identity_bytes)
            resource_count += 1
            resource_type = identity[0]
            resource_hasher = resource_hasher_by_type.setdefault(
                resource_type, hashlib.sha256()
            )
            if resource_count_by_type.get(resource_type, 0):
                resource_hasher.update(b"\n")
            resource_hasher.update(identity_bytes)
            resource_count_by_type[resource_type] = (
                resource_count_by_type.get(resource_type, 0) + 1
            )
        after_resource_type, after_resource_id, _payload_hash = (
            _endpoint_dataset_hash_identity(resource_rows[-1])
        )
        if len(resource_rows) < batch_size:
            break
    return _completed_endpoint_dataset_content_proof(
        content_hash, resource_count, resource_hasher_by_type, resource_count_by_type
    )


async def _endpoint_dataset_content_page(
    connection: Any,
    dataset_id: str,
    batch_size: int,
    after_resource_type: str | None,
    after_resource_id: str | None,
    *,
    include_payload_json: bool,
) -> list[Any]:
    """Read one stable ordered page for the immutable content proof."""
    query_params_by_name: dict[str, Any] = {
        "dataset_id": dataset_id,
        "batch_size": batch_size,
    }
    has_cursor = after_resource_type is not None
    if has_cursor:
        query_params_by_name.update(
            after_resource_type=after_resource_type,
            after_resource_id=after_resource_id,
        )
    return await connection.all(
        _endpoint_dataset_hash_page_sql(
            has_cursor,
            include_payload_json=include_payload_json,
        ),
        **query_params_by_name,
    )


def _assert_endpoint_dataset_resource_payload_hash(
    resource_row: Any,
    *,
    resource_hash_contract: str | None = None,
) -> None:
    resource_map = _pagination_checkpoint_row_mapping(resource_row)
    raw_payload = resource_map.get("payload_json")
    if isinstance(raw_payload, str):
        try:
            raw_payload = json.loads(raw_payload)
        except json.JSONDecodeError as exc:
            raise ProviderDirectoryArtifactBuildStale(
                "provider_directory_endpoint_dataset_payload_invalid"
            ) from exc
    if not isinstance(raw_payload, dict):
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_endpoint_dataset_payload_invalid"
        )
    acquired_resource_sha256 = resource_map.get(
        "acquired_resource_sha256"
    )
    resource_type = _clean_text(resource_map.get("resource_type"))
    stored_hash = _clean_text(resource_map.get("payload_hash"))
    if acquired_resource_sha256 is not None:
        is_payload_hash_match = (
            subset_payload_sha256(resource_content_hash_payload(raw_payload))
            == stored_hash
        )
    elif resource_hash_contract is not None:
        if resource_hash_contract not in RESOURCE_HASH_CONTRACTS:
            raise ProviderDirectoryArtifactBuildStale(
                "provider_directory_resource_hash_contract_invalid"
            )
        is_payload_hash_match = (
            resource_payload_sha256_for_contract(
                raw_payload,
                resource_hash_contract,
                resource_type=resource_type,
            )
            == stored_hash
        )
    else:
        is_payload_hash_match = is_resource_payload_hash_match(
            raw_payload,
            stored_hash,
            resource_type,
        )
    if not is_payload_hash_match:
        raise ProviderDirectoryArtifactBuildStale(
            "provider_directory_endpoint_dataset_payload_hash_mismatch"
        )


def _completed_endpoint_dataset_content_proof(
    content_hash: Any,
    resource_count: int,
    resource_hasher_by_type: dict[str, Any],
    resource_count_by_type: dict[str, int],
) -> EndpointDatasetContentProof:
    return EndpointDatasetContentProof(
        dataset_hash=content_hash.hexdigest(),
        resource_count=resource_count,
        resource_hashes={
            resource_type: resource_hasher_by_type[resource_type].hexdigest()
            for resource_type in sorted(resource_hasher_by_type)
        },
        resource_counts={
            resource_type: resource_count_by_type[resource_type]
            for resource_type in sorted(resource_count_by_type)
        },
    )


async def _endpoint_dataset_content_hash(
    connection: Any,
    dataset_id: str,
) -> tuple[str, int]:
    """Retain the established aggregate-hash interface."""
    content_proof = await _endpoint_dataset_content_proof(connection, dataset_id)
    return content_proof.dataset_hash, content_proof.resource_count


async def _acquiring_uhc_metadata(
    connection: Any,
    candidate: EndpointDatasetCandidate,
) -> dict[str, Any]:
    metadata_record = await connection.first(
        f"""
        SELECT publication_metadata_json
          FROM {_qt(_schema(), ProviderDirectoryEndpointDataset.__tablename__)}
         WHERE dataset_id = :dataset_id
           AND endpoint_id = :endpoint_id
           AND acquisition_root_run_id IS NOT DISTINCT FROM
               :acquisition_root_run_id
           AND status = :acquiring_status
           AND is_current = false;
        """,
        dataset_id=candidate.dataset_id,
        endpoint_id=candidate.endpoint_id,
        acquisition_root_run_id=candidate.acquisition_root_run_id,
        acquiring_status=ENDPOINT_DATASET_ACQUIRING,
    )
    return _json_object(
        _pagination_checkpoint_row_mapping(metadata_record).get(
            "publication_metadata_json"
        )
    )


async def _uhc_candidate_content_proof(
    connection: Any,
    candidate: EndpointDatasetCandidate,
) -> EndpointDatasetContentProof | None:
    """Return the retained canonical proof only for the legacy source."""

    if candidate.source_ids != (UHC_RETAINED_SOURCE_ID,):
        return None
    metadata = await _acquiring_uhc_metadata(connection, candidate)
    try:
        uhc_proof = validate_uhc_canonical_content_proof(
            metadata.get(UHC_CANONICAL_CONTENT_PROOF_METADATA_KEY),
            dataset_id=candidate.dataset_id,
            endpoint_id=candidate.endpoint_id,
            acquisition_root_run_id=candidate.acquisition_root_run_id or "",
        )
    except UhcCanonicalProofError as error:
        raise RuntimeError(
            "provider_directory_uhc_canonical_proof_invalid"
        ) from error
    if tuple(sorted(uhc_proof["resource_counts"])) != candidate.selected_resources:
        raise RuntimeError(
            "provider_directory_uhc_canonical_proof_scope_changed"
        )
    return EndpointDatasetContentProof(
        dataset_hash=uhc_proof["dataset_hash"],
        resource_count=uhc_proof["resource_count"],
        resource_hashes=dict(uhc_proof["resource_hashes"]),
        resource_counts=dict(uhc_proof["resource_counts"]),
    )


async def _stored_candidate_content_proof(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    acquisition_root_run_id: str,
) -> Any:
    """Load one sealed shard proof under the candidate's exact identity."""

    return await build_stored_dataset_proof(
        connection,
        _schema(),
        dataset_id=candidate.dataset_id,
        endpoint_id=candidate.endpoint_id,
        acquisition_root_run_id=acquisition_root_run_id,
        source_ids=candidate.source_ids,
        selected_resources=candidate.selected_resources,
        options=ProviderDirectoryStoredProofOptions(
            proof_resource_scope=_candidate_proof_resource_scope(candidate),
            expected_resource_hash_contract=candidate.resource_hash_contract,
            expected_semantic_projection_as_of=(
                candidate.semantic_projection_as_of
            ),
        ),
    )


async def _assert_candidate_semantic_content_proof(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    stored_proof: Any,
) -> None:
    """Require v3 shard and retained-row proofs to match exactly."""

    if not is_semantic_resource_hash_contract(
        candidate.resource_hash_contract
    ):
        return
    content_resource_scope = (
        _candidate_proof_resource_scope(candidate)
        or candidate.selected_resources
    )
    direct_content_proof = await _endpoint_dataset_content_proof(
        connection,
        candidate.dataset_id,
        content_resource_scope,
        verify_payload_hashes=True,
        resource_hash_contract=candidate.resource_hash_contract,
    )
    direct_identity = (
        direct_content_proof.dataset_hash,
        direct_content_proof.resource_count,
        direct_content_proof.resource_hashes,
        direct_content_proof.resource_counts,
    )
    stored_identity = (
        stored_proof.dataset_hash,
        stored_proof.resource_count,
        stored_proof.resource_hashes,
        stored_proof.resource_counts,
    )
    if direct_identity != stored_identity:
        raise RuntimeError(
            "provider_directory_semantic_content_proof_mismatch"
        )


def _candidate_content_proof_from_stored(
    stored_proof: Any,
) -> EndpointDatasetContentProof:
    """Project a sealed shard proof into the importer proof value."""

    return EndpointDatasetContentProof(
        dataset_hash=stored_proof.dataset_hash,
        resource_count=stored_proof.resource_count,
        resource_hashes=stored_proof.resource_hashes,
        resource_counts=stored_proof.resource_counts,
        source_metrics=stored_proof.source_metrics,
        proof_metadata=stored_proof.metadata,
    )


async def _candidate_endpoint_dataset_content_proof(
    connection: Any,
    candidate: EndpointDatasetCandidate,
) -> EndpointDatasetContentProof:
    """Build the stored projected and raw-resource content commitments."""

    retained_content_proof = await _uhc_candidate_content_proof(
        connection,
        candidate,
    )
    if retained_content_proof is not None:
        return retained_content_proof
    acquisition_root_run_id = _clean_text(candidate.acquisition_root_run_id)
    if acquisition_root_run_id is None:
        raise RuntimeError(
            "provider_directory_content_proof_acquisition_root_required"
        )
    stored_proof = await _stored_candidate_content_proof(
        connection,
        candidate,
        acquisition_root_run_id,
    )
    await _assert_candidate_semantic_content_proof(
        connection,
        candidate,
        stored_proof,
    )
    content_proof = _candidate_content_proof_from_stored(stored_proof)
    if candidate.completion_proof_required_version != (
        SERVER_ISSUED_SUBSET_REQUIRED_VERSION
    ):
        return content_proof
    acquired_resource_hashes = await _subset_acquired_resource_hashes(
        connection,
        candidate,
        content_proof.resource_counts,
    )
    return replace(
        content_proof,
        acquired_resource_hashes=acquired_resource_hashes,
    )


async def _subset_acquired_resource_hashes(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    expected_count_by_type: dict[str, int],
) -> dict[str, str]:
    """Hash ordered raw-resource digests without retaining private transport data."""

    acquired_resource_rows = await connection.all(
        f"""
        SELECT resource_type, resource_id,
               acquired_resource_sha256
          FROM {_qt(_schema(), ProviderDirectoryDatasetResource.__tablename__)}
         WHERE dataset_id = :dataset_id
           AND resource_type = ANY(CAST(:resource_types AS varchar[]))
         ORDER BY resource_type, resource_id;
        """,
        dataset_id=candidate.dataset_id,
        resource_types=list(candidate.selected_resources),
    )
    entry_by_type: dict[str, list[dict[str, str]]] = {
        resource_type: [] for resource_type in candidate.selected_resources
    }
    for acquired_resource_row in acquired_resource_rows:
        row_map = _pagination_checkpoint_row_mapping(acquired_resource_row)
        resource_type = _clean_text(row_map.get("resource_type"))
        resource_id = _clean_text(row_map.get("resource_id"))
        acquired_sha256 = _clean_text(
            row_map.get("acquired_resource_sha256")
        )
        if (
            resource_type not in entry_by_type
            or resource_id is None
            or acquired_sha256 is None
            or re.fullmatch(r"[0-9a-f]{64}", acquired_sha256) is None
        ):
            raise RuntimeError(
                "provider_directory_subset_acquired_content_invalid"
            )
        entry_by_type[resource_type].append(
            {"resource_id": resource_id, "sha256": acquired_sha256}
        )
    if any(
        len(entry_by_type[resource_type])
        != expected_count_by_type.get(resource_type)
        for resource_type in candidate.selected_resources
    ):
        raise RuntimeError(
            "provider_directory_subset_acquired_content_count_mismatch"
        )
    return {
        resource_type: subset_canonical_sha256(entry_by_type[resource_type])
        for resource_type in sorted(entry_by_type)
    }


def _outcome_resource_count_proof(
    candidate: EndpointDatasetCandidate,
    content_proof: EndpointDatasetContentProof,
) -> dict[str, Any]:
    """Bind exact per-family counts to one immutable dataset proof."""
    selected_resources = tuple(sorted(candidate.selected_resources))
    resource_count_by_type = dict(
        sorted(content_proof.resource_counts.items())
    )
    if (
        not set(selected_resources).issubset(resource_count_by_type)
        or not set(resource_count_by_type).issubset(DEFAULT_RESOURCES)
        or any(
            isinstance(count, bool) or not isinstance(count, int) or count < 0
            for count in resource_count_by_type.values()
        )
        or sum(resource_count_by_type.values()) != content_proof.resource_count
    ):
        raise RuntimeError(
            "provider_directory_outcome_resource_count_proof_invalid"
        )
    return {
        "complete": True,
        "version": 1,
        "dataset_id": candidate.dataset_id,
        "endpoint_id": candidate.endpoint_id,
        "acquisition_root_run_id": candidate.acquisition_root_run_id,
        "dataset_hash": content_proof.dataset_hash,
        "source_ids": list(candidate.source_ids),
        "selected_resources": list(candidate.selected_resources),
        "resource_count": content_proof.resource_count,
        "resource_counts": resource_count_by_type,
    }


def _endpoint_dataset_source_summary_metrics_sql() -> str:
    """Aggregate display metrics once from the immutable dataset payload."""
    return source_summary_metrics_sql(
        _qt(_schema(), ProviderDirectoryDatasetResource.__tablename__)
    )


def _source_summary_metric_count(
    metric_row: dict[str, Any],
    field_name: str,
) -> int:
    metric_value = metric_row.get(field_name)
    if (
        isinstance(metric_value, bool)
        or not isinstance(metric_value, int)
        or metric_value < 0
    ):
        raise RuntimeError(
            f"provider_directory_source_summary_{field_name}_invalid"
        )
    return metric_value


def _source_summary_relation_edge_count(
    relation_proof_by_name: dict[str, dict[str, Any]],
    metadata_key: str,
) -> int:
    relation_proof = relation_proof_by_name.get(metadata_key)
    if (
        not isinstance(relation_proof, dict)
        or relation_proof.get("complete") is not True
    ):
        raise RuntimeError(
            "provider_directory_source_summary_relation_proof_missing"
        )
    edge_count = relation_proof.get("edge_count")
    if (
        isinstance(edge_count, bool)
        or not isinstance(edge_count, int)
        or edge_count < 0
    ):
        raise RuntimeError(
            "provider_directory_source_summary_relation_count_invalid"
        )
    return edge_count


def _source_summary_counts(
    content_proof: EndpointDatasetContentProof,
    relation_proof_by_name: dict[str, dict[str, Any]],
    metric_row: dict[str, Any],
) -> dict[str, int]:
    return {
        "individual_practitioners": content_proof.resource_counts.get(
            "Practitioner", 0
        ),
        "organization_resources": content_proof.resource_counts.get(
            "Organization", 0
        ),
        "practitioner_role_resources": content_proof.resource_counts.get(
            "PractitionerRole", 0
        ),
        "network_plan_links": _source_summary_relation_edge_count(
            relation_proof_by_name,
            PROVIDER_DIRECTORY_DATASET_NETWORK_PLAN_METADATA_KEY,
        ),
        "organization_affiliation_links": (
            _source_summary_relation_edge_count(
                relation_proof_by_name,
                PROVIDER_DIRECTORY_DATASET_AFFILIATION_ORGANIZATION_METADATA_KEY,
            )
        ),
        **{
            field_name: _source_summary_metric_count(metric_row, field_name)
            for field_name in (
                "distinct_npis",
                "address_records",
                "addressed_locations",
                "geocoded_locations",
            )
        },
    }


def _build_endpoint_dataset_source_summary(
    candidate: EndpointDatasetCandidate,
    content_proof: EndpointDatasetContentProof,
    count_by_field: dict[str, int],
    acquisition_root_run_id: str,
) -> dict[str, Any]:
    return build_source_summary(
        binding=ProviderDirectorySourceSummaryBinding(
            dataset_id=candidate.dataset_id,
            endpoint_id=candidate.endpoint_id,
            acquisition_root_run_id=acquisition_root_run_id,
            dataset_hash=content_proof.dataset_hash,
        ),
        source_ids=candidate.source_ids,
        selected_resources=candidate.selected_resources,
        count_by_resource=content_proof.resource_counts,
        hash_by_resource=content_proof.resource_hashes,
        count_by_field=count_by_field,
        count_by_category={
            "intentional_drop_counts": {},
            "unknown_field_counts": {},
        },
        identity_by_field={
            "semantic_contract_id": (
                PROVIDER_DIRECTORY_FHIR_SOURCE_SUMMARY_SEMANTIC_CONTRACT_ID
            )
        },
    )


def _expected_uhc_resource_count(
    count_by_field: Mapping[str, int],
    intentional_drop_count_by_field: Mapping[str, int],
    count_field: str,
    drop_field: str,
    rejected_count: int,
) -> int:
    return (
        count_by_field[count_field]
        - int(intentional_drop_count_by_field.get(drop_field, 0))
        - rejected_count
    )


def _assert_uhc_relationship_summary_counts(
    resource_count_by_type: Mapping[str, int],
    count_by_field: Mapping[str, int],
    intentional_drop_count_by_field: Mapping[str, int],
    rejected_totals: Mapping[str, int],
) -> None:
    membership_count = (
        count_by_field["raw_provider_plan_rows"]
        - rejected_totals["provider_plan_rows"]
        - int(
            intentional_drop_count_by_field.get(
                "ifp_unpaired_retained_only_provider_plan_rows", 0
            )
        )
    )
    role_and_affiliation_count = resource_count_by_type.get(
        "PractitionerRole", 0
    ) + resource_count_by_type.get("OrganizationAffiliation", 0)
    plan_count = count_by_field["membership_plan_key_count"] + count_by_field[
        "orphan_plan_detail_count"
    ]
    if (
        role_and_affiliation_count != membership_count
        or resource_count_by_type.get("InsurancePlan", 0) != plan_count
    ):
        raise RuntimeError(
            "provider_directory_uhc_canonical_relationship_counts_inconsistent"
        )


_UHC_CANONICAL_COUNT_FIELDS = (
    "raw_individual_records",
    "raw_facility_records",
    "raw_address_rows",
    "raw_provider_plan_rows",
    "invalid_npi_count",
    "membership_plan_key_count",
    "orphan_plan_detail_count",
)


def _uhc_summary_mapping(value: Any, error_code: str) -> dict[str, Any]:
    if not isinstance(value, Mapping):
        raise RuntimeError(error_code)
    try:
        return dict(value)
    except (KeyError, TypeError, ValueError) as error:
        raise RuntimeError(error_code) from error


def _validated_uhc_canonical_counts(
    count_by_field: Mapping[str, Any],
) -> dict[str, int]:
    count_map = _uhc_summary_mapping(
        count_by_field,
        "provider_directory_uhc_summary_count_scope_invalid",
    )
    if any(
        isinstance(count_map.get(field_name), bool)
        or not isinstance(count_map.get(field_name), int)
        or count_map[field_name] < 0
        for field_name in _UHC_CANONICAL_COUNT_FIELDS
    ):
        raise RuntimeError(
            "provider_directory_uhc_summary_count_scope_invalid"
        )
    return count_map


def _validated_uhc_drop_counts(
    intentional_drop_counts: Mapping[str, Any],
) -> dict[str, int]:
    drop_map = _uhc_summary_mapping(
        intentional_drop_counts,
        "provider_directory_uhc_summary_drop_scope_invalid",
    )
    if drop_map and set(drop_map) != set(
        SOURCE_SUMMARY_UHC_RETAINED_ONLY_DROP_FIELDS
    ):
        raise RuntimeError("provider_directory_uhc_summary_drop_scope_invalid")
    if any(
        isinstance(count, bool) or not isinstance(count, int) or count < 0
        for count in drop_map.values()
    ):
        raise RuntimeError("provider_directory_uhc_summary_drop_scope_invalid")
    return drop_map


def _validated_uhc_summary_count_inputs(
    count_by_field: Mapping[str, Any],
    intentional_drop_counts: Mapping[str, Any],
    rejected_counts: Mapping[str, Any],
) -> tuple[dict[str, int], dict[str, Any], dict[str, int]]:
    count_map = _validated_uhc_canonical_counts(count_by_field)
    drop_map = _validated_uhc_drop_counts(intentional_drop_counts)
    rejected_map = _uhc_summary_mapping(
        rejected_counts,
        "provider_directory_uhc_summary_rejection_scope_invalid",
    )
    try:
        rejected_totals = provider_quarantine_rejected_totals(
            rejected_map,
            count_map["invalid_npi_count"],
        )
    except UhcProviderQuarantineError as error:
        raise RuntimeError(
            "provider_directory_uhc_summary_rejection_scope_invalid"
        ) from error
    return count_map, drop_map, rejected_totals


def _assert_uhc_canonical_summary_counts(
    content_proof: EndpointDatasetContentProof,
    count_by_field: dict[str, int],
    intentional_drop_counts: Mapping[str, int],
    rejected_counts: Mapping[str, int],
) -> None:
    """Bind retained semantic counters to the six emitted resource families."""

    count_by_field, intentional_drop_counts, rejected_totals = (
        _validated_uhc_summary_count_inputs(
            count_by_field,
            intentional_drop_counts,
            rejected_counts,
        )
    )
    resource_count_by_type = content_proof.resource_counts
    exact_field_by_resource_type = {
        "Practitioner": (
            "raw_individual_records",
            "ifp_unpaired_retained_only_individual_records",
            "individual_records",
        ),
        "Organization": (
            "raw_facility_records",
            "ifp_unpaired_retained_only_facility_records",
            "facility_records",
        ),
        "Location": (
            "raw_address_rows",
            "ifp_unpaired_retained_only_address_rows",
            "address_rows",
        ),
    }
    if any(
        resource_count_by_type.get(resource_type, 0)
        != _expected_uhc_resource_count(
            count_by_field,
            intentional_drop_counts,
            field_name,
            drop_key,
            rejected_totals[rejected_key],
        )
        for resource_type, (
            field_name,
            drop_key,
            rejected_key,
        ) in exact_field_by_resource_type.items()
    ):
        raise RuntimeError(
            "provider_directory_uhc_canonical_resource_counts_inconsistent"
        )
    _assert_uhc_relationship_summary_counts(
        resource_count_by_type,
        count_by_field,
        intentional_drop_counts,
        rejected_totals,
    )


async def _uhc_candidate_summary_input(
    connection: Any,
    candidate: EndpointDatasetCandidate,
) -> dict[str, Any] | None:
    """Load and validate retained semantic input for one UHC candidate."""
    metadata_record = await connection.first(
        f"""
        SELECT publication_metadata_json
          FROM {_qt(_schema(), ProviderDirectoryEndpointDataset.__tablename__)}
         WHERE dataset_id = :dataset_id
           AND endpoint_id = :endpoint_id
           AND acquisition_root_run_id IS NOT DISTINCT FROM
               :acquisition_root_run_id;
        """,
        dataset_id=candidate.dataset_id,
        endpoint_id=candidate.endpoint_id,
        acquisition_root_run_id=candidate.acquisition_root_run_id,
    )
    metadata = _json_object(
        _pagination_checkpoint_row_mapping(metadata_record).get(
            "publication_metadata_json"
        )
    )
    raw_summary_input = metadata.get(UHC_RETAINED_SUMMARY_INPUT_METADATA_KEY)
    if raw_summary_input is None:
        return None
    try:
        summary_input = validate_uhc_summary_input(raw_summary_input)
    except UhcRetainedDatasetError as error:
        raise RuntimeError(
            "provider_directory_uhc_summary_input_invalid"
        ) from error
    except UhcCanonicalProofError as error:
        raise RuntimeError(
            "provider_directory_uhc_final_content_proof_invalid"
        ) from error
    if (
        candidate.source_ids != (UHC_RETAINED_SOURCE_ID,)
        or candidate.selected_resources != tuple(
            sorted(UHC_SUPPORTED_RESOURCES)
        )
        or candidate.expected_resources != tuple(sorted(UHC_SUPPORTED_RESOURCES))
        or summary_input["semantic_contract_id"]
        != SOURCE_SUMMARY_UHC_SEMANTIC_CONTRACT_ID
    ):
        raise RuntimeError(
            "provider_directory_uhc_summary_candidate_identity_invalid"
        )
    return summary_input


def _uhc_summary_category_counts(
    summary_input: Mapping[str, Any],
) -> tuple[dict[str, int], dict[str, int], dict[str, int]]:
    summary_map = _uhc_summary_mapping(
        summary_input,
        "provider_directory_uhc_summary_input_invalid",
    )
    count_by_field = _uhc_summary_mapping(
        summary_map.get("count_by_field"),
        "provider_directory_uhc_summary_input_invalid",
    )
    category_map = _uhc_summary_mapping(
        summary_map.get("count_by_category"),
        "provider_directory_uhc_summary_input_invalid",
    )
    intentional_drop_count_by_field = _validated_uhc_drop_counts(
        category_map.get("intentional_drop_counts"),
    )
    rejected_count_by_field = _uhc_summary_mapping(
        category_map.get("rejected_counts"),
        "provider_directory_uhc_summary_rejection_scope_invalid",
    )
    try:
        provider_quarantine_rejected_totals(
            rejected_count_by_field,
            count_by_field.get("invalid_npi_count", 0),
        )
    except UhcProviderQuarantineError as error:
        raise RuntimeError(
            "provider_directory_uhc_summary_rejection_scope_invalid"
        ) from error
    return (
        count_by_field,
        intentional_drop_count_by_field,
        rejected_count_by_field,
    )


def _build_uhc_endpoint_summary(
    candidate: EndpointDatasetCandidate,
    content_proof: EndpointDatasetContentProof,
    summary_input: Mapping[str, Any],
    count_by_field: Mapping[str, int],
    acquisition_root_run_id: str,
) -> dict[str, Any]:
    return build_source_summary(
        binding=ProviderDirectorySourceSummaryBinding(
            dataset_id=candidate.dataset_id,
            endpoint_id=candidate.endpoint_id,
            acquisition_root_run_id=acquisition_root_run_id,
            dataset_hash=content_proof.dataset_hash,
        ),
        source_ids=candidate.source_ids,
        selected_resources=candidate.selected_resources,
        count_by_resource=content_proof.resource_counts,
        hash_by_resource=content_proof.resource_hashes,
        count_by_field=count_by_field,
        count_by_category=summary_input["count_by_category"],
        identity_by_field={
            "semantic_contract_id": summary_input["semantic_contract_id"],
            "input_set_sha256": summary_input["input_set_sha256"],
            "layout_set_sha256": summary_input["layout_set_sha256"],
            "encoder_digest": summary_input["encoder_digest"],
            "quarantine_proof_sha256": summary_input[
                "quarantine_proof_sha256"
            ],
        },
    )


async def _uhc_endpoint_dataset_source_summary(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    content_proof: EndpointDatasetContentProof,
) -> dict[str, Any] | None:
    """Build UHC's v2 semantic summary from its durable candidate input."""

    if candidate.source_ids != (UHC_RETAINED_SOURCE_ID,):
        return None
    summary_input = await _uhc_candidate_summary_input(
        connection,
        candidate,
    )
    if summary_input is None:
        return None
    (
        count_by_field,
        intentional_drop_count_by_field,
        rejected_count_by_field,
    ) = _uhc_summary_category_counts(summary_input)
    _assert_uhc_canonical_summary_counts(
        content_proof,
        count_by_field,
        intentional_drop_count_by_field,
        rejected_count_by_field,
    )
    acquisition_root_run_id = _clean_text(candidate.acquisition_root_run_id)
    if acquisition_root_run_id is None:
        raise RuntimeError("provider_directory_uhc_acquisition_root_required")
    return _build_uhc_endpoint_summary(
        candidate,
        content_proof,
        summary_input,
        count_by_field,
        acquisition_root_run_id,
    )


async def _endpoint_dataset_source_summary(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    content_proof: EndpointDatasetContentProof,
    relation_proof_by_name: dict[str, dict[str, Any]],
) -> dict[str, Any] | None:
    """Build one immutable source-local summary during dataset validation."""
    acquisition_root_run_id = _clean_text(
        candidate.acquisition_root_run_id
    )
    if acquisition_root_run_id is None:
        return None
    uhc_summary = await _uhc_endpoint_dataset_source_summary(
        connection,
        candidate,
        content_proof,
    )
    if uhc_summary is not None:
        return uhc_summary
    metric_record = content_proof.source_metrics
    if metric_record is None:
        metric_record = _pagination_checkpoint_row_mapping(
            await connection.first(
                _endpoint_dataset_source_summary_metrics_sql(),
                dataset_id=candidate.dataset_id,
                summary_resource_types=[
                    "HealthcareService",
                    "Location",
                    "Organization",
                    "Practitioner",
                    "PractitionerRole",
                ],
                npi_resource_types=[
                    "HealthcareService",
                    "Organization",
                    "Practitioner",
                    "PractitionerRole",
                ],
                normalized_address_resource_types=[
                    "Location",
                    "Practitioner",
                ],
            )
        )
    count_by_field = _source_summary_counts(
        content_proof,
        relation_proof_by_name,
        metric_record,
    )
    return _build_endpoint_dataset_source_summary(
        candidate,
        content_proof,
        count_by_field,
        acquisition_root_run_id,
    )


def _embedded_twin_hash_contract_fields(
    resource_hash_contract: str,
) -> dict[str, str]:
    """Bind only v4 embedded twin proofs to an explicit hash contract."""

    if resource_hash_contract != SEMANTIC_CONTENT_V4_RESOURCE_HASH_CONTRACT:
        return {}
    return {
        RESOURCE_HASH_CONTRACT_METADATA_KEY: (
            SEMANTIC_CONTENT_V4_RESOURCE_HASH_CONTRACT
        )
    }


def _base_twin_root_content_proof(
    candidate: EndpointDatasetCandidate,
    content_proof: EndpointDatasetContentProof,
) -> dict[str, Any]:
    """Build the contract-independent portion of one twin-root proof."""

    proof_resource_scope = _candidate_proof_resource_scope(candidate)
    return {
        "endpoint_id": candidate.endpoint_id,
        "acquisition_root_run_id": candidate.acquisition_root_run_id,
        "source_ids": list(candidate.source_ids),
        "selected_resources": list(candidate.selected_resources),
        **_embedded_twin_hash_contract_fields(
            candidate.resource_hash_contract
        ),
        **(
            {
                PROVIDER_DIRECTORY_PROOF_RESOURCE_SCOPE_METADATA_KEY: list(
                    proof_resource_scope
                )
            }
            if proof_resource_scope is not None
            else {}
        ),
        "expected_resources": list(candidate.expected_resources),
        TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY: (
            candidate.verification_campaign_id
        ),
        TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY: (
            candidate.verification_source_scope_hash
        ),
        "dataset_hash": content_proof.dataset_hash,
        "resource_count": content_proof.resource_count,
        "resource_hashes": content_proof.resource_hashes,
        "resource_counts": content_proof.resource_counts,
        **(
            {
                SEMANTIC_PROJECTION_AS_OF_METADATA_KEY: (
                    candidate.semantic_projection_as_of
                )
            }
            if is_semantic_resource_hash_contract(
                candidate.resource_hash_contract
            )
            else {}
        ),
    }


def _subset_twin_content_proof_fields(
    candidate: EndpointDatasetCandidate,
    content_proof: EndpointDatasetContentProof,
) -> dict[str, Any]:
    """Validate and return the optional server-issued subset proof."""

    if candidate.completion_proof_required_version is None:
        return {}
    try:
        completion_proof, completion_sha256 = (
            validate_subset_completion_proof_pair(
                content_proof.completion_proof,
                content_proof.completion_proof_sha256,
            )
        )
    except ValueError as exc:
        raise RuntimeError(
            "provider_directory_subset_completion_proof_invalid"
        ) from exc
    if (
        candidate.subset_contract is None
        or completion_proof["campaign_id"]
        != candidate.subset_contract.campaign_id
        or completion_proof["cutoff"] != candidate.subset_contract.cutoff
        or completion_proof["page_count"]
        != candidate.subset_contract.page_count
    ):
        raise RuntimeError(
            "provider_directory_subset_completion_contract_mismatch"
        )
    return {
        "completion_proof": completion_proof,
        "completion_proof_sha256": completion_sha256,
    }


def _twin_root_content_proof(
    candidate: EndpointDatasetCandidate,
    content_proof: EndpointDatasetContentProof,
) -> dict[str, Any]:
    """Seal exact dataset, contract, scope, and projection identity."""

    return {
        **_base_twin_root_content_proof(candidate, content_proof),
        **_subset_twin_content_proof_fields(candidate, content_proof),
    }


def _twin_root_mismatch_fields(
    baseline_proof: dict[str, Any],
    candidate_proof: dict[str, Any],
) -> list[str]:
    return [
        field_name
        for field_name in (
            "endpoint_id",
            "source_ids",
            "selected_resources",
            RESOURCE_HASH_CONTRACT_METADATA_KEY,
            PROVIDER_DIRECTORY_PROOF_RESOURCE_SCOPE_METADATA_KEY,
            "expected_resources",
            TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY,
            TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY,
            SEMANTIC_PROJECTION_AS_OF_METADATA_KEY,
            "dataset_hash",
            "resource_count",
            "resource_hashes",
            "resource_counts",
            "completion_proof",
            "completion_proof_sha256",
        )
        if baseline_proof.get(field_name) != candidate_proof.get(field_name)
    ]


def _assert_twin_root_decision_policy(
    candidate: EndpointDatasetCandidate,
    baseline: dict[str, Any] | None,
) -> None:
    policy = candidate.reviewed_root_policy
    if policy is not None and (
        candidate.requires_twin_root_verification
        is not policy.is_twin_root_required
        or (
            not policy.is_twin_root_required
            and (
                candidate.verification_role is not None
                or candidate.verification_baseline_dataset_id is not None
                or baseline is not None
            )
        )
    ):
        raise RuntimeError(
            "provider_directory_reviewed_root_policy_candidate_invalid"
        )


def _twin_root_verification_decision(
    candidate: EndpointDatasetCandidate,
    content_proof: EndpointDatasetContentProof,
    baseline: dict[str, Any] | None,
) -> tuple[str, dict[str, Any], list[str]]:
    _assert_twin_root_decision_policy(candidate, baseline)
    if not candidate.requires_twin_root_verification:
        return ENDPOINT_DATASET_VALIDATED, {}, []
    proof = _twin_root_content_proof(candidate, content_proof)
    mismatch_fields = (
        _twin_root_mismatch_fields(_twin_root_baseline_proof(baseline), proof)
        if baseline
        else []
    )
    status = (
        ENDPOINT_DATASET_VERIFICATION_MISMATCH
        if mismatch_fields
        else (
            ENDPOINT_DATASET_VALIDATED
            if baseline
            else ENDPOINT_DATASET_VERIFICATION_BASELINE
        )
    )
    verification_metadata_map = {
        "role": "verification_candidate" if baseline else "baseline",
        "admission_role": candidate.verification_role,
        "result": (
            "mismatch"
            if mismatch_fields
            else ("matched" if baseline else "baseline_recorded")
        ),
        "proof": proof,
    }
    if baseline:
        verification_metadata_map.update(
            baseline_dataset_id=baseline.get("dataset_id"),
            baseline_acquisition_root_run_id=baseline.get(
                "acquisition_root_run_id"
            ),
            mismatch_fields=mismatch_fields,
        )
    return (
        status,
        {TWIN_ROOT_VERIFICATION_METADATA_KEY: verification_metadata_map},
        mismatch_fields,
    )


async def _endpoint_dataset_bulk_transaction_times(
    connection: Any,
    dataset_id: str | None,
) -> dict[str, str]:
    if not dataset_id:
        return {}
    transaction_rows = await connection.all(
        f"""
        SELECT resource_type,
               manifest_json::jsonb ->> 'transactionTime' AS transaction_time
          FROM {_bulk_acquisition_checkpoint_table_ref()}
         WHERE dataset_id = :dataset_id
           AND state = :complete_state;
        """,
        dataset_id=dataset_id,
        complete_state=BULK_EXPORT_CHECKPOINT_COMPLETE,
    )
    return {
        resource_type: transaction_time
        for transaction_row in transaction_rows
        if (
            resource_type := _clean_text(
                _pagination_checkpoint_row_mapping(transaction_row).get(
                    "resource_type"
                )
            )
        )
        and (
            transaction_time := _clean_text(
                _pagination_checkpoint_row_mapping(transaction_row).get(
                    "transaction_time"
                )
            )
        )
    }


def _assert_endpoint_dataset_bulk_freshness(
    diagnostics: dict[str, dict[str, Any]],
    candidate_transaction_times: dict[str, str],
    previous_transaction_times: dict[str, str],
) -> None:
    expected_bulk_resources = {
        resource_type
        for resource_type, diagnostic in diagnostics.items()
        if diagnostic.get("fetch_mode") == "checkpointed_bulk_export"
    }
    missing_transaction_times = expected_bulk_resources - set(
        candidate_transaction_times
    )
    if missing_transaction_times:
        raise RuntimeError("provider_directory_bulk_transaction_time_missing")
    try:
        for candidate_time in candidate_transaction_times.values():
            _assert_bulk_transaction_time_window(candidate_time)
    except ValueError as exc:
        raise RuntimeError(str(exc)) from exc
    for resource_type, candidate_time in candidate_transaction_times.items():
        previous_time = previous_transaction_times.get(resource_type)
        if previous_time and _parsed_bulk_transaction_time(
            candidate_time
        ) < _parsed_bulk_transaction_time(previous_time):
            raise RuntimeError("provider_directory_bulk_snapshot_older_than_current")


async def _locked_endpoint_dataset_candidate_record(
    connection: Any,
    candidate: EndpointDatasetCandidate,
) -> dict[str, Any]:
    """Lock the endpoint and return its mutable candidate row."""

    endpoint_ref = _qt(_schema(), ProviderDirectoryAPIEndpoint.__tablename__)
    dataset_ref = _qt(_schema(), ProviderDirectoryEndpointDataset.__tablename__)
    endpoint_record = await connection.first(
        f"SELECT endpoint_id FROM {endpoint_ref} "
        "WHERE endpoint_id = :endpoint_id FOR UPDATE;",
        endpoint_id=candidate.endpoint_id,
    )
    if endpoint_record is None:
        raise RuntimeError(
            "provider_directory_api_endpoint_missing_during_validation"
        )
    candidate_record = await connection.first(
        f"""
        SELECT dataset_id, acquisition_root_run_id, is_current, status,
               previous_dataset_id, completion_proof_required_version,
               completion_proof_json, completion_proof_sha256,
               publication_metadata_json
          FROM {dataset_ref}
         WHERE dataset_id = :dataset_id
           AND endpoint_id = :endpoint_id
         FOR UPDATE;
        """,
        dataset_id=candidate.dataset_id,
        endpoint_id=candidate.endpoint_id,
    )
    if candidate_record is None:
        raise RuntimeError(
            "provider_directory_endpoint_dataset_candidate_missing"
        )
    return _pagination_checkpoint_row_mapping(candidate_record)


def _assert_locked_candidate_identity(
    candidate_record_map: dict[str, Any],
    candidate: EndpointDatasetCandidate,
) -> None:
    """Require a locked row to retain every mutable candidate field."""

    try:
        persisted_hash_contract = _dataset_resource_hash_contract(
            candidate_record_map
        )
        persisted_projection_as_of = _dataset_semantic_projection_as_of(
            candidate_record_map,
            persisted_hash_contract,
        )
        persisted_proof_resource_scope = _dataset_proof_resource_scope(
            candidate_record_map,
            candidate.selected_resources,
            persisted_hash_contract,
        )
    except RuntimeError as error:
        raise RuntimeError(
            "provider_directory_endpoint_dataset_candidate_stale"
        ) from error
    is_stale = bool(
        candidate_record_map.get("is_current") is True
        or _clean_text(candidate_record_map.get("status"))
        in IMMUTABLE_ENDPOINT_DATASET_STATUSES
        or _clean_text(candidate_record_map.get("acquisition_root_run_id"))
        != candidate.acquisition_root_run_id
        or candidate_record_map.get("completion_proof_required_version")
        != candidate.completion_proof_required_version
        or candidate_record_map.get("completion_proof_json") is not None
        or candidate_record_map.get("completion_proof_sha256") is not None
        or persisted_hash_contract != candidate.resource_hash_contract
        or persisted_projection_as_of != candidate.semantic_projection_as_of
        or persisted_proof_resource_scope
        != _candidate_proof_resource_scope(candidate)
    )
    if is_stale:
        raise RuntimeError(
            "provider_directory_endpoint_dataset_candidate_stale"
        )


async def _locked_current_endpoint_dataset_id(
    connection: Any,
    candidate: EndpointDatasetCandidate,
) -> str | None:
    """Lock and verify the incumbent expected by one candidate."""

    dataset_ref = _qt(_schema(), ProviderDirectoryEndpointDataset.__tablename__)
    current_dataset_record = await connection.first(
        f"""
        SELECT dataset_id
          FROM {dataset_ref}
         WHERE endpoint_id = :endpoint_id
           AND is_current = true
           AND dataset_id <> :dataset_id
         FOR UPDATE;
        """,
        endpoint_id=candidate.endpoint_id,
        dataset_id=candidate.dataset_id,
    )
    current_dataset_map = _pagination_checkpoint_row_mapping(
        current_dataset_record
    )
    current_dataset_id = _clean_text(current_dataset_map.get("dataset_id"))
    if current_dataset_id != candidate.previous_dataset_id:
        raise RuntimeError(
            "provider_directory_endpoint_dataset_current_changed"
        )
    return current_dataset_id


async def _lock_endpoint_dataset_for_validation(
    connection: Any,
    candidate: EndpointDatasetCandidate,
) -> str | None:
    """Lock and verify the complete candidate identity before validation."""

    candidate_record_map = await _locked_endpoint_dataset_candidate_record(
        connection,
        candidate,
    )
    _assert_locked_candidate_identity(candidate_record_map, candidate)
    return await _locked_current_endpoint_dataset_id(connection, candidate)


def _store_validated_endpoint_dataset_sql() -> str:
    """Return the marker- and proof-guarded terminal UPDATE."""

    dataset_ref = _qt(
        _schema(),
        ProviderDirectoryEndpointDataset.__tablename__,
    )
    return f"""
        UPDATE {dataset_ref}
           SET previous_dataset_id = :previous_dataset_id,
               dataset_hash = :dataset_hash, status = :status,
               is_current = false, resource_count = :resource_count,
               validated_at = CASE WHEN :marks_validated THEN now() ELSE NULL END,
               published_at = NULL, superseded_at = NULL,
               publication_metadata_json = CAST(:publication_metadata_json AS jsonb),
               completion_proof_json = CAST(:completion_proof_json AS jsonb),
               completion_proof_sha256 = :completion_proof_sha256
         WHERE dataset_id = :dataset_id AND endpoint_id = :endpoint_id
           AND acquisition_root_run_id IS NOT DISTINCT FROM
               :acquisition_root_run_id
           AND is_current = false
           AND completion_proof_required_version IS NOT DISTINCT FROM
               :completion_proof_required_version
           AND completion_proof_json IS NULL
           AND completion_proof_sha256 IS NULL
           AND NOT status = ANY(CAST(:immutable_statuses AS varchar[]));
    """


async def _store_validated_endpoint_dataset(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    previous_dataset_id: str | None,
    dataset_hash: str,
    resource_count: int,
    metadata: dict[str, Any],
    *,
    status: str = ENDPOINT_DATASET_VALIDATED,
    completion_proof_pair: tuple[
        dict[str, Any] | None,
        str | None,
    ] | None = None,
) -> None:
    """Atomically terminalize one candidate with its immutable proof pair."""

    serialized_completion_proof, completion_proof_sha256 = (
        _serialized_subset_completion_proof_pair(
            candidate,
            completion_proof_pair,
        )
    )
    validated_count = await connection.status(
        _store_validated_endpoint_dataset_sql(),
        previous_dataset_id=previous_dataset_id,
        dataset_hash=dataset_hash,
        status=status,
        resource_count=resource_count,
        publication_metadata_json=json.dumps(
            metadata,
            sort_keys=True,
            default=_json_default,
        ),
        completion_proof_json=serialized_completion_proof,
        completion_proof_sha256=completion_proof_sha256,
        completion_proof_required_version=(
            candidate.completion_proof_required_version
        ),
        dataset_id=candidate.dataset_id,
        endpoint_id=candidate.endpoint_id,
        acquisition_root_run_id=candidate.acquisition_root_run_id,
        marks_validated=status == ENDPOINT_DATASET_VALIDATED,
        immutable_statuses=list(IMMUTABLE_ENDPOINT_DATASET_STATUSES),
    )
    if _coerce_rowcount(validated_count) <= 0:
        raise RuntimeError("provider_directory_endpoint_dataset_validation_lost")


def _serialized_subset_completion_proof_pair(
    candidate: EndpointDatasetCandidate,
    completion_proof_pair: tuple[
        dict[str, Any] | None,
        str | None,
    ] | None,
) -> tuple[str | None, str | None]:
    if candidate.completion_proof_required_version is None:
        if completion_proof_pair not in (None, (None, None)):
            raise RuntimeError(
                "provider_directory_subset_completion_proof_unexpected"
            )
        return None, None
    if (
        candidate.completion_proof_required_version
        != SERVER_ISSUED_SUBSET_REQUIRED_VERSION
        or completion_proof_pair is None
    ):
        raise RuntimeError(
            "provider_directory_subset_completion_proof_required"
        )
    try:
        completion_proof, completion_sha256 = (
            validate_subset_completion_proof_pair(*completion_proof_pair)
        )
    except ValueError as exc:
        raise RuntimeError(
            "provider_directory_subset_completion_proof_invalid"
        ) from exc
    contract = candidate.subset_contract
    if (
        contract is None
        or completion_proof["campaign_id"] != contract.campaign_id
        or completion_proof["cutoff"] != contract.cutoff
        or completion_proof["page_count"] != contract.page_count
    ):
        raise RuntimeError(
            "provider_directory_subset_completion_contract_mismatch"
        )
    return (
        json.dumps(
            completion_proof,
            sort_keys=True,
            separators=(",", ":"),
        ),
        completion_sha256,
    )


async def _validated_endpoint_bulk_transaction_times(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    previous_dataset_id: str | None,
    diagnostics: dict[str, dict[str, Any]],
) -> dict[str, str]:
    candidate_transaction_times = await _endpoint_dataset_bulk_transaction_times(
        connection,
        candidate.dataset_id,
    )
    previous_transaction_times = await _endpoint_dataset_bulk_transaction_times(
        connection,
        previous_dataset_id,
    )
    _assert_endpoint_dataset_bulk_freshness(
        diagnostics,
        candidate_transaction_times,
        previous_transaction_times,
    )
    return candidate_transaction_times


async def _build_endpoint_dataset_serving_relations(
    connection: Any,
    candidate: EndpointDatasetCandidate,
) -> dict[str, dict[str, Any]]:
    await _lock_dataset_serving_relation_build(connection, candidate.dataset_id)
    common_options_by_name = {
        "build_run_id": candidate.import_run_id,
        "expected_acquisition_root_run_id": (
            candidate.acquisition_root_run_id
        ),
    }
    network_plan_proof = await _build_provider_directory_dataset_network_plan(
        connection,
        candidate.dataset_id,
        **common_options_by_name,
    )
    affiliation_proof = (
        await _build_provider_directory_dataset_affiliation_organization(
            connection,
            candidate.dataset_id,
            **common_options_by_name,
        )
    )
    return {
        PROVIDER_DIRECTORY_DATASET_NETWORK_PLAN_METADATA_KEY: network_plan_proof,
        PROVIDER_DIRECTORY_DATASET_AFFILIATION_ORGANIZATION_METADATA_KEY: (
            affiliation_proof
        ),
    }


async def _locked_twin_root_verification_decision(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    content_proof: EndpointDatasetContentProof,
) -> tuple[str, dict[str, Any], list[str]]:
    baseline_dataset_map = None
    if candidate.requires_twin_root_verification:
        locked_state = await _locked_endpoint_verification_state(
            connection, candidate
        )
        admitted_candidate = _candidate_with_locked_twin_root_admission(
            candidate, locked_state
        )
        _assert_candidate_hash_contract_supported(admitted_candidate)
        if admitted_candidate != candidate:
            raise RuntimeError(
                "provider_directory_endpoint_dataset_verification_admission_missing"
            )
        if candidate.verification_role == TWIN_ROOT_VERIFICATION_CANDIDATE_ROLE:
            baseline_dataset_map = _compatible_twin_root_baseline(
                candidate,
                locked_state,
            )
            assert baseline_dataset_map is not None
            _assert_twin_root_resource_hash_contract(
                candidate,
                baseline_dataset_map,
            )
    return _twin_root_verification_decision(
        candidate, content_proof, baseline_dataset_map
    )


def _endpoint_dataset_validation_summary(
    candidate: EndpointDatasetCandidate,
    previous_dataset_id: str | None,
    content_proof: EndpointDatasetContentProof,
    relation_proof_by_name: dict[str, dict[str, Any]],
    final_status: str,
    mismatch_fields: list[str],
    baseline_payload_rows_retired: int = 0,
) -> dict[str, Any]:
    return {
        "dataset_id": candidate.dataset_id,
        "previous_dataset_id": previous_dataset_id,
        "dataset_hash": content_proof.dataset_hash,
        "resource_count": content_proof.resource_count,
        **relation_proof_by_name,
        "status": final_status,
        "validated": final_status == ENDPOINT_DATASET_VALIDATED,
        "published": False,
        **({"mismatch_fields": mismatch_fields} if mismatch_fields else {}),
        **(
            {
                "baseline_payload_rows_retired": (
                    baseline_payload_rows_retired
                )
            }
            if final_status == ENDPOINT_DATASET_VALIDATED
            and candidate.verification_role
            == TWIN_ROOT_VERIFICATION_CANDIDATE_ROLE
            else {}
        ),
    }


async def _store_endpoint_dataset_verification_result(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    previous_dataset_id: str | None,
    content_proof: EndpointDatasetContentProof,
    metadata: dict[str, Any],
    final_status: str,
) -> None:
    positional_arguments = (
        connection,
        candidate,
        previous_dataset_id,
        content_proof.dataset_hash,
        content_proof.resource_count,
        metadata,
    )
    completion_proof_pair = (
        content_proof.completion_proof,
        content_proof.completion_proof_sha256,
    )
    store_options_by_name: dict[str, Any] = {}
    if (
        candidate.completion_proof_required_version
        == SERVER_ISSUED_SUBSET_REQUIRED_VERSION
    ):
        store_options_by_name["completion_proof_pair"] = completion_proof_pair
    if final_status == ENDPOINT_DATASET_VALIDATED:
        await _store_validated_endpoint_dataset(
            *positional_arguments,
            **store_options_by_name,
        )
        return
    await _store_validated_endpoint_dataset(
        *positional_arguments,
        status=final_status,
        **store_options_by_name,
    )


async def _retire_matched_twin_root_baseline_payload(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    metadata: dict[str, Any],
    final_status: str,
) -> int:
    """Retain immutable baseline proof while retiring its duplicate payload."""
    baseline_dataset_id = candidate.verification_baseline_dataset_id
    if (
        candidate.completion_proof_required_version
        == SERVER_ISSUED_SUBSET_REQUIRED_VERSION
        or final_status != ENDPOINT_DATASET_VALIDATED
        or candidate.verification_role
        != TWIN_ROOT_VERIFICATION_CANDIDATE_ROLE
        or not baseline_dataset_id
    ):
        return 0
    deleted_count = await _delete_matched_baseline_resource_rows(
        connection,
        candidate,
        baseline_dataset_id,
    )
    _record_baseline_payload_retirement(
        metadata,
        baseline_dataset_id,
        deleted_count,
    )
    await _store_baseline_payload_retirement(
        connection,
        candidate,
        baseline_dataset_id,
        metadata,
    )
    return deleted_count


async def _delete_matched_baseline_resource_rows(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    baseline_dataset_id: str,
) -> int:
    """Retire a locked immutable baseline only after exact successor proof."""
    deleted_status = await connection.status(
        f"""
        DELETE FROM {_qt(_schema(), ProviderDirectoryDatasetResource.__tablename__)} AS resource
         USING {_qt(_schema(), ProviderDirectoryEndpointDataset.__tablename__)} AS baseline,
               {_qt(_schema(), ProviderDirectoryEndpointDataset.__tablename__)} AS successor
         WHERE resource.dataset_id = :baseline_dataset_id
           AND baseline.dataset_id = resource.dataset_id
           AND baseline.endpoint_id = :endpoint_id
           AND baseline.is_current = false
           AND baseline.status = :baseline_status
           AND successor.dataset_id = :successor_dataset_id
           AND successor.endpoint_id = baseline.endpoint_id
           AND successor.is_current = false
           AND successor.status = :validated_status
           AND successor.publication_metadata_json::jsonb
                 ->> '{TWIN_ROOT_VERIFICATION_CAMPAIGN_KEY}'
                 = :verification_campaign_id
           AND successor.publication_metadata_json::jsonb
                 ->> '{TWIN_ROOT_VERIFICATION_SOURCE_SCOPE_KEY}'
                 = :verification_source_scope_hash
           AND successor.publication_metadata_json::jsonb
                 ->> '{TWIN_ROOT_VERIFICATION_ROLE_KEY}'
                 = :verification_candidate_role
           AND successor.publication_metadata_json::jsonb
                 ->> '{TWIN_ROOT_VERIFICATION_BASELINE_DATASET_KEY}'
                 = baseline.dataset_id
           AND successor.publication_metadata_json::jsonb
                 -> '{TWIN_ROOT_VERIFICATION_METADATA_KEY}'
                 ->> 'result' = 'matched';
        """,
        baseline_dataset_id=baseline_dataset_id,
        endpoint_id=candidate.endpoint_id,
        baseline_status=ENDPOINT_DATASET_VERIFICATION_BASELINE,
        successor_dataset_id=candidate.dataset_id,
        validated_status=ENDPOINT_DATASET_VALIDATED,
        verification_campaign_id=candidate.verification_campaign_id,
        verification_source_scope_hash=(
            candidate.verification_source_scope_hash
        ),
        verification_candidate_role=TWIN_ROOT_VERIFICATION_CANDIDATE_ROLE,
    )
    return _coerce_rowcount(deleted_status)


def _record_baseline_payload_retirement(
    metadata: dict[str, Any],
    baseline_dataset_id: str,
    deleted_count: int,
) -> None:
    verification_metadata = metadata.get(TWIN_ROOT_VERIFICATION_METADATA_KEY)
    if not isinstance(verification_metadata, dict):
        raise RuntimeError(
            "provider_directory_endpoint_dataset_verification_metadata_invalid"
        )
    verification_metadata["baseline_payload_retirement"] = {
        "baseline_dataset_id": baseline_dataset_id,
        "deleted_resource_rows": deleted_count,
    }


async def _store_baseline_payload_retirement(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    baseline_dataset_id: str,
    metadata: dict[str, Any],
) -> None:
    updated_status = await connection.status(
        f"""
        UPDATE {_qt(_schema(), ProviderDirectoryEndpointDataset.__tablename__)}
           SET publication_metadata_json = CAST(:publication_metadata_json AS jsonb)
         WHERE dataset_id = :dataset_id
           AND endpoint_id = :endpoint_id
           AND status = :validated_status
           AND is_current = false
           AND publication_metadata_json::jsonb
                 ->> '{TWIN_ROOT_VERIFICATION_BASELINE_DATASET_KEY}'
                 = :baseline_dataset_id;
        """,
        publication_metadata_json=json.dumps(
            metadata,
            sort_keys=True,
            default=_json_default,
        ),
        dataset_id=candidate.dataset_id,
        endpoint_id=candidate.endpoint_id,
        validated_status=ENDPOINT_DATASET_VALIDATED,
        baseline_dataset_id=baseline_dataset_id,
    )
    if _coerce_rowcount(updated_status) <= 0:
        raise RuntimeError(
            "provider_directory_endpoint_dataset_baseline_payload_retirement_lost"
        )


async def _validate_endpoint_dataset_candidate(
    candidate: EndpointDatasetCandidate,
    diagnostics: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    """Persist immutable completion proof without changing the serving pointer."""
    async with db.acquire() as connection:
        validation_state = await _persist_endpoint_dataset_validation(
            connection, candidate, diagnostics
        )
    (
        previous_dataset_id,
        content_proof,
        relation_proof_by_name,
        final_status,
        mismatch_fields,
        baseline_payload_rows_retired,
    ) = validation_state
    return _endpoint_dataset_validation_summary(
        candidate,
        previous_dataset_id,
        content_proof,
        relation_proof_by_name,
        final_status,
        mismatch_fields,
        baseline_payload_rows_retired,
    )


async def _endpoint_dataset_validation_proofs(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    diagnostics: dict[str, dict[str, Any]] | None = None,
) -> tuple[
    EndpointDatasetContentProof,
    dict[str, dict[str, Any]],
    str,
    dict[str, Any],
    list[str],
]:
    content_proof = await _candidate_endpoint_dataset_content_proof(
        connection,
        candidate,
    )
    content_proof = _content_proof_with_subset_completion(
        candidate,
        diagnostics or {},
        content_proof,
    )
    final_status, verification_metadata, mismatch_fields = (
        await _locked_twin_root_verification_decision(
            connection, candidate, content_proof
        )
    )
    relation_proof_by_name = {}
    if final_status == ENDPOINT_DATASET_VALIDATED:
        relation_proof_by_name = (
            await _build_endpoint_dataset_serving_relations(
                connection,
                candidate,
            )
        )
    return (
        content_proof,
        relation_proof_by_name,
        final_status,
        verification_metadata,
        mismatch_fields,
    )


def _content_proof_with_subset_completion(
    candidate: EndpointDatasetCandidate,
    diagnostics: dict[str, dict[str, Any]],
    content_proof: EndpointDatasetContentProof,
) -> EndpointDatasetContentProof:
    """Attach the canonical v3 proof only for a marker-bound full resource set."""

    if candidate.completion_proof_required_version is None:
        return content_proof
    if (
        candidate.completion_proof_required_version
        != SERVER_ISSUED_SUBSET_REQUIRED_VERSION
        or candidate.subset_contract is None
        or content_proof.acquired_resource_hashes is None
    ):
        raise RuntimeError(
            "provider_directory_subset_completion_proof_identity_invalid"
        )
    resource_proof_by_type: dict[str, dict[str, Any]] = {}
    for resource_type in candidate.subset_contract.resources:
        diagnostic = diagnostics.get(resource_type)
        proof = (
            diagnostic.get("server_issued_subset_completeness")
            if isinstance(diagnostic, dict)
            else None
        )
        if not isinstance(proof, dict):
            raise RuntimeError(
                "provider_directory_subset_completion_proof_incomplete"
            )
        resource_proof_by_type[resource_type] = proof
    try:
        completion_proof, completion_sha256 = build_subset_completion_proof(
            contract=candidate.subset_contract,
            resource_proof_by_type=resource_proof_by_type,
            dataset_hash=content_proof.dataset_hash,
            resource_count=content_proof.resource_count,
            resource_hash_by_type=content_proof.resource_hashes,
            acquired_resource_hash_by_type=(
                content_proof.acquired_resource_hashes
            ),
            resource_count_by_type=content_proof.resource_counts,
        )
    except ValueError as exc:
        raise RuntimeError(
            "provider_directory_subset_completion_proof_invalid"
        ) from exc
    return replace(
        content_proof,
        completion_proof=completion_proof,
        completion_proof_sha256=completion_sha256,
    )


def _subset_replay_metadata(
    candidate: EndpointDatasetCandidate,
    diagnostics: Mapping[str, Any],
    content_proof: EndpointDatasetContentProof,
) -> dict[str, Any]:
    """Build the per-root opaque-hop evidence kept outside twin equality."""

    if candidate.completion_proof_required_version is None:
        return {}
    if (
        candidate.completion_proof_required_version
        != SERVER_ISSUED_SUBSET_REQUIRED_VERSION
        or candidate.subset_contract is None
        or content_proof.completion_proof is None
        or content_proof.completion_proof_sha256 is None
    ):
        raise RuntimeError(
            "provider_directory_subset_replay_evidence_invalid"
        )
    execution_proof_by_type: dict[str, dict[str, Any]] = {}
    for resource_type in candidate.subset_contract.resources:
        diagnostic = diagnostics.get(resource_type)
        safe_proof = (
            diagnostic.get("server_issued_subset_completeness")
            if isinstance(diagnostic, Mapping)
            else None
        )
        internal_evidence = (
            diagnostic.get(_SERVER_ISSUED_SUBSET_INTERNAL_REPLAY_KEY)
            if isinstance(diagnostic, Mapping)
            else None
        )
        if (
            not isinstance(safe_proof, Mapping)
            or not isinstance(internal_evidence, Mapping)
        ):
            raise RuntimeError(
                "provider_directory_subset_replay_evidence_invalid"
            )
        execution_proof_by_type[resource_type] = {
            **dict(safe_proof),
            "continuation_hop_sha256": internal_evidence.get(
                "continuation_hop_sha256"
            ),
        }
    try:
        replay_evidence, replay_sha256 = build_subset_replay_evidence(
            resource_proof_by_type=execution_proof_by_type,
            completion_proof=content_proof.completion_proof,
            completion_sha256=content_proof.completion_proof_sha256,
        )
    except ValueError as exc:
        raise RuntimeError(
            "provider_directory_subset_replay_evidence_invalid"
        ) from exc
    return {
        SERVER_ISSUED_SUBSET_REPLAY_EVIDENCE_KEY: replay_evidence,
        SERVER_ISSUED_SUBSET_REPLAY_EVIDENCE_SHA256_KEY: replay_sha256,
    }


async def _endpoint_dataset_source_summary_metadata(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    content_proof: EndpointDatasetContentProof,
    relation_proof_by_name: dict[str, dict[str, Any]],
    final_status: str,
) -> dict[str, Any]:
    if final_status != ENDPOINT_DATASET_VALIDATED:
        return {}
    source_summary = await _endpoint_dataset_source_summary(
        connection,
        candidate,
        content_proof,
        relation_proof_by_name,
    )
    if source_summary is None:
        return {}
    metadata = {SOURCE_SUMMARY_METADATA_KEY: source_summary}
    if (
        source_summary.get("semantic_contract_id")
        != SOURCE_SUMMARY_UHC_SEMANTIC_CONTRACT_ID
    ):
        return metadata
    return await _validated_uhc_source_summary_metadata(
        connection,
        candidate,
        content_proof,
        source_summary,
    )


async def _validated_uhc_source_summary_metadata(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    content_proof: EndpointDatasetContentProof,
    source_summary: dict[str, Any],
) -> dict[str, Any]:
    retained_metadata = await _acquiring_uhc_metadata(connection, candidate)
    try:
        summary_input = validate_uhc_summary_input(
            retained_metadata.get(UHC_RETAINED_SUMMARY_INPUT_METADATA_KEY)
        )
        canonical_proof = validate_uhc_canonical_content_proof(
            retained_metadata.get(UHC_CANONICAL_CONTENT_PROOF_METADATA_KEY),
            dataset_id=candidate.dataset_id,
            endpoint_id=candidate.endpoint_id,
            acquisition_root_run_id=(
                candidate.acquisition_root_run_id or ""
            ),
        )
    except UhcRetainedDatasetError as error:
        raise RuntimeError(
            "provider_directory_uhc_validation_lineage_invalid"
        ) from error
    except UhcCanonicalProofError as error:
        raise RuntimeError(
            "provider_directory_uhc_validation_content_proof_invalid"
        ) from error
    expected_publication_identity = _expected_uhc_publication_identity(
        summary_input,
        dataset_id=candidate.dataset_id,
        acquisition_root_run_id=candidate.acquisition_root_run_id,
    )
    if (
        retained_metadata.get(UHC_RETAINED_PUBLICATION_METADATA_KEY)
        != expected_publication_identity
        or canonical_proof["dataset_hash"] != content_proof.dataset_hash
        or canonical_proof["resource_count"] != content_proof.resource_count
        or canonical_proof["resource_hashes"]
        != content_proof.resource_hashes
        or canonical_proof["resource_counts"]
        != content_proof.resource_counts
    ):
        raise RuntimeError(
            "provider_directory_uhc_validation_lineage_changed"
        )
    return {
        SOURCE_SUMMARY_METADATA_KEY: source_summary,
        UHC_RETAINED_SUMMARY_INPUT_METADATA_KEY: summary_input,
        UHC_RETAINED_PUBLICATION_METADATA_KEY: (
            expected_publication_identity
        ),
        UHC_CANONICAL_CONTENT_PROOF_METADATA_KEY: canonical_proof,
    }


def _validated_stored_content_proof_metadata(
    candidate: EndpointDatasetCandidate,
    content_proof: EndpointDatasetContentProof,
) -> dict[str, Any]:
    """Validate optional proof shards and return their sealed projection."""

    if content_proof.proof_metadata is None:
        return {}
    acquisition_root_run_id = _clean_text(candidate.acquisition_root_run_id)
    if acquisition_root_run_id is None:
        raise RuntimeError(
            "provider_directory_content_proof_acquisition_root_required"
        )
    validated_proof = validate_stored_dataset_proof_metadata(
        content_proof.proof_metadata,
        dataset_id=candidate.dataset_id,
        endpoint_id=candidate.endpoint_id,
        acquisition_root_run_id=acquisition_root_run_id,
        source_ids=candidate.source_ids,
        selected_resources=candidate.selected_resources,
        options=ProviderDirectoryStoredProofOptions(
            proof_resource_scope=_candidate_proof_resource_scope(candidate),
            expected_resource_hash_contract=candidate.resource_hash_contract,
            expected_semantic_projection_as_of=(
                candidate.semantic_projection_as_of
            ),
        ),
    )
    expected_values = (
        content_proof.dataset_hash,
        content_proof.resource_count,
        content_proof.resource_hashes,
        content_proof.resource_counts,
        content_proof.source_metrics,
    )
    proof_values = tuple(
        validated_proof[field_name]
        for field_name in (
            "dataset_hash",
            "resource_count",
            "resource_hashes",
            "resource_counts",
            "source_metrics",
        )
    )
    if proof_values != expected_values:
        raise RuntimeError(
            "provider_directory_content_proof_metadata_changed"
        )
    return {PROVIDER_DIRECTORY_CONTENT_PROOF_METADATA_KEY: validated_proof}


def _dataset_validation_metadata(
    candidate: EndpointDatasetCandidate,
    diagnostics: dict[str, dict[str, Any]],
    content_proof: EndpointDatasetContentProof,
    bulk_transaction_times: dict[str, str],
    relation_proof_by_name: dict[str, dict[str, Any]],
    verification_metadata: dict[str, Any],
    source_summary_metadata: dict[str, Any],
) -> dict[str, Any]:
    """Build sealed validation metadata, replay evidence, and coverage."""

    content_proof_metadata_by_key = _validated_stored_content_proof_metadata(
        candidate,
        content_proof,
    )
    replay_metadata = _subset_replay_metadata(
        candidate,
        diagnostics,
        content_proof,
    )
    coverage_metadata = _subset_dataset_coverage_metadata(
        candidate,
        diagnostics,
        content_proof,
        relation_proof_by_name,
        verification_metadata,
    )
    return _endpoint_dataset_publication_metadata(
        candidate,
        diagnostics,
        dataset_hash=content_proof.dataset_hash,
        resource_count=content_proof.resource_count,
        bulk_transaction_times=bulk_transaction_times,
        **{
            PROVIDER_DIRECTORY_OUTCOME_RESOURCE_COUNTS_METADATA_KEY: (
                _outcome_resource_count_proof(candidate, content_proof)
            )
        },
        **relation_proof_by_name,
        **verification_metadata,
        **source_summary_metadata,
        **content_proof_metadata_by_key,
        **replay_metadata,
        **coverage_metadata,
    )


def _subset_resource_coverage_map(
    diagnostics: Mapping[str, Any],
    *,
    twin_state: str = "pending_matching_reviewed_root",
) -> dict[str, Any]:
    """Return sanitized terminal coverage for every reviewed family."""

    coverage_by_resource: dict[str, Any] = {}
    for resource_type in SERVER_ISSUED_SUBSET_RESOURCE_TYPES:
        diagnostic = diagnostics.get(resource_type)
        proof = (
            diagnostic.get("server_issued_subset_completeness")
            if isinstance(diagnostic, Mapping)
            else None
        )
        coverage = _server_issued_subset_coverage(proof)
        if coverage is None:
            raise RuntimeError("provider_directory_subset_coverage_invalid")
        coverage["twin_state"] = twin_state
        coverage_by_resource[resource_type] = coverage
    return coverage_by_resource


def _subset_unresolved_relation_counts(
    relation_proof_by_name: Mapping[str, Any],
) -> dict[str, int]:
    """Return exact missing-target counts only after relation validation."""

    unresolved_by_relation: dict[str, int] = {}
    for relation_name in (
        PROVIDER_DIRECTORY_DATASET_NETWORK_PLAN_METADATA_KEY,
        PROVIDER_DIRECTORY_DATASET_AFFILIATION_ORGANIZATION_METADATA_KEY,
    ):
        relation_proof = relation_proof_by_name.get(relation_name)
        if not isinstance(relation_proof, Mapping):
            unresolved_by_relation = {}
            break
        unresolved_count = relation_proof.get("unresolved_reference_count")
        if (
            type(unresolved_count) is not int
            or unresolved_count < 0
        ):
            raise RuntimeError("provider_directory_subset_coverage_invalid")
        unresolved_by_relation[relation_name] = unresolved_count
    return unresolved_by_relation


def _subset_aggregate_coverage_counts(
    resources: Mapping[str, Mapping[str, Any]],
) -> dict[str, int]:
    return {
        count_name: sum(
            resource[count_name] for resource in resources.values()
        )
        for count_name in (
            "advertised_pre",
            "advertised_post",
            "returned_unique",
            "deficit",
        )
    }


def _subset_dataset_coverage(
    candidate: EndpointDatasetCandidate,
    diagnostics: Mapping[str, Any],
    completion_proof: Mapping[str, Any],
    completion_sha256: str,
    relation_proof_by_name: Mapping[str, Any],
    verification_metadata: Mapping[str, Any],
) -> dict[str, Any]:
    """Build the sealed safe coverage object from validated proof inputs."""

    is_single_root = bool(
        candidate.reviewed_root_policy is not None
        and not candidate.reviewed_root_policy.is_twin_root_required
    )
    coverage_by_resource = _subset_resource_coverage_map(
        diagnostics,
        twin_state=(
            "not_required"
            if is_single_root
            else "pending_matching_reviewed_root"
        ),
    )
    unresolved_by_relation = _subset_unresolved_relation_counts(
        relation_proof_by_name
    )
    twin_verification = verification_metadata.get(
        TWIN_ROOT_VERIFICATION_METADATA_KEY
    )
    twin_state = (
        twin_verification.get("result")
        if isinstance(twin_verification, Mapping)
        else "not_required"
    )
    resources = completion_proof["resources"]
    return {
        "cutoff": completion_proof["cutoff"],
        "scope": "server_issued_traversal_subset",
        **_subset_aggregate_coverage_counts(resources),
        "resources": coverage_by_resource,
        "traversal_complete": True,
        "twin_state": twin_state,
        "proof_sha256": completion_sha256,
        "unresolved_reference_count": (
            sum(unresolved_by_relation.values())
            if unresolved_by_relation
            else None
        ),
        "unresolved_reference_counts": (
            dict(sorted(unresolved_by_relation.items()))
            if unresolved_by_relation
            else None
        ),
        "missing_target_semantics": "preserved_not_synthesized",
        "absence_semantics": "unknown_under_subset",
        "publication_state_at_completion": "not_published",
    }


def _subset_dataset_coverage_metadata(
    candidate: EndpointDatasetCandidate,
    diagnostics: Mapping[str, Any],
    content_proof: EndpointDatasetContentProof,
    relation_proof_by_name: Mapping[str, Any],
    verification_metadata: Mapping[str, Any],
) -> dict[str, Any]:
    """Summarize honest subset coverage without asserting absent resources."""

    if candidate.completion_proof_required_version is None:
        return {}
    completion_proof = content_proof.completion_proof
    completion_sha256 = content_proof.completion_proof_sha256
    if not isinstance(completion_proof, Mapping) or not completion_sha256:
        raise RuntimeError("provider_directory_subset_coverage_invalid")
    return {
        SERVER_ISSUED_SUBSET_COVERAGE_KEY: _subset_dataset_coverage(
            candidate,
            diagnostics,
            completion_proof,
            completion_sha256,
            relation_proof_by_name,
            verification_metadata,
        )
    }


async def _store_dataset_validation_state(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    previous_dataset_id: str | None,
    content_proof: EndpointDatasetContentProof,
    relation_proof_by_name: dict[str, Any],
    final_status: str,
    mismatch_fields: list[str],
    metadata: dict[str, Any],
) -> tuple[
    str | None, EndpointDatasetContentProof, dict[str, Any],
    str, list[str], int,
]:
    await _store_endpoint_dataset_verification_result(
        connection,
        candidate,
        previous_dataset_id,
        content_proof,
        metadata,
        final_status,
    )
    retired_row_count = await _retire_matched_twin_root_baseline_payload(
        connection, candidate, metadata, final_status
    )
    if content_proof.proof_metadata is not None:
        await delete_dataset_proof_shards(
            connection,
            _schema(),
            candidate.dataset_id,
        )
    return (
        previous_dataset_id,
        content_proof,
        relation_proof_by_name,
        final_status,
        mismatch_fields,
        retired_row_count,
    )


async def _persist_endpoint_dataset_validation(
    connection: Any,
    candidate: EndpointDatasetCandidate,
    diagnostics: dict[str, dict[str, Any]],
) -> tuple[
    str | None, EndpointDatasetContentProof, dict[str, Any],
    str, list[str], int,
]:
    """Validate and store one candidate inside its repeatable-read transaction."""
    await connection.status("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;")
    previous_dataset_id = await _lock_endpoint_dataset_for_validation(
        connection, candidate
    )
    candidate_transaction_times = await _validated_endpoint_bulk_transaction_times(
        connection,
        candidate,
        previous_dataset_id,
        diagnostics,
    )
    (
        content_proof,
        relation_proof_by_name,
        final_status,
        verification_metadata,
        mismatch_fields,
    ) = await _endpoint_dataset_validation_proofs(
        connection,
        candidate,
        diagnostics,
    )
    source_summary_metadata = await _endpoint_dataset_source_summary_metadata(
        connection,
        candidate,
        content_proof,
        relation_proof_by_name,
        final_status,
    )
    metadata = _dataset_validation_metadata(
        candidate,
        diagnostics,
        content_proof,
        candidate_transaction_times,
        relation_proof_by_name,
        verification_metadata,
        source_summary_metadata,
    )
    return await _store_dataset_validation_state(
        connection,
        candidate,
        previous_dataset_id,
        content_proof,
        relation_proof_by_name,
        final_status,
        mismatch_fields,
        metadata,
    )


async def _finalize_endpoint_dataset_candidate(
    candidate: EndpointDatasetCandidate | None,
    diagnostics: dict[str, dict[str, Any]],
) -> dict[str, Any] | None:
    if candidate is None:
        return None
    if _is_endpoint_dataset_publishable(candidate, diagnostics):
        return await _validate_endpoint_dataset_candidate(
            candidate,
            diagnostics,
        )
    status = (
        ENDPOINT_DATASET_FAILED
        if any(diagnostic.get("error") for diagnostic in diagnostics.values())
        else ENDPOINT_DATASET_INCOMPLETE
    )
    await _mark_endpoint_dataset_candidate(candidate, status, diagnostics)
    return {
        "dataset_id": candidate.dataset_id,
        "status": status,
        "published": False,
    }


async def _clear_finalized_endpoint_dataset_pagination_checkpoints(
    candidate: EndpointDatasetCandidate | None,
    finalization: dict[str, Any] | None,
) -> None:
    """Drop acquisition checkpoints only after immutable dataset validation."""
    if candidate is None or candidate.checkpoint_context is None:
        return
    is_finalized = bool(
        candidate.already_validated
        or candidate.already_published
        or candidate.verification_terminal_status
        in {
            ENDPOINT_DATASET_VERIFICATION_BASELINE,
            ENDPOINT_DATASET_VERIFICATION_MISMATCH,
        }
        or (
            finalization
            and (
                finalization.get("validated") is True
                or finalization.get("published") is True
                or finalization.get("status")
                in {
                    ENDPOINT_DATASET_VALIDATED,
                    ENDPOINT_DATASET_PUBLISHED,
                    ENDPOINT_DATASET_VERIFICATION_BASELINE,
                    ENDPOINT_DATASET_VERIFICATION_MISMATCH,
                }
            )
        )
    )
    if not is_finalized:
        return
    await _clear_finalized_dataset_checkpoints(candidate)


async def _clear_finalized_dataset_checkpoints(
    candidate: EndpointDatasetCandidate,
) -> int:
    """Retire every checkpoint attached to an immutable finalized dataset."""
    async with db.acquire() as connection:
        deleted_status = await connection.status(
            f"""
            DELETE FROM {_pagination_checkpoint_table_ref()} AS checkpoint
             USING {_qt(_schema(), ProviderDirectoryEndpointDataset.__tablename__)} AS dataset
             WHERE checkpoint.dataset_id = :dataset_id
               AND checkpoint.acquisition_root_run_id = :acquisition_root_run_id
               AND dataset.dataset_id = checkpoint.dataset_id
               AND dataset.endpoint_id = :endpoint_id
               AND dataset.acquisition_root_run_id IS NOT DISTINCT FROM
                   :acquisition_root_run_id
               AND dataset.status = ANY(
                   CAST(:finalized_statuses AS varchar[])
               );
            """,
            dataset_id=candidate.dataset_id,
            endpoint_id=candidate.endpoint_id,
            acquisition_root_run_id=candidate.acquisition_root_run_id,
            finalized_statuses=[
                ENDPOINT_DATASET_VALIDATED,
                ENDPOINT_DATASET_PUBLISHED,
                ENDPOINT_DATASET_VERIFICATION_BASELINE,
                ENDPOINT_DATASET_VERIFICATION_MISMATCH,
            ],
        )
        remaining_count = int(
            await connection.scalar(
                f"""
                SELECT count(*)
                  FROM {_pagination_checkpoint_table_ref()}
                 WHERE dataset_id = :dataset_id
                   AND acquisition_root_run_id = :acquisition_root_run_id;
                """,
                dataset_id=candidate.dataset_id,
                acquisition_root_run_id=candidate.acquisition_root_run_id,
            )
            or 0
        )
        if remaining_count:
            raise RuntimeError(
                "provider_directory_finalized_dataset_checkpoint_cleanup_incomplete"
            )
    return _coerce_rowcount(deleted_status)


async def _prepare_resource_import_source_group(
    source_records: list[dict[str, Any]],
    resources: list[str],
    *,
    run_id: str | None,
    retry_of_run_id: str | None,
    pagination_root_run_id: str | None,
    is_checkpointing_enabled: bool,
) -> tuple[list[dict[str, Any]], EndpointDatasetCandidate | None]:
    checkpoint_context = _resource_group_pagination_checkpoint_context(
        source_records,
        run_id=run_id,
        retry_of_run_id=retry_of_run_id,
        pagination_root_run_id=pagination_root_run_id,
        is_checkpointing_enabled=is_checkpointing_enabled,
    )
    dataset_resources = _endpoint_dataset_selected_resources(
        source_records,
        resources,
    )
    candidate = await _prepare_endpoint_dataset_candidate(
        source_records,
        dataset_resources,
        run_id=run_id,
        retry_of_run_id=retry_of_run_id,
        pagination_root_run_id=pagination_root_run_id,
        checkpoint_context=checkpoint_context,
    )
    prepared_source_records = [dict(source_record) for source_record in source_records]
    checkpoint_owner_run_id = pagination_root_run_id or retry_of_run_id or run_id
    if candidate is not None:
        checkpoint_context = candidate.checkpoint_context
    for source_record in prepared_source_records:
        if candidate is not None:
            source_record["_endpoint_id"] = candidate.endpoint_id
            source_record["_endpoint_dataset_id"] = candidate.dataset_id
            source_record["_resource_hash_contract"] = (
                candidate.resource_hash_contract
            )
            if (
                proof_resource_scope := _candidate_proof_resource_scope(
                    candidate
                )
            ) is not None:
                source_record["_proof_resource_scope"] = list(
                    proof_resource_scope
                )
            if candidate.semantic_projection_as_of is not None:
                source_record["_semantic_projection_as_of"] = (
                    candidate.semantic_projection_as_of
                )
        if checkpoint_context is not None:
            source_record["_pagination_checkpoint_context"] = checkpoint_context
        if checkpoint_owner_run_id:
            source_record["_partition_checkpoint_owner_run_id"] = (
                checkpoint_owner_run_id
            )
    return prepared_source_records, candidate


def _resource_group_pagination_checkpoint_context(
    source_records: list[dict[str, Any]],
    *,
    run_id: str | None,
    retry_of_run_id: str | None,
    pagination_root_run_id: str | None,
    is_checkpointing_enabled: bool,
) -> PaginationCheckpointContext | None:
    if not is_checkpointing_enabled:
        return None
    source_id_values = sorted(
        source_record["source_id"] for source_record in source_records
    )
    checkpoint_source_record = _scoped_partition_source_record(
        source_records,
        source_id_values,
    )
    return _pagination_checkpoint_context(
        checkpoint_source_record,
        source_id_values,
        run_id=run_id,
        retry_of_run_id=retry_of_run_id,
        pagination_root_run_id=pagination_root_run_id,
    )


ResourceImportGroupResult = tuple[
    list[str],
    dict[str, dict[str, Any]],
    dict[str, int],
    dict[str, int],
    dict[str, dict[str, Any]],
    dict[str, int],
    dict[str, list[str]],
]


@dataclass(frozen=True)
class ResourceImportGroupFailure:
    """Describe one settled source-group failure without retaining its payload."""

    source_ids: tuple[str, ...]
    error_type: str


class ResourceImportProgressFailure(RuntimeError):
    """Keep shared progress failures batch-fatal across source isolation."""


class ResourceImportControlPlaneFailure(RuntimeError):
    """Keep cancellation-authority failures batch-fatal across source isolation."""


async def _raise_if_resource_import_cancelled(
    cancel_ctx: dict[str, Any] | None,
    cancel_task: dict[str, Any] | None,
) -> None:
    """Preserve cancellation while classifying its backend outage as global."""
    if cancel_ctx is None:
        return
    try:
        await raise_if_cancelled(cancel_ctx, cancel_task)
    except (asyncio.CancelledError, ImportCancelledError):
        raise
    except Exception as failure:
        raise ResourceImportControlPlaneFailure(
            "provider_directory_cancellation_probe_failed"
        ) from failure


def _resource_import_failure_source_id(raw_source_id: Any) -> str:
    """Return a bounded, log-safe source identity for aggregate errors."""
    source_id = _clean_text(raw_source_id) or "unknown-source"
    return re.sub(r"[^A-Za-z0-9_.-]", "_", source_id)[:128]


def _resource_import_group_failure(
    source_records: list[dict[str, Any]],
    failure: Exception,
) -> ResourceImportGroupFailure:
    """Convert a source-local exception into a deterministic safe result."""
    source_ids = tuple(
        sorted(
            {
                _resource_import_failure_source_id(source.get("source_id"))
                for source in source_records
            }
        )
    )
    error_type = type(failure).__name__
    LOGGER.warning(
        "Provider Directory source group failed: source_ids=%s error_type=%s",
        ",".join(source_ids),
        error_type,
    )
    return ResourceImportGroupFailure(
        source_ids=source_ids,
        error_type=error_type,
    )


def _finalized_endpoint_dataset_import_summary(
    candidate: EndpointDatasetCandidate,
    resource_completion: dict[str, set[str]] | None = None,
) -> ResourceImportGroupResult:
    _assert_finalized_endpoint_dataset_replay(candidate)
    finalized_metadata, state_name = _finalized_endpoint_dataset_metadata(
        candidate
    )
    assert finalized_metadata is not None
    persisted_diagnostics = finalized_metadata["resource_diagnostics"]
    diagnostics_by_resource = {
        resource_type: dict(persisted_diagnostics[resource_type])
        for resource_type in candidate.selected_resources
        if isinstance(persisted_diagnostics.get(resource_type), dict)
    }
    if set(diagnostics_by_resource) != set(candidate.selected_resources):
        raise RuntimeError(
            "provider_directory_endpoint_dataset_"
            f"{state_name}_diagnostics_incomplete"
        )
    if not _is_endpoint_dataset_publishable(candidate, diagnostics_by_resource):
        raise RuntimeError(
            "provider_directory_endpoint_dataset_"
            f"{state_name}_completion_proof_invalid"
        )
    if resource_completion is not None:
        for resource_type in candidate.selected_resources:
            resource_completion.setdefault(resource_type, set()).update(
                candidate.source_ids
            )
    return (
        list(candidate.source_ids),
        diagnostics_by_resource,
        {resource_type: 0 for resource_type in candidate.selected_resources},
        {},
        {},
        {},
        {},
    )


def _is_finalized_endpoint_dataset_candidate(
    candidate: EndpointDatasetCandidate | None,
) -> bool:
    return bool(
        candidate is not None
        and (
            candidate.already_validated
            or candidate.already_published
            or candidate.verification_terminal_status
            in {
                ENDPOINT_DATASET_VERIFICATION_BASELINE,
                ENDPOINT_DATASET_VERIFICATION_MISMATCH,
            }
        )
    )


async def _replay_finalized_candidate_and_clear_checkpoints(
    candidate: EndpointDatasetCandidate,
    resource_completion: dict[str, set[str]] | None,
    source_records: list[dict[str, Any]] | None = None,
) -> ResourceImportGroupResult:
    """Return replay proof and retire its completed acquisition checkpoints."""
    is_verification_mismatch = candidate.verification_terminal_status == (
        ENDPOINT_DATASET_VERIFICATION_MISMATCH
    )
    import_summary = _finalized_endpoint_dataset_import_summary(
        candidate,
        None if is_verification_mismatch else resource_completion,
    )
    if source_records is not None:
        finalized_metadata, _state_name = (
            _finalized_endpoint_dataset_metadata(candidate)
        )
        _validate_current_version_census_diagnostics(
            source_records,
            _diagnostics_with_persisted_subset_replay(
                import_summary[1],
                finalized_metadata,
            ),
        )
    await _clear_finalized_endpoint_dataset_pagination_checkpoints(
        candidate,
        None,
    )
    if is_verification_mismatch:
        raise RuntimeError(
            "provider_directory_endpoint_dataset_verification_mismatch"
        )
    return import_summary


async def _replay_finalized_candidate_after_cancellation(
    candidate: EndpointDatasetCandidate,
    resource_completion: dict[str, set[str]] | None,
    source_records: list[dict[str, Any]],
    cancellation: _ResourceImportCancellation,
) -> ResourceImportGroupResult:
    """Fence replay cleanup behind the shared cancellation authority."""
    await cancellation.check()
    if not any(
        current_version_census_contract(source_record) is not None
        for source_record in source_records
    ):
        return await _replay_finalized_candidate_and_clear_checkpoints(
            candidate,
            resource_completion,
        )
    return await _replay_finalized_candidate_and_clear_checkpoints(
        candidate,
        resource_completion,
        source_records,
    )


async def _finalize_candidate_and_clear_checkpoints(
    candidate: EndpointDatasetCandidate | None,
    diagnostics_by_resource: dict[str, dict[str, Any]],
) -> None:
    """Validate a candidate before retiring its acquisition checkpoints."""
    finalization = await _finalize_endpoint_dataset_candidate(
        candidate,
        diagnostics_by_resource,
    )
    await _clear_finalized_endpoint_dataset_pagination_checkpoints(
        candidate,
        finalization,
    )
    if finalization and finalization.get("status") == (
        ENDPOINT_DATASET_VERIFICATION_MISMATCH
    ):
        raise RuntimeError(
            "provider_directory_endpoint_dataset_verification_mismatch"
        )


def _diagnostic_validation_proof(
    contract: CurrentVersionCensusContract,
    diagnostic_by_field: Mapping[str, Any],
    proof_by_field: dict[str, Any],
) -> dict[str, Any]:
    """Rejoin token-specific replay only for internal v3 validation."""

    if not contract.is_server_issued_subset_v3:
        return proof_by_field
    replay_evidence = diagnostic_by_field.get(
        _SERVER_ISSUED_SUBSET_INTERNAL_REPLAY_KEY
    )
    if not isinstance(replay_evidence, Mapping):
        return proof_by_field
    return {
        **proof_by_field,
        "continuation_hop_sha256": replay_evidence.get(
            "continuation_hop_sha256"
        ),
    }


def _validated_census_diagnostic_count(
    contract: CurrentVersionCensusContract,
    resource_type: str,
    diagnostic_by_field: Mapping[str, Any],
) -> int:
    """Validate one terminal diagnostic and return its stable pre-count."""

    expected_fetch_mode = (
        SERVER_ISSUED_SUBSET_FETCH_MODE
        if contract.is_server_issued_subset_v3
        else CURRENT_VERSION_CENSUS_FETCH_MODE
    )
    diagnostic_key = (
        "server_issued_subset_completeness"
        if contract.is_server_issued_subset_v3
        else "current_version_census_completeness"
    )
    proof_by_field = diagnostic_by_field.get(diagnostic_key)
    if (
        diagnostic_by_field.get("fetch_mode") != expected_fetch_mode
        or not isinstance(proof_by_field, dict)
    ):
        raise RuntimeError(
            "provider_directory_current_version_census_proof_incomplete"
        )
    try:
        validated_proof_by_field = validated_current_version_census_completed_proof(
            _diagnostic_validation_proof(
                contract,
                diagnostic_by_field,
                proof_by_field,
            ),
            contract,
            resource_type,
            rows_processed=diagnostic_by_field.get("rows_fetched"),
            pages_processed=diagnostic_by_field.get("pages_fetched"),
        )
    except ValueError as exc:
        raise RuntimeError(
            "provider_directory_current_version_census_proof_incomplete"
        ) from exc
    return validated_proof_by_field["pre_count"]


def _validate_current_version_census_diagnostics(
    source_records: list[dict[str, Any]],
    diagnostics_by_resource: dict[str, dict[str, Any]],
) -> None:
    """Require a terminal identity-bound proof for every selected family."""

    bound_sources = [
        source_record
        for source_record in source_records
        if current_version_census_contract(source_record) is not None
    ]
    if not bound_sources:
        return
    if len(bound_sources) != 1 or len(source_records) != 1:
        raise RuntimeError(
            "provider_directory_current_version_census_source_group_invalid"
        )
    contract = current_version_census_contract(bound_sources[0])
    assert contract is not None
    if set(diagnostics_by_resource) != set(contract.resources):
        raise RuntimeError(
            "provider_directory_current_version_census_diagnostics_incomplete"
        )
    count_by_resource = {
        resource_type: _validated_census_diagnostic_count(
            contract,
            resource_type,
            diagnostics_by_resource[resource_type],
        )
        for resource_type in contract.resources
    }
    validated_current_version_census_count_map(contract, count_by_resource)


def _diagnostics_with_persisted_subset_replay(
    diagnostics_by_resource: Mapping[str, Any],
    metadata: Any,
) -> dict[str, dict[str, Any]]:
    """Reattach sealed per-root hashes only for internal replay validation."""

    diagnostics_by_resource = {
        resource_type: dict(diagnostic)
        for resource_type, diagnostic in diagnostics_by_resource.items()
        if isinstance(diagnostic, Mapping)
    }
    if not isinstance(metadata, Mapping):
        return diagnostics_by_resource
    replay_evidence = metadata.get(SERVER_ISSUED_SUBSET_REPLAY_EVIDENCE_KEY)
    replay_resources = (
        replay_evidence.get("resources")
        if isinstance(replay_evidence, Mapping)
        else None
    )
    if not isinstance(replay_resources, Mapping):
        return diagnostics_by_resource
    for resource_type, diagnostic in diagnostics_by_resource.items():
        replay_resource = replay_resources.get(resource_type)
        if isinstance(replay_resource, Mapping):
            diagnostic[_SERVER_ISSUED_SUBSET_INTERNAL_REPLAY_KEY] = {
                "continuation_hop_sha256": replay_resource.get(
                    "continuation_hop_sha256"
                )
            }
    return diagnostics_by_resource


async def _validate_and_finalize_import_candidate(
    candidate: EndpointDatasetCandidate | None,
    source_records: list[dict[str, Any]],
    diagnostics_by_resource: dict[str, dict[str, Any]],
    cancellation: _ResourceImportCancellation,
) -> None:
    """Validate a reviewed traversal before finalizing its retained candidate."""

    await cancellation.check()
    _validate_current_version_census_diagnostics(
        source_records,
        diagnostics_by_resource,
    )
    await cancellation.check()
    await _finalize_candidate_and_clear_checkpoints(
        candidate,
        diagnostics_by_resource,
    )


def _published_endpoint_dataset_import_summary(
    candidate: EndpointDatasetCandidate,
) -> ResourceImportGroupResult:
    """Retain the published-only helper name for focused callers."""
    return _finalized_endpoint_dataset_import_summary(candidate)


async def _mark_failed_endpoint_dataset_without_masking(
    candidate: EndpointDatasetCandidate | None,
    diagnostics_by_resource: dict[str, dict[str, Any]],
    failure: BaseException,
) -> None:
    if candidate is None:
        return
    try:
        await _mark_endpoint_dataset_candidate(
            candidate,
            ENDPOINT_DATASET_FAILED,
            diagnostics_by_resource,
            error=_short_error(failure),
        )
    except Exception:
        LOGGER.exception(
            "Failed to mark Provider Directory endpoint dataset %s failed",
            candidate.dataset_id,
        )


async def _retain_terminal_import_failure(
    candidate: EndpointDatasetCandidate | None,
    source_records: list[dict[str, Any]],
    run_id: str | None,
    failure: ProviderDirectoryPaginationTerminalFailure,
) -> None:
    """Retain terminal diagnostics and fail the candidate without masking."""

    source_ids = sorted(
        {
            source_id
            for source_record in source_records
            if (source_id := _clean_text(source_record.get("source_id")))
        }
    )
    try:
        await _update_source_resource_import_metadata(
            source_ids,
            run_id=run_id,
            diagnostics=failure.diagnostics_by_resource,
        )
    except Exception:
        LOGGER.exception(
            "Failed to retain terminal Provider Directory source diagnostics"
        )
    await _mark_failed_endpoint_dataset_without_masking(
        candidate,
        failure.diagnostics_by_resource,
        failure,
    )


def _has_expired_cursor_abandonment_evidence(
    diagnostics_by_resource: Mapping[str, Any],
    resource_types: tuple[str, ...],
) -> bool:
    """Return whether every resource satisfies the closed HTTP-410 contract."""

    from process.provider_directory_fhir_subset_abandonment_contract import (
        ReviewedSubsetAbandonmentError,
        validated_terminal_diagnostics,
    )

    try:
        validated_terminal_diagnostics(
            diagnostics_by_resource,
            resource_types,
        )
    except ReviewedSubsetAbandonmentError:
        return False
    return True


async def _abandon_terminal_reviewed_subset_without_masking(
    source_records: list[dict[str, Any]],
    failure: ProviderDirectoryPaginationTerminalFailure,
    guard_lease: _PaginationCheckpointGuardLease | None,
) -> None:
    """Seal only the checked-in reviewed v3 root under its worker lock."""

    if len(source_records) != 1:
        return
    source_record = source_records[0]
    census_contract = current_version_census_contract(source_record)
    canonical_api_base = _canonical_base(
        source_record.get("canonical_api_base") or source_record.get("api_base")
    )
    if (
        census_contract is None
        or not census_contract.is_server_issued_subset_v3
        or set(failure.diagnostics_by_resource) != set(census_contract.resources)
        or not _has_expired_cursor_abandonment_evidence(
            failure.diagnostics_by_resource,
            tuple(sorted(census_contract.resources)),
        )
        or guard_lease is None
        or not guard_lease.is_held
        or guard_lease.context.canonical_api_base != canonical_api_base
    ):
        return
    try:
        from process.provider_directory_fhir_manual_catalog import (
            reviewed_manual_census_source_id,
        )
        from process.provider_directory_fhir_subset_abandonment_store import (
            sync_reviewed_subset_abandonment_transaction,
        )

        expected_source_id = reviewed_manual_census_source_id()
        if _clean_text(source_record.get("source_id")) != expected_source_id:
            return
        await sync_reviewed_subset_abandonment_transaction(
            guard_lease.database,
            expected_source_id,
            tuple(sorted(census_contract.resources)),
            held_pagination_guard_key=guard_lease.lock_key,
        )
    except (asyncio.CancelledError, ImportCancelledError):
        raise
    except Exception:
        LOGGER.exception(
            "Failed to seal terminal reviewed Provider Directory subset evidence"
        )


async def _retain_and_abandon_terminal_failure(
    candidate: EndpointDatasetCandidate | None,
    source_records: list[dict[str, Any]],
    run_id: str | None,
    failure: ProviderDirectoryPaginationTerminalFailure,
    guard_lease: _PaginationCheckpointGuardLease | None,
) -> None:
    """Persist terminal diagnostics and seal before releasing the guard."""

    await _retain_terminal_import_failure(
        candidate,
        source_records,
        run_id,
        failure,
    )
    await _abandon_terminal_reviewed_subset_without_masking(
        source_records,
        failure,
        guard_lease,
    )


def _is_validated_uhc_official_source_group(
    source_records: list[dict[str, Any]],
) -> bool:
    has_official_source = any(
        _uses_uhc_official_file_connector(source_record)
        for source_record in source_records
    )
    if not has_official_source:
        return False
    if (
        len(source_records) != 1
        or not _uses_uhc_official_file_connector(source_records[0])
    ):
        raise RuntimeError(
            "provider_directory_uhc_official_file_group_invalid"
        )
    return True


def _provider_directory_progress_counts_snapshot(
    completed_count_by_resource: Mapping[str, int],
    active_count_by_group: Mapping[int, Mapping[str, int]],
    high_water_by_resource: dict[str, int],
) -> dict[str, int]:
    """Preserve row-count movement across partial-to-complete handoffs."""
    current_count_by_resource = dict(completed_count_by_resource)
    for partial_count_by_resource in active_count_by_group.values():
        for resource_type, row_count in partial_count_by_resource.items():
            current_count_by_resource[resource_type] = (
                current_count_by_resource.get(resource_type, 0) + row_count
            )
    for resource_type, row_count in current_count_by_resource.items():
        high_water_by_resource[resource_type] = max(
            row_count,
            high_water_by_resource.get(resource_type, 0),
        )
    return dict(high_water_by_resource)


@dataclass(frozen=True)
class ResourceGroupScanOptions:
    per_resource_limit: int
    page_limit: int
    page_count: int
    timeout: int
    run_id: str | None
    stream_batch_size: int
    cancel_ctx: dict[str, Any] | None
    cancel_task: dict[str, Any] | None
    bulk_export: bool
    bulk_export_max_pending_seconds: int
    resource_deadline_seconds: int
    linked_resource_limit: int
    stale_cleanup: bool
    seen_stage_table: str | None
    scan_role_reverse_lookup_planned: bool
    source_concurrency: int
    requested_resource_concurrency: int
    checkpointing_enabled: bool
    deferred_materialization: bool


@dataclass
class ResourceGroupScanRunner:
    """Own shared state while independent resource cursors run concurrently."""

    source_record: dict[str, Any]
    source_ids: list[str]
    group_key: int
    options: ResourceGroupScanOptions
    progress_lock: asyncio.Lock
    active_group_by_key: dict[int, dict[str, Any]]
    report_progress: Callable[..., Awaitable[None]]
    persist_rows: Callable[[type, list[dict[str, Any]]], Awaitable[int]]
    partial_progress: Callable[[int, str, int], Awaitable[None]]
    mark_stale_ready: Callable[[str, ResourceFetchResult], Awaitable[None]]
    count_by_resource: dict[str, int]
    stats_by_resource: dict[str, dict[str, Any]]
    resource_completion: dict[str, set[str]] | None
    rows_by_resource: dict[str, list[dict[str, Any]]]
    diagnostic_by_resource: dict[str, dict[str, Any]]
    effective_concurrency: int = field(init=False, default=1)

    @property
    def is_streaming(self) -> bool:
        """Return whether page rows are persisted through the batch callback."""
        return self.options.stream_batch_size > 0

    async def activate(
        self,
        resource_types: tuple[str, ...],
        *,
        summary: str | None = None,
    ) -> None:
        """Publish every resource cursor active for this source group."""
        started_at = _now().isoformat(timespec="seconds") + "Z"
        async with self.progress_lock:
            active_group = self.active_group_by_key[self.group_key]
            active_group["current_resource"] = summary or resource_types[0]
            active_group["current_resources"] = list(resource_types)
            active_group["resource_scan_concurrency_requested"] = (
                self.options.requested_resource_concurrency
            )
            active_group["resource_scan_concurrency_effective"] = (
                self.effective_concurrency
            )
            active_group["resource_started_at"] = started_at
            active_group["resource_started_monotonic"] = time.monotonic()
        await self.report_progress(force=True)

    async def persist_batch(
        self,
        resource_type: str,
        model: type,
        resource_rows: list[dict[str, Any]],
    ) -> int:
        """Persist one resource-owned batch and publish partial progress."""
        if self.options.linked_resource_limit > 0 or (
            self.options.scan_role_reverse_lookup_planned
            and resource_type
            in _practitioner_role_reverse_lookup_resources(self.source_record)
        ):
            self.rows_by_resource.setdefault(resource_type, []).extend(
                _compact_linked_reference_rows(resource_type, resource_rows)
            )
        written = await self.persist_rows(model, resource_rows)
        await self.partial_progress(self.group_key, resource_type, written)
        return written

    async def fetch(
        self,
        resource_type: str,
        source_record_by_field: dict[str, Any],
        *,
        report_start: bool,
    ) -> ResourceFetchResult | None:
        """Fetch and persist one isolated resource cursor."""
        await _raise_if_resource_import_cancelled(
            self.options.cancel_ctx,
            self.options.cancel_task,
        )
        if resource_type == "PractitionerRole" and (
            _needs_practitioner_role_reverse_lookup(
                self.source_record,
                "PractitionerRole",
            )
        ):
            return None
        if report_start:
            await self.activate((resource_type,))
        if self.options.stale_cleanup and resource_type == "PractitionerRole" and (
            _is_uhc_role_postal_partition_enabled(self.source_record)
        ):
            await _mark_postal_checkpointed_roles_seen(
                self.source_record,
                [self.source_record["source_id"]],
                self.options.run_id,
                self.options.seen_stage_table,
            )
        return await self._fetch_rows(resource_type, source_record_by_field)

    async def _fetch_rows(
        self,
        resource_type: str,
        source_record_by_field: dict[str, Any],
    ) -> ResourceFetchResult | None:
        """Invoke the generic FHIR reader with one task-local source record."""
        return await _fetch_resource_rows(
            source_record_by_field,
            resource_type,
            per_resource_limit=self.options.per_resource_limit,
            page_limit=self.options.page_limit,
            page_count=self.options.page_count,
            timeout=self.options.timeout,
            run_id=self.options.run_id,
            row_batch_handler=(
                partial(self.persist_batch, resource_type)
                if self.is_streaming
                else None
            ),
            row_batch_size=self.options.stream_batch_size,
            retain_rows=not self.is_streaming,
            cancel_ctx=self.options.cancel_ctx,
            cancel_task=self.options.cancel_task,
            bulk_export=self.options.bulk_export,
            bulk_export_max_pending_seconds=(
                self.options.bulk_export_max_pending_seconds
            ),
            deadline_seconds=self.options.resource_deadline_seconds,
            pagination_checkpoint=source_record_by_field.get(
                "_pagination_checkpoint_context"
            ),
        )

    async def record(
        self,
        resource_type: str,
        source_record_by_field: dict[str, Any],
        fetch_result: ResourceFetchResult | None,
    ) -> ResourceFetchResult | None:
        """Merge one settled fetch in resource-owned result slots."""
        if fetch_result is None:
            return None
        fetch_result = _fail_closed_on_unexpected_empty_resource(
            source_record_by_field,
            resource_type,
            fetch_result,
        )
        await _reset_unexpected_empty_pagination_checkpoint(
            source_record_by_field,
            resource_type,
            self.options.page_count,
            fetch_result,
        )
        self._record_stats(resource_type, source_record_by_field, fetch_result)
        written_total = await self._written_total(fetch_result)
        self.count_by_resource[resource_type] += written_total
        resource_diagnostic = _resource_fetch_diagnostic(
            fetch_result,
            rows_written=written_total,
        )
        resource_diagnostic["resource_scan_concurrency_requested"] = (
            self.options.requested_resource_concurrency
        )
        resource_diagnostic["resource_scan_concurrency_effective"] = (
            self.effective_concurrency
        )
        self.diagnostic_by_resource[resource_type] = resource_diagnostic
        is_zero_role = bool(
            resource_type == "PractitionerRole"
            and fetch_result.complete
            and not fetch_result.error
            and not fetch_result.is_bounded
            and fetch_result.rows_fetched == 0
            and written_total == 0
        )
        if is_zero_role:
            return fetch_result
        await self.mark_stale_ready(resource_type, fetch_result)
        return None

    def _record_stats(
        self,
        resource_type: str,
        source_record_by_field: dict[str, Any],
        fetch_result: ResourceFetchResult,
    ) -> None:
        """Record completion, fetch timing, and retained linked rows."""
        checkpoint_context = (
            source_record_by_field.get("_pagination_checkpoint_context")
            if self.is_streaming
            and self.options.per_resource_limit <= 0
            and self.options.page_limit <= 0
            else None
        )
        _record_resource_fetch_stats(
            self.stats_by_resource,
            resource_type,
            fetch_result,
            bulk_export_selection=_source_bulk_export_selection(
                source_record_by_field,
                self.options.bulk_export,
                per_resource_limit=self.options.per_resource_limit,
                checkpoint_context=checkpoint_context,
            ),
        )
        _record_resource_completion(
            self.resource_completion,
            resource_type,
            self.source_ids,
            fetch_result,
        )
        if fetch_result.rows or resource_type not in self.rows_by_resource:
            self.rows_by_resource[resource_type] = fetch_result.rows

    async def _written_total(self, fetch_result: ResourceFetchResult) -> int:
        """Return callback writes or persist a retained result once."""
        if self.is_streaming:
            return fetch_result.rows_written
        return await self.persist_rows(fetch_result.model, fetch_result.rows)

    async def import_one(
        self,
        resource_type: str,
        *,
        report_start: bool,
    ) -> ResourceFetchResult | None:
        """Fetch one task-local source view and merge its settled outcome."""
        source_record_by_field = dict(self.source_record)
        fetch_result = await self.fetch(
            resource_type,
            source_record_by_field,
            report_start=report_start,
        )
        return await self.record(
            resource_type,
            source_record_by_field,
            fetch_result,
        )

    async def _run_bounded(
        self,
        resource_type: str,
        resource_semaphore: asyncio.Semaphore,
    ) -> ResourceFetchResult | None:
        """Run one resource only while holding a bounded wave slot."""
        async with resource_semaphore:
            return await self.import_one(resource_type, report_start=False)

    async def wave(
        self,
        resource_types: tuple[str, ...],
        concurrency: int,
    ) -> list[ResourceFetchResult | None]:
        """Run a fail-fast wave and always cancel and join every sibling."""
        resource_semaphore = asyncio.Semaphore(concurrency)
        resource_tasks = [
            asyncio.create_task(
                self._run_bounded(resource_type, resource_semaphore),
                name="provider-directory-resource-scan",
            )
            for resource_type in resource_types
        ]
        try:
            return list(await asyncio.gather(*resource_tasks))
        finally:
            for resource_task in resource_tasks:
                if not resource_task.done():
                    resource_task.cancel()
            if resource_tasks:
                await asyncio.gather(*resource_tasks, return_exceptions=True)

    def _effective_concurrency(
        self,
        ordered_resource_types: tuple[str, ...],
    ) -> int:
        """Return the fail-closed cursor concurrency for this source group."""
        return _effective_resource_scan_concurrency(
            self.source_record,
            ResourceScanConcurrencyOptions(
                resource_types=ordered_resource_types,
                requested_concurrency=(
                    self.options.requested_resource_concurrency
                ),
                per_resource_limit=self.options.per_resource_limit,
                page_limit=self.options.page_limit,
                page_count=self.options.page_count,
                stream_batch_size=self.options.stream_batch_size,
                source_concurrency=self.options.source_concurrency,
                linked_resource_limit=self.options.linked_resource_limit,
                stale_cleanup=self.options.stale_cleanup,
                bulk_export=self.options.bulk_export,
                checkpointing_enabled=self.options.checkpointing_enabled,
                deferred_materialization=(
                    self.options.deferred_materialization
                ),
            ),
        )

    async def scan(
        self,
        requested_resource_types: list[str],
    ) -> ResourceFetchResult | None:
        """Run a foundation wave and retain the serial role-tail outcome."""
        ordered_resource_types = tuple(
            _source_resource_fetch_order(
                self.source_record,
                requested_resource_types,
            )
        )
        concurrency = self._effective_concurrency(ordered_resource_types)
        self.effective_concurrency = concurrency
        if concurrency > 1:
            foundation_types = tuple(
                resource_type
                for resource_type in ordered_resource_types
                if resource_type != "PractitionerRole"
            )
            await self.activate(
                foundation_types,
                summary="parallel FHIR resources",
            )
            await self.wave(foundation_types, concurrency)
            serial_types = tuple(
                resource_type
                for resource_type in ordered_resource_types
                if resource_type == "PractitionerRole"
            )
        else:
            serial_types = ordered_resource_types
        zero_role_result = None
        for resource_type in serial_types:
            candidate = await self.import_one(resource_type, report_start=True)
            if candidate is not None:
                zero_role_result = candidate
        return zero_role_result


async def _import_resources(
    source_records: list[dict[str, Any]],
    *,
    resources: list[str],
    per_resource_limit: int,
    page_limit: int,
    page_count: int,
    timeout: int,
    run_id: str | None,
    linked_resource_limit: int = 0,
    linked_resource_concurrency: int = 5,
    linked_resource_deadline_seconds: int = 0,
    resource_deadline_seconds: int = 0,
    linked_counts: dict[str, int] | None = None,
    resource_fetch_stats: dict[str, dict[str, Any]] | None = None,
    resource_completion: dict[str, set[str]] | None = None,
    resource_retry_not_before: dict[str, str] | None = None,
    stale_counts: dict[str, int] | None = None,
    stale_cleanup: bool = False,
    stream_batch_size: int = 0,
    source_concurrency: int = 1,
    resource_scan_concurrency: int = 1,
    bulk_export: bool = False,
    bulk_export_max_pending_seconds: int = (
        DEFAULT_BULK_EXPORT_MAX_PENDING_SECONDS
    ),
    cancel_ctx: dict[str, Any] | None = None,
    cancel_task: dict[str, Any] | None = None,
    progress_callback: Callable[[int, int, dict[str, int], dict[str, Any] | None], Awaitable[None]] | None = None,
    preserve_seen_stage: bool = False,
    is_pagination_checkpointing_enabled: bool = False,
    defer_typed_materialization: bool = False,
    retry_of_run_id: str | None = None,
    pagination_root_run_id: str | None = None,
    pagination_resume_required: set[str] | None = None,
    provider_directory_endpoint_scope: str | None = None,
    require_complete_resources: bool = False,
) -> dict[str, int]:
    """Import resources into the provider-directory snapshot."""
    if defer_typed_materialization:
        if not is_pagination_checkpointing_enabled:
            raise ValueError(
                "provider_directory_deferred_typed_materialization_checkpoint_required"
            )
        if stale_cleanup or linked_resource_limit > 0:
            raise ValueError(
                "provider_directory_deferred_typed_materialization_incompatible_mode"
            )
        if any(
            _uses_alohr_graphql_connector(source_record)
            or _uses_uhc_official_file_connector(source_record)
            or _should_use_uhc_plan_graph(
                source_record,
                resources,
                per_resource_limit=per_resource_limit,
                page_limit=page_limit,
            )
            for source_record in source_records
        ):
            raise ValueError(
                "provider_directory_deferred_typed_materialization_source_unsupported"
            )
    count_by_resource: dict[str, int] = {resource: 0 for resource in resources}
    semaphore = asyncio.Semaphore(max(1, source_concurrency))
    resource_import_cancellation = _ResourceImportCancellation(
        cancel_ctx,
        cancel_task,
    )
    _validate_provider_directory_endpoint_scope(
        source_records,
        provider_directory_endpoint_scope,
    )
    source_groups = _group_resource_import_sources(source_records, linked_resource_limit=linked_resource_limit)
    total_groups = len(source_groups)
    completed_groups = 0
    report_every = max(1, total_groups // 20)
    progress_lock = asyncio.Lock()
    active_partial_count_by_group: dict[int, dict[str, int]] = {}
    active_group_by_key: dict[int, dict[str, Any]] = {}
    progress_high_water_by_resource: dict[str, int] = {}
    progress_timer_by_name = {"next_partial_progress_at": 0.0}

    def merge_counts(target: dict[str, int], source_counts: dict[str, int]) -> None:
        """Merge resource counters into the aggregate import totals."""
        for key, value in source_counts.items():
            target[key] = target.get(key, 0) + value

    def merge_resource_stats(target: dict[str, dict[str, Any]], source_stats: dict[str, dict[str, Any]]) -> None:
        """Merge per-resource statistics into the group summary."""
        for resource_type, entry in source_stats.items():
            target_entry = target.setdefault(resource_type, _empty_resource_stats())
            for key, value in entry.items():
                target_entry[key] = target_entry.get(key, 0) + value

    def merge_retry_not_before(
        target_by_resource: dict[str, str],
        diagnostics_by_resource: dict[str, dict[str, Any]],
    ) -> None:
        """Keep the latest upstream retry boundary for each resource."""
        for resource_type, diagnostic_dict in diagnostics_by_resource.items():
            retry_at = _clean_text(diagnostic_dict.get("retry_not_before"))
            if not retry_at:
                continue
            current_retry_at = target_by_resource.get(resource_type)
            if current_retry_at is None or retry_at > current_retry_at:
                target_by_resource[resource_type] = retry_at

    def progress_counts_snapshot() -> dict[str, int]:
        """Return monotonic activity counts across partial-to-complete handoffs."""
        return _provider_directory_progress_counts_snapshot(
            count_by_resource,
            active_partial_count_by_group,
            progress_high_water_by_resource,
        )

    def active_group_snapshot() -> list[dict[str, Any]]:
        """Return a stable snapshot of active provider-directory groups."""
        now = time.monotonic()
        groups: list[dict[str, Any]] = []
        for detail in active_group_by_key.values():
            group_detail_by_field = {
                key: value
                for key, value in detail.items()
                if key not in {"started_monotonic", "resource_started_monotonic"}
            }
            group_detail_by_field["elapsed_seconds"] = int(now - detail["started_monotonic"])
            if detail.get("resource_started_monotonic") is not None:
                group_detail_by_field["resource_elapsed_seconds"] = int(now - detail["resource_started_monotonic"])
            groups.append(group_detail_by_field)
        return sorted(
            groups,
            key=lambda group_detail: (
                str(group_detail.get("sample_org_name") or ""),
                str(group_detail.get("sample_plan_name") or ""),
                str(group_detail.get("sample_source_id") or ""),
            ),
        )

    async def report_progress(force: bool = False) -> None:
        """Publish current provider-directory import progress."""
        if not progress_callback:
            return
        progress_count_by_resource: dict[str, int] | None = None
        progress_detail_by_field: dict[str, Any] | None = None
        async with progress_lock:
            now = time.monotonic()
            if force or now >= progress_timer_by_name["next_partial_progress_at"]:
                if not force:
                    progress_timer_by_name["next_partial_progress_at"] = now + 15.0
                progress_count_by_resource = progress_counts_snapshot()
                progress_detail_by_field = {"active_source_groups": active_group_snapshot()}
        if progress_count_by_resource is not None:
            try:
                await progress_callback(
                    completed_groups,
                    total_groups,
                    progress_count_by_resource,
                    progress_detail_by_field,
                )
            except (asyncio.CancelledError, ImportCancelledError):
                raise
            except Exception as failure:
                raise ResourceImportProgressFailure(
                    "provider_directory_progress_callback_failed"
                ) from failure

    async def maybe_report_partial_progress(
        group_key: int,
        resource_type: str,
        written: int,
    ) -> None:
        """Report partial progress when the configured interval elapses."""
        if not progress_callback or written <= 0:
            return
        async with progress_lock:
            group_counts = active_partial_count_by_group.setdefault(group_key, {})
            group_counts[resource_type] = group_counts.get(resource_type, 0) + written
        await report_progress()

    async def clear_partial_progress(group_key: int) -> None:
        """Clear persisted partial progress for the active source group."""
        async with progress_lock:
            active_partial_count_by_group.pop(group_key, None)
            active_group_by_key.pop(group_key, None)

    async def import_one_group(
        source_group: list[dict[str, Any]],
        resume_required_entries: set[str] | None,
    ) -> ResourceImportGroupResult:
        """Import, validate, and finalize one provider-directory source group."""
        await _raise_if_resource_import_cancelled(cancel_ctx, cancel_task)
        group_key = id(source_group)
        source_ids = sorted(source_record["source_id"] for source_record in source_group)
        _validate_provider_directory_endpoint_scope(
            source_group,
            provider_directory_endpoint_scope,
        )
        partition_source = _scoped_partition_source_record(source_group, source_ids)
        async with progress_lock:
            active_group_by_key[group_key] = {
                "source_ids": source_ids[:10],
                "source_count": len(source_ids),
                "sample_source_id": partition_source.get("source_id"),
                "sample_org_name": partition_source.get("org_name"),
                "sample_plan_name": partition_source.get("plan_name"),
                "api_base": partition_source.get("canonical_api_base") or partition_source.get("api_base"),
                "current_resource": None,
                "current_resources": [],
                "started_at": _now().isoformat(timespec="seconds") + "Z",
                "started_monotonic": time.monotonic(),
                "resource_started_at": None,
                "resource_started_monotonic": None,
            }
        await report_progress(force=True)
        source_count_by_resource: dict[str, int] = {resource: 0 for resource in resources}
        linked_count_by_resource: dict[str, int] = {}
        resource_stats_by_type: dict[str, dict[str, Any]] = {}
        resource_diagnostic_by_type: dict[str, dict[str, Any]] = {}
        stale_count_by_resource: dict[str, int] = {}
        stale_ready_source_ids_by_resource: dict[str, list[str]] = {}
        rows_by_resource: dict[str, list[dict[str, Any]]] = {}
        deferred_zero_role_cleanup: ResourceFetchResult | None = None
        is_scan_role_reverse_lookup_planned = (
            _is_practitioner_role_reverse_lookup_planned(partition_source, resources)
        )

        async def mark_resource_stale_cleanup_ready(resource_type: str, result: ResourceFetchResult) -> None:
            """Mark one resource type ready for stale-row cleanup."""
            if not stale_cleanup or not _is_resource_fetch_complete_for_publish(result):
                return
            if seen_stage_table:
                stale_ready_source_ids_by_resource[resource_type] = [partition_source["source_id"]]
                return
            stale_deleted = await _delete_stale_resource_rows(
                result.model,
                partition_source["source_id"],
                run_id,
                use_seen_table=True,
            )
            if stale_deleted:
                stale_count_by_resource[resource_type] = (
                    stale_count_by_resource.get(resource_type, 0) + stale_deleted
                )

        def should_retry_zero_practitioner_role(result: ResourceFetchResult | None) -> bool:
            """Return whether a zero-role result should be retried."""
            return (
                result is not None
                and not is_scan_role_reverse_lookup_planned
                and bool(_resource_start_url(partition_source, "PractitionerRole", page_count=page_count))
                and result.complete
                and not result.error
                and not result.is_bounded
                and result.rows_fetched == 0
                and result.rows_written == 0
                and source_count_by_resource.get("Practitioner", 0) > 0
                and source_count_by_resource.get("Location", 0) > 0
            )

        async def persist_resource_rows(
            model: type,
            resource_rows: list[dict[str, Any]],
        ) -> int:
            """Write one generic-source batch in the selected materialization mode."""

            compatibility_rows = _rows_for_compatibility_source(
                resource_rows,
                partition_source["source_id"],
            )
            dataset_scope = _endpoint_dataset_write_scope(
                partition_source
            )
            if defer_typed_materialization:
                return await _upsert_deferred_resource_rows(
                    model,
                    compatibility_rows,
                    dataset_id=(
                        dataset_scope.dataset_id if dataset_scope else None
                    ),
                    track_seen=stale_cleanup,
                    resource_hash_contract=(
                        dataset_scope.resource_hash_contract
                        if dataset_scope
                        else None
                    ),
                    semantic_projection_as_of=(
                        dataset_scope.semantic_projection_as_of
                        if dataset_scope
                        else None
                    ),
                )
            return await _upsert_resource_rows(
                model,
                compatibility_rows,
                options=ProviderDirectoryResourceWriteOptions(
                    run_id=run_id,
                    track_seen=stale_cleanup,
                    seen_table=seen_stage_table,
                    canonical_api_base=(
                        partition_source.get("canonical_api_base")
                        or partition_source.get("api_base")
                    ),
                    source_ids=[partition_source["source_id"]],
                    dataset_scope=dataset_scope,
                ),
            )

        if _uses_alohr_graphql_connector(partition_source):
            async with progress_lock:
                active_group_by_key[group_key]["current_resource"] = "ALOHR GraphQL"
                active_group_by_key[group_key]["resource_started_at"] = _now().isoformat(timespec="seconds") + "Z"
                active_group_by_key[group_key]["resource_started_monotonic"] = time.monotonic()
            await report_progress(force=True)
            return await _import_alohr_graphql_source_group(
                source_group,
                resources,
                AlohrGraphQLImportOptions(
                    per_resource_limit=per_resource_limit,
                    page_limit=page_limit,
                    timeout=timeout,
                    run_id=run_id,
                    stale_cleanup=stale_cleanup,
                    seen_table=seen_stage_table,
                    checkpoint_context=partition_source.get("_pagination_checkpoint_context"),
                    resume_required_entries=resume_required_entries,
                    dataset_id=partition_source.get("_endpoint_dataset_id"),
                    resource_hash_contract=partition_source.get(
                        "_resource_hash_contract"
                    ),
                    semantic_projection_as_of=partition_source.get(
                        "_semantic_projection_as_of"
                    ),
                ),
            )
        if _uses_uhc_official_file_connector(partition_source):
            async with progress_lock:
                active_group_by_key[group_key]["current_resource"] = (
                    "Official provider files"
                )
                active_group_by_key[group_key]["resource_started_at"] = (
                    _now().isoformat(timespec="seconds") + "Z"
                )
                active_group_by_key[group_key]["resource_started_monotonic"] = (
                    time.monotonic()
                )
            await report_progress(force=True)
            import_summary = await _import_uhc_official_file_source_group(
                source_group,
                resources,
                ctx=cancel_ctx or {"context": {}},
                task=cancel_task or {"run_id": run_id},
                run_id=run_id,
            )
            _record_uhc_plan_graph_completion(
                resource_completion,
                import_summary[0],
                import_summary[1],
            )
            return import_summary
        if _should_use_uhc_plan_graph(
            partition_source,
            resources,
            per_resource_limit=per_resource_limit,
            page_limit=page_limit,
        ):
            async with progress_lock:
                active_group_by_key[group_key]["current_resource"] = "InsurancePlan graph"
                active_group_by_key[group_key]["resource_started_at"] = (
                    _now().isoformat(timespec="seconds") + "Z"
                )
                active_group_by_key[group_key]["resource_started_monotonic"] = time.monotonic()
            await report_progress(force=True)
            import_summary = await _import_uhc_plan_graph_source_group(
                partition_source,
                resources,
                page_count=page_count,
                timeout=timeout,
                run_id=run_id,
                deadline_seconds=resource_deadline_seconds,
                stale_cleanup=stale_cleanup,
                seen_table=seen_stage_table,
            )
            await _finalize_source_pagination_checkpoints(
                partition_source,
                import_summary[1],
                resume_required_entries,
                require_complete_resources=require_complete_resources,
                retain_complete_checkpoint=bool(
                    partition_source.get("_endpoint_dataset_id")
                ),
            )
            _record_uhc_plan_graph_completion(
                resource_completion,
                import_summary[0],
                import_summary[1],
            )
            return import_summary
        use_streaming = stream_batch_size > 0
        deferred_zero_role_cleanup = await ResourceGroupScanRunner(
            source_record=partition_source,
            source_ids=source_ids,
            group_key=group_key,
            options=ResourceGroupScanOptions(
                per_resource_limit=per_resource_limit,
                page_limit=page_limit,
                page_count=page_count,
                timeout=timeout,
                run_id=run_id,
                stream_batch_size=stream_batch_size,
                cancel_ctx=cancel_ctx,
                cancel_task=cancel_task,
                bulk_export=bulk_export,
                bulk_export_max_pending_seconds=(
                    bulk_export_max_pending_seconds
                ),
                resource_deadline_seconds=resource_deadline_seconds,
                linked_resource_limit=linked_resource_limit,
                stale_cleanup=stale_cleanup,
                seen_stage_table=seen_stage_table,
                scan_role_reverse_lookup_planned=(
                    is_scan_role_reverse_lookup_planned
                ),
                source_concurrency=source_concurrency,
                requested_resource_concurrency=resource_scan_concurrency,
                checkpointing_enabled=is_pagination_checkpointing_enabled,
                deferred_materialization=defer_typed_materialization,
            ),
            progress_lock=progress_lock,
            active_group_by_key=active_group_by_key,
            report_progress=report_progress,
            persist_rows=persist_resource_rows,
            partial_progress=maybe_report_partial_progress,
            mark_stale_ready=mark_resource_stale_cleanup_ready,
            count_by_resource=source_count_by_resource,
            stats_by_resource=resource_stats_by_type,
            resource_completion=resource_completion,
            rows_by_resource=rows_by_resource,
            diagnostic_by_resource=resource_diagnostic_by_type,
        ).scan(resources)
        if should_retry_zero_practitioner_role(deferred_zero_role_cleanup):
            async with progress_lock:
                active_group_by_key[group_key]["current_resource"] = "PractitionerRole retry"
                active_group_by_key[group_key]["resource_started_at"] = _now().isoformat(timespec="seconds") + "Z"
                active_group_by_key[group_key]["resource_started_monotonic"] = time.monotonic()
            await report_progress(force=True)

            use_streaming = stream_batch_size > 0

            async def retry_row_batch_handler(model: type, rows: list[dict[str, Any]]) -> int:
                """Persist a retry batch for the active source group."""
                written = await persist_resource_rows(model, rows)
                await maybe_report_partial_progress(group_key, "PractitionerRole", written)
                return written

            retry_result = await _fetch_resource_rows(
                partition_source,
                "PractitionerRole",
                per_resource_limit=per_resource_limit,
                page_limit=page_limit,
                page_count=page_count,
                timeout=timeout,
                run_id=run_id,
                row_batch_handler=retry_row_batch_handler if use_streaming else None,
                row_batch_size=stream_batch_size,
                retain_rows=linked_resource_limit > 0 or not use_streaming,
                cancel_ctx=cancel_ctx,
                cancel_task=cancel_task,
                bulk_export=False,
                deadline_seconds=resource_deadline_seconds,
            )
            if retry_result is None:
                retry_result = replace(
                    deferred_zero_role_cleanup,
                    complete=False,
                    error=PRACTITIONER_ROLE_ZERO_RETRY_EMPTY_ERROR,
                    fetch_mode=f"{deferred_zero_role_cleanup.fetch_mode}_retry",
                )
                retry_written_total = 0
            else:
                retry_result = replace(retry_result, fetch_mode=f"{retry_result.fetch_mode}_retry")
                _record_resource_fetch_stats(
                    resource_stats_by_type,
                    "PractitionerRole",
                    retry_result,
                )
                _record_resource_completion(
                    resource_completion,
                    "PractitionerRole",
                    source_ids,
                    retry_result,
                )
                if retry_result.rows or "PractitionerRole" not in rows_by_resource:
                    rows_by_resource["PractitionerRole"] = retry_result.rows
                retry_written_total = (
                    retry_result.rows_written
                    if use_streaming
                    else await persist_resource_rows(
                        retry_result.model,
                        retry_result.rows,
                    )
                )
                source_count_by_resource["PractitionerRole"] = source_count_by_resource.get("PractitionerRole", 0) + retry_written_total
                if (
                    retry_result.complete
                    and not retry_result.error
                    and not retry_result.is_bounded
                    and retry_result.rows_fetched == 0
                    and retry_written_total == 0
                ):
                    retry_result = replace(
                        retry_result,
                        complete=False,
                        error=PRACTITIONER_ROLE_ZERO_RETRY_EMPTY_ERROR,
                    )
            retry_diagnostic = _resource_fetch_diagnostic(
                retry_result,
                rows_written=retry_written_total,
            )
            retry_diagnostic["retry_of_zero_rows"] = True
            retry_diagnostic["retry_reason"] = PRACTITIONER_ROLE_ZERO_RETRY_REASON
            resource_diagnostic_by_type["PractitionerRole"] = retry_diagnostic
            if retry_result.error != PRACTITIONER_ROLE_ZERO_RETRY_EMPTY_ERROR:
                await mark_resource_stale_cleanup_ready("PractitionerRole", retry_result)
        elif deferred_zero_role_cleanup is not None:
            await mark_resource_stale_cleanup_ready("PractitionerRole", deferred_zero_role_cleanup)
        if (
            "PractitionerRole" in resources
            and _needs_practitioner_role_reverse_lookup(partition_source, "PractitionerRole")
            and "PractitionerRole" not in resource_diagnostic_by_type
        ):
            async with progress_lock:
                active_group_by_key[group_key]["current_resource"] = "PractitionerRole reverse lookup"
                active_group_by_key[group_key]["resource_started_at"] = _now().isoformat(timespec="seconds") + "Z"
                active_group_by_key[group_key]["resource_started_monotonic"] = time.monotonic()
            await report_progress(force=True)
            use_streaming = stream_batch_size > 0
            scan_seed_stage_table = (
                seen_stage_table
                if use_streaming
                and seen_stage_table
                and is_scan_role_reverse_lookup_planned
                else None
            )
            if scan_seed_stage_table:
                await _prepare_import_seen_stage_lookup(scan_seed_stage_table)
                for seed_resource_type in _practitioner_role_reverse_lookup_resources(partition_source):
                    rows_by_resource.pop(seed_resource_type, None)

            async def scan_role_row_batch_handler(model: type, rows: list[dict[str, Any]]) -> int:
                """Write streamed SCAN PractitionerRole rows for the compatibility owner."""
                written = await persist_resource_rows(model, rows)
                await maybe_report_partial_progress(group_key, "PractitionerRole", written)
                return written

            fetch_result = await _fetch_scan_practitioner_role_rows(
                partition_source,
                rows_by_resource,
                ScanPractitionerRoleFetchOptions(
                    per_resource_limit=per_resource_limit,
                    page_limit=page_limit,
                    page_count=page_count,
                    timeout=timeout,
                    run_id=run_id,
                    row_batch_handler=scan_role_row_batch_handler if use_streaming else None,
                    row_batch_size=stream_batch_size,
                    retain_rows=not use_streaming,
                    cancel_ctx=cancel_ctx,
                    cancel_task=cancel_task,
                    deadline_seconds=linked_resource_deadline_seconds,
                    source=partition_source,
                    seed_stage_table=scan_seed_stage_table,
                    seed_source_ids=(
                        (partition_source["source_id"],)
                        if scan_seed_stage_table
                        else ()
                    ),
                    existing_seed_source_ids=(
                        (partition_source["source_id"],)
                        if not scan_seed_stage_table
                        else ()
                    ),
                    resume_completed_seeds=per_resource_limit <= 0 and page_limit <= 0,
                    seen_table=seen_stage_table,
                ),
            )
            _record_resource_fetch_stats(
                resource_stats_by_type,
                "PractitionerRole",
                fetch_result,
            )
            _record_resource_completion(resource_completion, "PractitionerRole", source_ids, fetch_result)
            written_total = (
                fetch_result.rows_written
                if use_streaming
                else await persist_resource_rows(
                    fetch_result.model,
                    fetch_result.rows,
                )
            )
            source_count_by_resource["PractitionerRole"] = source_count_by_resource.get("PractitionerRole", 0) + written_total
            rows_by_resource["PractitionerRole"] = fetch_result.rows
            resource_diagnostic_by_type["PractitionerRole"] = _resource_fetch_diagnostic(
                fetch_result,
                rows_written=written_total,
            )
            await mark_resource_stale_cleanup_ready("PractitionerRole", fetch_result)
        if linked_resource_limit > 0 and rows_by_resource:
            async with progress_lock:
                active_group_by_key[group_key]["current_resource"] = "Linked resources"
                active_group_by_key[group_key]["resource_started_at"] = _now().isoformat(timespec="seconds") + "Z"
                active_group_by_key[group_key]["resource_started_monotonic"] = time.monotonic()
            await report_progress(force=True)

            async def linked_progress(resource_type: str, written: int) -> None:
                """Report linked-resource progress for the active source group."""
                await maybe_report_partial_progress(group_key, resource_type, written)

            linked_count_by_resource = await _import_linked_resource_rows(
                partition_source,
                rows_by_resource,
                per_source_limit=linked_resource_limit,
                concurrency=linked_resource_concurrency,
                timeout=timeout,
                run_id=run_id,
                source_ids=[partition_source["source_id"]],
                track_seen=stale_cleanup,
                seen_table=seen_stage_table,
                progress_callback=linked_progress,
                deadline_seconds=linked_resource_deadline_seconds,
                dataset_id=partition_source.get("_endpoint_dataset_id"),
            )
        await _finalize_source_pagination_checkpoints(
            partition_source,
            resource_diagnostic_by_type,
            resume_required_entries,
            require_complete_resources=require_complete_resources,
            retain_complete_checkpoint=bool(
                partition_source.get("_endpoint_dataset_id")
            ),
        )
        return (
            source_ids,
            resource_diagnostic_by_type,
            source_count_by_resource,
            linked_count_by_resource,
            resource_stats_by_type,
            stale_count_by_resource,
            stale_ready_source_ids_by_resource,
        )

    seen_stage_table = (
        await _ensure_import_seen_stage_table(run_id)
        if stale_cleanup and run_id and _is_seen_stage_enabled()
        else None
    )
    stale_ready_source_ids_by_resource: dict[str, set[str]] = {}

    async def replay_finalized_candidate(
        candidate: EndpointDatasetCandidate,
        prepared_source_records: list[dict[str, Any]],
    ) -> ResourceImportGroupResult:
        """Replay one immutable candidate after the cancellation fence."""

        return await _replay_finalized_candidate_after_cancellation(
            candidate,
            resource_completion,
            prepared_source_records,
            resource_import_cancellation,
        )

    async def run_guarded_group(
        source_records: list[dict[str, Any]],
        prepared_source_lists: list[list[dict[str, Any]]],
        guard_lease: _PaginationCheckpointGuardLease | None,
    ) -> ResourceImportGroupResult:
        """Prepare, validate, and finalize one checkpoint-owned source group."""
        group_resume_required = set() if pagination_resume_required is not None else None
        if _is_validated_uhc_official_source_group(source_records):
            return await import_one_group(source_records, group_resume_required)
        prepared_source_records, candidate = (
            await _prepare_resource_import_source_group(
                source_records,
                resources,
                run_id=run_id,
                retry_of_run_id=retry_of_run_id,
                pagination_root_run_id=pagination_root_run_id,
                is_checkpointing_enabled=is_pagination_checkpointing_enabled,
            )
        )
        prepared_source_lists[0] = prepared_source_records
        if _is_finalized_endpoint_dataset_candidate(candidate):
            assert candidate is not None
            return await replay_finalized_candidate(
                candidate, prepared_source_records
            )
        diagnostics_by_resource: dict[str, dict[str, Any]] = {}
        try:
            import_summary = await import_one_group(
                prepared_source_records,
                group_resume_required,
            )
            diagnostics_by_resource = import_summary[1]
            if group_resume_required:
                await resource_import_cancellation.check()
                assert pagination_resume_required is not None
                pagination_resume_required.update(group_resume_required)
                return import_summary
            await _validate_and_finalize_import_candidate(
                candidate,
                prepared_source_records,
                diagnostics_by_resource,
                resource_import_cancellation,
            )
            return import_summary
        except ProviderDirectoryPaginationTerminalFailure as failure:
            await _retain_and_abandon_terminal_failure(
                candidate,
                prepared_source_records,
                run_id,
                failure,
                guard_lease,
            )
            raise
        except BaseException as failure:
            await _mark_failed_endpoint_dataset_without_masking(
                candidate,
                diagnostics_by_resource,
                failure,
            )
            raise

    async def run_with_limit(source_records: list[dict[str, Any]]) -> ResourceImportGroupResult:
        """Run one import coroutine under the shared concurrency limit."""
        async with semaphore:
            prepared_source_lists = [source_records]
            async with _provider_directory_import_progress_scope(
                lambda: (completed_groups / max(total_groups, 1)) * 100,
                lambda: clear_partial_progress(id(prepared_source_lists[0])),
            ):
                checkpoint_guard_context = (
                    _resource_group_pagination_checkpoint_context(
                        source_records,
                        run_id=run_id,
                        retry_of_run_id=retry_of_run_id,
                        pagination_root_run_id=pagination_root_run_id,
                        is_checkpointing_enabled=is_pagination_checkpointing_enabled,
                    )
                )
                async with _pagination_checkpoint_worker_guard(
                    checkpoint_guard_context
                ) as guard_lease:
                    return await run_guarded_group(
                        source_records,
                        prepared_source_lists,
                        guard_lease,
                    )

    async def run_isolated_group(
        source_records: list[dict[str, Any]],
    ) -> ResourceImportGroupResult | ResourceImportGroupFailure:
        """Settle ordinary source failures while preserving batch-fatal signals."""
        try:
            for source_record in source_records:
                _assert_resource_acquisition_allowed(source_record, resources)
            return await run_with_limit(source_records)
        except ProviderDirectoryPaginationTerminalFailure as failure:
            if total_groups == 1:
                raise
            return _resource_import_group_failure(source_records, failure)
        except (
            asyncio.CancelledError,
            ImportCancelledError,
            ResourceImportControlPlaneFailure,
            ResourceImportProgressFailure,
            asyncpg.PostgresError,
            asyncpg.InterfaceError,
            SQLAlchemyError,
        ):
            raise
        except Exception as failure:
            if total_groups == 1:
                raise
            return _resource_import_group_failure(source_records, failure)

    tasks: list[asyncio.Task] = []
    failed_source_ids: set[str] = set()
    try:
        tasks = [
            asyncio.create_task(run_isolated_group(source_group))
            for source_group in source_groups
        ]
        for task in asyncio.as_completed(tasks):
            group_result = await task
            if isinstance(group_result, ResourceImportGroupFailure):
                failed_source_ids.update(group_result.source_ids)
                completed_groups += 1
                if progress_callback is not None and (
                    completed_groups == total_groups
                    or completed_groups % report_every == 0
                ):
                    await report_progress(force=True)
                continue
            (
                source_ids,
                source_resource_diagnostics,
                source_counts,
                source_linked_counts,
                source_resource_stats,
                source_stale_counts,
                source_stale_ready_source_ids,
            ) = group_result
            await _update_source_resource_import_metadata(
                source_ids,
                run_id=run_id,
                diagnostics=source_resource_diagnostics,
            )
            merge_counts(count_by_resource, source_counts)
            if linked_counts is not None:
                merge_counts(linked_counts, source_linked_counts)
            if resource_fetch_stats is not None:
                merge_resource_stats(resource_fetch_stats, source_resource_stats)
            if resource_retry_not_before is not None:
                merge_retry_not_before(
                    resource_retry_not_before,
                    source_resource_diagnostics,
                )
            if stale_counts is not None:
                merge_counts(stale_counts, source_stale_counts)
            for resource_type, ready_source_ids in source_stale_ready_source_ids.items():
                stale_ready_source_ids_by_resource.setdefault(resource_type, set()).update(ready_source_ids)
            completed_groups += 1
            if progress_callback is not None and (
                completed_groups == total_groups or completed_groups % report_every == 0
            ):
                await report_progress(force=True)

        if seen_stage_table and stale_ready_source_ids_by_resource:
            await _prepare_import_seen_stage_lookup(seen_stage_table)
            for resource_type, ready_source_ids in stale_ready_source_ids_by_resource.items():
                model = RESOURCE_MODELS_BY_TYPE.get(resource_type)
                if model is None:
                    continue
                for source_id in sorted(ready_source_ids):
                    stale_deleted = await _delete_stale_resource_rows(
                        model,
                        source_id,
                        run_id,
                        seen_table=seen_stage_table,
                    )
                    if stale_deleted and stale_counts is not None:
                        stale_counts[resource_type] = stale_counts.get(resource_type, 0) + stale_deleted
        if failed_source_ids:
            raise RuntimeError(
                "provider_directory_source_groups_failed:"
                + ",".join(sorted(failed_source_ids))
            )
        return count_by_resource
    except BaseException:
        for task in tasks:
            task.cancel()
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)
        raise
    finally:
        if seen_stage_table and not preserve_seen_stage:
            await _drop_import_seen_stage_table(seen_stage_table)


async def _import_resources_with_source_http_session(
    source_records: list[dict[str, Any]],
    **import_options: Any,
) -> dict[str, int]:
    """Run one resource import inside its optional anonymous HTTP session."""
    force_session = any(
        current_version_census_contract(source_record) is not None
        for source_record in source_records
    )
    async with _source_http_session_scope(
        force=force_session,
        require_verified_tls=force_session,
    ):
        return await _import_resources(source_records, **import_options)


def _dataset_rehydrate_resource_types(raw: Any) -> tuple[str, ...]:
    if raw in (None, "", (), []):
        return ()
    values = raw.split(",") if isinstance(raw, str) else raw
    if isinstance(values, (bytes, bytearray, dict)) or not hasattr(values, "__iter__"):
        raise ValueError("provider_directory_dataset_rehydrate_resources_invalid")
    resource_types = tuple(_clean_text(value) for value in values)
    if not all(resource_types) or len(resource_types) != len(set(resource_types)):
        raise ValueError("provider_directory_dataset_rehydrate_resources_invalid")
    return resource_types


async def _run_provider_directory_dataset_rehydrate(
    ctx: dict[str, Any], task: dict[str, Any], run_id: str | None, source_ids: list[str]
) -> dict[str, Any]:
    """Run the retained-dataset path without source discovery or network access."""
    request = _dataset_rehydration_request(task, run_id, source_ids)
    runtime = _dataset_rehydration_runtime(ctx, task, request)
    metrics = await rehydrate_current_dataset(runtime, request)
    ctx["context"]["audit"] = metrics
    ctx["context"]["run"] = ctx["context"].get("run", 0) + 1
    print(
        "PROVIDER_DIRECTORY_DATASET_REHYDRATE_DONE\t"
        + json.dumps(metrics, sort_keys=True, default=str)
    )
    return metrics


def _dataset_rehydration_request(
    task: dict[str, Any],
    run_id: str | None,
    source_ids: list[str],
) -> RehydrationRequest:
    """Validate task exclusivity and build an exact dataset request."""
    if len(source_ids) != 1:
        raise ValueError("provider_directory_dataset_rehydrate_requires_exactly_one_source_id")
    if not run_id:
        raise ValueError("provider_directory_dataset_rehydrate_run_id_required")
    dataset_id = _clean_text(task.get("rehydrate_dataset_id"))
    root_run_id = _clean_text(task.get("rehydrate_acquisition_root_run_id"))
    if not dataset_id or not root_run_id:
        raise ValueError("provider_directory_dataset_rehydrate_dataset_and_root_required")
    incompatible_fields = (
        "canonical_backfill_only", "contact_backfill_only", "publish_artifacts_only",
        "publish_artifacts", "publish_after_acquisition", "import_resources",
        "full_refresh", "stale_cleanup", "bulk_export", "seed_only", "refresh_preset",
        "resources", "resource_limit", "page_limit", "stream_batch_size",
    )
    if any(task.get(field_name) for field_name in incompatible_fields):
        raise ValueError("provider_directory_dataset_rehydrate_incompatible_parameters")
    return RehydrationRequest(
        source_id=source_ids[0],
        dataset_id=dataset_id,
        acquisition_root_run_id=root_run_id,
        owner_run_id=run_id,
        resource_types=_dataset_rehydrate_resource_types(
            task.get("rehydrate_resources") or task.get("rehydrate_resource")
        ),
        batch_size=_int_or_default(
            task.get("rehydrate_batch_size"),
            DEFAULT_DATASET_REHYDRATE_BATCH_SIZE,
        ),
    )


def _dataset_rehydration_runtime(
    ctx: dict[str, Any],
    task: dict[str, Any],
    request: RehydrationRequest,
) -> RehydrationRuntime:
    """Bind normal upserts and control lifecycle callbacks to a request."""

    async def upsert(model: type, rows: list[dict[str, Any]], scope: DatasetScope) -> int:
        """Write one retained batch through normal provenance upserts."""
        return await _upsert_resource_rows(
            model,
            rows,
            options=ProviderDirectoryResourceWriteOptions(
                run_id=scope.acquisition_root_run_id,
                track_seen=False,
                canonical_api_base=scope.canonical_api_base,
                source_ids=[scope.source_id],
                resource_hash_contract=scope.resource_hash_contract,
                semantic_projection_as_of=scope.semantic_projection_as_of,
                derive_location_contacts=False,
            ),
        )

    async def cancelled() -> None:
        """Raise when the owning control run is cancelled."""
        await _raise_if_resource_import_cancelled(ctx, task)

    async def report(progress: dict[str, Any]) -> None:
        """Publish bounded row progress without failing the import."""
        try:
            await mark_control_run(
                request.owner_run_id,
                status="running",
                phase_detail=str(progress["phase"]),
                progress=progress,
                metrics={
                    "dataset_rehydrate": {
                        "source_id": request.source_id,
                        "dataset_id": request.dataset_id,
                    }
                },
            )
        except Exception as error:
            LOGGER.warning("Provider Directory rehydration progress update failed: %s", error)

    return RehydrationRuntime(
        database=db,
        schema=_schema(),
        models_by_type=RESOURCE_MODELS_BY_TYPE,
        upsert_batch=upsert,
        cancel_check=cancelled,
        progress_callback=report,
    )


def _uhc_official_file_endpoint_row(
    *,
    observed_at: datetime.datetime,
) -> dict[str, Any]:
    """Build the non-FHIR transport identity for the official file dataset."""

    admitted = _admit_provider_directory_endpoint_components(
        canonical_api_base=UHC_PROVIDER_FILE_CATALOG_BASE,
        credential_descriptor_json={},
        endpoint_signature_json={
            "transport": "official_provider_files",
            "adapter_id": UHC_PROVIDER_FILE_ADAPTER_ID,
            "adapter_contract": UHC_PROVIDER_FILE_ADAPTER_CONTRACT,
            "resource_types": sorted(UHC_SUPPORTED_RESOURCES),
        },
    )
    return {
        "endpoint_id": admitted["endpoint_id"],
        "canonical_api_base": admitted["canonical_api_base"],
        "credential_descriptor_hash": admitted[
            "credential_descriptor_hash"
        ],
        "endpoint_signature_hash": admitted["endpoint_signature_hash"],
        "credential_descriptor_json": admitted[
            "credential_descriptor_json"
        ],
        "endpoint_signature_json": admitted["endpoint_signature_json"],
        "first_seen_at": observed_at,
        "last_seen_at": observed_at,
        "metadata_json": {
            "identity_version": "official-provider-files-v1",
            "transport": "official_provider_files",
            "source_entry_id": UHC_PROVIDER_FILE_ENTRY_ID,
        },
        "created_at": observed_at,
        "updated_at": observed_at,
    }


def _uhc_official_file_source_row(
    endpoint_id: str,
    *,
    observed_at: datetime.datetime,
) -> dict[str, Any]:
    """Build the distinct corporate source row without FHIR URL semantics."""

    return {
        "source_id": UHC_RETAINED_SOURCE_ID,
        "org_name": UHC_PROVIDER_FILE_DISPLAY_NAME,
        "plan_name": None,
        "portal_url": UHC_PROVIDER_FILE_PORTAL_BASE,
        "api_base": UHC_PROVIDER_FILE_CATALOG_BASE,
        "canonical_api_base": UHC_PROVIDER_FILE_CATALOG_BASE,
        "endpoint_id": endpoint_id,
        "requires_registration": False,
        "requires_api_key": False,
        "auth_type": "none",
        "last_validated_status": "valid",
        "compliance_flag": "official_provider_files",
        "data_quality_flag": "retained_semantic_proof",
        "seed_source": UHC_PROVIDER_FILE_ENTRY_ID,
        "seed_source_detail": UHC_PROVIDER_FILE_ADAPTER_CONTRACT,
        "seed_source_url": UHC_PROVIDER_FILE_CATALOG_BASE,
        "metadata_json": {
            "provider_directory_source_kind": "official_provider_files",
            "provider_directory_transport": "official_provider_files",
            "provider_directory_source_entry_id": UHC_PROVIDER_FILE_ENTRY_ID,
            "provider_directory_adapter_id": UHC_PROVIDER_FILE_ADAPTER_ID,
            "provider_directory_adapter_contract": (
                UHC_PROVIDER_FILE_ADAPTER_CONTRACT
            ),
            "provider_directory_catalog_base": UHC_PROVIDER_FILE_CATALOG_BASE,
            "provider_directory_supported_resources": sorted(
                UHC_SUPPORTED_RESOURCES
            ),
            "provider_directory_acquisition_enabled": True,
            "provider_directory_profile_eligible": True,
            "provider_directory_fhir_endpoint": False,
        },
        "created_at": observed_at,
        "updated_at": observed_at,
    }


def _should_add_uhc_official_file_source(
    *,
    requested_source_ids: list[str],
    source_query: str | None,
    test_mode: bool,
    limit: int | None,
) -> bool:
    """Include UHC in normal catalog resolution when its scope matches."""

    return should_select_uhc_official_file_source(
        requested_source_ids=set(requested_source_ids),
        source_query=source_query,
        test_mode=test_mode,
        limit=limit,
    )


def _add_uhc_official_file_source(
    source_rows: list[dict[str, Any]],
    *,
    requested_source_ids: list[str],
    source_query: str | None,
    test_mode: bool,
    limit: int | None,
) -> list[dict[str, Any]]:
    """Add the official-file adapter to the ordinary source catalog."""

    if not _should_add_uhc_official_file_source(
        requested_source_ids=requested_source_ids,
        source_query=source_query,
        test_mode=test_mode,
        limit=limit,
    ):
        return source_rows
    observed_at = _now()
    endpoint = _uhc_official_file_endpoint_row(observed_at=observed_at)
    return _dedupe_source_rows(
        [
            *source_rows,
            _uhc_official_file_source_row(
                str(endpoint["endpoint_id"]),
                observed_at=observed_at,
            ),
        ]
    )


def _uhc_retained_candidate_id(
    endpoint_id: str,
    acquisition_root_run_id: str,
) -> str:
    return _endpoint_dataset_candidate_id(
        endpoint_id,
        tuple(sorted(UHC_SUPPORTED_RESOURCES)),
        acquisition_root_run_id,
    )


def _expected_uhc_publication_identity(
    summary_input: dict[str, Any],
    *,
    dataset_id: str,
    acquisition_root_run_id: str,
) -> dict[str, Any]:
    return uhc_publication_identity(
        summary_input,
        dataset_id=dataset_id,
        acquisition_root_run_id=acquisition_root_run_id,
    )


def _assert_existing_uhc_candidate_identity(
    state: dict[str, Any],
    expected_publication_identity: dict[str, Any],
    summary_input: dict[str, Any],
) -> None:
    metadata = _json_object(state.get("publication_metadata_json"))
    raw_identity = metadata.get(UHC_RETAINED_PUBLICATION_METADATA_KEY)
    raw_summary_input = metadata.get(UHC_RETAINED_SUMMARY_INPUT_METADATA_KEY)
    if raw_identity is None and not int(state.get("resource_count") or 0):
        return
    try:
        persisted_summary_input = validate_uhc_summary_input(raw_summary_input)
    except UhcRetainedDatasetError as error:
        raise RuntimeError(
            "provider_directory_uhc_retained_candidate_lineage_invalid"
        ) from error
    if (
        raw_identity != expected_publication_identity
        or persisted_summary_input != summary_input
    ):
        raise RuntimeError(
            "provider_directory_uhc_retained_candidate_lineage_changed"
        )


async def _uhc_candidate_from_state(
    endpoint_id: str,
    dataset_id: str,
    run_id: str,
    state: Mapping[str, Any],
) -> EndpointDatasetCandidate:
    """Build a candidate value from its current durable state."""
    selected_resources = tuple(sorted(UHC_SUPPORTED_RESOURCES))
    status = _clean_text(state.get("status"))
    is_current = state.get("is_current") is True
    metadata = _json_object(state.get("publication_metadata_json"))
    candidate = EndpointDatasetCandidate(
        endpoint_id=endpoint_id,
        dataset_id=dataset_id,
        acquisition_root_run_id=run_id,
        source_ids=(UHC_RETAINED_SOURCE_ID,),
        selected_resources=selected_resources,
        import_run_id=run_id,
        previous_dataset_id=(
            _clean_text(state.get("previous_dataset_id"))
            if state
            else await _current_endpoint_dataset_id(
                endpoint_id,
                exclude_dataset_id=dataset_id,
            )
        ),
        resource_hash_contract=(
            _dataset_resource_hash_contract(state)
            if state
            else TRANSPORT_NEUTRAL_RESOURCE_HASH_CONTRACT
        ),
        expected_resources=selected_resources,
        reused_from_checkpoint=bool(state),
        already_validated=status == ENDPOINT_DATASET_VALIDATED,
        validated_metadata=(
            metadata if status == ENDPOINT_DATASET_VALIDATED else None
        ),
        already_published=(
            status == ENDPOINT_DATASET_PUBLISHED and is_current
        ),
        published_metadata=(
            metadata
            if status == ENDPOINT_DATASET_PUBLISHED and is_current
            else None
        ),
    )
    _assert_candidate_hash_contract_supported(candidate)
    return candidate


async def _persist_uhc_candidate_identity(
    candidate: EndpointDatasetCandidate,
    expected_publication_identity: Mapping[str, Any],
    summary_input: Mapping[str, Any],
) -> None:
    """Persist the immutable UHC publication and summary identities."""
    metadata_update_count = _coerce_rowcount(
        await db.status(
            f"""
            UPDATE {_qt(_schema(), ProviderDirectoryEndpointDataset.__tablename__)}
               SET publication_metadata_json =
                   COALESCE(publication_metadata_json::jsonb, '{{}}'::jsonb)
                   || jsonb_build_object(
                        CAST(:publication_key AS text),
                        CAST(:publication_identity AS jsonb),
                        CAST(:summary_key AS text),
                        CAST(:summary_input AS jsonb)
                   )
             WHERE dataset_id=:dataset_id
               AND endpoint_id=:endpoint_id
               AND acquisition_root_run_id=:acquisition_root_run_id
               AND status=:acquiring_status
               AND is_current=false;
            """,
            publication_key=UHC_RETAINED_PUBLICATION_METADATA_KEY,
            publication_identity=json.dumps(
                expected_publication_identity,
                sort_keys=True,
            ),
            summary_key=UHC_RETAINED_SUMMARY_INPUT_METADATA_KEY,
            summary_input=json.dumps(summary_input, sort_keys=True),
            dataset_id=candidate.dataset_id,
            endpoint_id=candidate.endpoint_id,
            acquisition_root_run_id=candidate.acquisition_root_run_id,
            acquiring_status=ENDPOINT_DATASET_ACQUIRING,
        )
    )
    if metadata_update_count != 1:
        raise RuntimeError(
            "provider_directory_uhc_candidate_lineage_update_lost"
        )


async def _prepare_uhc_retained_candidate(
    source_record: dict[str, Any],
    *,
    run_id: str,
    summary_input: dict[str, Any],
) -> EndpointDatasetCandidate:
    """Create or resume the source-local UHC canonical dataset candidate."""
    endpoint_id = _clean_text(source_record.get("endpoint_id"))
    if endpoint_id is None:
        raise RuntimeError("provider_directory_uhc_endpoint_id_missing")
    dataset_id = _uhc_retained_candidate_id(endpoint_id, run_id)
    state = await _endpoint_dataset_state(dataset_id)
    expected_publication_identity = _expected_uhc_publication_identity(
        summary_input,
        dataset_id=dataset_id,
        acquisition_root_run_id=run_id,
    )
    if state:
        if (
            _clean_text(state.get("endpoint_id")) != endpoint_id
            or _clean_text(state.get("acquisition_root_run_id")) != run_id
        ):
            raise RuntimeError(
                "provider_directory_uhc_retained_candidate_identity_collision"
            )
        _assert_existing_uhc_candidate_identity(
            state,
            expected_publication_identity,
            summary_input,
        )
    candidate = await _uhc_candidate_from_state(
        endpoint_id,
        dataset_id,
        run_id,
        state,
    )
    if candidate.already_validated or candidate.already_published:
        _assert_finalized_endpoint_dataset_replay(candidate)
        return candidate
    if (
        state.get("is_current") is True
        or _clean_text(state.get("status"))
        in IMMUTABLE_ENDPOINT_DATASET_STATUSES
    ):
        raise RuntimeError(
            "provider_directory_uhc_retained_candidate_finalized_invalid"
        )
    candidate = await _initialize_endpoint_dataset_candidate(candidate, ())
    await _persist_uhc_candidate_identity(
        candidate,
        expected_publication_identity,
        summary_input,
    )
    persisted_state = await _endpoint_dataset_state(dataset_id)
    _assert_existing_uhc_candidate_identity(
        persisted_state,
        expected_publication_identity,
        summary_input,
    )
    return candidate


def _bound_uhc_stage_proof(
    candidate: EndpointDatasetCandidate,
    stage: UhcCanonicalStage,
) -> tuple[str, dict[str, Any], int]:
    acquisition_root_run_id = _clean_text(candidate.acquisition_root_run_id)
    if acquisition_root_run_id is None:
        raise RuntimeError(
            "provider_directory_uhc_acquisition_root_required"
        )
    try:
        bound_content_proof = bind_uhc_canonical_content_proof(
            stage.content_proof,
            dataset_id=candidate.dataset_id,
            endpoint_id=candidate.endpoint_id,
            acquisition_root_run_id=acquisition_root_run_id,
        )
    except UhcCanonicalProofError as error:
        raise RuntimeError(
            "provider_directory_uhc_stage_content_proof_invalid"
        ) from error
    expected_count = sum(stage.resource_counts.values())
    if (
        bound_content_proof["resource_count"] != expected_count
        or bound_content_proof["resource_counts"] != stage.resource_counts
    ):
        raise RuntimeError(
            "provider_directory_uhc_stage_content_proof_changed"
        )
    return acquisition_root_run_id, bound_content_proof, expected_count


async def _bind_uhc_candidate_content_proof(
    executor: Any,
    candidate: EndpointDatasetCandidate,
    acquisition_root_run_id: str,
    bound_content_proof: Mapping[str, Any],
) -> int:
    """Bind canonical content proof to one acquiring UHC candidate."""
    return _coerce_rowcount(
        await executor.status(
            f"""
            UPDATE {_qt(_schema(), ProviderDirectoryEndpointDataset.__tablename__)}
               SET publication_metadata_json =
                   COALESCE(publication_metadata_json::jsonb, '{{}}'::jsonb)
                   || jsonb_build_object(
                        CAST(:proof_key AS text),
                        CAST(:proof_json AS jsonb)
                   )
             WHERE dataset_id=:dataset_id
               AND endpoint_id=:endpoint_id
               AND acquisition_root_run_id IS NOT DISTINCT FROM
                   :acquisition_root_run_id
               AND status=:acquiring_status
               AND is_current=false;
            """,
            proof_key=UHC_CANONICAL_CONTENT_PROOF_METADATA_KEY,
            proof_json=json.dumps(bound_content_proof, sort_keys=True),
            dataset_id=candidate.dataset_id,
            endpoint_id=candidate.endpoint_id,
            acquisition_root_run_id=acquisition_root_run_id,
            acquiring_status=ENDPOINT_DATASET_ACQUIRING,
        )
    )


async def _replace_uhc_candidate_resources(
    candidate: EndpointDatasetCandidate,
    stage: UhcCanonicalStage,
) -> int:
    """Atomically replace one candidate and bind its independent proof."""

    acquisition_root_run_id, bound_content_proof, expected_count = (
        _bound_uhc_stage_proof(candidate, stage)
    )
    async with _mutable_endpoint_dataset_resource_mutation(
        [candidate.dataset_id]
    ) as executor:
        await executor.status(
            f"""
            DELETE FROM {_qt(_schema(), ProviderDirectoryDatasetResource.__tablename__)}
             WHERE dataset_id=:dataset_id;
            """,
            dataset_id=candidate.dataset_id,
        )
        await delete_dataset_proof_shards(
            executor,
            _schema(),
            candidate.dataset_id,
        )
        inserted = _coerce_rowcount(
            await executor.status(
                f"""
                INSERT INTO {_qt(_schema(), ProviderDirectoryDatasetResource.__tablename__)} (
                    dataset_id, resource_type, resource_id,
                    payload_hash, payload_json
                )
                SELECT :dataset_id, resource_type, resource_id,
                       payload_hash, payload_json
                  FROM {stage.resource_ref}
                 ORDER BY resource_type, resource_id;
                """,
                dataset_id=candidate.dataset_id,
            )
        )
        proof_update_count = await _bind_uhc_candidate_content_proof(
            executor,
            candidate,
            acquisition_root_run_id,
            bound_content_proof,
        )
        if inserted != expected_count or proof_update_count != 1:
            raise RuntimeError(
                "provider_directory_uhc_candidate_copy_incomplete"
            )
    return expected_count


def _uhc_resource_diagnostics(
    resource_counts: dict[str, int],
) -> dict[str, dict[str, Any]]:
    return {
        resource_type: {
            "complete": True,
            "rows": resource_counts[resource_type],
            "pages": 0,
            "next_url_remaining": False,
            "retained_semantic_contract_id": (
                SOURCE_SUMMARY_UHC_SEMANTIC_CONTRACT_ID
            ),
        }
        for resource_type in sorted(resource_counts)
    }


async def _assert_uhc_candidate_content(
    candidate: EndpointDatasetCandidate,
    stage: UhcCanonicalStage,
) -> EndpointDatasetContentProof:
    async with db.acquire() as connection:
        proof = await _candidate_endpoint_dataset_content_proof(
            connection,
            candidate,
        )
    if (
        proof.dataset_hash != stage.content_proof.get("dataset_hash")
        or proof.resource_count != stage.content_proof.get("resource_count")
        or proof.resource_counts != stage.resource_counts
        or proof.resource_hashes
        != stage.content_proof.get("resource_hashes")
    ):
        raise RuntimeError(
            "provider_directory_uhc_candidate_content_proof_mismatch"
        )
    return proof


def _validated_uhc_final_metadata(
    candidate: EndpointDatasetCandidate,
    metadata: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    """Validate and return summary input, source summary, and content proof."""
    try:
        summary_input = validate_uhc_summary_input(
            metadata.get(UHC_RETAINED_SUMMARY_INPUT_METADATA_KEY)
        )
        source_summary = validate_semantic_source_summary(
            metadata.get(SOURCE_SUMMARY_METADATA_KEY),
            expected_by_field={
                "dataset_id": candidate.dataset_id,
                "endpoint_id": candidate.endpoint_id,
                "acquisition_root_run_id": candidate.acquisition_root_run_id,
                "source_ids": list(candidate.source_ids),
                "selected_resources": list(candidate.selected_resources),
                "semantic_contract_id": (
                    SOURCE_SUMMARY_UHC_SEMANTIC_CONTRACT_ID
                ),
            },
            expected_semantic_contract_id=(
                SOURCE_SUMMARY_UHC_SEMANTIC_CONTRACT_ID
            ),
        )
        canonical_proof = validate_uhc_canonical_content_proof(
            metadata.get(UHC_CANONICAL_CONTENT_PROOF_METADATA_KEY),
            dataset_id=candidate.dataset_id,
            endpoint_id=candidate.endpoint_id,
            acquisition_root_run_id=(
                candidate.acquisition_root_run_id or ""
            ),
        )
    except ProviderDirectorySourceSummaryError as error:
        raise RuntimeError(
            "provider_directory_uhc_final_source_summary_invalid"
        ) from error
    except UhcCanonicalProofError as error:
        raise RuntimeError(
            "provider_directory_uhc_final_content_proof_invalid"
        ) from error
    except UhcRetainedDatasetError as error:
        raise RuntimeError(
            "provider_directory_uhc_final_summary_input_invalid"
        ) from error
    return summary_input, source_summary, canonical_proof


def _is_uhc_final_publication_consistent(
    state: Mapping[str, Any],
    metadata: Mapping[str, Any],
    outcome: Any,
    source_summary: Mapping[str, Any],
    canonical_proof: Mapping[str, Any],
    expected_publication_identity: Mapping[str, Any],
) -> bool:
    """Return whether all final UHC publication proofs agree."""
    return bool(
        _clean_text(state.get("status")) == ENDPOINT_DATASET_PUBLISHED
        and state.get("is_current") is True
        and isinstance(outcome, dict)
        and outcome.get("complete") is True
        and outcome.get("dataset_hash") == state.get("dataset_hash")
        and outcome.get("resource_counts") == source_summary["resource_counts"]
        and canonical_proof["dataset_hash"] == state.get("dataset_hash")
        and canonical_proof["resource_counts"]
        == source_summary["resource_counts"]
        and canonical_proof["resource_hashes"]
        == source_summary["resource_hashes"]
        and metadata.get(UHC_RETAINED_PUBLICATION_METADATA_KEY)
        == expected_publication_identity
    )


async def _assert_final_uhc_publication(
    candidate: EndpointDatasetCandidate,
) -> dict[str, Any]:
    """Prove the published UHC dataset matches its validated candidate."""
    state = await _endpoint_dataset_state(candidate.dataset_id)
    metadata = _json_object(state.get("publication_metadata_json"))
    summary_input, source_summary, canonical_proof = (
        _validated_uhc_final_metadata(candidate, metadata)
    )
    expected_publication_identity = _expected_uhc_publication_identity(
        summary_input,
        dataset_id=candidate.dataset_id,
        acquisition_root_run_id=candidate.acquisition_root_run_id,
    )
    outcome = metadata.get(
        PROVIDER_DIRECTORY_OUTCOME_RESOURCE_COUNTS_METADATA_KEY
    )
    if not _is_uhc_final_publication_consistent(
        state,
        metadata,
        outcome,
        source_summary,
        canonical_proof,
        expected_publication_identity,
    ):
        raise RuntimeError(
            "provider_directory_uhc_current_publication_proof_invalid"
        )
    return {
        "dataset_id": candidate.dataset_id,
        "dataset_hash": state.get("dataset_hash"),
        "resource_count": int(state.get("resource_count") or 0),
        "resource_counts": outcome["resource_counts"],
        "source_summary": source_summary,
        "status": ENDPOINT_DATASET_PUBLISHED,
        "is_current": True,
    }


async def _publish_validated_uhc_dataset(
    candidate: EndpointDatasetCandidate,
) -> None:
    """Publish one proven UHC dataset without replacing global artifacts."""

    fence = await _resolve_provider_directory_artifact_datasets(
        [UHC_RETAINED_SOURCE_ID],
        should_select_validated_candidates=True,
    )
    if (
        len(fence.datasets) != 1
        or len(fence.promotion_datasets) != 1
        or fence.datasets[0].source_id != UHC_RETAINED_SOURCE_ID
        or fence.datasets[0].dataset_id != candidate.dataset_id
        or fence.datasets[0].endpoint_id != candidate.endpoint_id
        or fence.datasets[0].evidence_run_id
        != candidate.acquisition_root_run_id
    ):
        raise RuntimeError(
            "provider_directory_uhc_source_local_fence_invalid"
        )
    try:
        async with asyncio.timeout(
            _provider_directory_artifact_transaction_timeout_seconds(fence)
        ) as cutover_timeout:
            async with db.transaction():
                await db.status(
                    "SET LOCAL lock_timeout = "
                    f"'{PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_LOCK_TIMEOUT}';"
                )
                await db.status(
                    "SET LOCAL statement_timeout = "
                    f"'{PROVIDER_DIRECTORY_ARTIFACT_CUTOVER_STATEMENT_TIMEOUT}';"
                )
                await _lock_artifact_cutover_fence(fence)
                _tighten_provider_directory_artifact_cutover_timeout(
                    cutover_timeout
                )
                await _promote_provider_directory_artifact_datasets(fence)
    except Exception as promotion_error:
        try:
            is_cutover_committed = (
                await _is_provider_directory_dataset_cutover_committed(fence)
            )
        except Exception:
            LOGGER.warning(
                "Source-local dataset cutover acknowledgement and committed-state "
                "verification both failed",
                exc_info=True,
            )
            is_cutover_committed = False
        if not is_cutover_committed:
            raise
        LOGGER.warning(
            "Source-local dataset cutover acknowledgement was lost after commit "
            "(%s); verified the exact dataset and source pointers",
            type(promotion_error).__name__,
        )


def _uhc_acquisition_progress_callback(
    run_id: str,
    catalog_set_sha256: str,
) -> Callable[[int, int, str, str], Awaitable[None]]:
    """Create the durable per-file progress callback."""
    async def report_file_progress(
        done: int,
        total: int,
        file_name: str,
        disposition: str,
    ) -> None:
        """Persist progress for one admitted or reused official file."""
        await _mark_provider_directory_progress(
            run_id,
            phase="provider-directory official-file acquisition",
            done=done,
            total=total,
            overall_pct=_provider_directory_import_progress_pct(),
            message=(
                f"{disposition} official provider file "
                f"{done}/{total}: {file_name}"
            ),
            details=_provider_directory_progress_details(
                {
                    "catalog_set_sha256": catalog_set_sha256,
                    "file_name": file_name,
                    "disposition": disposition,
                },
                stage_id="provider-directory-import-official-file-acquisition",
                stage_ordinal=PROVIDER_DIRECTORY_PROGRESS_STAGE_IMPORT,
            ),
        )
    return report_file_progress


def _uhc_acquisition_cancel_check(
    ctx: dict[str, Any],
    task: dict[str, Any],
) -> Callable[[], Awaitable[None]]:
    """Create a cancellation callback bound to the import task."""
    async def check_cancelled() -> None:
        """Raise promptly when import control has cancelled this run."""
        await raise_if_cancelled(ctx, task)
    return check_cancelled


async def _select_uhc_catalog_for_acquisition(
    requested_catalog_hash: str | None,
    *,
    is_repair_replay: bool,
) -> dict[str, Any]:
    """Select current catalog state or one exact retained repair pin."""

    if not is_repair_replay:
        return await refresh_uhc_provider_file_catalog()
    try:
        return await uhc_provider_file_catalog(
            catalog_set_sha256=requested_catalog_hash,
        )
    except (UHCFileCatalogError, UHCFileCatalogNotFound) as error:
        raise RuntimeError(
            "provider_directory_uhc_catalog_selection_is_not_retained"
        ) from error


async def _recheck_uhc_catalog_after_acquisition(
    catalog_set_sha256: str,
    acquisition: UHCOfficialFileAcquisitionResult,
    *,
    is_repair_replay: bool,
) -> None:
    """Require an unchanged current or retained catalog after acquisition."""

    if is_repair_replay:
        try:
            final_catalog = await uhc_provider_file_catalog(
                catalog_set_sha256=catalog_set_sha256,
            )
        except (UHCFileCatalogError, UHCFileCatalogNotFound) as error:
            raise RuntimeError(
                "provider_directory_uhc_catalog_changed_during_acquisition"
            ) from error
    else:
        final_catalog = await refresh_uhc_provider_file_catalog()
    if (
        final_catalog.get("catalog_set_sha256") != catalog_set_sha256
        or int(final_catalog.get("catalog_file_count") or 0)
        != acquisition.file_count
    ):
        raise RuntimeError(
            "provider_directory_uhc_catalog_changed_during_acquisition"
        )


async def _acquire_current_uhc_official_file_set(
    ctx: dict[str, Any],
    task: dict[str, Any],
    *,
    run_id: str,
) -> tuple[str, UHCOfficialFileAcquisitionResult]:
    """Acquire one current catalog or an exact retained repair-generation pin."""

    validate_uhc_official_file_admission(task, required=True)
    requested_catalog_hash = _clean_text(
        task.get("uhc_catalog_set_sha256")
    )
    is_repair_replay = is_uhc_official_file_repair_replay(task)
    initial_catalog = await _select_uhc_catalog_for_acquisition(
        requested_catalog_hash,
        is_repair_replay=is_repair_replay,
    )
    catalog_set_sha256 = _clean_text(
        initial_catalog.get("catalog_set_sha256")
    )
    if (
        not catalog_set_sha256
        or requested_catalog_hash != catalog_set_sha256
    ):
        selection_error = (
            "provider_directory_uhc_catalog_selection_is_not_retained"
            if is_repair_replay
            else "provider_directory_uhc_catalog_selection_is_not_current"
        )
        raise RuntimeError(selection_error)

    async with db.acquire_driver() as driver_connection:
        acquisition = await acquire_complete_uhc_catalog_set(
            driver_connection,
            catalog_set_sha256,
            progress_callback=_uhc_acquisition_progress_callback(
                run_id,
                catalog_set_sha256,
            ),
            cancel_check=_uhc_acquisition_cancel_check(ctx, task),
            connection_factory=db.acquire_driver,
        )
        await load_complete_admitted_uhc_catalog_set(
            driver_connection,
            catalog_set_sha256,
        )

    await raise_if_cancelled(ctx, task)
    await _recheck_uhc_catalog_after_acquisition(
        catalog_set_sha256,
        acquisition,
        is_repair_replay=is_repair_replay,
    )
    return catalog_set_sha256, acquisition


async def _build_uhc_publication_stage(
    ctx: dict[str, Any],
    task: dict[str, Any],
    run_id: str,
    catalog_set_sha256: str,
) -> UhcCanonicalStage:
    """Seal semantic files and build the canonical publication stage."""
    await _mark_provider_directory_progress(
        run_id,
        phase="provider-directory UHC retained semantic build",
        details=_provider_directory_progress_details(
            stage_id="provider-directory-import-official-file-build",
            stage_ordinal=PROVIDER_DIRECTORY_PROGRESS_STAGE_IMPORT,
        ),
        done=0,
        total=4,
        overall_pct=_provider_directory_import_progress_pct(),
        message="validating complete admitted UHC provider-file catalog",
    )
    async with db.acquire_driver() as driver_connection:
        admitted_set = await load_complete_admitted_uhc_catalog_set(
            driver_connection,
            catalog_set_sha256,
        )
    await raise_if_cancelled(ctx, task)
    sealed_files = await ensure_sealed_uhc_semantic_set(
        None,
        admitted_set,
        connection_factory=db.acquire_driver,
    )
    await _mark_provider_directory_progress(
        run_id,
        phase="provider-directory UHC retained semantic sealed",
        done=1,
        total=4,
        overall_pct=_provider_directory_import_progress_pct(),
        message=(
            f"sealed {len(sealed_files)}/{len(admitted_set.files)} "
            "admitted UHC files under semantic v3"
        ),
        details=_provider_directory_progress_details(
            {
                "semantic_file_concurrency": (
                    uhc_semantic_file_concurrency()
                ),
            },
            stage_id="provider-directory-import-official-file-build",
            stage_ordinal=PROVIDER_DIRECTORY_PROGRESS_STAGE_IMPORT,
        ),
    )
    await raise_if_cancelled(ctx, task)
    async with db.acquire_driver() as driver_connection:
        return await build_uhc_canonical_stage(
            driver_connection,
            admitted_set,
            sealed_files,
        )


def _uhc_publication_result_details(
    stage: UhcCanonicalStage,
    catalog_set_sha256: str,
    acquisition: UHCOfficialFileAcquisitionResult,
    *,
    replayed: bool,
) -> dict[str, Any]:
    """Build stable result details for a new or replayed publication."""
    return {
        "retained_catalog_set_sha256": catalog_set_sha256,
        "acquisition": {
            "file_count": acquisition.file_count,
            "downloaded_file_count": acquisition.downloaded_file_count,
            "reused_file_count": acquisition.reused_file_count,
            "downloaded_byte_count": acquisition.downloaded_byte_count,
        },
        "semantic_build_ids": list(stage.semantic_build_ids),
        "replayed": replayed,
    }


async def _validate_and_publish_uhc_candidate(
    ctx: dict[str, Any],
    task: dict[str, Any],
    run_id: str,
    candidate: EndpointDatasetCandidate,
    stage: UhcCanonicalStage,
) -> None:
    """Validate a new candidate and publish its immutable source dataset."""
    if not candidate.already_validated:
        copied_rows = await _replace_uhc_candidate_resources(
            candidate,
            stage,
        )
        await _assert_uhc_candidate_content(candidate, stage)
        diagnostics = _uhc_resource_diagnostics(stage.resource_counts)
        finalization = await _finalize_endpoint_dataset_candidate(
            candidate,
            diagnostics,
        )
        if not finalization or finalization.get("validated") is not True:
            raise RuntimeError(
                "provider_directory_uhc_candidate_validation_failed"
            )
    else:
        copied_rows = int(
            candidate.validated_metadata.get("resource_count")
            if isinstance(candidate.validated_metadata, dict)
            else 0
        )
    await _mark_provider_directory_progress(
        run_id,
        phase="provider-directory UHC retained dataset validated",
        details=_provider_directory_progress_details(
            stage_id="provider-directory-import-official-file-build",
            stage_ordinal=PROVIDER_DIRECTORY_PROGRESS_STAGE_IMPORT,
        ),
        done=3,
        total=4,
        overall_pct=_provider_directory_import_progress_pct(),
        message=(
            f"validated {copied_rows} canonical UHC resources; "
            "publishing the source-local immutable dataset"
        ),
    )
    await raise_if_cancelled(ctx, task)
    await _publish_validated_uhc_dataset(candidate)


async def _record_uhc_source_import_complete(
    run_id: str,
    candidate: EndpointDatasetCandidate,
    publication_result: dict[str, Any],
) -> None:
    """Record source-local completion inside the shared import lifecycle."""

    await _mark_provider_directory_progress(
        run_id,
        phase="provider-directory official-file source complete",
        done=4,
        total=4,
        overall_pct=_provider_directory_import_progress_pct(),
        message=(
            f"published current UHC dataset {candidate.dataset_id} "
            f"with {publication_result['resource_count']} resources; "
            "continuing shared Provider Directory completion"
        ),
        details=_provider_directory_progress_details(
            {
                "source_id": UHC_RETAINED_SOURCE_ID,
                "dataset_id": candidate.dataset_id,
            },
            stage_id="provider-directory-import-official-file-build",
            stage_ordinal=PROVIDER_DIRECTORY_PROGRESS_STAGE_IMPORT,
        ),
    )


def _required_uhc_source_import_run_id(
    run_id: str | None,
) -> str:
    """Require the normal import run identity for atomic official files."""

    if not run_id:
        raise ValueError("UHC official-file source import requires run_id")
    return run_id


def _uhc_official_file_resource_stats(
    resource_counts: Mapping[str, int],
    publication_result: Mapping[str, Any],
) -> dict[str, dict[str, Any]]:
    """Represent atomic file publication in common fetch statistics."""

    stats_by_resource: dict[str, dict[str, Any]] = {}
    acquisition = _json_object(publication_result.get("acquisition"))
    performance = _json_object(publication_result.get("performance"))
    for resource_type, row_count in resource_counts.items():
        stats = _empty_resource_stats()
        stats.update(
            {
                "sources_attempted": 1,
                "sources_completed": 1,
                "collection_complete_sources": 1,
                "rows_fetched": int(row_count),
                "official_provider_file_sources": 1,
                "official_catalog_files": int(
                    acquisition.get("file_count") or 0
                ),
                "official_files_downloaded": int(
                    acquisition.get("downloaded_file_count") or 0
                ),
                "official_files_reused": int(
                    acquisition.get("reused_file_count") or 0
                ),
                "official_acquisition_seconds": float(
                    performance.get("acquisition_seconds") or 0
                ),
                "official_semantic_build_seconds": float(
                    performance.get("semantic_build_seconds") or 0
                ),
            }
        )
        stats_by_resource[resource_type] = stats
    return stats_by_resource


def _uhc_import_performance(
    acquisition_seconds: float,
    semantic_build_seconds: float,
) -> dict[str, Any]:
    return {
        "acquisition_seconds": round(acquisition_seconds, 3),
        "semantic_build_seconds": round(semantic_build_seconds, 3),
        "download_concurrency": uhc_provider_file_download_concurrency(),
        "admission_concurrency": uhc_provider_file_admission_concurrency(),
        "semantic_file_concurrency": uhc_semantic_file_concurrency(),
    }


async def _publish_or_replay_uhc_candidate(
    ctx: dict[str, Any],
    task: dict[str, Any],
    run_id: str,
    candidate: EndpointDatasetCandidate,
    stage: UhcCanonicalStage,
) -> dict[str, Any]:
    if not candidate.already_published:
        await _validate_and_publish_uhc_candidate(
            ctx,
            task,
            run_id,
            candidate,
            stage,
        )
    return await _assert_final_uhc_publication(candidate)


def _uhc_source_group_result(
    publication_result: Mapping[str, Any],
) -> ResourceImportGroupResult:
    resource_counts_by_type = dict(publication_result["resource_counts"])
    return (
        [UHC_RETAINED_SOURCE_ID],
        _uhc_resource_diagnostics(resource_counts_by_type),
        resource_counts_by_type,
        {},
        _uhc_official_file_resource_stats(
            resource_counts_by_type,
            publication_result,
        ),
        {},
        {},
    )


def _validated_uhc_import_source(
    source_group: list[dict[str, Any]],
    resources: list[str],
    run_id: str | None,
) -> tuple[str, dict[str, Any]]:
    required_run_id = _required_uhc_source_import_run_id(run_id)
    if (
        len(source_group) != 1
        or not _uses_uhc_official_file_connector(source_group[0])
    ):
        raise ValueError("UHC official-file source group is invalid")
    if not set(resources).intersection(UHC_SUPPORTED_RESOURCES):
        raise ValueError(
            "UHC official-file source import has no supported resources"
        )
    return required_run_id, source_group[0]


async def _acquire_and_build_uhc_stage(
    ctx: dict[str, Any],
    task: dict[str, Any],
    run_id: str,
) -> tuple[
    str,
    UHCOfficialFileAcquisitionResult,
    UhcCanonicalStage,
    float,
    float,
]:
    acquisition_started = time.monotonic()
    catalog_hash, acquisition = await _acquire_current_uhc_official_file_set(
        ctx,
        task,
        run_id=run_id,
    )
    acquisition_seconds = time.monotonic() - acquisition_started
    semantic_started = time.monotonic()
    stage = await _build_uhc_publication_stage(
        ctx,
        task,
        run_id,
        catalog_hash,
    )
    return (
        catalog_hash,
        acquisition,
        stage,
        acquisition_seconds,
        time.monotonic() - semantic_started,
    )


async def _import_uhc_official_file_source_group(
    source_group: list[dict[str, Any]],
    resources: list[str],
    *,
    ctx: dict[str, Any],
    task: dict[str, Any],
    run_id: str | None,
) -> ResourceImportGroupResult:
    """Import official files as one normal Provider Directory source group."""
    required_run_id, source_record = _validated_uhc_import_source(
        source_group,
        resources,
        run_id,
    )
    (
        catalog_set_sha256,
        acquisition,
        stage,
        acquisition_seconds,
        semantic_build_seconds,
    ) = await _acquire_and_build_uhc_stage(
        ctx,
        task,
        required_run_id,
    )
    try:
        candidate = await _prepare_uhc_retained_candidate(
            source_record,
            run_id=run_id,
            summary_input=stage.summary_input,
        )
        publication_result = await _publish_or_replay_uhc_candidate(
            ctx,
            task,
            required_run_id,
            candidate,
            stage,
        )
        publication_result.update(
            _uhc_publication_result_details(
                stage,
                catalog_set_sha256,
                acquisition,
                replayed=candidate.already_published,
            )
        )
        publication_result["performance"] = _uhc_import_performance(
            acquisition_seconds,
            semantic_build_seconds,
        )
        if not candidate.already_published:
            await _record_uhc_source_import_complete(
                required_run_id,
                candidate,
                publication_result,
            )
        return _uhc_source_group_result(publication_result)
    finally:
        async with db.acquire_driver() as cleanup_connection:
            await cleanup_uhc_canonical_stage(cleanup_connection, stage)


async def process_provider_directory_fhir_data(
    ctx: dict[str, Any],
    task: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Run provider-directory discovery, import, and publication."""
    task = _apply_provider_directory_refresh_preset(task or {})
    census_request = current_version_census_request(
        task,
        allowed_resources=DEFAULT_RESOURCES,
    )
    reviewed_census_seed_rows: list[dict[str, Any]] = []
    context = ctx.get("context")
    context_test_mode = bool(
        isinstance(context, dict) and context.get("test_mode")
    )
    validate_uhc_official_file_admission(
        task,
        test_mode=bool(
            task.get("test")
            or task.get("test_mode")
            or context_test_mode
        ),
    )
    ctx.setdefault("context", {})
    test_mode = bool(task.get("test") or task.get("test_mode") or ctx["context"].get("test_mode"))
    ctx["context"]["test_mode"] = test_mode

    task_run_id = _clean_text(task.get("run_id"))
    control_run_id = _clean_text(ctx.get("control_run_id"))
    if (
        task_run_id is not None
        and control_run_id is not None
        and task_run_id != control_run_id
    ):
        raise ValueError(
            "provider_directory_task_control_run_id_mismatch"
        )
    run_id = control_run_id or task_run_id
    retry_of_run_id = _clean_text(task.get("retry_of_run_id"))
    pagination_root_run_id = _clean_text(
        task.get("provider_directory_pagination_root_run_id")
    )
    endpoint_scope_input = _clean_text(task.get("provider_directory_endpoint_scope"))
    provider_directory_endpoint_scope = endpoint_scope_input.rstrip("/") if endpoint_scope_input else None
    requested_source_ids = (
        [census_request.source_id]
        if census_request is not None
        else _clean_source_id_list(
            task.get("source_ids")
            or task.get("source_id")
            or task.get("provider_directory_source_ids")
            or task.get("provider_directory_source_id")
        )
    )
    dataset_followup_only = bool(task.get("dataset_followup_only", False))
    dataset_rehydrate_only = bool(task.get("dataset_rehydrate_only"))
    if dataset_followup_only and bool(task.get("dataset_rehydrate_only")):
        raise ValueError(
            "provider_directory_dataset_followup_replay_scope_invalid"
        )
    limit = int(task.get("limit") or 0) or None
    source_query = _clean_text(task.get("source_query"))
    timeout = int(task.get("timeout") or os.getenv("HLTHPRT_PROVIDER_DIRECTORY_TIMEOUT", "15"))
    concurrency = int(task.get("concurrency") or os.getenv("HLTHPRT_PROVIDER_DIRECTORY_CONCURRENCY", "5"))
    seed_only = bool(task.get("seed_only", False))
    probe = bool(task.get("probe", True))
    import_resources = bool(task.get("import_resources", False))
    canonical_backfill_only = bool(task.get("canonical_backfill_only", False))
    contact_backfill_only = bool(task.get("contact_backfill_only", False))
    publish_artifacts_only = bool(task.get("publish_artifacts_only", False))
    should_publish_corroboration = _is_publish_corroboration_enabled(
        task.get("publish_corroboration")
    )
    publish_artifacts_targets = _provider_directory_publish_artifact_targets(
        task.get("publish_artifacts_targets")
        or task.get("publish_artifact_targets")
        or task.get("publish_targets")
    )
    profile_execution = (
        validated_profile_execution(task)
        if any(
            field_name in task
            for field_name in (
                "provider_directory_profile_contract_id",
                "provider_directory_profile_generation",
                "provider_directory_profile_selection_attestation",
            )
        )
        else None
    )
    open_only = bool(task.get("open_only", True))
    include_auth_required = bool(task.get("include_auth_required", False))
    include_supplemental_catalogs = _is_bool_or_default(task.get("include_supplemental_catalogs"), False)
    seed_db_path = _clean_text(task.get("seed_db_path"))
    retest_results_path = _clean_text(task.get("retest_results_path"))
    remote_catalog_input_fields = tuple(
        field_name
        for field_name in (
            "seed_db_url",
            "retest_results_url",
            "amerihealth_caritas_catalog_url",
            "contra_costa_catalog_url",
            "cms_sma_endpoint_directory_url",
        )
        if _clean_text(task.get(field_name))
    )
    local_alternate_catalog_input_fields = tuple(
        field_name
        for field_name in (
            "seed_db_path",
            "amerihealth_caritas_catalog_path",
            "contra_costa_catalog_path",
            "cms_sma_endpoint_directory_path",
        )
        if _clean_text(task.get(field_name))
    )
    if (
        retest_results_path is None
        and os.getenv("HLTHPRT_PROVIDER_DIRECTORY_RETEST_RESULTS_URL")
    ):
        remote_catalog_input_fields += ("retest_results_environment_url",)
    credential_config_file = _clean_text(task.get("credential_config_file"))
    _PROVIDER_DIRECTORY_CREDENTIALS_FILE_OVERRIDE.set(credential_config_file)
    has_credential_configuration = bool(
        credential_config_file
        or _clean_text(os.getenv(PROVIDER_DIRECTORY_CREDENTIALS_FILE_ENV))
        or _clean_text(os.getenv(PROVIDER_DIRECTORY_CREDENTIALS_JSON_ENV))
    )
    full_refresh = bool(task.get("full_refresh", False))
    default_resource_limit = 1 if test_mode else (0 if full_refresh else 25)
    default_page_limit = 1 if test_mode else (0 if full_refresh else 3)
    default_page_count = 25 if test_mode else (100 if full_refresh else 25)
    resource_limit = _int_or_default(task.get("resource_limit"), default_resource_limit)
    page_limit = _int_or_default(task.get("page_limit"), default_page_limit)
    page_count = _int_or_default(task.get("page_count"), default_page_count)
    linked_resource_limit = _int_or_default(
        task.get("linked_resource_limit"),
        _env_int("HLTHPRT_PROVIDER_DIRECTORY_LINKED_RESOURCE_LIMIT", resource_limit),
    )
    linked_resource_deadline_seconds = _int_or_default(
        task.get("linked_resource_deadline_seconds"),
        _env_int("HLTHPRT_PROVIDER_DIRECTORY_LINKED_RESOURCE_DEADLINE_SECONDS", 0),
    )
    resource_deadline_seconds = _int_or_default(
        task.get("resource_deadline_seconds"),
        _env_int("HLTHPRT_PROVIDER_DIRECTORY_RESOURCE_DEADLINE_SECONDS", 0),
    )
    stream_batch_size = _int_or_default(
        task.get("stream_batch_size"),
        0 if test_mode else _env_int("HLTHPRT_PROVIDER_DIRECTORY_STREAM_BATCH_SIZE", DEFAULT_STREAM_BATCH_SIZE),
    )
    use_bulk_export = _is_bulk_export_enabled(task.get("bulk_export"))
    bulk_export_max_pending_seconds = max(
        1,
        _int_or_default(
            task.get("bulk_export_max_pending_seconds"),
            _env_int(
                "HLTHPRT_PROVIDER_DIRECTORY_BULK_EXPORT_MAX_PENDING_SECONDS",
                DEFAULT_BULK_EXPORT_MAX_PENDING_SECONDS,
            ),
        ),
    )
    source_concurrency = _int_or_default(
        task.get("source_concurrency"),
        1 if test_mode else _env_int("HLTHPRT_PROVIDER_DIRECTORY_SOURCE_CONCURRENCY", 1),
    )
    resource_scan_concurrency = _validated_resource_scan_concurrency(
        task.get("resource_scan_concurrency")
        if task.get("resource_scan_concurrency") not in (None, "")
        else _env_int(SOURCE_RESOURCE_SCAN_CONCURRENCY_ENV, 1)
    )
    stale_cleanup_raw = task.get("stale_cleanup")
    should_cleanup_stale_rows = _is_bool_or_default(
        stale_cleanup_raw,
        not test_mode and import_resources,
    )
    resources = (
        list(census_request.resources)
        if census_request is not None
        else _selected_resources(task.get("resources"))
    )
    should_publish_artifacts = _is_bool_or_default(
        task.get("publish_artifacts"),
        import_resources and set(resources) == set(DEFAULT_RESOURCES),
    )
    publish_after_acquisition = bool(task.get("publish_after_acquisition", False))
    is_pagination_checkpointing_enabled = _is_pagination_checkpoint_mode_enabled(
        run_id=run_id,
        full_refresh=full_refresh,
        resource_limit=resource_limit,
        page_limit=page_limit,
        stream_batch_size=stream_batch_size,
        stale_cleanup=should_cleanup_stale_rows,
        publish_artifacts=should_publish_artifacts,
    )
    should_defer_typed_materialization = _is_bool_or_default(
        task.get("defer_typed_materialization"),
        False,
    )
    if should_defer_typed_materialization and not import_resources:
        raise ValueError(
            "provider_directory_deferred_typed_materialization_import_required"
        )
    if should_defer_typed_materialization and publish_after_acquisition:
        raise ValueError(
            "provider_directory_deferred_typed_materialization_incompatible_mode"
        )
    if census_request is not None:
        validate_current_version_census_runtime(
            census_request,
            CurrentVersionCensusRuntime(
                checkpointing_enabled=is_pagination_checkpointing_enabled,
                full_refresh=full_refresh,
                resource_limit=resource_limit,
                page_limit=page_limit,
                stream_batch_size=stream_batch_size,
                source_concurrency=source_concurrency,
                resource_scan_concurrency=resource_scan_concurrency,
                linked_resource_limit=linked_resource_limit,
                linked_resource_deadline_seconds=(
                    linked_resource_deadline_seconds
                ),
                resource_deadline_seconds=resource_deadline_seconds,
                probe=probe,
                seed_only=seed_only,
                test_mode=test_mode,
                dataset_rehydrate_only=dataset_rehydrate_only,
                dataset_followup_only=dataset_followup_only,
                canonical_backfill_only=canonical_backfill_only,
                contact_backfill_only=contact_backfill_only,
                publish_artifacts_only=publish_artifacts_only,
                local_seed_catalog=True,
                local_retest_catalog=retest_results_path is not None,
                supplemental_catalogs=include_supplemental_catalogs,
                local_supplemental_catalog_inputs=(
                    local_alternate_catalog_input_fields
                ),
                remote_catalog_inputs=remote_catalog_input_fields,
                bulk_export=use_bulk_export,
                stale_cleanup=should_cleanup_stale_rows,
                publication_requested=bool(
                    should_publish_artifacts
                    or publish_after_acquisition
                    or should_publish_corroboration
                ),
                defer_typed_materialization=(
                    should_defer_typed_materialization
                ),
                bounded_source_selection=bool(limit or source_query),
                endpoint_scope_configured=(
                    provider_directory_endpoint_scope is not None
                ),
                credential_configured=has_credential_configuration,
                open_only=open_only,
                include_auth_required=include_auth_required,
            ),
        )
        _validate_current_version_census_lineage(
            run_id,
            retry_of_run_id,
            pagination_root_run_id,
        )
        root_policy_document = task.get(
            "provider_directory_reviewed_root_policy"
        )
        reviewed_root_policy = (
            reviewed_root_policy_from_document(root_policy_document)
            if root_policy_document is not None
            else None
        )
        reviewed_census_seed_rows = reviewed_manual_census_seed_rows(
            census_request.source_id,
            root_policy=reviewed_root_policy,
        )
    elif task.get("provider_directory_reviewed_root_policy") is not None:
        raise ValueError(
            "provider_directory_reviewed_root_policy_scope_invalid"
        )
    await _raise_if_resource_import_cancelled(ctx, task)
    await ensure_database(test_mode)
    if not ctx["context"].get("provider_directory_tables_ready"):
        await _ensure_provider_directory_tables()
        ctx["context"]["provider_directory_tables_ready"] = True
    if dataset_rehydrate_only:
        return await _run_provider_directory_dataset_rehydrate(
            ctx, task, run_id, requested_source_ids
        )
    seen_stage_table_for_publish = (
        _import_seen_stage_table_name(run_id)
        if should_publish_artifacts
        and should_cleanup_stale_rows
        and run_id
        and _is_seen_stage_enabled()
        else None
    )
    if dataset_followup_only:
        incompatible_followup_mode_by_name = {
            "canonical_backfill_only": canonical_backfill_only,
            "contact_backfill_only": contact_backfill_only,
            "dataset_rehydrate_only": bool(task.get("dataset_rehydrate_only")),
            "import_resources": import_resources,
            "publish_after_acquisition": publish_after_acquisition,
            "publish_artifacts": should_publish_artifacts,
            "publish_artifacts_only": publish_artifacts_only,
            "seed_only": seed_only,
        }
        if len(requested_source_ids) != 1 or any(
            incompatible_followup_mode_by_name.values()
        ):
            raise ValueError(
                "provider_directory_dataset_followup_replay_scope_invalid"
            )
        dataset_followup = await _source_local_dataset_followup_if_current(
            source_ids=requested_source_ids,
            expected_acquisition_root_run_id=None,
        )
        if dataset_followup is None:
            raise RuntimeError(
                "provider_directory_dataset_followup_current_dataset_missing"
            )
        metrics_by_key = {
            "dataset_followup_only": True,
            "source_ids": requested_source_ids,
            "dataset_followup": dataset_followup,
        }
        ctx["context"]["audit"] = metrics_by_key
        ctx["context"]["run"] = ctx["context"].get("run", 0) + 1
        return metrics_by_key
    if canonical_backfill_only:
        metrics_by_key = await backfill_provider_directory_canonical_resources(
            resources=task.get("resources"),
        )
        ctx["context"]["audit"] = metrics_by_key
        ctx["context"]["run"] = ctx["context"].get("run", 0) + 1
        return metrics_by_key
    if contact_backfill_only:
        metrics_by_key = await backfill_provider_directory_location_contacts()
        ctx["context"]["audit"] = metrics_by_key
        ctx["context"]["run"] = ctx["context"].get("run", 0) + 1
        return metrics_by_key
    if publish_artifacts_only:
        publish_metric_by_name = {
            "publish_artifacts": True,
            "publish_artifacts_only": True,
            "source_ids": requested_source_ids,
        }
        if profile_execution is None:
            publish_metric_by_name = await _publish_provider_directory_dataset_artifacts(
                run_id=run_id,
                metrics=publish_metric_by_name,
                source_ids=requested_source_ids,
                publish_corroboration=should_publish_corroboration,
                publish_artifacts_targets=publish_artifacts_targets,
                require_complete_global_profile_fence=bool(
                    task.get("require_complete_global_profile_fence")
                ),
            )
        else:
            publish_metric_by_name = await _publish_attested_provider_directory_profile(
                run_id=run_id,
                control_run_id=control_run_id,
                metrics=publish_metric_by_name,
                execution=profile_execution,
            )
        if (
            profile_execution is None
            and _should_select_validated_artifacts(
                publish_artifacts_targets
            )
            and len(requested_source_ids) == 1
        ):
            dataset_followup = (
                await _source_local_dataset_followup_if_current(
                    source_ids=requested_source_ids,
                    expected_acquisition_root_run_id=None,
                )
            )
            if dataset_followup is None:
                raise RuntimeError(
                    "provider_directory_dataset_followup_current_dataset_missing"
                )
            publish_metric_by_name["dataset_followup"] = dataset_followup
        ctx["context"]["audit"] = publish_metric_by_name
        ctx["context"]["run"] = ctx["context"].get("run", 0) + 1
        print("PROVIDER_DIRECTORY_ARTIFACT_PUBLISH_DONE\t" + json.dumps(publish_metric_by_name, sort_keys=True, default=str))
        return publish_metric_by_name
    await _clear_resource_rows_seen(run_id)

    seed_rows: list[dict[str, Any]]
    tmpdir = None
    retest_tmpdir = None
    retest_path = None
    supplemental_retest_seed_rows: list[dict[str, Any]] = []
    supplemental_catalog_seed_rows: list[dict[str, Any]] = []
    supplemental_catalog_metric_by_name: dict[str, Any] = {
        "enabled": include_supplemental_catalogs,
        "rows": 0,
        "catalogs": {},
    }
    await _mark_provider_directory_progress(
        run_id,
        phase="provider-directory resolving source catalog",
        details=_provider_directory_progress_details(
            stage_ordinal=PROVIDER_DIRECTORY_PROGRESS_STAGE_CATALOG
        ),
        done=0,
        total=1,
        message="resolving Provider Directory source catalog",
    )
    if census_request is not None:
        seed_rows = reviewed_census_seed_rows
    elif test_mode and not task.get("seed_db_path") and not task.get("seed_db_url"):
        seed_rows = [
            {
                "id": "test-cigna",
                "org_name": "Cigna",
                "plan_name": "test open fhir",
                "api_base": "https://fhir.cigna.com/ProviderDirectory/v1",
                "auth_type": "open",
                "last_validated_status": "valid",
                "data_quality_flag": "VERIFIED_REAL",
                "source": "test_fixture",
            }
        ][: limit or 1]
    else:
        seed_path, tmpdir = _resolve_seed_db(
            seed_db_path,
            _clean_text(task.get("seed_db_url")),
        )
        if seed_path is None:
            raise RuntimeError("Provider Directory seed database could not be resolved.")
        seed_rows = _seed_rows_from_sqlite(
            seed_path,
            limit=None if (task.get("retest_results_path") or task.get("retest_results_url")) else limit,
            source_query=source_query,
        )
    if census_request is None:
        retest_path, retest_tmpdir = _resolve_retest_results(
            retest_results_path,
            _clean_text(task.get("retest_results_url")),
        )
        if retest_path is not None:
            supplemental_retest_seed_rows = _seed_rows_from_retest_results(
                retest_path,
                source_query=source_query,
            )
            seed_rows.extend(supplemental_retest_seed_rows)
        if include_supplemental_catalogs:
            (
                supplemental_catalog_seed_rows,
                supplemental_catalog_metric_by_name,
            ) = _seed_rows_from_supplemental_catalogs(
                source_query=source_query,
                timeout=timeout,
                amerihealth_caritas_catalog_path=_clean_text(task.get("amerihealth_caritas_catalog_path")),
                amerihealth_caritas_catalog_url=_clean_text(task.get("amerihealth_caritas_catalog_url")),
                contra_costa_catalog_path=_clean_text(task.get("contra_costa_catalog_path")),
                contra_costa_catalog_url=_clean_text(task.get("contra_costa_catalog_url")),
                cms_sma_endpoint_directory_path=_clean_text(task.get("cms_sma_endpoint_directory_path")),
                cms_sma_endpoint_directory_url=_clean_text(task.get("cms_sma_endpoint_directory_url")),
            )
            supplemental_catalog_metric_by_name["enabled"] = True
            seed_rows.extend(supplemental_catalog_seed_rows)

    try:
        source_rows = _dedupe_source_rows(
            [_source_row_from_seed(seed_record) for seed_record in seed_rows]
        )
        if census_request is None:
            source_rows = _add_uhc_official_file_source(
                source_rows,
                requested_source_ids=requested_source_ids,
                source_query=source_query,
                test_mode=test_mode,
                limit=limit,
            )
        source_rows = _scope_source_rows(source_rows, requested_source_ids)
        if limit and (task.get("retest_results_path") or task.get("retest_results_url")):
            source_rows = source_rows[:limit]
        census_contract = (
            bind_current_version_census_contract(census_request, source_rows)
            if census_request is not None
            else None
        )
        for source_record in source_rows:
            _validate_current_version_census_source_transport(source_record)
        endpoint_rows_seeded = await _upsert_provider_directory_source_rows(source_rows)
        stale_source_deletion_by_type = {}
        protected_source_ids: list[str] = []
        missing_protected_source_ids: list[str] = []
        if _is_source_catalog_stale_cleanup_enabled(
            stale_cleanup=should_cleanup_stale_rows,
            full_refresh=full_refresh,
            source_query=source_query,
            limit=limit,
            requested_source_ids=requested_source_ids,
            retest_results_configured=retest_path is not None,
        ):
            protected_source_ids = _configured_catalog_protected_source_ids(task)
            catalog_cleanup_result = await _delete_stale_provider_directory_source_catalog(
                [source_record["source_id"] for source_record in source_rows],
                protected_source_ids=protected_source_ids,
            )
            stale_source_deletion_by_type = catalog_cleanup_result["deleted"]
            missing_protected_source_ids = catalog_cleanup_result["protected_source_ids_missing"]
        metrics_by_key: dict[str, Any] = {
            "sources_seeded": len(source_rows),
            "api_endpoints_seeded": endpoint_rows_seeded,
            "source_ids": requested_source_ids,
            "supplemental_retest_sources_considered": len(supplemental_retest_seed_rows),
            "supplemental_catalog_sources_considered": len(supplemental_catalog_seed_rows),
            "supplemental_catalogs": supplemental_catalog_metric_by_name,
            "stale_source_rows_deleted": stale_source_deletion_by_type,
            "protected_source_ids": protected_source_ids,
            "protected_source_ids_missing": missing_protected_source_ids,
            "sources_probed": 0,
            "valid_capability_sources": 0,
            "resource_rows": {},
            "full_refresh": full_refresh,
            "resource_limit": resource_limit,
            "linked_resource_limit": linked_resource_limit,
            "linked_resource_deadline_seconds": linked_resource_deadline_seconds,
            "resource_deadline_seconds": resource_deadline_seconds,
            "page_limit": page_limit,
            "page_count": page_count,
            "stream_batch_size": stream_batch_size,
            "bulk_export": use_bulk_export,
            "bulk_export_max_pending_seconds": (
                bulk_export_max_pending_seconds
            ),
            "bulk_export_mode": _bulk_export_mode_metrics(use_bulk_export, {}),
            "source_concurrency": source_concurrency,
            "resource_scan_concurrency": resource_scan_concurrency,
            "rest_http_keepalive": _is_source_http_keepalive_enabled(),
            "stale_cleanup": should_cleanup_stale_rows,
            "publish_artifacts": should_publish_artifacts,
            "publish_after_acquisition": publish_after_acquisition,
            "publish_corroboration": should_publish_corroboration,
            "pagination_checkpoints_enabled": is_pagination_checkpointing_enabled,
            "defer_typed_materialization": should_defer_typed_materialization,
            "retry_of_run_id": retry_of_run_id,
            "provider_directory_pagination_root_run_id": pagination_root_run_id,
            "provider_directory_endpoint_scope": provider_directory_endpoint_scope,
            "credential_config_file_configured": bool(credential_config_file),
            "current_version_census_identity": (
                census_contract.identity()
                if census_contract is not None
                else None
            ),
        }
        await _mark_provider_directory_progress(
            run_id,
            phase="provider-directory sources seeded",
            details=_provider_directory_progress_details(
                stage_ordinal=PROVIDER_DIRECTORY_PROGRESS_STAGE_SOURCES
            ),
            done=1,
            total=1,
            message=f"seeded {len(source_rows)} Provider Directory source(s)",
            metrics=metrics_by_key,
        )
        valid_source_ids: set[str] | None = None
        probe_source_rows = _source_rows_allowed_for_probe(source_rows)
        metrics_by_key["manual_only_sources_skipped_before_probe"] = (
            len(source_rows) - len(probe_source_rows)
        )
        if not seed_only and probe and probe_source_rows:
            async with _source_http_session_scope(
                force=census_contract is not None,
                require_verified_tls=census_contract is not None,
            ):
                probed, valid, valid_source_ids = await _run_source_probe_batch(
                    probe_source_rows,
                    timeout=timeout,
                    concurrency=concurrency,
                    run_id=run_id,
                )
            metrics_by_key["sources_probed"] = probed
            metrics_by_key["valid_capability_sources"] = valid
        if not seed_only and import_resources and source_rows:
            checkpoint_retry_source_ids = (
                set(requested_source_ids)
                if is_pagination_checkpointing_enabled
                and retry_of_run_id
                and pagination_root_run_id
                else set()
            )
            importable, selection_metrics = _select_resource_import_sources(
                source_rows,
                valid_source_ids=valid_source_ids,
                open_only=open_only,
                include_auth_required=include_auth_required,
                checkpoint_retry_source_ids=checkpoint_retry_source_ids,
                requested_resource_types=resources,
            )
            metrics_by_key.update(selection_metrics)
            if requested_source_ids and not importable:
                selection_error = _requested_source_import_empty_error(
                    requested_source_ids,
                    selection_metrics,
                )
                metrics_by_key["requested_source_import_error"] = selection_error
                ctx["context"]["audit"] = metrics_by_key
                raise RuntimeError(selection_error)
            try:
                resolved_endpoint_scope = _validate_provider_directory_endpoint_scope(
                    importable,
                    provider_directory_endpoint_scope,
                )
            except RuntimeError as endpoint_scope_error:
                metrics_by_key["provider_directory_endpoint_scope_error"] = str(
                    endpoint_scope_error
                )
                ctx["context"]["audit"] = metrics_by_key
                raise
            metrics_by_key["provider_directory_endpoint_scope_resolved"] = (
                resolved_endpoint_scope
            )
            source_import_groups = _group_resource_import_sources(
                importable,
                linked_resource_limit=linked_resource_limit,
            )
            metrics_by_key["source_import_groups_attempted"] = len(source_import_groups)
            metrics_by_key["source_import_duplicate_sources_collapsed"] = len(importable) - len(source_import_groups)

            async def resource_progress(
                done: int,
                total: int,
                counts: dict[str, int],
                details: dict[str, Any] | None = None,
            ) -> None:
                """Publish progress for the active provider-directory resource."""
                metrics_by_key["resource_rows"] = counts
                metrics_by_key["resource_fetch_completed_source_ids"] = {
                    resource_type: sorted(source_ids)
                    for resource_type, source_ids in sorted(
                        completed_source_ids_by_resource.items()
                    )
                }
                active_source_groups = (
                    details.get("active_source_groups", [])
                    if isinstance(details, dict)
                    else []
                )
                metrics_by_key["active_source_groups"] = active_source_groups
                active_preview = ", ".join(
                    (
                        f"{group.get('sample_org_name') or group.get('sample_source_id')}:"
                        f"{group.get('current_resource') or 'starting'}"
                    )
                    for group in active_source_groups[:3]
                )
                active_suffix = f"; active={active_preview}" if active_preview else ""
                await _mark_provider_directory_progress(
                    run_id,
                    phase="provider-directory importing resources",
                    done=done,
                    total=total,
                    message=(
                        f"imported resources for {done}/{total} source group(s); "
                        f"rows_written={sum(counts.values())}"
                        f"{active_suffix}"
                    ),
                    details=_provider_directory_progress_details(
                        {"active_source_groups": active_source_groups},
                        stage_ordinal=PROVIDER_DIRECTORY_PROGRESS_STAGE_IMPORT,
                        counters={
                            "resource_rows_written": sum(counts.values()),
                            "source_groups_completed": done,
                            "source_groups_total": total,
                        },
                    ),
                    metrics=metrics_by_key,
                )

            await _mark_provider_directory_progress(
                run_id,
                phase="provider-directory importing resources",
                done=0,
                total=max(len(source_import_groups), 1),
                message=f"importing resources from {len(source_import_groups)} source group(s)",
                details=_provider_directory_progress_details(
                    stage_ordinal=PROVIDER_DIRECTORY_PROGRESS_STAGE_IMPORT,
                    counters={
                        "resource_rows_written": 0,
                        "source_groups_completed": 0,
                        "source_groups_total": len(source_import_groups),
                    },
                ),
                metrics=metrics_by_key,
            )
            completed_source_ids_by_resource: dict[str, set[str]] = {}
            retry_not_before_by_resource: dict[str, str] = {}
            pagination_resume_required_entries: set[str] = set()
            metrics_by_key["resource_rows"] = {}
            if importable:
                metrics_by_key["resource_rows"] = await _import_resources_with_source_http_session(
                    importable,
                    resources=resources,
                    per_resource_limit=resource_limit,
                    page_limit=page_limit,
                    page_count=page_count,
                    timeout=timeout,
                    run_id=run_id,
                    linked_resource_limit=linked_resource_limit,
                    linked_resource_concurrency=concurrency,
                    linked_resource_deadline_seconds=linked_resource_deadline_seconds,
                    resource_deadline_seconds=resource_deadline_seconds,
                    linked_counts=metrics_by_key.setdefault("linked_resource_rows", {}),
                    resource_fetch_stats=metrics_by_key.setdefault("resource_fetch_stats", {}),
                    resource_completion=completed_source_ids_by_resource,
                    resource_retry_not_before=retry_not_before_by_resource,
                    stale_counts=metrics_by_key.setdefault("stale_resource_rows_deleted", {}),
                    stale_cleanup=should_cleanup_stale_rows,
                    stream_batch_size=stream_batch_size,
                    source_concurrency=source_concurrency,
                    resource_scan_concurrency=resource_scan_concurrency,
                    bulk_export=use_bulk_export,
                    bulk_export_max_pending_seconds=(
                        bulk_export_max_pending_seconds
                    ),
                    cancel_ctx=ctx,
                    cancel_task={**task, "run_id": run_id},
                    progress_callback=resource_progress,
                    preserve_seen_stage=bool(seen_stage_table_for_publish),
                    is_pagination_checkpointing_enabled=is_pagination_checkpointing_enabled,
                    defer_typed_materialization=should_defer_typed_materialization,
                    retry_of_run_id=retry_of_run_id,
                    pagination_root_run_id=pagination_root_run_id,
                    pagination_resume_required=pagination_resume_required_entries,
                    provider_directory_endpoint_scope=provider_directory_endpoint_scope,
                    require_complete_resources=(
                        full_refresh
                        and resource_limit <= 0
                        and page_limit <= 0
                    ),
                )
            if retry_not_before_by_resource:
                metrics_by_key["provider_directory_retry_not_before_by_resource"] = dict(
                    sorted(retry_not_before_by_resource.items())
                )
                metrics_by_key[SOURCE_RETRY_NOT_BEFORE_METRIC] = max(
                    retry_not_before_by_resource.values()
                )
            metrics_by_key["bulk_export_mode"] = _bulk_export_mode_metrics(
                use_bulk_export,
                metrics_by_key.get("resource_fetch_stats") or {},
            )
            metrics_by_key["plan_graph_complete_resource_fetches"] = _resource_fetch_metric_total(
                metrics_by_key.get("resource_fetch_stats") or {},
                "plan_graph_complete_sources",
            )
            metrics_by_key["collection_complete_resource_fetches"] = _resource_fetch_metric_total(
                metrics_by_key.get("resource_fetch_stats") or {},
                "collection_complete_sources",
            )
            metrics_by_key["resource_fetch_completed_source_ids"] = {
                resource_type: sorted(source_ids)
                for resource_type, source_ids in sorted(
                    completed_source_ids_by_resource.items()
                )
            }
            if pagination_resume_required_entries:
                required_entries = sorted(pagination_resume_required_entries)
                metrics_by_key["pagination_resume_required"] = required_entries
                ctx["context"]["audit"] = metrics_by_key
                raise RuntimeError(
                    f"{PAGINATION_RESUME_REQUIRED_ERROR}:"
                    + ",".join(required_entries)
                )
            metrics_by_key["sources_import_attempted"] = len(importable)
            if should_publish_artifacts or publish_after_acquisition:
                artifact_source_ids = requested_source_ids
                if not artifact_source_ids:
                    artifact_source_ids = [
                        importable_source["source_id"]
                        for importable_source in importable
                        if _clean_text(importable_source.get("source_id")) is not None
                    ]
                required_publish_resources = [
                    resource_type
                    for resource_type in ("PractitionerRole", "Practitioner", "Location")
                    if resource_type in resources
                ]
                resource_fetch_stats_by_resource = metrics_by_key.get("resource_fetch_stats") or {}
                completion_tracking_available = bool(completed_source_ids_by_resource) or bool(
                    resource_fetch_stats_by_resource
                )
                if required_publish_resources and completion_tracking_available:
                    publishable_artifact_source_ids = [
                        source_id
                        for source_id in artifact_source_ids
                        if all(
                            source_id in completed_source_ids_by_resource.get(resource_type, set())
                            for resource_type in required_publish_resources
                        )
                    ]
                else:
                    publishable_artifact_source_ids = list(artifact_source_ids)
                metrics_by_key["publishable_artifact_source_ids"] = publishable_artifact_source_ids
                skipped_artifact_source_ids = sorted(set(artifact_source_ids) - set(publishable_artifact_source_ids))
                if skipped_artifact_source_ids:
                    metrics_by_key["artifact_publish_skipped_source_ids"] = skipped_artifact_source_ids
                    metrics_by_key["artifact_publish_required_resources"] = required_publish_resources
                if required_publish_resources and not publishable_artifact_source_ids:
                    skip_payload_by_metric = {
                        "skipped": True,
                        "reason": "critical_resource_fetch_incomplete",
                        "required_resources": required_publish_resources,
                        "source_ids": artifact_source_ids,
                    }
                    metrics_by_key["location_contacts_backfilled"] = skip_payload_by_metric
                    metrics_by_key["location_coordinates_backfilled"] = skip_payload_by_metric
                    metrics_by_key["location_address_keys_stamped"] = skip_payload_by_metric
                    metrics_by_key["location_archive"] = skip_payload_by_metric
                    metrics_by_key["address_overlay"] = skip_payload_by_metric
                    metrics_by_key["network_catalog"] = skip_payload_by_metric
                    metrics_by_key["ptg_corroboration_view_published"] = False
                    metrics_by_key["ptg_corroboration_view_skipped"] = skip_payload_by_metric
                else:
                    metrics_by_key = await _publish_selected_provider_directory_artifacts(
                        run_id=run_id,
                        metrics=metrics_by_key,
                        source_ids=publishable_artifact_source_ids,
                        seen_table=seen_stage_table_for_publish,
                        publish_after_acquisition=publish_after_acquisition,
                        publish_corroboration=should_publish_corroboration,
                        publish_artifacts_targets=publish_artifacts_targets,
                    )
            else:
                metrics_by_key["location_contacts_backfilled"] = {
                    "skipped": True,
                    "reason": "publish_artifacts_disabled",
                }
                metrics_by_key["location_coordinates_backfilled"] = {
                    "skipped": True,
                    "reason": "publish_artifacts_disabled",
                }
                metrics_by_key["location_address_keys_stamped"] = 0
                metrics_by_key["location_archive"] = {"skipped": True, "reason": "publish_artifacts_disabled"}
                metrics_by_key["ptg_corroboration_view_published"] = False
            source_local_ids = list(requested_source_ids)
            if not source_local_ids and len(importable) == 1:
                source_id = _clean_text(importable[0].get("source_id"))
                source_local_ids = [source_id] if source_id is not None else []
            profile_followup = await _source_local_profile_followup_if_current(
                source_ids=source_local_ids,
                expected_acquisition_root_run_id=(
                    pagination_root_run_id or run_id
                ),
            )
            if profile_followup is not None:
                metrics_by_key["profile_followup"] = profile_followup
            if _has_dataset_publication_followup_trigger(
                metrics_by_key,
                source_local_ids,
                importable,
            ):
                dataset_followup = (
                    await _source_local_dataset_followup_if_current(
                        source_ids=source_local_ids,
                        expected_acquisition_root_run_id=(
                            pagination_root_run_id or run_id
                        ),
                    )
                )
                if dataset_followup is not None:
                    metrics_by_key["dataset_followup"] = dataset_followup
        ctx["context"]["audit"] = metrics_by_key
        ctx["context"]["run"] = ctx["context"].get("run", 0) + 1
        print(
            "Provider Directory FHIR import done: "
            f"sources_seeded={metrics_by_key['sources_seeded']} "
            f"sources_probed={metrics_by_key['sources_probed']} "
            f"valid_capability_sources={metrics_by_key['valid_capability_sources']} "
            f"resource_rows={metrics_by_key['resource_rows']}"
        )
        print("PROVIDER_DIRECTORY_FHIR_IMPORT_DONE\t" + json.dumps(metrics_by_key, sort_keys=True, default=str))
        return metrics_by_key
    finally:
        if seen_stage_table_for_publish:
            await _drop_import_seen_stage_table(seen_stage_table_for_publish)
        await _clear_resource_rows_seen(run_id)
        if tmpdir is not None:
            tmpdir.cleanup()
        if retest_tmpdir is not None:
            retest_tmpdir.cleanup()


process_data = process_provider_directory_fhir_data
process_data.__name__ = "process_data"


async def startup(ctx: dict[str, Any]) -> None:
    """Initialize provider-directory process dependencies."""
    ctx.setdefault("context", {})
    ctx["context"].setdefault("run", 0)
    ctx["context"].setdefault("start", _now())
    ctx["import_date"] = _normalize_import_id(ctx.get("import_date"))
    await ensure_database(bool(ctx["context"].get("test_mode", False)))
    await _ensure_provider_directory_tables()
    ctx["context"]["provider_directory_tables_ready"] = True


async def shutdown(ctx: dict[str, Any]) -> None:
    """Release provider-directory process dependencies."""
    ctx.setdefault("context", {})["finished_at"] = _now().isoformat()


