async def run_provider_directory_fhir_command(
    **command_fields: Any,
) -> dict[str, Any]:
    """Run the provider-directory import command."""
    options = _ProviderDirectoryFhirCommandOptions(**command_fields)
    runtime_context_by_key: dict[str, Any] = {
        "context": {"test_mode": options.test_mode}
    }
    command_options = asdict(options)
    required_root_count = command_options.pop(
        "provider_directory_reviewed_root_count"
    )
    task_by_field = _apply_provider_directory_refresh_preset(command_options)
    if (
        options.provider_directory_acquisition_strategy
        == "server-issued-traversal-subset"
    ):
        task_by_field["provider_directory_reviewed_root_policy"] = (
            ReviewedRootPolicy(required_root_count).document()
        )
    elif required_root_count != DEFAULT_REQUIRED_ROOT_COUNT:
        raise ValueError(
            "provider_directory_reviewed_root_policy_scope_invalid"
        )
    validate_uhc_official_file_admission(task_by_field, test_mode=options.test_mode)
    census_request = current_version_census_request(
        task_by_field,
        allowed_resources=DEFAULT_RESOURCES,
    )
    if census_request is None:
        await startup(runtime_context_by_key)
    try:
        return await process_data(runtime_context_by_key, task_by_field)
    finally:
        await shutdown(runtime_context_by_key)


run_provider_directory_fhir_command.__annotations__ = {
    **_ProviderDirectoryFhirCommandOptions.__annotations__,
    "return": "dict[str, Any]",
}
run_provider_directory_fhir_command.__signature__ = inspect.signature(
    _ProviderDirectoryFhirCommandOptions
).replace(return_annotation="dict[str, Any]")


main = run_provider_directory_fhir_command
main.__name__ = "main"


def _clean_source_id_list(raw_source_ids: Any) -> list[str]:
    if raw_source_ids in (None, ""):
        return []
    if isinstance(raw_source_ids, str):
        source_id_values = raw_source_ids.split(",")
    elif isinstance(raw_source_ids, (bytes, bytearray, dict)) or not hasattr(raw_source_ids, "__iter__"):
        source_id_values = (raw_source_ids,)
    else:
        source_id_values = raw_source_ids
    cleaned_source_ids: list[str] = []
    seen_source_ids: set[str] = set()
    for source_id_candidate in source_id_values:
        source_id_text = _clean_text(source_id_candidate)
        if not source_id_text or source_id_text in seen_source_ids:
            continue
        seen_source_ids.add(source_id_text)
        cleaned_source_ids.append(source_id_text)
    return cleaned_source_ids


def _scope_source_rows(
    source_rows: list[dict[str, Any]],
    requested_source_ids: list[str],
) -> list[dict[str, Any]]:
    if not requested_source_ids:
        return source_rows
    rows_by_source_id = {
        source_id: row
        for row in source_rows
        if (source_id := _clean_text(row.get("source_id")))
    }
    missing_source_ids = [source_id for source_id in requested_source_ids if source_id not in rows_by_source_id]
    if missing_source_ids:
        raise ValueError(
            "Provider Directory source_id not found in resolved source catalog: "
            + ", ".join(missing_source_ids)
        )
    return [rows_by_source_id[source_id] for source_id in requested_source_ids]


PROVIDER_DIRECTORY_ADDRESS_OVERLAY_TABLE = "provider_directory_address_overlay"
PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_PREFIX = "provider_directory_address_overlay_stage"
PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_CLEANUP_LIMIT = 16
PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_OWNER_HISTORY_LIMIT = 4096
PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_CLEANUP_MIN_AGE_SECONDS = 6 * 60 * 60
PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_OWNER_TOKEN_LENGTH = 12
PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_LEGACY_IDENTIFIER_HEX_LENGTH = 16
PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_NONCE_HEX_LENGTH = 10
PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_IDENTIFIER_HEX_LENGTH = (
    PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_OWNER_TOKEN_LENGTH
    + PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_NONCE_HEX_LENGTH
)
PROVIDER_DIRECTORY_ADDRESS_OVERLAY_INDEX_SUFFIXES = (
    "source_record_idx",
    "npi_idx",
    "address_key_idx",
    "source_idx",
    "phone_idx",
    "source_run_resource_idx",
)


def _address_overlay_stage_table_name(run_id: str | None = None) -> str:
    if run_id:
        owner_token = _address_overlay_stage_owner_token(run_id)
        nonce = os.urandom(
            PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_NONCE_HEX_LENGTH // 2
        ).hex()
        digest = f"{owner_token}{nonce}"
    else:
        raw_identifier = f"full:{os.getpid()}:{time.time_ns()}:{os.urandom(8).hex()}"
        digest = hashlib.sha1(
            raw_identifier.encode("utf-8", errors="ignore")
        ).hexdigest()[
            :PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_IDENTIFIER_HEX_LENGTH
        ]
    return f"{PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_PREFIX}_{digest}"


def _address_overlay_stage_owner_token(run_id: str) -> str:
    return hashlib.sha1(
        f"run:{run_id}".encode("utf-8", errors="ignore")
    ).hexdigest()[:PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_OWNER_TOKEN_LENGTH]


def _is_address_overlay_stage_table_name(table_name: str) -> bool:
    """Accept only identifiers emitted by the overlay stage-name helper."""

    return bool(
        re.fullmatch(
            rf"{re.escape(PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_PREFIX)}_"
            rf"(?:"
            rf"[0-9a-f]{{{PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_LEGACY_IDENTIFIER_HEX_LENGTH}}}"
            rf"|[0-9a-f]{{{PROVIDER_DIRECTORY_ADDRESS_OVERLAY_STAGE_IDENTIFIER_HEX_LENGTH}}}"
            rf")",
            table_name,
        )
    )


def _coerce_rowcount(value: Any) -> int:
    if value is None:
        return 0
    text_value = str(value)
    matches = re.findall(r"(\d+)", text_value)
    return int(matches[-1]) if matches else 0


def _coordinate_country_key_sql(country_expr: str) -> str:
    return f"regexp_replace(upper(COALESCE(({country_expr})::varchar, '')), '[^A-Z0-9]', '', 'g')"


def _coordinate_pair_plausible_sql(latitude_expr: str, longitude_expr: str, country_expr: str) -> str:
    country_key = _coordinate_country_key_sql(country_expr)
    default_us = f"{country_key} IN ('', 'US', 'USA', 'UNITEDSTATES', 'UNITEDSTATESOFAMERICA', '840', '001')"
    return f"""
        ({latitude_expr}) BETWEEN -90 AND 90
        AND ({longitude_expr}) BETWEEN -180 AND 180
        AND NOT (ABS({latitude_expr}) < 0.0000001 AND ABS({longitude_expr}) < 0.0000001)
        AND (
            NOT ({default_us})
            OR (({latitude_expr}) BETWEEN 24 AND 50 AND ({longitude_expr}) BETWEEN -125 AND -66)
            OR (({latitude_expr}) BETWEEN 51 AND 72 AND ({longitude_expr}) BETWEEN -180 AND -129)
            OR (({latitude_expr}) BETWEEN 18 AND 23 AND ({longitude_expr}) BETWEEN -161 AND -154)
            OR (({latitude_expr}) BETWEEN 17 AND 19 AND ({longitude_expr}) BETWEEN -68 AND -64)
            OR (({latitude_expr}) BETWEEN 13 AND 16 AND ({longitude_expr}) BETWEEN 144 AND 146)
            OR (({latitude_expr}) BETWEEN -15 AND -10 AND ({longitude_expr}) BETWEEN -171 AND -168)
        )
    """


def _coordinate_from_location_sql(
    latitude_expr: str,
    longitude_expr: str,
    country_expr: str,
    *,
    axis: str,
) -> str:
    if axis not in {"lat", "long"}:
        raise ValueError(f"unsupported coordinate axis: {axis}")
    numeric_re = r"^-?[0-9]+(\.[0-9]+)?$"
    raw_lat = f"({latitude_expr})::numeric"
    raw_long = f"({longitude_expr})::numeric"
    scaled_1m_lat = f"(({latitude_expr})::numeric / 1000000)"
    scaled_1m_long = f"(({longitude_expr})::numeric / 1000000)"
    scaled_10m_lat = f"(({latitude_expr})::numeric / 10000000)"
    scaled_10m_long = f"(({longitude_expr})::numeric / 10000000)"
    raw_value = raw_lat if axis == "lat" else raw_long
    scaled_1m_value = scaled_1m_lat if axis == "lat" else scaled_1m_long
    scaled_10m_value = scaled_10m_lat if axis == "lat" else scaled_10m_long
    numeric_guard = (
        f"({latitude_expr}) ~ '{numeric_re}' AND ({longitude_expr}) ~ '{numeric_re}'"
    )
    return f"""
        CASE
            WHEN {numeric_guard}
             AND {_coordinate_pair_plausible_sql(raw_lat, raw_long, country_expr)}
                THEN {raw_value}
            WHEN {numeric_guard}
             AND {_coordinate_pair_plausible_sql(scaled_1m_lat, scaled_1m_long, country_expr)}
                THEN {scaled_1m_value}
            WHEN {numeric_guard}
             AND {_coordinate_pair_plausible_sql(scaled_10m_lat, scaled_10m_long, country_expr)}
                THEN {scaled_10m_value}
            ELSE NULL::numeric
        END
    """


def _coordinate_text_sql(numeric_expr: str) -> str:
    return (
        "NULLIF(TRIM(TRAILING '.' FROM "
        f"TRIM(TRAILING '0' FROM ROUND(({numeric_expr})::numeric, 8)::varchar)"
        "), '')::varchar"
    )


